function getStreakTitle(streak = 0, tier) {
  const s = Number(streak) || 0;
  const t = Number(tier !== undefined ? tier : getStreakTier(s));
  const milestone = STREAK_MILESTONES.slice().reverse().find(m => m.tier <= t && s >= m.days);
  if (milestone) return milestone.title;
  if (t === 5) return "Độc nhất vô nhị";
  if (t === 4) return "Bậc thầy học thuật";
  if (t === 3) return "Nhà nghiên cứu tài năng";
  if (t === 2) return "Học giả bền bỉ";
  if (t === 1) return "Sinh viên năng động";
  return "Tân binh";
}

window.openStreakJourneyModal = function () {
  const modal = document.getElementById("streakJourneyModal");
  if (!modal) return;

  const currentStreak = Number(session?.streak || window.currentStreakCount || 0);
  const listEl = document.getElementById("journeyMilestonesList");
  if (listEl) {
    listEl.innerHTML = STREAK_MILESTONES.map(m => {
      const isUnlocked = currentStreak >= m.days;
      const flame = getFlameSVG(m.tier, 26);
      return `
        <div class="journey-milestone-card ${isUnlocked ? 'unlocked' : ''}">
          <div class="milestone-badge-icon">${flame}</div>
          <div class="milestone-info">
            <div class="milestone-title-row">
              <span class="milestone-days">Mốc ${m.days} ngày · ${m.title}</span>
              <span class="milestone-status">${isUnlocked ? '✓ Đã mở khóa' : `Còn ${m.days - currentStreak} ngày`}</span>
            </div>
            <div class="milestone-perks-container">
              <div class="milestone-perk-row">
                <span class="milestone-perk-tag perk-forum">Diễn đàn</span>
                <span class="milestone-perk-text">${m.forumDesc}</span>
              </div>
              <div class="milestone-perk-row">
                <span class="milestone-perk-tag perk-study">Phòng tự học</span>
                <span class="milestone-perk-text">${m.studyDesc}</span>
              </div>
            </div>
          </div>
        </div>
      `;
    }).join("");
  }
  modal.showModal();
};

window.closeStreakJourneyModal = function () {
  const modal = document.getElementById("streakJourneyModal");
  if (modal) modal.close();
};

let currentShieldLogs = [];
let shieldHistoryFilter = "all";

window.openStreakShieldModal = async function () {
  const modal = document.getElementById("streakShieldModal");
  if (!modal) return;

  if (!session) {
    openAuth();
    return;
  }

  modal.showModal();

  // Reset filter to 'all'
  shieldHistoryFilter = "all";
  $$(".shield-tab-btn").forEach(btn => {
    btn.classList.toggle("active", btn.dataset.shieldFilter === "all");
  });

  const listEl = document.getElementById("shieldHistoryList");
  if (listEl) {
    listEl.innerHTML = `<div class="shield-history-loading" style="text-align: center; padding: 20px; color: var(--muted); font-size: 13px;">Đang tải dữ liệu khiên...</div>`;
  }

  try {
    const res = await requestAPI("/api/me/shields");
    if (!res) throw new Error("Không thể tải thông tin khiên.");

    const count = Number(res.shields) || 0;
    const max = Number(res.maxShields) || 3;
    currentShieldLogs = Array.isArray(res.logs) ? res.logs : [];

    // Cập nhật số khiên trên modal
    const countEl = document.getElementById("shieldModalCount");
    if (countEl) countEl.textContent = count;

    // Cập nhật số khiên trên badge trang chủ và hành trình
    const b1 = document.getElementById("streakShieldsCount");
    const b2 = document.getElementById("journeyShieldsCount");
    if (b1) b1.textContent = count;
    if (b2) b2.textContent = count;

    // Render 3 slots khiên
    const slotsEl = document.getElementById("shieldModalSlots");
    if (slotsEl) {
      let slotsHTML = "";
      for (let i = 1; i <= max; i++) {
        const isFilled = i <= count;
        slotsHTML += `<div class="shield-slot ${isFilled ? 'filled' : 'empty'}" title="${isFilled ? `Khiên số ${i} (Đang kích hoạt)` : `Ô khiên ${i} (Trống)`}">${isFilled ? '<svg class="shield-icon-svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>' : '<svg class="ui-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>'}</div>`;
      }
      slotsEl.innerHTML = slotsHTML;
    }

    // Status pill
    const statusDot = document.getElementById("shieldModalStatusDot");
    const statusText = document.getElementById("shieldModalStatusText");
    if (statusDot && statusText) {
      if (count > 0) {
        statusDot.innerHTML = `<svg width="10" height="10" viewBox="0 0 24 24" fill="#10b981"><circle cx="12" cy="12" r="10"/></svg>`;
        statusText.textContent = `Đang sẵn sàng tự động giữ chuỗi: Bạn có ${count} khiên bảo vệ phòng khi bận rộn.`;
      } else {
        statusDot.innerHTML = `<svg width="10" height="10" viewBox="0 0 24 24" fill="#94a3b8"><circle cx="12" cy="12" r="10"/></svg>`;
        statusText.textContent = "Đang cạn khiên: Hãy duy trì hoạt động hoặc tham gia Đấu trường Arena để nhận thêm!";
      }
    }

    renderShieldHistoryUI(currentShieldLogs, shieldHistoryFilter);
  } catch (err) {
    if (listEl) {
      listEl.innerHTML = `<div class="shield-history-empty" style="color: #ef4444;">Không thể tải lịch sử khiên. Vui lòng thử lại sau.</div>`;
    }
  }
};

window.closeStreakShieldModal = function () {
  const modal = document.getElementById("streakShieldModal");
  if (modal) modal.close();
};

window.filterShieldHistory = function (filterType) {
  shieldHistoryFilter = filterType;
  $$(".shield-tab-btn").forEach(btn => {
    btn.classList.toggle("active", btn.dataset.shieldFilter === filterType);
  });
  renderShieldHistoryUI(currentShieldLogs, shieldHistoryFilter);
};

function renderShieldHistoryUI(logs = [], filterType = "all") {
  const listEl = document.getElementById("shieldHistoryList");
  if (!listEl) return;

  let filtered = logs;
  if (filterType === "add") {
    filtered = logs.filter(l => l.changeType === "add");
  } else if (filterType === "use") {
    filtered = logs.filter(l => l.changeType === "use");
  }

  if (!filtered.length) {
    const emptyMsg = filterType === "add"
      ? "Chưa có lịch sử được cộng khiên nào."
      : (filterType === "use" ? "Chưa có lịch sử tiêu hao khiên nào." : "Chưa có biến động khiên nào được ghi nhận.");
    listEl.innerHTML = `<div class="shield-history-empty">${emptyMsg}</div>`;
    return;
  }

  listEl.innerHTML = filtered.map(item => {
    const isAdd = item.changeType === "add";
    const deltaText = isAdd ? `+${item.amount}` : `-${item.amount}`;
    const badgeClass = isAdd ? "add" : "use";
    const itemClass = isAdd ? "is-add" : "is-use";
    const badgeIcon = isAdd ? '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-1px;"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>+' : '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-1px;"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>-';

    let timeStr = "";
    if (item.createdAt) {
      try {
        const d = new Date(item.createdAt.includes("Z") || item.createdAt.includes("T") ? item.createdAt : item.createdAt.replace(" ", "T") + "Z");
        if (!isNaN(d.getTime())) {
          timeStr = d.toLocaleString("vi-VN", {
            timeZone: "Asia/Ho_Chi_Minh",
            hour: "2-digit",
            minute: "2-digit",
            day: "2-digit",
            month: "2-digit",
            year: "numeric"
          });
        } else {
          timeStr = item.createdAt;
        }
      } catch (e) {
        timeStr = item.createdAt;
      }
    }

    return `
      <div class="shield-log-item ${itemClass}">
        <div class="shield-log-left">
          <div class="shield-log-badge ${badgeClass}">${badgeIcon}</div>
          <div class="shield-log-info">
            <span class="shield-log-reason" title="${escapeHTML(item.reason)}">${escapeHTML(item.reason)}</span>
            <span class="shield-log-time"><svg class="ui-icon" width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-1px; margin-right:3px;"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>${escapeHTML(timeStr)}</span>
          </div>
        </div>
        <div class="shield-log-right">
          <span class="shield-log-delta ${badgeClass}">${deltaText} khiên</span>
          <span class="shield-log-balance">Số dư: ${item.balanceAfter}/3</span>
        </div>
      </div>
    `;
  }).join("");
}

function triggerMilestoneCelebration(streak, tier) {
  if (typeof currentRoute !== "undefined" && currentRoute !== "home") return;
  if (document.querySelector("dialog[open]")) return;
  if (tier < 1) return;

  const storageKey = `re_search_celebrated_tier_${session?.id || 'guest'}`;
  const lastCelebrated = Number(localStorage.getItem(storageKey) || 0);
  if (tier <= lastCelebrated) return;

  localStorage.setItem(storageKey, tier);

  const canvas = document.createElement("canvas");
  canvas.style.position = "fixed";
  canvas.style.top = "0";
  canvas.style.left = "0";
  canvas.style.width = "100vw";
  canvas.style.height = "100vh";
  canvas.style.pointerEvents = "none";
  canvas.style.zIndex = "999999";
  document.body.appendChild(canvas);

  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
  const ctx = canvas.getContext("2d");

  const particles = [];
  const colors = isChristmas2026Season()
    ? ["#dc2626", "#16a34a", "#fbbf24", "#e0f2fe", "#ffffff", "#f43f5e"]
    : ["#ffd43b", "#f783ac", "#7048e8", "#4dabf7", "#ff6b6b", "#69db7c"];
  for (let i = 0; i < 70; i++) {
    particles.push({
      x: canvas.width * 0.5 + (Math.random() - 0.5) * 200,
      y: canvas.height * 0.35 + (Math.random() - 0.5) * 100,
      vx: (Math.random() - 0.5) * 12,
      vy: Math.random() * -10 - 4,
      size: Math.random() * 8 + 4,
      color: colors[Math.floor(Math.random() * colors.length)],
      rotation: Math.random() * 360,
      rotSpeed: (Math.random() - 0.5) * 10,
      opacity: 1,
    });
  }

  let startTime = Date.now();
  function animate() {
    const elapsed = Date.now() - startTime;
    if (elapsed > 3500) {
      canvas.remove();
      return;
    }
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    particles.forEach((p) => {
      p.x += p.vx;
      p.y += p.vy;
      p.vy += 0.35;
      p.rotation += p.rotSpeed;
      p.opacity = Math.max(0, 1 - elapsed / 3500);

      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate((p.rotation * Math.PI) / 180);
      ctx.fillStyle = p.color;
      ctx.globalAlpha = p.opacity;
      ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
      ctx.restore();
    });
    requestAnimationFrame(animate);
  }
  requestAnimationFrame(animate);

  toast(`🎉 Chúc mừng bạn đã đạt chuỗi ${streak} ngày và mở khóa đặc quyền mới!`);
}

function normalizePost(p) {
  const authorObj = p.author || {};
  return {
    id: p.id,
    title: p.title,
    content: p.content,
    excerpt: stripHTML(p.content),
    topic: p.topic,
    authorId: authorObj.id || p.author_id || p.authorId,
    author: p.isAuthor ? ("Bạn" + (p.isAnonymous || p.anonymous ? " (Ẩn danh)" : "")) : (authorObj.displayName || p.author),
    authorRole: authorObj.role || p.authorRole,
    streakTier: Number(authorObj.streakTier || p.streakTier || 0),
    initials: authorObj.initials || p.initials,
    time: formatTime(p.createdAt),
    createdAt: p.createdAt,
    editedAt: p.editedAt,
    isAuthor: p.isAuthor,
    upvotes: p.helpfulCount || p.upvotes || 0,
    responses: p.responseCount || p.responses || 0,
    anonymous: p.isAnonymous || p.anonymous,
    chosen: Boolean(p.selectedResponseId || p.chosen),
    isPinned: Boolean(p.isPinned),
    lecturerRecommended: Boolean(p.lecturerRecommended),
    readCount: Number(p.readCount || 0),
    documentId: p.documentId || p.document_id || (p.linkedDocument?.id) || null,
    documentIds: Array.isArray(p.documentIds) ? p.documentIds : (p.documentId ? [p.documentId] : []),
    linkedDocument: p.linkedDocument || p.document || (Array.isArray(p.linkedDocuments) ? p.linkedDocuments[0] : null) || null,
    linkedDocuments: Array.isArray(p.linkedDocuments) ? p.linkedDocuments : (p.linkedDocument ? [p.linkedDocument] : []),
    status: p.status || "visible",
  };
}
window.getRoleDisplay = function (role) {
  if (role === "admin") return "Admin";
  if (role === "lecturer") return "Giảng viên";
  if (role === "ta") return "TA";
  if (role === "member") return "Thành viên";
  if (role === "student") return "Sinh viên";
  return "Khách";
};

function isStudentProfileCompleted(u) {
  if (!u) return false;
  return Boolean(
    (u.studentId || "").trim() &&
    (u.realName || "").trim() &&
    (u.className || "").trim()
  );
}
window.isStudentProfileCompleted = isStudentProfileCompleted;

function applySession(user) {
  session = user || null;
  if (user) {
    setCachedUser(user);
  } else {
    setCachedUser(null);
    setCachedContribs(null);
  }
  const roleDisplay = getRoleDisplay(user?.role);
  const streakTier = Number(user?.streakTier || 0);

  // Apply theme shift
  if (streakTier >= 5) {
    document.documentElement.dataset.userTheme = "mythic";
  } else if (streakTier >= 4) {
    document.documentElement.dataset.userTheme = "ruby";
  } else {
    delete document.documentElement.dataset.userTheme;
  }

  $$(".profile-chip-text").forEach(
    (el) =>
    (el.innerHTML = user
      ? `<span class="${getNameClass(streakTier)}">${escapeHTML(user.displayName)}</span> <b>${roleDisplay}</b>`
      : "Đăng nhập"),
  );
  if (typeof window.syncAdaptiveGlassHeaderMetrics === "function") {
    window.syncAdaptiveGlassHeaderMetrics();
  }

  const accountName = $(".account-header h1");
  if (accountName) {
    accountName.textContent = user ? user.displayName : "Khách";
    accountName.className = getNameClass(streakTier);
  }

  const roleLabel = $(".role-label");
  if (roleLabel)
    roleLabel.textContent = user
      ? roleDisplay
      : "Khách";

  // Cảnh báo tài khoản không hoạt động 60 ngày
  if (user?.inactivityWarning?.isWarning) {
    setTimeout(() => {
      if (typeof showInactivityWarningModal === "function") {
        showInactivityWarningModal(user.inactivityWarning);
      }
    }, 450);
  }

  const headerAvatar = $("#headerAvatar");
  if (headerAvatar) {
    headerAvatar.textContent = user ? user.initials || "🦊" : "🦊";
    headerAvatar.className = "avatar avatar-lg " + getAvatarClass(streakTier, false, user?.role);
  }

  const navAvatar = $("#navAvatar");
  if (navAvatar) {
    navAvatar.textContent = user ? user.initials || "🦊" : "🦊";
    navAvatar.className = "avatar avatar-sm " + getAvatarClass(streakTier, false, user?.role);
  }

  const changeBtn = $("#changeAvatarBtn");
  if (changeBtn) {
    if (user) {
      changeBtn.style.display = "inline-flex";
      if (user.canChangeAvatar === false) {
        changeBtn.disabled = true;
        changeBtn.innerHTML = `${user.avatarRemainingDays || 7}d`;
        changeBtn.title = `Bạn chỉ có thể đổi lại avatar sau ${user.avatarRemainingDays || 7} ngày`;
      } else {
        changeBtn.disabled = false;
        changeBtn.innerHTML = `<svg class="change-avatar-icon" width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3a2.828 2.828 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5L17 3z"></path></svg><span class="change-avatar-text">Đổi</span>`;
        changeBtn.title = "Đổi icon avatar (1 lần mỗi 7 ngày)";
      }
    } else {
      changeBtn.style.display = "none";
    }
  }

  const isAuth = Boolean(user);
  const setAuthBtn = (id, show, displayStyle = "") => {
    const el = $(id);
    if (!el) return;
    el.style.display = show ? displayStyle : "none";
    if (show) {
      el.removeAttribute("hidden");
      el.classList.remove("is-hidden");
    } else {
      el.setAttribute("hidden", "true");
      el.classList.add("is-hidden");
    }
  };

  setAuthBtn("#viewMyNamecardBtn", isAuth);
  setAuthBtn("#editNamecardBtn", isAuth);
  setAuthBtn("#editProfile", isAuth);
  setAuthBtn("#openChangePasswordBtn", isAuth);
  setAuthBtn("#logoutButton", isAuth);
  setAuthBtn("#accountLoginBtn", !isAuth);
  setAuthBtn("#accountGrid", isAuth);
  setAuthBtn("#accountStudentPromptCard", isAuth && !isStudentProfileCompleted(user), "block");
  setAuthBtn("#accountSecurityCard", false);
  if ($("#adminPanel")) $("#adminPanel").style.display = (isAuth && (user.role === "admin" || user.role === "ta")) ? "" : "none";
  if (typeof updateQuickMenuUser === "function") updateQuickMenuUser(user);

  const badgeDesk = $("#studyNavBadgeDesktop");
  const badgeMob = $("#studyNavBadgeMobile");
  if (badgeDesk) badgeDesk.style.display = "none";
  if (badgeMob) badgeMob.style.display = "none";

  const notice = $("#studyLockedNotice");
  const mainStudy = $("#studyMainContent");
  if (notice) notice.style.display = "none";
  if (mainStudy) mainStudy.style.display = "block";

  const arenaNotice = $("#arenaLockedNotice");
  const arenaMain = $("#arenaMainContent");
  if (canAccessArena(user)) {
    if (arenaNotice) arenaNotice.style.display = "none";
    if (arenaMain) arenaMain.style.display = "block";
    const adminBar = $("#arenaAdminBar");
    if (adminBar) adminBar.style.display = (user && user.role === "admin") ? "flex" : "none";
  } else {
    if (arenaNotice) arenaNotice.style.display = "block";
    if (arenaMain) arenaMain.style.display = "none";
  }

  // --- Giới hạn tính năng cho email không phải VLU ---
  const isVLU = isVLUEmail(user);

  // Tab "Top đóng góp": mọi người dùng (kể cả Thành viên và Khách) đều có thể xem bảng xếp hạng
  const tabContrib = $("#tabTopContrib");
  if (tabContrib) {
    tabContrib.style.display = "";
  }
  const dotContrib = document.querySelector(".lb-dot[data-tab='contributions']");
  if (dotContrib) {
    dotContrib.style.display = "";
  }

  // Nút "Đề xuất tài liệu": ẩn nếu không phải VLU
  const shareDocBtn = $("#shareDocument");
  if (shareDocBtn) {
    shareDocBtn.style.display = isVLU ? "" : "none";
  }

  if (typeof updateStudyStreakPerks === "function") {
    updateStudyStreakPerks();
  }
  if (typeof fetchStudyLounge === "function") {
    fetchStudyLounge();
  }
  if (currentActiveRoute === "arena") {
    onEnterArena();
  }

  if (user) {
    if (typeof initWebActivityTracker === "function") initWebActivityTracker();
    if (pendingJoinMeetingId) {
      const rId = pendingJoinMeetingId;
      pendingJoinMeetingId = null;
      if (typeof go === "function") go("study", false);
      setTimeout(() => {
        if (typeof joinStudySpace === "function") joinStudySpace(rId);
      }, 350);
    }
  } else {
    if (typeof stopWebActivityTracker === "function") stopWebActivityTracker();
  }
  if (typeof renderChristmasTreeStudioUI === "function") {
    renderChristmasTreeStudioUI(false);
  }
}

let currentLeaderboardTab = "contributions";
let cachedLeaderboardData = { leaderboard: [], streakLeaderboard: [], arenaLeaderboard: [], likesLeaderboard: [], studyLeaderboard: [], currentUser: null };

function formatLeaderboardRank(rank) {
  if (!rank || rank <= 0) return "--";
  if (rank <= 9) return String(rank);
  if (rank <= 19) return "10+";
  if (rank <= 29) return "20+";
  if (rank <= 39) return "30+";
  if (rank <= 49) return "40+";
  return "50+";
}

const LEADERBOARD_TABS = [
  { id: "contributions", title: "Đại sứ tri thức" },
  { id: "streak", title: "Người giữ lửa" },
  { id: "competition", title: "Tinh thông thần tốc" },
  { id: "likes", title: "Vạn người mê" },
  { id: "study", title: "Ong chăm chỉ" }
];

window.cycleLeaderboardTab = function (direction = 1) {
  const availableTabs = LEADERBOARD_TABS;
  const currentIdx = availableTabs.findIndex(t => t.id === currentLeaderboardTab);
  let nextIdx = (currentIdx === -1 ? 0 : currentIdx + direction);
  if (nextIdx >= availableTabs.length) nextIdx = 0;
  if (nextIdx < 0) nextIdx = availableTabs.length - 1;
  window.switchLeaderboardTab(availableTabs[nextIdx].id);
};

window.switchLeaderboardTab = function (tab) {
  currentLeaderboardTab = tab;

  // Cập nhật tiêu đề carousel và dots
  const tabObj = LEADERBOARD_TABS.find(t => t.id === tab);
  const titleEl = $("#lbActiveTitle");
  if (titleEl && tabObj) {
    titleEl.textContent = tabObj.title;
  }
  document.querySelectorAll(".lb-dot").forEach(dot => {
    dot.classList.toggle("active", dot.getAttribute("data-tab") === tab);
  });

  // Hỗ trợ backwards compatibility nếu các nút cũ còn tồn tại
  $("#tabTopContrib")?.classList.toggle("active", tab === "contributions");
  $("#tabTopStreak")?.classList.toggle("active", tab === "streak");
  $("#tabTopArena")?.classList.toggle("active", tab === "competition");
  $("#tabTopLikes")?.classList.toggle("active", tab === "likes");
  $("#tabTopStudy")?.classList.toggle("active", tab === "study");

  renderLeaderboard();
};

function renderLeaderboard() {
  const lbEl = $("#leaderboardList");
  if (!lbEl) return;

  // Đảm bảo tiêu đề và dots đồng bộ với currentLeaderboardTab
  const tabObj = LEADERBOARD_TABS.find(t => t.id === currentLeaderboardTab);
  const titleEl = $("#lbActiveTitle");
  if (titleEl && tabObj) {
    titleEl.textContent = tabObj.title;
  }
  document.querySelectorAll(".lb-dot").forEach(dot => {
    dot.classList.toggle("active", dot.getAttribute("data-tab") === currentLeaderboardTab);
  });

  const isContrib = currentLeaderboardTab === "contributions";
  const isStreak = currentLeaderboardTab === "streak";
  const isArena = currentLeaderboardTab === "competition";
  const isLikes = currentLeaderboardTab === "likes";
  const isStudy = currentLeaderboardTab === "study";

  let list = [];
  let userRankInfo = null;

  if (isContrib) {
    list = cachedLeaderboardData.leaderboard || [];
    if (cachedLeaderboardData.currentUser && cachedLeaderboardData.currentUser.contributions?.isParticipant) {
      userRankInfo = {
        ...cachedLeaderboardData.currentUser,
        rank: cachedLeaderboardData.currentUser.contributions?.rank,
        valDisplay: `${cachedLeaderboardData.currentUser.contributions?.totalPoints || 0}đ`
      };
    }
  } else if (isStreak) {
    list = cachedLeaderboardData.streakLeaderboard || [];
    if (cachedLeaderboardData.currentUser && cachedLeaderboardData.currentUser.streak?.isParticipant) {
      userRankInfo = {
        ...cachedLeaderboardData.currentUser,
        rank: cachedLeaderboardData.currentUser.streak?.rank,
        streak: cachedLeaderboardData.currentUser.streak?.streak || 0,
        streakTier: cachedLeaderboardData.currentUser.streak?.streakTier || 0,
        valDisplay: `<span style="display:inline-flex;align-items:center;gap:3px;">${getFlameSVG(cachedLeaderboardData.currentUser.streak?.streakTier || 0, 14)} ${cachedLeaderboardData.currentUser.streak?.streak || 0}n</span>`
      };
    }
  } else if (isArena) {
    list = cachedLeaderboardData.arenaLeaderboard || [];
    if (cachedLeaderboardData.currentUser && cachedLeaderboardData.currentUser.arena?.isParticipant) {
      userRankInfo = {
        ...cachedLeaderboardData.currentUser,
        rank: cachedLeaderboardData.currentUser.arena?.rank,
        valDisplay: `⭐ ${cachedLeaderboardData.currentUser.arena?.score || 0}`
      };
    }
  } else if (isLikes) {
    list = cachedLeaderboardData.likesLeaderboard || [];
    if (cachedLeaderboardData.currentUser && cachedLeaderboardData.currentUser.likes?.isParticipant) {
      const myLikes = cachedLeaderboardData.currentUser.likes;
      userRankInfo = {
        ...cachedLeaderboardData.currentUser,
        rank: myLikes.rank,
        valDisplay: `<span style="display:inline-flex;align-items:center;gap:3px;color:#e11d48;font-weight:700;"><svg width="12" height="12" viewBox="0 0 24 24" fill="#e11d48"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg> ${myLikes.count || 0}</span>`
      };
    }
  } else if (isStudy) {
    list = cachedLeaderboardData.studyLeaderboard || [];
    if (cachedLeaderboardData.currentUser && cachedLeaderboardData.currentUser.study?.isParticipant) {
      const myStudy = cachedLeaderboardData.currentUser.study;
      userRankInfo = {
        ...cachedLeaderboardData.currentUser,
        rank: myStudy.rank,
        valDisplay: `${myStudy.hours ?? Math.floor((myStudy.totalMinutes || 0) / 60)}h`
      };
    }
  }

  if (!cachedLeaderboardData.leaderboard?.length && !cachedLeaderboardData.arenaLeaderboard?.length && !cachedLeaderboardData.streakLeaderboard?.length && !cachedLeaderboardData.likesLeaderboard?.length && !cachedLeaderboardData.studyLeaderboard?.length) {
    requestAPI("/api/leaderboard").then(data => {
      if (data && (data.leaderboard || data.streakLeaderboard || data.arenaLeaderboard || data.likesLeaderboard || data.studyLeaderboard)) {
        cachedLeaderboardData = data;
        renderLeaderboard();
        updateResponsiveAsidePlacement();
      }
    }).catch(() => { });
  }

  if (!list || list.length === 0) {
    let emptyMsg = "Chưa có dữ liệu đóng góp.";
    if (isStreak) emptyMsg = "Chưa có dữ liệu chuỗi.";
    if (isArena) emptyMsg = "Chưa có dữ liệu thi đua từ các tuần đã chốt.";
    if (isLikes) emptyMsg = "Chưa có dữ liệu lượt yêu thích thẻ tên.";
    if (isStudy) emptyMsg = "Chưa có dữ liệu thời gian tự học.";
    lbEl.innerHTML = `<p style="color: var(--muted); font-size: 13px; text-align: center; padding: 12px 0;">${emptyMsg}</p>`;
    return;
  }

  const currentUserId = cachedLeaderboardData.currentUser?.id;
  const isUserInTop5 = Boolean(currentUserId && list.slice(0, 5).some(u => u.id === currentUserId));

  let html = list
    .slice(0, 5)
    .map((user, idx) => {
      const isMe = Boolean(currentUserId && user.id === currentUserId);
      const pointsDisplay = isContrib
        ? `${user.totalPoints}đ`
        : (isStreak
          ? `<span style="display:inline-flex;align-items:center;gap:3px;">${getFlameSVG(user.streakTier || 0, 14)} ${user.streak}n</span>`
          : (isArena
            ? `⭐ ${user.score || 0}`
            : (isLikes
              ? `<span style="display:inline-flex;align-items:center;gap:4px;color:#e11d48;font-weight:700;"><svg width="13" height="13" viewBox="0 0 24 24" fill="#e11d48"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg> ${user.likesCount || 0}</span>`
              : `${user.hours ?? Math.floor((user.totalMinutes || 0) / 60)}h`)));

      const coverStyle = getMiniCoverStyle(user.coverImage);

      return `
        <div class="leaderboard-item ${isMe ? "is-me" : ""}" data-namecard-user-id="${user.id}" style="cursor: pointer;">
          <div class="lb-capsule">
            <div class="lb-cover-art-wrap">
              <div class="lb-cover-art" style="${coverStyle}"></div>
              <div class="lb-cover-overlay"></div>
            </div>
            <div class="lb-avatar-wrap">
              <span class="avatar avatar-sm ${getAvatarClass(user.streakTier, false, user.role)}">${user.initials || '?'}</span>
              <span class="lb-rank-badge rank-${idx + 1}">${idx + 1}</span>
            </div>
            <div class="lb-info">
              <span class="lb-name ${getNameClass(user.streakTier)}">${escapeHTML(user.displayName)}</span>
              ${user.role && user.role !== 'student' ? `<span class="lb-role lb-role-${user.role}">${getRoleDisplay(user.role)}</span>` : ""}
            </div>
          </div>
          <div class="lb-points ${isLikes ? "lb-points-likes" : (isStudy ? "lb-points-study" : "")}">${pointsDisplay}</div>
        </div>
      `;
    })
    .join("");

  if (!isUserInTop5 && userRankInfo && (userRankInfo.rank || isLikes || isStudy)) {
    const userCoverStyle = getMiniCoverStyle(userRankInfo.coverImage);
    const userRankDisplay = formatLeaderboardRank(userRankInfo.rank);

    html += `
      <div class="leaderboard-item is-me lb-my-rank-row" data-namecard-user-id="${userRankInfo.id}" style="cursor: pointer;">
        <div class="lb-capsule">
          <div class="lb-cover-art-wrap">
            <div class="lb-cover-art" style="${userCoverStyle}"></div>
            <div class="lb-cover-overlay"></div>
          </div>
          <div class="lb-avatar-wrap">
            <span class="avatar avatar-sm ${getAvatarClass(userRankInfo.streakTier, false, userRankInfo.role)}">${userRankInfo.initials || '?'}</span>
            <span class="lb-rank-badge rank-me">${userRankDisplay}</span>
          </div>
          <div class="lb-info">
            <span class="lb-name ${getNameClass(userRankInfo.streakTier)}">${escapeHTML(userRankInfo.displayName)}</span>
            ${userRankInfo.role && userRankInfo.role !== 'student' ? `<span class="lb-role lb-role-${userRankInfo.role}">${getRoleDisplay(userRankInfo.role)}</span>` : ""}
          </div>
        </div>
        <div class="lb-points ${isLikes ? "lb-points-likes" : (isStudy ? "lb-points-study" : "")}">${userRankInfo.valDisplay}</div>
      </div>
    `;
  }

  // Chú thích chế độ xem cho Thành viên hoặc Khách khi xem bảng đóng góp hoặc Arena
  if ((isContrib || isArena) && session?.role === "member") {
    html += `
      <div class="lb-spectator-note" style="margin-top: 10px; padding: 7px 10px; background: rgba(59, 130, 246, 0.08); border: 1px solid rgba(59, 130, 246, 0.18); border-radius: 8px; font-size: 11.5px; color: var(--muted); text-align: center; line-height: 1.4;">
        ℹ️ Bảng xếp hạng dành cho sinh viên Văn Lang. Bạn đang ở chế độ xem (Thành viên không tham gia bảng này).
      </div>
    `;
  } else if ((isContrib || isArena) && !session) {
    html += `
      <div class="lb-spectator-note" style="margin-top: 10px; padding: 7px 10px; background: rgba(148, 163, 184, 0.08); border: 1px solid rgba(148, 163, 184, 0.18); border-radius: 8px; font-size: 11.5px; color: var(--muted); text-align: center; line-height: 1.4;">
        ℹ️ Bảng xếp hạng dành cho sinh viên Văn Lang. Khách đang ở chế độ theo dõi.
      </div>
    `;
  }

  lbEl.innerHTML = html;
}

window.showInactivityWarningModal = function (warningInfo) {
  const modal = $("#inactivityWarningModal");
  if (!modal) return;
  const countdownText = $("#inactivityCountdownText");
  if (countdownText && warningInfo) {
    countdownText.innerHTML = `Thời gian còn lại: <strong>${warningInfo.daysRemaining} ngày</strong> (không hoạt động trong ${warningInfo.inactiveDays} ngày) trước khi bị xoá hoàn toàn`;
  }
  if (typeof modal.showModal === "function") {
    if (!modal.open) modal.showModal();
  } else {
    modal.style.display = "block";
  }
};

window.closeInactivityWarningModal = function () {
  const modal = $("#inactivityWarningModal");
  if (!modal) return;
  if (typeof modal.close === "function") {
    if (modal.open) modal.close();
  } else {
    modal.style.display = "none";
  }
};

window.confirmMaintainAccount = async function () {
  const btn = $("#confirmMaintainAccountBtn");
  if (btn) {
    btn.disabled = true;
    btn.textContent = "Đang xử lý...";
  }
  try {
    const res = await requestAPI("/api/auth/confirm-maintain-account", {
      method: "POST"
    });
    if (res && res.ok) {
      if (session) {
        session.inactivityWarning = null;
        if (res.user) {
          applySession(res.user);
        }
      }
      closeInactivityWarningModal();
      toast("✅ Đã xác nhận duy trì tài khoản thành công! Chu kỳ 60 ngày tiếp theo đã được bắt đầu.");
    } else {
      toast("⚠️ " + (res?.error || "Không thể xác nhận lúc này, vui lòng thử lại sau."));
    }
  } catch (err) {
    toast("⚠️ " + (err.message || "Lỗi kết nối khi xác nhận duy trì tài khoản."));
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = `<svg class="ui-btn-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg> Xác nhận duy trì tài khoản`;
    }
  }
};

function renderProfileStats(profileData) {
  if (!profileData) return;
  const streak = Number(profileData.streak || 0);
  const streakTier = Number(profileData.streakTier || getStreakTier(streak));
  window.currentStreakCount = streak;
  window.currentStreakTier = streakTier;

  const contribCard = $("#homeContributionCard");
  if (contribCard) {
    contribCard.setAttribute("data-streak-tier", streakTier);
  }

  const flameHero = $("#streakFlameHero");
  if (flameHero) {
    flameHero.innerHTML = getFlameSVG(streakTier, 46);
  }

  if ($("#activityStreak"))
    $("#activityStreak").innerHTML = `${streak} <span>ngày</span>`;

  const tierLabel = $("#streakTierLabel");
  if (tierLabel) {
    tierLabel.textContent = getStreakTitle(streak, streakTier);
  }

  const shieldsCount = $("#streakShieldsCount");
  if (shieldsCount) {
    shieldsCount.textContent = profileData.shields || 0;
  }
  const journeyShieldsCount = $("#journeyShieldsCount");
  if (journeyShieldsCount) {
    journeyShieldsCount.textContent = profileData.shields || 0;
  }

  const shieldNotice = $("#streakShieldNotice");
  if (shieldNotice) {
    shieldNotice.style.display = profileData.autoShieldUsed ? "block" : "none";
  }

  if ($("#profilePoints"))
    $("#profilePoints").textContent = profileData.total || 0;
  if ($("#profileStreak"))
    $("#profileStreak").innerHTML = `${streak} <em>ngày</em>`;
  if ($("#profileCount"))
    $("#profileCount").textContent = profileData.count || 0;

  if ($("#restoreStreakContainer")) {
    const container = $("#restoreStreakContainer");
    container.style.display = profileData.canRestoreStreak ? "block" : "none";
    const btn = container.querySelector("button");
    if (btn) {
      const cost = profileData.restoreShieldsCost || 1;
      btn.innerHTML = `<svg class="ui-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z"/></svg> Khôi phục chuỗi (${cost} khiên)`;
    }
  }

  if (typeof triggerMilestoneCelebration === "function") {
    triggerMilestoneCelebration(streak, streakTier);
  }

  const grid = $("#activityGrid");
  if (grid) {
    const days = ["T2", "T3", "T4", "T5", "T6", "T7", "CN"];
    const now = new Date(new Date().toLocaleString("en-US", { timeZone: "Asia/Ho_Chi_Minh" }));

    window.restoreStreak = async function () {
      const btn = document.querySelector("#restoreStreakContainer button");
      try {
        if (btn) {
          btn.disabled = true;
          btn.textContent = "Đang khôi phục...";
        }
        const res = await requestAPI("/api/auth/restore-streak", { method: "POST" });
        toast(res?.message || "Đã khôi phục chuỗi thành công! 🛡️🔥");
        await hydrateServer();
      } catch (e) {
        toast(e?.message || "Không thể khôi phục chuỗi.");
        if (btn) {
          btn.disabled = false;
          const cost = profileData?.restoreShieldsCost || 1;
          btn.innerHTML = `<svg class="ui-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z"/></svg> Khôi phục chuỗi (${cost} khiên)`;
        }
      }
    };
    const today = now.getDay();
    const vnDayIndex = today === 0 ? 6 : today - 1;

    const startOfWeek = new Date(now);
    startOfWeek.setDate(now.getDate() - vnDayIndex);

    const weekDates = [];
    for (let i = 0; i < 7; i++) {
      const d = new Date(startOfWeek);
      d.setDate(startOfWeek.getDate() + i);
      const y = d.getFullYear();
      const m = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      weekDates.push(`${y}-${m}-${day}`);
    }

    const activeSet = new Set(profileData.activityDays || []);

    grid.innerHTML = days
      .map((d, i) => {
        const dateStr = weekDates[i];
        const isActive = activeSet.has(dateStr);
        const isToday = i === vnDayIndex;

        let cls = "";
        let mark = "";

        if (isActive) {
          cls = "done";
          mark = getFlameSVG(streakTier, 14);
        } else if (isToday) {
          cls = "today";
          mark = `<span style="opacity: 0.5;">${getFlameSVG(0, 13)}</span>`;
        } else {
          mark = "○";
        }

        return `<div class="day ${cls}"><small>${d}</small><i>${mark}</i></div>`;
      })
      .join("");
  }
}

let initialStudyRouteHandled = false;

function updateCommunityStats(serverStats) {
  const elTotal = $("#statTotalPosts");
  const elRatio = $("#statAnsweredRatio");
  if (!elTotal && !elRatio) return;

  if (serverStats && typeof serverStats.totalPosts === "number") {
    if (elTotal) elTotal.textContent = serverStats.totalPosts;
    if (elRatio) elRatio.textContent = serverStats.answeredRatio + "%";
    return;
  }

  const visiblePosts = posts.filter((p) => !p.status || p.status === "visible");
  const totalPosts = visiblePosts.length;
  const answeredPosts = visiblePosts.filter((p) => (Number(p.responses) || 0) > 0).length;
  const ratio = totalPosts > 0 ? Math.round((answeredPosts / totalPosts) * 100) : 0;

  if (elTotal) elTotal.textContent = totalPosts;
  if (elRatio) elRatio.textContent = ratio + "%";
}

async function hydrateServer(force = false) {
  if (!serverMode) return;
  // Hoãn làm mới ngầm nếu người dùng đang gõ văn bản hoặc đang mở hộp thoại
  if (!force && typeof isUserBusyWithCriticalTask === "function" && isUserBusyWithCriticalTask()) {
    return;
  }
  try {
    const isHomeOrForum = !currentActiveRoute || currentActiveRoute === "home" || currentActiveRoute === "forum";
    const shouldFetchForumLb = isHomeOrForum;

    // Kích hoạt tất cả API song song ngay từ đầu để loại bỏ hoàn toàn độ trễ waterfall
    const sessionPromise = requestAPI("/api/session", { headers: {} }).catch(() => ({ authenticated: false, user: null }));
    const hasHintedSession = Boolean(
      (typeof session !== "undefined" && session) ||
      (typeof getCachedUser === "function" && getCachedUser())
    );
    const contribsPromise = hasHintedSession ? requestAPI("/api/me/contributions").catch(() => null) : null;
    const postsPromise = requestAPI("/api/posts").catch(() => ({ posts: [] }));
    const docsPromise = requestAPI("/api/documents").catch(() => ({ documents: [] }));
    const leaderboardPromise = shouldFetchForumLb ? requestAPI("/api/leaderboard").catch(() => null) : Promise.resolve(null);
    const topicsPromise = requestAPI("/api/topics").catch(() => ({ topics: [] }));

    const current = await sessionPromise;
    csrfToken = current.csrfToken;
    applySession(current.user);

    // Only navigate to requested study route ONCE on initial app boot
    const initialRouteBase = (typeof initialRequestedRoute !== "undefined" && initialRequestedRoute) ? initialRequestedRoute.split("?")[0].split("&")[0] : "";
    if (!initialStudyRouteHandled && initialRouteBase === "study") {
      initialStudyRouteHandled = true;
      if (canAccessStudyLounge(current.user)) {
        go(initialRequestedRoute, false);
      } else {
        toast(STUDY_MAINTENANCE_MSG);
      }
    }

    const [postsData, docsData, leaderboardData, topicsData] = await Promise.all([
      postsPromise,
      docsPromise,
      leaderboardPromise,
      topicsPromise,
    ]);

    if (topicsData.topics) {
      allTopics = topicsData.topics;
      topics = allTopics.filter(t => t.status === "approved").map(t => t.name);
      renderTopicsDropdown();
    }

    if (postsData.posts) {
      posts = postsData.posts.map(normalizePost);
      // Only re-render home/forum if relevant to avoid scroll/DOM disruptions
      if (!currentActiveRoute || currentActiveRoute === "home") renderHome();
      if (currentActiveRoute === "forum") renderPosts();

      updateCommunityStats(postsData.stats);
    }

    if (leaderboardData) {
      cachedLeaderboardData = leaderboardData;
      renderLeaderboard();
      updateResponsiveAsidePlacement();
    }
    if (docsData.documents) {
      documents.length = 0;
      docsData.documents.forEach((d) => {
        documents.push({
          id: d.id,
          type: d.category || d.type,
          format: d.format || "LINK",
          title: d.title,
          subtitle: d.subtitle || "",
          desc: d.desc || d.description,
          author: d.submittedBy || d.author,
          authorId: d.submittedById || d.submitted_by || null,
          authorRole: d.submittedByRole || "member",
          initials: d.submittedByAvatar || getAvatarEmoji(d.submittedBy || d.author || "TL"),
          streakTier: Number(d.submittedByStreakTier || d.streakTier || 0),
          createdAt: d.createdAt,
          date: formatTime(d.createdAt || d.date),
          url: d.url || d.sourceUrl,
          isSaved: Boolean(d.isSaved),
        });
      });
      if (!currentActiveRoute || currentActiveRoute === "documents") renderDocuments();
    }

    if (current.authenticated) {
      const user = current.user;
      const setAuthBtn = (id, show, displayStyle = "") => {
        const el = $(id);
        if (!el) return;
        el.style.display = show ? displayStyle : "none";
        if (show) {
          el.removeAttribute("hidden");
          el.classList.remove("is-hidden");
        } else {
          el.setAttribute("hidden", "true");
          el.classList.add("is-hidden");
        }
      };
      setAuthBtn("#accountGrid", true);
      setAuthBtn("#viewMyNamecardBtn", true);
      setAuthBtn("#editNamecardBtn", true);
      setAuthBtn("#editProfile", true);
      setAuthBtn("#openChangePasswordBtn", true);
      const isComplete = isStudentProfileCompleted(user);
      setAuthBtn("#accountStudentPromptCard", !isComplete, "block");
      setAuthBtn("#accountSecurityCard", false);
      setAuthBtn("#logoutButton", true);
      setAuthBtn("#accountLoginBtn", false);

      try {
        const profileData = await (contribsPromise || requestAPI("/api/me/contributions").catch(() => null));
        if (profileData) {
          setCachedContribs(profileData);
          renderProfileStats(profileData);

          const container = $("#recentContributionsContainer");
          if (container && profileData.recentContributions) {
            container.innerHTML = profileData.recentContributions.length
              ? profileData.recentContributions
                .map(renderActivityRow)
                .join("")
              : `<p class="empty-state">Chưa có hoạt động nào gần đây.</p>`;
          }
          if ($("#myPostsContainer")) {
            const myPosts = posts.filter(p => p.isAuthor);
            if (myPosts.length > 0) {
              $("#myPostsContainer").innerHTML = myPosts.map(postCard).join("");
              $$("#myPostsContainer .post-card").forEach(el =>
                el.addEventListener("click", () => openDetail(Number(el.dataset.postId)))
              );
            } else {
              $("#myPostsContainer").innerHTML = `<p class="empty-state">Bạn chưa đăng bài đăng nào.</p>`;
            }
          }
          if ($("#savedPostsContainer")) {
            try {
              const savedData = await requestAPI(`/api/users/${current.user.id}/saved-posts`).catch(() => ({ posts: [] }));
              const hasPosts = savedData && savedData.posts && savedData.posts.length > 0;

              if (!hasPosts) {
                $("#savedPostsContainer").innerHTML = `
                     <div class="activity-empty-state">
                       <div class="empty-state-icon">
                         <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/></svg>
                       </div>
                       <p class="empty-state-title">Chưa có bài thảo luận nào được lưu</p>
                       <p class="empty-state-desc">Khi đọc các bài thảo luận trên diễn đàn, nhấn <b>★ Lưu</b> để đánh dấu và xem lại thuận tiện tại đây.</p>
                       <button type="button" class="button button-outline button-sm" onclick="go('forum')">Khám phá Diễn đàn thảo luận →</button>
                     </div>`;
              } else {
                const normalizedSaved = savedData.posts.map(normalizePost);
                $("#savedPostsContainer").innerHTML = normalizedSaved.map(postCard).join("");
                $$("#savedPostsContainer .post-card").forEach(el =>
                  el.addEventListener("click", () => openDetail(Number(el.dataset.postId)))
                );
              }
            } catch (e) {
              console.error(e);
            }
          }
          if ($("#savedDocsContainer")) {
            try {
              const savedDocsData = await requestAPI(`/api/users/${current.user.id}/saved-documents`).catch(() => ({ documents: [] }));
              const hasDocs = savedDocsData && savedDocsData.documents && savedDocsData.documents.length > 0;

              if (!hasDocs) {
                $("#savedDocsContainer").innerHTML = `
                     <div class="activity-empty-state">
                       <div class="empty-state-icon">
                         <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>
                       </div>
                       <p class="empty-state-title">Chưa có tài liệu nào được lưu</p>
                       <p class="empty-state-desc">Bạn có thể lưu các tài liệu quan trọng trong kho tài liệu để truy cập nhanh chóng bất cứ lúc nào.</p>
                       <button type="button" class="button button-outline button-sm" onclick="go('documents')">Khám phá Kho tài liệu →</button>
                     </div>`;
              } else {
                $("#savedDocsContainer").innerHTML = `
                     <div class="document-grid" style="display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 14px;">
                       ${savedDocsData.documents.map(d => `
                         <article class="document-card" data-doc="${d.id}" style="cursor: pointer; position: relative;">
                           <div class="document-header-badges">
                             <div class="document-type" data-format="${d.format}">${d.format}</div>
                             <span class="document-id-badge" title="Mã tài liệu: #TL-${d.id}">#TL-${d.id}</span>
                           </div>
                           <p class="eyebrow">${d.category === "course" ? "TÀI LIỆU MÔN HỌC" : "TÀI LIỆU THAM KHẢO"}</p>
                           <h2>${escapeHTML(d.title)}</h2>
                           ${d.subtitle ? `<div class="document-subtitle"><span class="doc-sub-icon">📖</span> ${escapeHTML(d.subtitle)}</div>` : ''}
                           <div class="document-desc ql-editor">${DOMPurify.sanitize(d.description)}</div>
                           <div class="document-footer">
                             <div class="document-footer-author">
                               <span>${escapeHTML(d.submittedBy)}</span>
                             </div>
                             <div class="document-footer-actions">
                               <button type="button" class="doc-card-action-btn" onclick="event.stopPropagation(); copyDocumentLink(${d.id})" title="Sao chép link">📋 Chia sẻ</button>
                               <button type="button" class="doc-card-action-btn is-saved" onclick="event.stopPropagation(); toggleSaveDocument(${d.id})" title="Bỏ lưu">★ Đã lưu</button>
                             </div>
                           </div>
                         </article>
                       `).join("")}
                     </div>`;
                $$("#savedDocsContainer .document-card").forEach(el =>
                  el.addEventListener("click", () => viewDocumentById(Number(el.dataset.doc)))
                );
              }
            } catch (e) {
              console.error(e);
            }
          }
        }
      } catch (e) {
        if (e.message && e.message.includes("bị khóa")) {
          toast(e.message);
        }
      }
      if (current.user?.role === "admin" || current.user?.role === "ta") {
        if ($("#adminPanel")) $("#adminPanel").style.display = "";
        try {
          const adminData = await requestAPI("/api/admin/overview");
          if (adminData) {
            if ($("#adminTotalUsers"))
              $("#adminTotalUsers").textContent = adminData.members || 0;
            if ($("#adminPendingDocs"))
              $("#adminPendingDocs").textContent =
                adminData.pendingDocuments || 0;
          }
        } catch (e) { }
      } else {
        if ($("#adminPanel")) $("#adminPanel").style.display = "none";
      }
    } else {
      setCachedUser(null);
      setCachedContribs(null);
      const setAuthBtn = (id, show, displayStyle = "") => {
        const el = $(id);
        if (!el) return;
        el.style.display = show ? displayStyle : "none";
        if (show) {
          el.removeAttribute("hidden");
          el.classList.remove("is-hidden");
        } else {
          el.setAttribute("hidden", "true");
          el.classList.add("is-hidden");
        }
      };
      setAuthBtn("#accountGrid", false);
      setAuthBtn("#viewMyNamecardBtn", false);
      setAuthBtn("#editNamecardBtn", false);
      setAuthBtn("#editProfile", false);
      setAuthBtn("#openChangePasswordBtn", false);
      setAuthBtn("#accountStudentPromptCard", false);
      setAuthBtn("#accountSecurityCard", false);
      setAuthBtn("#logoutButton", false);
      setAuthBtn("#accountLoginBtn", true);
      if ($("#adminPanel")) $("#adminPanel").style.display = "none";
    }

    // Tải trạng thái module thi đua tuần & đánh giá website
    loadWeeklyCompetitionStatus();
    loadSiteReviews();
  } catch {
    toast("Không thể tải dữ liệu máy chủ.");
  }
}
function openAuth() {
  const modal = $("#authModal");
  modal.classList.remove("registering");
  $$(".auth-tab").forEach((tab, i) => tab.classList.toggle("active", i === 0));
  $("#authTitle").textContent = "Đăng nhập để tiếp tục";
  $("#authSubmit").innerHTML = "Đăng nhập <span>→</span>";
  $("#authName").required = false;
  $("#authForm").reset();
  modal.showModal();
  $("#authEmail").focus();
}

function stripHtml(html) {
  if (!html) return "";
  let text = String(html);
  for (let i = 0; i < 2; i++) {
    text = text.replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&amp;/g, "&");
  }
  text = text.replace(/<\/(p|div|h[1-6]|li|blockquote|tr)>/gi, " ");
  text = text.replace(/<(br|hr)\s*\/?>/gi, " ");
  text = text.replace(/<[^>]*>/g, "");
  text = text.replace(/&nbsp;/g, " ");
  return text.replace(/\s+/g, " ").trim();
}

