window.openNamecard = async function (userId) {
  if (!userId) return;
  if (typeof closeNamecardLikesPopover === "function") {
    closeNamecardLikesPopover();
  }
  try {
    const data = await requestAPI(`/api/users/${userId}/namecard`);
    if (!data || !data.user) return;
    currentViewingNamecardUserId = userId;
    if (data.user.isSelf && session) {
      if (data.user.limitedItems) {
        session.limitedItems = data.user.limitedItems;
      }
    }

    // Reset scroll & action buttons visibility
    const cardEl = $("#namecardCard");
    if (cardEl) cardEl.scrollTop = 0;
    const closeBtnEl = $("#namecardCloseBtn");
    if (closeBtnEl) closeBtnEl.classList.remove("nc-hidden");
    const coverActionsEl = $(".namecard-cover-actions");
    if (coverActionsEl) coverActionsEl.classList.remove("nc-hidden");

    const streakTier = Number(data.streakCard?.streakTier || 0);

    // Header Identity
    $("#namecardAvatar").textContent = data.user.avatar || "🌱";
    const avatarCircle = $("#namecardAvatarCircle");
    if (avatarCircle) {
      avatarCircle.className = "namecard-avatar-circle avatar " + getAvatarClass(streakTier, false, data.user.role);
    }
    const nameEl = $("#namecardDisplayName");
    if (nameEl) {
      nameEl.textContent = data.user.displayName || "Người dùng";
      nameEl.className = "namecard-display-name " + getNameClass(streakTier);
    }

    // Namecard Like / Heart Widget
    const likeBtn = $("#namecardLikeBtn");
    const likeCountEl = $("#namecardLikeCount");
    const isSelf = Boolean(data.user.isSelf);
    const hasLiked = Boolean(data.user.hasLiked);

    if (likeBtn) {
      likeBtn.setAttribute("data-streak-tier", streakTier);
      likeBtn.classList.toggle("has-liked", hasLiked);
      likeBtn.classList.toggle("is-self", isSelf);
      if (likeCountEl) likeCountEl.textContent = data.user.likesCount || 0;

      if (isSelf) {
        likeBtn.title = "Bấm để xem danh sách người đã yêu thích thẻ tên của bạn";
        likeBtn.onclick = (e) => {
          e.stopPropagation();
          toggleNamecardLikesPopover(data.user.id);
        };
      } else {
        if (hasLiked) {
          likeBtn.title = "Bạn đã yêu thích thẻ tên này";
          likeBtn.onclick = (e) => {
            e.stopPropagation();
            toast("Bạn đã yêu thích thẻ tên này rồi.");
          };
        } else {
          likeBtn.title = "Bấm để yêu thích thẻ tên";
          likeBtn.onclick = async (e) => {
            e.stopPropagation();
            if (!session) {
              toast("Vui lòng đăng nhập để yêu thích thẻ tên.");
              return;
            }
            likeBtn.disabled = true;
            try {
              const res = await requestAPI(`/api/users/${data.user.id}/like-namecard`, { method: "POST" });
              if (res && res.ok) {
                likeBtn.classList.add("has-liked");
                likeBtn.classList.add("animate-pop");
                setTimeout(() => likeBtn.classList.remove("animate-pop"), 400);
                if (likeCountEl) likeCountEl.textContent = res.likesCount;
                likeBtn.title = "Bạn đã yêu thích thẻ tên này";
                likeBtn.onclick = (ev) => {
                  ev.stopPropagation();
                  toast("Bạn đã yêu thích thẻ tên này rồi.");
                };
                data.user.hasLiked = true;
                data.user.likesCount = res.likesCount;
                toast("Đã yêu thích thẻ tên!");
                requestAPI("/api/leaderboard").then(lb => {
                  if (lb) {
                    cachedLeaderboardData = lb;
                    renderLeaderboard();
                  }
                }).catch(() => { });
              }
            } catch (err) {
              toast(err.message || "Không thể gửi yêu thích.");
            } finally {
              likeBtn.disabled = false;
            }
          };
        }
      }
    }

    // Role Badge
    const roleText = $("#namecardRoleText");
    const roleBadge = $("#namecardRoleBadge");
    const isAnonymizedUser = Boolean(data.user.displayName === "Vô danh" || data.user.avatar === "🥷");
    if (isAnonymizedUser) {
      if (roleText) roleText.textContent = "Vô danh";
      if (roleBadge) {
        roleBadge.style.background = "var(--sage-2)";
        roleBadge.style.color = "var(--muted)";
        roleBadge.style.borderColor = "var(--line)";
      }
    } else if (data.user.role === "admin" || data.user.role === "ta") {
      if (roleText) roleText.textContent = "Quản trị viên";
      if (roleBadge) {
        roleBadge.style.background = "#fef3c7";
        roleBadge.style.color = "#92400e";
        roleBadge.style.borderColor = "#fde68a";
      }
    } else if (data.user.role === "lecturer") {
      if (roleText) roleText.textContent = "Giảng viên";
      if (roleBadge) {
        roleBadge.style.background = "#e0f2fe";
        roleBadge.style.color = "#0369a1";
        roleBadge.style.borderColor = "#bae6fd";
      }
    } else {
      if (roleText) roleText.textContent = "Sinh viên";
      if (roleBadge) {
        roleBadge.style.background = "#e8f5e9";
        roleBadge.style.color = "#1b5e20";
        roleBadge.style.borderColor = "#c8e6c9";
      }
    }

    // User ID
    $("#namecardIdText").textContent = `ID ${data.user.userCode || String(data.user.id).padStart(5, '0')}`;
    $("#namecardBio").textContent = isAnonymizedUser ? "" : (data.user.bio || "Hỏi, trao đổi, cùng tiến bộ 🌱\nTìm hiểu sâu hơn, mỗi ngày một chút.");

    // Cover Image
    const coverEl = $("#namecardCover");
    const coverVal = data.user.coverImage || "default";
    currentViewingCoverVal = coverVal;
    if (coverEl) coverEl.dataset.coverVal = coverVal;
    if (coverVal.startsWith("data:image/") || coverVal.startsWith("http")) {
      coverEl.style.background = `url("${coverVal}") center / cover no-repeat`;
    } else if (coverVal.startsWith("color:")) {
      coverEl.style.background = coverVal.replace("color:", "");
    } else {
      const foundPreset = COVER_PRESETS.find(p => p.id === coverVal);
      if (foundPreset) {
        if (foundPreset.type === "image") {
          coverEl.style.background = `url("${foundPreset.value}") center / cover no-repeat`;
        } else {
          coverEl.style.background = foundPreset.value;
        }
      } else {
        coverEl.style.background = "linear-gradient(135deg, #1e3a8a 0%, #3b82f6 50%, #93c5fd 100%)";
      }
    }

    // Edit buttons for self
    if ($("#namecardEditCoverBtn")) $("#namecardEditCoverBtn").style.display = isSelf ? "inline-flex" : "none";
    if ($("#namecardEditNameBtn")) $("#namecardEditNameBtn").style.display = isSelf ? "inline-flex" : "none";

    // Frame is a visual overlay; it must never affect the card's measured layout.
    const activeFrame = FRAME_OPTIONS.some(frame => frame.id === data.user.namecardFrame && frame.id !== "default")
      ? data.user.namecardFrame
      : "none";
    $("#namecardCard").setAttribute("data-frame", activeFrame);
    $("#namecardFrameLayer")?.setAttribute("data-frame", activeFrame);

    // 1. Diễn đàn
    $("#ncStatContrib").textContent = data.forum.contributionPoints;
    $("#ncStatPosts").textContent = data.forum.postsAndResponsesCount;
    $("#ncStatMaxStreak").textContent = `${data.forum.maxStreak} ngày`;
    $("#ncStatCurStreak").textContent = `${data.forum.currentStreak} ngày`;
    $("#ncStatActiveDays").textContent = `${data.forum.activeDaysCount} ngày`;

    // 2. Thành tích tự học
    $("#ncStatStudyDays").textContent = `${data.study.studyDaysCount} ngày`;
    const mins = data.study.totalStudyMinutes || 0;
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    $("#ncStatStudyTime").textContent = h > 0 ? (m > 0 ? `${h} giờ ${m} phút` : `${h} giờ`) : `${m} phút`;

    // 3. Thành tích thi đua
    $("#ncStatWeeks").textContent = `${data.arena.weeksParticipated} tuần`;
    $("#ncStatBestWeekScore").textContent = `${data.arena.bestWeekScore} điểm`;
    $("#ncStatLastWeekScore").textContent = `${data.arena.lastWeekScore} điểm`;
    const r = data.arena.bestRank;
    $("#ncStatBestRank").textContent = r ? (r <= 3 ? `Top ${r}` : `Hạng ${r}`) : "Chưa có";
    $("#ncStatPerfect").textContent = data.arena.perfectCount;
    const sec = data.arena.fastestSeconds;
    if (sec && sec > 0) {
      const fm = Math.floor(sec / 60);
      const fs = sec % 60;
      $("#ncStatFastest").textContent = fm > 0 ? `${fm} phút ${fs} giây` : `${fs} giây`;
    } else {
      $("#ncStatFastest").textContent = "Chưa có";
    }

    // 0. Khối thông tin hồ sơ người dùng (Nội bộ - Chỉ hiển thị cho Admin/TA)
    const identityBlock = $("#ncIdentityBlock");
    const canSeeIdentity = Boolean(data.user.isPrivilegedViewer);
    if (identityBlock) {
      if (canSeeIdentity) {
        identityBlock.style.display = "block";
        const noticeEl = $("#ncIdentityNotice");
        if (noticeEl) {
          noticeEl.textContent = "(Chỉ Quản trị viên thấy)";
        }
        if ($("#ncStatStudentId")) $("#ncStatStudentId").textContent = data.user.studentId || "Chưa cập nhật";
        if ($("#ncStatRealName")) $("#ncStatRealName").textContent = data.user.realName || "Chưa cập nhật";
        if ($("#ncStatClassName")) $("#ncStatClassName").textContent = data.user.className || "Chưa cập nhật";
        if ($("#ncStatEmail")) $("#ncStatEmail").textContent = data.user.email || "Chưa cập nhật";
      } else {
        identityBlock.style.display = "none";
      }
    }

    $("#namecardModal").showModal();
    syncNamecardModalScale();
  } catch (err) {
    toast(err.message || "Không thể tải thẻ tên.");
  }
};

