window.openEditProfileModal = function () {
  if (!session) {
    toast("Vui lòng đăng nhập để chỉnh sửa hồ sơ.");
    return;
  }
  const emailInput = $("#profileEmail");
  const emailHint = $("#profileEmailHint");
  const changeEmailBtn = $("#changeEmailActionBtn");
  if (emailInput) {
    emailInput.value = session.email || "";
    if (session.emailChanged) {
      emailInput.disabled = true;
      if (changeEmailBtn) changeEmailBtn.style.display = "none";
      if (emailHint) {
        emailHint.textContent = "Bạn đã sử dụng lượt đổi email duy nhất của tài khoản.";
        emailHint.style.color = "var(--error)";
      }
    } else {
      emailInput.disabled = false;
      if (changeEmailBtn) {
        changeEmailBtn.style.display = "inline-block";
        changeEmailBtn.disabled = false;
        changeEmailBtn.textContent = "Đổi email";
      }
      if (emailHint) {
        emailHint.textContent = "Mỗi người dùng có một lần đổi email duy nhất.";
        emailHint.style.color = "var(--muted)";
      }
    }
  }
  $("#profileStudentId").value = session.studentId || "";
  $("#profileRealName").value = session.realName || "";
  $("#profileClassName").value = session.className || "";
  $("#editProfileModal").showModal();
};

window.openEditProfileModalForArena = function () {
  if (typeof openEditProfileModal === "function") {
    openEditProfileModal();
    setTimeout(() => {
      const studentIdInput = $("#profileStudentId");
      if (studentIdInput) {
        studentIdInput.focus();
        studentIdInput.select();
      }
    }, 120);
  }
};

const changeEmailBtn = $("#changeEmailActionBtn");
if (changeEmailBtn) {
  changeEmailBtn.onclick = async () => {
    if (!session) return;
    if (session.emailChanged) {
      toast("Bạn đã sử dụng lượt đổi email duy nhất của tài khoản.");
      return;
    }
    const emailInput = $("#profileEmail");
    const newEmail = emailInput ? emailInput.value.trim().toLowerCase() : "";
    const currentEmail = (session.email || "").trim().toLowerCase();
    if (!newEmail || newEmail === currentEmail) {
      toast("Vui lòng nhập địa chỉ email mới khác email hiện tại.");
      if (emailInput) emailInput.focus();
      return;
    }
    if (!/^\S+@\S+\.\S+$/.test(newEmail)) {
      toast("Định dạng email không hợp lệ.");
      return;
    }
    const confirmed = confirm("Bạn chỉ có một lần đổi email duy nhất. Bạn có chắc chắn chứ");
    if (!confirmed) return;

    changeEmailBtn.disabled = true;
    changeEmailBtn.textContent = "Đang đổi...";
    try {
      const res = await requestAPI("/api/me/profile", {
        method: "PATCH",
        body: JSON.stringify({ email: newEmail }),
      });
      if (res.user) {
        session = { ...session, ...res.user };
      }
      toast("Đổi email thành công! Vui lòng dùng email mới để đăng nhập.");
      if (emailInput) {
        emailInput.value = session.email || newEmail;
        emailInput.disabled = true;
      }
      changeEmailBtn.style.display = "none";
      const hint = $("#profileEmailHint");
      if (hint) {
        hint.textContent = "Bạn đã sử dụng lượt đổi email duy nhất của tài khoản.";
        hint.style.color = "var(--error)";
      }
      if (typeof syncAuth === "function") syncAuth(session);
      hydrateServer();
    } catch (err) {
      toast(err.message || "Không thể đổi email.");
      changeEmailBtn.disabled = false;
      changeEmailBtn.textContent = "Đổi email";
    }
  };
}

if ($("#editProfileForm")) {
  $("#editProfileForm").onsubmit = async (e) => {
    e.preventDefault();
    const emailInput = $("#profileEmail");
    const newEmail = emailInput ? emailInput.value.trim().toLowerCase() : "";
    const currentEmail = (session?.email || "").trim().toLowerCase();
    const isChangingEmail = Boolean(newEmail && newEmail !== currentEmail);

    if (isChangingEmail) {
      if (session?.emailChanged) {
        toast("Bạn đã sử dụng lượt đổi email duy nhất của tài khoản.");
        return;
      }
      const confirmed = confirm("Bạn chỉ có một lần đổi email duy nhất. Bạn có chắc chắn chứ");
      if (!confirmed) {
        return;
      }
    }

    setSubmitLoading(e, true);
    try {
      const payload = {
        studentId: $("#profileStudentId").value.trim(),
        realName: $("#profileRealName").value.trim(),
        className: $("#profileClassName").value.trim(),
      };
      if (isChangingEmail) {
        payload.email = newEmail;
      }
      const res = await requestAPI("/api/me/profile", {
        method: "PATCH",
        body: JSON.stringify(payload),
      });
      if (res.user) {
        session = { ...session, ...res.user };
      }
      toast("Đã lưu hồ sơ cá nhân!");
      $("#editProfileModal").close();
      if (typeof syncAuth === "function") syncAuth(session);
      hydrateServer();
      if (typeof currentActiveRoute !== "undefined" && currentActiveRoute === "arena") {
        if (typeof onEnterArena === "function") onEnterArena();
      }
    } catch (err) {
      toast(err.message);
      if (err.message && err.message.toLowerCase().includes("mã số sinh viên")) {
        $("#profileStudentId")?.focus();
      }
    } finally {
      setSubmitLoading(e, false);
    }
  };
}

function syncNamecardModalScale() {
  const modal = document.getElementById("namecardModal");
  if (!modal) return;
  const rect = modal.getBoundingClientRect();
  const width = rect.width || modal.offsetWidth || 0;
  if (width > 0) {
    const scale = Math.min(1, width / 830);
    modal.style.setProperty("--nc-scale", scale.toFixed(5));
  } else {
    modal.style.setProperty("--nc-scale", "1");
  }
}
window.syncNamecardModalScale = syncNamecardModalScale;
window.addEventListener("resize", () => {
  const modal = document.getElementById("namecardModal");
  if (modal && modal.open) {
    syncNamecardModalScale();
  }
}, { passive: true });

