function describePieSlice(cx, cy, r, angleDeg) {
  if (angleDeg <= 0.05) return "";
  if (angleDeg >= 359.9) {
    return `M ${cx} ${cy - r} A ${r} ${r} 0 1 1 ${cx - 0.01} ${cy - r} Z`;
  }
  const rad = (angleDeg - 90) * Math.PI / 180;
  const x = (cx + r * Math.cos(rad)).toFixed(2);
  const y = (cy + r * Math.sin(rad)).toFixed(2);
  const largeArc = angleDeg > 180 ? 1 : 0;
  return `M ${cx} ${cy} L ${cx} ${cy - r} A ${r} ${r} 0 ${largeArc} 1 ${x} ${y} Z`;
}

function renderKitchenDialMarks() {
  const g = document.getElementById("kitchenDialMarks");
  if (!g) return;
  if (g.children.length >= 84) return;
  g.innerHTML = "";
  const cx = 150;
  const cy = 150;

  // 1. Render 60 Minute Tick Marks on white plate (r=98 to r=108)
  for (let i = 0; i < 60; i++) {
    const isFive = (i % 5 === 0);
    const innerR = isFive ? 96 : 102;
    const outerR = 108;
    const angleDeg = i * 6 - 90;
    const rad = (angleDeg * Math.PI) / 180;
    const x1 = (cx + innerR * Math.cos(rad)).toFixed(2);
    const y1 = (cy + innerR * Math.sin(rad)).toFixed(2);
    const x2 = (cx + outerR * Math.cos(rad)).toFixed(2);
    const y2 = (cy + outerR * Math.sin(rad)).toFixed(2);

    const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
    line.setAttribute("x1", x1);
    line.setAttribute("y1", y1);
    line.setAttribute("x2", x2);
    line.setAttribute("y2", y2);
    line.setAttribute("stroke", isFive ? "#0f172a" : "#334155");
    line.setAttribute("stroke-width", isFive ? "2.2" : "1.2");
    line.setAttribute("opacity", isFive ? "0.9" : "0.4");
    line.setAttribute("stroke-linecap", "round");
    g.appendChild(line);

    // 2. Render 12 Bold Numbers (0, 5, 10, ... 55) aligned radially around the perimeter (r=124)
    if (isFive) {
      const textR = 124;
      const tx = (cx + textR * Math.cos(rad)).toFixed(2);
      const ty = (cy + textR * Math.sin(rad)).toFixed(2);
      const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
      text.setAttribute("x", tx);
      text.setAttribute("y", ty);
      text.setAttribute("text-anchor", "middle");
      text.setAttribute("dominant-baseline", "central");
      text.setAttribute("font-family", "'Inter', system-ui, -apple-system, sans-serif");
      text.setAttribute("font-size", "15");
      text.setAttribute("font-weight", "800");
      text.setAttribute("fill", "#0f172a");
      // Tangent rotation around center of number so text bottom points towards center
      text.setAttribute("transform", `rotate(${angleDeg + 90}, ${tx}, ${ty})`);
      text.textContent = String(i);
      g.appendChild(text);
    }
  }

  // 3. Inner radial spokes (r=28 to r=98) across the colored wedge
  const spokesG = document.createElementNS("http://www.w3.org/2000/svg", "g");
  spokesG.setAttribute("id", "kitchenWedgeSpokesGroup");
  for (let i = 0; i < 60; i += 5) {
    const angleDeg = i * 6 - 90;
    const rad = (angleDeg * Math.PI) / 180;
    const x1 = (cx + 28 * Math.cos(rad)).toFixed(2);
    const y1 = (cy + 28 * Math.sin(rad)).toFixed(2);
    const x2 = (cx + 98 * Math.cos(rad)).toFixed(2);
    const y2 = (cy + 98 * Math.sin(rad)).toFixed(2);
    const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
    line.setAttribute("x1", x1);
    line.setAttribute("y1", y1);
    line.setAttribute("x2", x2);
    line.setAttribute("y2", y2);
    line.setAttribute("stroke", "#0f172a");
    line.setAttribute("stroke-width", "1.5");
    line.setAttribute("opacity", "0.35");
    line.setAttribute("stroke-linecap", "round");
    line.setAttribute("data-minute", String(i));
    spokesG.appendChild(line);
  }
  g.appendChild(spokesG);
}

// 7-Segment SVG Geometry for Digital Alarm Clock (Ảnh Mẫu 3)
const SEG_POLYGONS = {
  a: "5,4 43,4 37,11 11,11",
  b: "43,6 43,39 37,34 37,12",
  c: "43,43 43,76 37,70 37,47",
  d: "11,71 37,71 43,78 5,78",
  e: "5,42 11,47 11,70 5,76",
  f: "5,6 11,12 11,35 5,40",
  g: "10,37 38,37 42,41 38,45 10,45 6,41"
};

const DIGIT_MAP = {
  '0': ['a', 'b', 'c', 'd', 'e', 'f'],
  '1': ['b', 'c'],
  '2': ['a', 'b', 'g', 'e', 'd'],
  '3': ['a', 'b', 'g', 'c', 'd'],
  '4': ['f', 'g', 'b', 'c'],
  '5': ['a', 'f', 'g', 'c', 'd'],
  '6': ['a', 'f', 'g', 'e', 'c', 'd'],
  '7': ['a', 'b', 'c'],
  '8': ['a', 'b', 'c', 'd', 'e', 'f', 'g'],
  '9': ['a', 'b', 'c', 'd', 'f', 'g']
};

function update7SegmentDigit(digitEl, char) {
  if (!digitEl) return;
  if (digitEl._lastChar === char && digitEl.children && digitEl.children.length === 7) return;
  digitEl._lastChar = char;
  if (!digitEl.children || digitEl.children.length !== 7) {
    digitEl.innerHTML = "";
    ['a', 'b', 'c', 'd', 'e', 'f', 'g'].forEach(seg => {
      const poly = document.createElementNS("http://www.w3.org/2000/svg", "polygon");
      poly.setAttribute("points", SEG_POLYGONS[seg]);
      poly.setAttribute("data-seg", seg);
      digitEl.appendChild(poly);
    });
  }
  const activeSegs = DIGIT_MAP[char] || [];
  for (let i = 0; i < digitEl.children.length; i++) {
    const child = digitEl.children[i];
    const segName = child.getAttribute("data-seg");
    const isOn = activeSegs.includes(segName);
    child.setAttribute("class", isOn ? "seg-on" : "seg-off");
  }
}

function renderDigitalBlocks(progressRatio) {
  const bar = document.getElementById("digitalLedBlocks");
  if (!bar) return;
  const total = 24;
  const filled = Math.round(Math.min(1, Math.max(0, progressRatio)) * total);
  if (bar._lastFilled === filled && bar.children.length === total) return;
  bar._lastFilled = filled;
  if (bar.children.length !== total) {
    bar.innerHTML = "";
    for (let i = 0; i < total; i++) {
      const blk = document.createElement("span");
      blk.className = `led-block ${i < filled ? 'active' : ''}`;
      bar.appendChild(blk);
    }
  } else {
    for (let i = 0; i < total; i++) {
      const shouldBeActive = (i < filled);
      if (bar.children[i].classList.contains("active") !== shouldBeActive) {
        bar.children[i].classList.toggle("active", shouldBeActive);
      }
    }
  }
}

function updateStaticStudyControlsUI() {
  const isFlowtime = (studySettings.timerPreset === 'flowtime');
  const isEyeRule = (studySettings.timerPreset === 'eye_rule');
  const maxCycles = Math.max(1, Number(studySettings.longBreakInterval) || 4);

  // 1. Preset Navigation Bar Active State
  $$("#studyPresetsBar .preset-chip").forEach(chip => {
    chip.classList.toggle("active", chip.dataset.preset === (studySettings.timerPreset || '25_5'));
  });

  // 2. Preset Pill Badge in Meta Row
  const presetBadge = $("#activePresetBadgeName");
  if (presetBadge) {
    const curPreset = studySettings.timerPreset || '25_5';
    if (curPreset === 'flowtime') {
      presetBadge.textContent = "# Flowtime";
    } else if (curPreset === 'eye_rule') {
      presetBadge.textContent = "# 20-20-20";
    } else if (curPreset === 'custom') {
      presetBadge.textContent = `# ${studySettings.focusMins || 25} / ${studySettings.shortBreakMins || 5}`;
    } else {
      const cfg = STUDY_PRESET_CONFIGS[curPreset];
      presetBadge.textContent = `# ${cfg ? cfg.label : '25 / 5'}`;
    }
  }

  // 3. Dynamic Mode Button Labels
  const labelFocus = $("#labelModeFocus");
  const labelShortBreak = $("#labelModeShortBreak");
  const labelLongBreak = $("#labelModeLongBreak");
  if (labelFocus) labelFocus.textContent = isFlowtime ? `🌊 Đếm xuôi` : `⏱️ ${studySettings.focusMins} phút`;
  if (labelShortBreak) labelShortBreak.textContent = isEyeRule ? `👀 20 giây` : `☕ ${studySettings.shortBreakMins} phút`;
  if (labelLongBreak) labelLongBreak.textContent = `🌿 ${studySettings.longBreakMins} phút`;

  // 4. Cycle Dots
  $$("#studyCycleDots .cycle-dot").forEach((dot) => {
    const c = Number(dot.dataset.cycle);
    dot.classList.remove("active", "completed");
    if (studyState.cycleIndex === 0) {
      // not started
    } else if (studyState.mode === 'longbreak') {
      dot.classList.add("completed");
    } else if (c < studyState.cycleIndex) {
      dot.classList.add("completed");
    } else if (c === studyState.cycleIndex) {
      dot.classList.add("active");
    }
  });

  // 5. Flowtime ratio buttons
  if (isFlowtime) {
    const ratio = studySettings.flowtimeRatio || "1/4";
    $$("#flowtimeRatioButtons .ft-ratio-btn").forEach(btn => {
      btn.classList.toggle("active", btn.dataset.ratio === ratio);
    });
  }
}

function updateTimerDisplay() {
  const clock = $("#timerClock");
  const progressCircle = $("#timerProgressCircle");
  const label = $("#timerStatusLabel");
  const startBtn = $("#studyStartBtn");
  const startBtnText = $("#studyStartBtnText");
  const pauseBtn = $("#studyPauseBtn");
  const completeBtn = $("#studyCompleteBtn");
  const resetBtn = $("#studyResetBtn");
  const nextBtn = $("#studyNextBtn");
  const presetsBar = $("#studyPresetsBar");
  const meetingNotice = $("#meetingGuestTimerNotice");
  const flowtimeBreakBtn = $("#studyFlowtimeBreakBtn");
  const cycleLabel = $("#studyCycleLabel");
  const isFlowtime = (studySettings.timerPreset === 'flowtime');
  const isFlowtimeFocus = (isFlowtime && studyState.mode === 'focus');
  const isEyeRule = (studySettings.timerPreset === 'eye_rule');
  const isLibraryRoom = Boolean(currentStudyRoomId && currentStudyRoomId.startsWith('lib_'));
  const isMeetingRoom = Boolean(currentStudyRoomData && currentStudyRoomData.type === 'meeting');
  const isMeetingGuest = Boolean(isMeetingRoom && !currentStudyRoomData.isHost);

  renderClockTicks();

  // 1. Clock Display (Định dạng chuẩn không giật số)
  const formattedClock = isFlowtimeFocus
    ? formatTimerClock(studyState.elapsedSessionSeconds, true)
    : formatTimerClock(studyState.remainingSeconds, false);

  if (clock) {
    clock.textContent = formattedClock;
  }

  // 2. Circular Progress & Knob
  let progressRatio = 0;
  if (isFlowtimeFocus) {
    progressRatio = ((studyState.elapsedSessionSeconds % 3600) / 3600);
  } else {
    const totalSecs = (studyState.durationMinutes > 0 ? studyState.durationMinutes * 60 : 0);
    progressRatio = totalSecs > 0 ? (1 - Math.max(0, studyState.remainingSeconds) / totalSecs) : 0;
  }
  progressRatio = Math.max(0, Math.min(1, progressRatio));

  if (progressCircle) {
    const circum = 716.28;
    progressCircle.style.strokeDashoffset = (circum * (1 - progressRatio)).toFixed(2);
    progressCircle.style.opacity = progressRatio <= 0.002 ? "0" : "1";
    progressCircle.style.transformBox = "view-box";
    progressCircle.style.transformOrigin = "140px 140px";
    if (isFlowtimeFocus) {
      // Đếm xuôi: quay thuận chiều kim đồng hồ
      progressCircle.style.transform = "rotate(-90deg)";
    } else {
      // Đếm ngược: quay ngược chiều kim đồng hồ từ đỉnh 12h
      progressCircle.style.transform = "scaleX(-1) rotate(-90deg)";
    }
  }

  const knob = $("#timerProgressKnob");
  if (knob) {
    // Đếm ngược thì quay theo ngược chiều kim đồng hồ, đếm xuôi thì quay thuận chiều
    // Giữ nguyên cx="140" cy="26" và xoay quanh tâm (140, 140) chuẩn viewBox
    const rotDeg = isFlowtimeFocus ? (progressRatio * 360) : (-progressRatio * 360);
    knob.style.transformBox = "view-box";
    knob.style.transformOrigin = "140px 140px";
    knob.style.transform = `rotate(${rotDeg.toFixed(2)}deg)`;
    knob.setAttribute("transform", `rotate(${rotDeg.toFixed(2)}, 140, 140)`);
  }

  // 3. Render 6 Active Clock Styles
  const activeStyle = studySettings.clockStyle || 'dial';
  const views = {
    dial: $("#clockViewDial"),
    flip: $("#clockViewFlip"),
    minimal: $("#clockViewMinimal"),
    kitchen: $("#clockViewKitchen"),
    digital: $("#clockViewDigital"),
    hourglass: $("#clockViewHourglass")
  };
  Object.keys(views).forEach(st => {
    if (views[st]) {
      views[st].style.display = (st === activeStyle) ? "flex" : "none";
    }
  });

  const safeTotalSecs = isFlowtimeFocus ? studyState.elapsedSessionSeconds : Math.max(0, studyState.remainingSeconds);
  const dispM = Math.floor(safeTotalSecs / 60);
  const dispS = safeTotalSecs % 60;
  const strM = String(dispM).padStart(2, '0');
  const strS = String(dispS).padStart(2, '0');

  // Sub status label (đồng bộ tiếng Việt cho cả 6 kiểu đồng hồ)
  let subText = "TẬP TRUNG";
  if (!studyState.isRunning && (studyState.remainingSeconds < studySettings.focusDuration * 60 || studyState.elapsedSessionSeconds > 0)) {
    subText = "TẠM DỪNG";
  } else if (isFlowtimeFocus) {
    subText = "DÒNG CHẢY";
  } else if (studyState.mode === 'shortbreak') {
    subText = "NGHỈ NGẮN";
  } else if (studyState.mode === 'longbreak') {
    subText = "NGHỈ DÀI";
  }

  const subLabels = [
    $("#timerCenterSub"),
    $("#flipStatusTag"),
    $("#minStatusTag"),
    $("#digitalStatusTag")
  ];
  subLabels.forEach(el => {
    if (el) el.textContent = subText;
  });

  // 2. Flip Clock (Chuẩn Ảnh Mẫu 1)
  const flipMinNum = $("#flipMinNum");
  const flipSecNum = $("#flipSecNum");
  if (flipMinNum) {
    const oldM = flipMinNum.textContent;
    if (oldM !== strM) {
      if (oldM) triggerFlipLeafAnimation($("#flipCardMin"), oldM);
      flipMinNum.textContent = strM;
    }
  }
  if (flipSecNum) {
    const oldS = flipSecNum.textContent;
    if (oldS !== strS) {
      if (oldS) triggerFlipLeafAnimation($("#flipCardSec"), oldS);
      flipSecNum.textContent = strS;
    }
  }
  const flipShelfProg = $("#flipShelfProgress");
  if (flipShelfProg) {
    flipShelfProg.style.width = `${(progressRatio * 100).toFixed(1)}%`;
  }

  // 3. Minimal Clock
  const minClock = $("#minimalClockText");
  if (minClock) minClock.textContent = formattedClock;
  const minProgFill = $("#minimalProgFill");
  if (minProgFill) {
    minProgFill.style.width = `${(progressRatio * 100).toFixed(1)}%`;
  }

  // 4. Kitchen Timer (Chuẩn Ảnh Mẫu 2 - Đồng hồ cơ học từ 60 phút trở về)
  if (activeStyle === 'kitchen') {
    renderKitchenDialMarks();
    const remMins = Math.min(60, Math.max(0, safeTotalSecs / 60));
    const angleDeg = remMins * 6; // 6 độ mỗi phút trên mặt 60 phút
    const wedgePath = $("#kitchenTimerWedge");
    if (wedgePath) {
      wedgePath.setAttribute("d", describePieSlice(150, 150, 98, angleDeg));
    }
    const kitchenDigital = $("#kitchenDigitalText");
    if (kitchenDigital) kitchenDigital.textContent = formattedClock;
  }

  // 5. Digital Clock (Chuẩn Ảnh Mẫu 3 - 7 Segment Retro Alarm)
  if (activeStyle === 'digital') {
    update7SegmentDigit($("#d7Digit1"), strM[0]);
    update7SegmentDigit($("#d7Digit2"), strM[1]);
    update7SegmentDigit($("#d7Digit3"), strS[0]);
    update7SegmentDigit($("#d7Digit4"), strS[1]);
    renderDigitalBlocks(progressRatio);
  }

  // 6. Hourglass (Đồng hồ cát tự nhiên, sống động)
  if (activeStyle === 'hourglass') {
    const remRatio = Math.max(0, Math.min(1, 1 - progressRatio));
    const topSand = $("#hourglassTopSand");
    const topDepth = $("#hourglassTopSandDepth");
    const botSand = $("#hourglassBottomSand");
    const botDepth = $("#hourglassBottomSandDepth");
    const stream = $("#hourglassStream");
    const particles = $("#hourglassParticles");
    const funnel = $("#hourglassFunnel");
    const ripple = $("#sandImpactRipple");

    // 1. Top sand: drains with natural funnel curve into the neck
    if (topSand) {
      if (remRatio <= 0.005) {
        topSand.setAttribute("d", "M 86 126 L 94 126 Z");
        if (topDepth) topDepth.setAttribute("d", "M 86 126 L 94 126 Z");
        if (funnel) funnel.style.opacity = "0";
      } else {
        const topY = 30 + (1 - remRatio) * 92;
        const centerDip = Math.min(125, topY + Math.min(16, remRatio * 16 + 2));
        const d = `M 40 ${topY.toFixed(1)} Q 90 ${centerDip.toFixed(1)} 140 ${topY.toFixed(1)} L 140 126 L 40 126 Z`;
        topSand.setAttribute("d", d);
        if (topDepth) topDepth.setAttribute("d", d);
        if (funnel) funnel.style.opacity = "0.9";
      }
    }

    // 2. Bottom sand: natural conical dune heap rising
    let peakY = 222;
    if (botSand) {
      if (progressRatio <= 0.005) {
        botSand.setAttribute("d", "M 40 222 L 140 222 Z");
        if (botDepth) botDepth.setAttribute("d", "M 40 222 L 140 222 Z");
        if (ripple) ripple.style.opacity = "0";
      } else {
        peakY = 222 - progressRatio * 82;
        const d = `M 40 222 C 66 222 78 ${(peakY + 10).toFixed(1)} 90 ${peakY.toFixed(1)} C 102 ${(peakY + 10).toFixed(1)} 114 222 140 222 Z`;
        botSand.setAttribute("d", d);
        if (botDepth) botDepth.setAttribute("d", d);
        if (ripple) {
          ripple.setAttribute("cy", peakY.toFixed(1));
          ripple.style.opacity = (studyState.isRunning && remRatio > 0.005) ? "0.65" : "0";
        }
      }
    }

    // 3. Falling sand stream & micro particles
    if (stream) {
      if (studyState.isRunning && remRatio > 0.005) {
        stream.setAttribute("y2", Math.min(220, peakY + 2).toFixed(1));
        stream.classList.add("hourglass-stream-active");
        stream.style.opacity = "1";
        if (particles) particles.style.opacity = "1";
      } else {
        stream.classList.remove("hourglass-stream-active");
        stream.style.opacity = "0";
        if (particles) particles.style.opacity = "0";
      }
    }

    const hgDigital = $("#hourglassDigitalText");
    if (hgDigital) hgDigital.textContent = formattedClock;
  }

  // Top banner
  const topBanner = $("#timerTopBanner");
  if (topBanner) {
    if (isEyeRule) {
      topBanner.textContent = "Quy tắc 20-20-20: Cho đôi mắt được nghỉ ngơi";
    } else if (isFlowtime) {
      topBanner.textContent = "Dòng chảy Flowtime: Tự do đắm chìm vào công việc";
    } else if (studyState.mode === 'shortbreak') {
      topBanner.textContent = "Ca nghỉ ngắn: Thư giãn và nạp lại năng lượng";
    } else if (studyState.mode === 'longbreak') {
      topBanner.textContent = "Ca nghỉ dài: Hoàn thành xuất sắc một chu kỳ!";
    } else {
      topBanner.textContent = "Ca học Pomodoro: Giữ vững sự tập trung cao độ";
    }
  }

  // Quick task prompt
  const quickText = $("#studyQuickTaskText");
  const clearBtn = $("#studyGoalClearBtn");
  if (quickText) {
    if (studyState.goal) {
      quickText.textContent = studyState.goal;
      quickText.classList.add("has-goal");
      if (clearBtn) clearBtn.style.display = "inline-flex";
    } else {
      quickText.textContent = "Bạn đang tập trung vào việc gì?";
      quickText.classList.remove("has-goal");
      if (clearBtn) clearBtn.style.display = "none";
    }
  }

  // Trong phòng học nhóm hoặc thư viện: ẩn lượt chu kỳ và chọn preset, chỉ để lại mục tiêu hôm nay
  const cyclePill = $("#studyCyclePill");
  const presetPill = $("#studyPresetPickerPill");
  if (isLibraryRoom || isMeetingRoom) {
    if (cyclePill) cyclePill.style.display = "none";
    if (presetPill) presetPill.style.display = "none";
  } else {
    if (cyclePill) cyclePill.style.display = "inline-flex";
    if (presetPill) presetPill.style.display = "inline-flex";
  }

  const presetBadge = $("#activePresetBadgeName");
  if (presetBadge) {
    const curPreset = studySettings.timerPreset || '25_5';
    if (curPreset === 'flowtime') {
      presetBadge.textContent = "# Flowtime";
    } else if (curPreset === 'eye_rule') {
      presetBadge.textContent = "# 20-20-20";
    } else if (curPreset === 'custom') {
      presetBadge.textContent = `# ${studySettings.focusMins || 25} / ${studySettings.shortBreakMins || 5}`;
    } else {
      const cfg = STUDY_PRESET_CONFIGS[curPreset];
      presetBadge.textContent = `# ${cfg ? cfg.label : '25 / 5'}`;
    }
  }

  // 3. Status Label
  if (label) {
    if (studyState.isRunning) {
      if (isFlowtimeFocus) {
        label.textContent = '🌊 Dòng chảy tập trung (Đếm xuôi)';
        label.style.color = '#0284c7';
      } else if (studyState.mode === 'shortbreak') {
        if (isFlowtime) {
          label.textContent = `☕ Nghỉ giải lao Flowtime (${studySettings.flowtimeRatio || '1/4'})`;
          label.style.color = '#38bdf8';
        } else if (isEyeRule) {
          label.textContent = '👀 Nhìn xa 20 feet trong 20s (20-20-20)';
          label.style.color = '#38bdf8';
        } else {
          label.textContent = '☕ Đang nghỉ ngắn phục hồi';
          label.style.color = '#38bdf8';
        }
      } else if (studyState.mode === 'longbreak') {
        label.textContent = '🌿 Đang nghỉ dài nạp năng lượng';
        label.style.color = '#4ade80';
      } else {
        label.textContent = '🔥 Đang tập trung cao độ';
        label.style.color = 'var(--primary)';
      }
    } else if (isFlowtimeFocus && studyState.elapsedSessionSeconds > 0) {
      label.textContent = '⏸ Tạm dừng dòng chảy Flowtime';
      label.style.color = 'var(--muted)';
    } else if (!isFlowtimeFocus && studyState.remainingSeconds < (studyState.durationMinutes * 60)) {
      label.textContent = '⏸ Đang tạm dừng';
      label.style.color = 'var(--muted)';
    } else {
      label.textContent = isFlowtime ? 'Sẵn sàng đắm chìm dòng chảy' : 'Sẵn sàng ca học';
      label.style.color = 'var(--muted)';
    }
  }

  // 4. Start / Resume / Break Button Text
  if (startBtnText) {
    if (isFlowtimeFocus) {
      startBtnText.textContent = studyState.elapsedSessionSeconds > 0 ? "Tiếp tục" : "Bắt đầu";
    } else if (studyState.remainingSeconds < (studyState.durationMinutes * 60) && !studyState.isRunning) {
      startBtnText.textContent = "Tiếp tục";
    } else if (studyState.mode === 'shortbreak' || studyState.mode === 'longbreak') {
      startBtnText.textContent = "Nghỉ";
    } else {
      startBtnText.textContent = "Bắt đầu";
    }
  }

  // 5. Flowtime Controls & Ratio Bar
  const ftRatioBar = $("#flowtimeRatioBar");
  const ftPreview = $("#flowtimeCalcPreview");
  if (ftRatioBar) {
    if (isFlowtime) {
      ftRatioBar.style.display = "flex";
      const ratio = studySettings.flowtimeRatio || "1/4";
      $$("#flowtimeRatioButtons .ft-ratio-btn").forEach(btn => {
        btn.classList.toggle("active", btn.dataset.ratio === ratio);
      });
      const elapsed = isFlowtimeFocus ? studyState.elapsedSessionSeconds : (studyState.flowtimeFocusHistorySecs || 0);
      const breakCalc = Math.round(elapsed * parseRatio(ratio));
      if (ftPreview) {
        ftPreview.textContent = elapsed > 0 ? `Nghỉ: ${formatMMSS(breakCalc)}` : `Tỷ lệ ${ratio}`;
      }
    } else {
      ftRatioBar.style.display = "none";
    }
  }

  if (flowtimeBreakBtn) {
    if (isFlowtimeFocus && studyState.isRunning && studyState.elapsedSessionSeconds >= 5) {
      flowtimeBreakBtn.style.display = "inline-flex";
    } else {
      flowtimeBreakBtn.style.display = "none";
    }
  }

  // 6. Cycle Indicator & Label
  const maxCycles = Math.max(1, Number(studySettings.longBreakInterval) || 4);
  if (cycleLabel) {
    if (isFlowtime) {
      cycleLabel.textContent = `Flowtime`;
    } else if (isEyeRule) {
      cycleLabel.textContent = `Lượt ${studyState.cycleIndex || 1}/${maxCycles}`;
    } else if (studyState.cycleIndex === 0) {
      cycleLabel.textContent = `Lượt 0/${maxCycles}`;
    } else {
      cycleLabel.textContent = `Lượt ${studyState.cycleIndex || 1}/${maxCycles}`;
    }
  }
  const cycleIndicator = $("#cyclePillIndicator");
  if (cycleIndicator) {
    cycleIndicator.classList.toggle("active", Boolean(studyState.isRunning && studyState.mode === 'focus'));
  }

  const modeButtons = $$(".study-mode-btn, .mode-capsule-btn");

  if (isLibraryRoom) {
    if (startBtn) startBtn.style.display = "none";
    if (pauseBtn) pauseBtn.style.display = "none";
    if (resetBtn) resetBtn.style.display = "none";
    if (nextBtn) nextBtn.style.display = "none";
    if (flowtimeBreakBtn) flowtimeBreakBtn.style.display = "none";
    if (presetsBar) presetsBar.style.display = "none";
    if (meetingNotice) meetingNotice.style.display = "none";

    if (completeBtn) {
      completeBtn.style.display = "inline-flex";
      completeBtn.className = "study-btn-pill study-btn-leave study-action-ctrl";
      completeBtn.innerHTML = `
        <span class="btn-icon">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
            <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"></path>
            <polyline points="16 17 21 12 16 7"></polyline>
            <line x1="21" y1="12" x2="9" y2="12"></line>
          </svg>
        </span>
        <span class="btn-label">Rời phòng</span>
      `;
      completeBtn.onclick = () => confirmLeaveCurrentRoom();
    }

    modeButtons.forEach(btn => {
      btn.style.pointerEvents = "none";
      btn.style.opacity = "0.9";
    });
  } else if (isMeetingGuest) {
    if (startBtn) startBtn.style.display = "none";
    if (pauseBtn) pauseBtn.style.display = "none";
    if (resetBtn) resetBtn.style.display = "none";
    if (nextBtn) nextBtn.style.display = "none";
    if (completeBtn) completeBtn.style.display = "none";
    if (flowtimeBreakBtn) flowtimeBreakBtn.style.display = "none";
    if (presetsBar) presetsBar.style.display = "none";

    modeButtons.forEach(btn => {
      btn.style.pointerEvents = "none";
      btn.style.opacity = "0.9";
    });

    if (meetingNotice) {
      meetingNotice.style.display = "inline-flex";
      if (studyState.isRunning) {
        meetingNotice.innerHTML = `
          <span class="live-pulse-dot" style="background:#10b981;"></span>
          <span style="font-weight:700; color:#059669; font-size:13px;">Đồng hồ do chủ phòng quản lý</span>
        `;
      } else {
        meetingNotice.innerHTML = `
          <svg class="ui-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#d97706" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="margin-right:4px;"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg>
          <span style="font-weight:700; color:#d97706; font-size:13px;">Chờ chủ phòng bắt đầu</span>
        `;
      }
    }
  } else {
    if (presetsBar) presetsBar.style.display = "flex";
    if (meetingNotice) meetingNotice.style.display = "none";

    modeButtons.forEach(btn => {
      btn.style.pointerEvents = "auto";
      btn.style.opacity = "1";
    });

    if (resetBtn) resetBtn.style.display = "inline-flex";
    if (nextBtn) nextBtn.style.display = "inline-flex";

    if (startBtn) startBtn.style.display = studyState.isRunning ? "none" : "inline-flex";
    if (pauseBtn) pauseBtn.style.display = studyState.isRunning ? "inline-flex" : "none";

    if (completeBtn) {
      completeBtn.style.display = studyState.isRunning ? "inline-flex" : "none";
      completeBtn.className = "study-btn-secondary study-action-ctrl";
      completeBtn.innerHTML = `
        <span class="btn-icon"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span>
        <span class="btn-label">Hoàn tất</span>
      `;
      completeBtn.onclick = () => finishStudySession(false);
    }
  }

  $("#btnModeFocus")?.classList.toggle("active", studyState.mode === 'focus');
  $("#btnModeShortBreak")?.classList.toggle("active", studyState.mode === 'shortbreak');
  $("#btnModeLongBreak")?.classList.toggle("active", studyState.mode === 'longbreak');

  updateTabTitle();
  if (typeof updateSelfCoStudyCard === 'function') {
    updateSelfCoStudyCard();
  }
}

window.applyTimerPreset = async function (presetId) {
  const cfg = STUDY_PRESET_CONFIGS[presetId];
  if (!cfg) return;

  pauseStudyTimer(false);
  studySettings.timerPreset = presetId;

  if (presetId === 'custom') {
    openStudySettingsModal('timer');
    return;
  }

  if (presetId === 'flowtime') {
    studyState.mode = 'focus';
    studyState.durationMinutes = 0;
    studyState.remainingSeconds = 0;
    studyState.elapsedSessionSeconds = 0;
    studyState.flowtimeElapsedSeconds = 0;
    studyState.targetEndMs = 0;
    toast("🌊 Đã chuyển sang Flowtime (Đếm xuôi). Bạn tự do tập trung và nghỉ giải lao theo tỷ lệ vàng!");
  } else if (presetId === 'eye_rule') {
    studySettings.focusMins = 20;
    studySettings.shortBreakMins = 20 / 60; // 20s
    studySettings.longBreakMins = 15;
    studyState.mode = 'focus';
    studyState.durationMinutes = 20;
    studyState.remainingSeconds = 20 * 60;
    studyState.targetEndMs = 0;
    studyState.elapsedSessionSeconds = 0;
    toast("👀 Đã chọn Quy tắc 20-20-20: Mỗi 20 phút nhìn xa 20 feet trong 20 giây!");
  } else {
    studySettings.focusMins = cfg.focus;
    studySettings.shortBreakMins = cfg.shortBreak;
    studySettings.longBreakMins = cfg.longBreak;
    studyState.mode = 'focus';
    studyState.durationMinutes = cfg.focus;
    studyState.remainingSeconds = cfg.focus * 60;
    studyState.targetEndMs = 0;
    studyState.elapsedSessionSeconds = 0;
    toast(`⏱️ Đã chọn preset ${cfg.label}!`);
  }

  saveStudySettings(false);
  updateStaticStudyControlsUI();
  updateTimerDisplay();
  await syncMeetingRoomTimerIfHost();
  await syncStudyToServer();
};

window.setFlowtimeBreakRatio = function (ratio) {
  studySettings.flowtimeRatio = ratio;
  saveStudySettings(false);
  updateStaticStudyControlsUI();

  const elapsed = (studyState.mode === 'shortbreak') ? (studyState.flowtimeFocusHistorySecs || 0) : (studyState.elapsedSessionSeconds || studyState.flowtimeFocusHistorySecs || 0);
  const ratioNum = parseRatio(ratio);
  const newBreakSecs = Math.round(elapsed * ratioNum);

  if (studyState.mode === 'shortbreak' && studySettings.timerPreset === 'flowtime') {
    studyState.remainingSeconds = Math.max(10, newBreakSecs);
    studyState.durationMinutes = Math.max(1, Math.ceil(studyState.remainingSeconds / 60));
    if (studyState.isRunning) {
      studyState.targetEndMs = Date.now() + studyState.remainingSeconds * 1000;
    }
  }

  updateTimerDisplay();
  if (elapsed > 0) {
    toast(`Đã chọn tỷ lệ nghỉ Flowtime: ${ratio} (${formatMMSS(newBreakSecs)})`);
  } else {
    toast(`Đã chọn tỷ lệ nghỉ Flowtime: ${ratio}`);
  }
};

window.triggerFlowtimeBreak = function () {
  if (studyState.elapsedSessionSeconds < 5) {
    toast("Hãy tập trung ít nhất vài phút trước khi bắt đầu nghỉ giải lao nhé!");
    return;
  }
  pauseStudyTimer(false);
  const elapsed = studyState.elapsedSessionSeconds;
  studyState.flowtimeFocusHistorySecs = elapsed;
  const ratioNum = parseRatio(studySettings.flowtimeRatio || "1/4");
  const breakSecs = Math.max(10, Math.round(elapsed * ratioNum));

  studyState.mode = 'shortbreak';
  studyState.durationMinutes = Math.max(1, Math.ceil(breakSecs / 60));
  studyState.remainingSeconds = breakSecs;
  studyState.targetEndMs = Date.now() + breakSecs * 1000;
  studyState.elapsedSessionSeconds = 0;

  if (studySettings.pauseSoundsDuringBreaks) {
    pauseActiveStudyAudioForBreak();
  }
  if (studyState._autoZenActive) {
    exitAutoZenMode();
  }

  toast(`☕ Bắt đầu nghỉ giải lao Flowtime (${studySettings.flowtimeRatio || '1/4'}): ${formatMMSS(breakSecs)}`);
  startStudyTimer();
  updateTimerDisplay();
};

function setStudyMode(mode, duration) {
  let standardMode = mode;
  if (mode === 'pomodoro') standardMode = 'focus';
  if (mode === 'deep') {
    standardMode = 'focus';
    duration = duration || 50;
  }

  if (studyState.isRunning) {
    pauseStudyTimer(false);
  }

  studyState.mode = standardMode;
  const isEye = (studySettings.timerPreset === 'eye_rule');
  const finalDuration = duration || (
    standardMode === 'focus' ? studySettings.focusMins :
      standardMode === 'shortbreak' ? (isEye ? (20 / 60) : studySettings.shortBreakMins) :
        studySettings.longBreakMins
  );

  studyState.durationMinutes = finalDuration;
  studyState.remainingSeconds = Math.round(finalDuration * 60);
  studyState.targetEndMs = 0;
  studyState.elapsedSessionSeconds = 0;

  updateStaticStudyControlsUI();
  updateTimerDisplay();
  syncMeetingRoomTimerIfHost();
  syncStudyToServer();
}

function advanceStudyCycle(manualSkip = false) {
  pauseStudyTimer(false);
  const maxCycles = Math.max(1, Number(studySettings.longBreakInterval) || 4);

  if (studyState.mode === 'focus') {
    if (studyState.cycleIndex === 0) {
      studyState.cycleIndex = 1;
    }
    if (studyState.cycleIndex < maxCycles) {
      studyState.cycleIndex++;
      studyState.mode = 'shortbreak';
      const isEye = (studySettings.timerPreset === 'eye_rule');
      const breakSecs = isEye ? 20 : (studySettings.shortBreakMins * 60);
      studyState.durationMinutes = isEye ? (20 / 60) : studySettings.shortBreakMins;
      studyState.remainingSeconds = breakSecs;

      if (studySettings.pauseSoundsDuringBreaks) {
        pauseActiveStudyAudioForBreak();
      }
      if (studyState._autoZenActive) {
        exitAutoZenMode();
      }

      toast(isEye ? "👀 Nghỉ mắt 20 giây: Nhìn xa 20 feet (6m) nhé!" : `☕ Hoàn thành lượt tập trung! Nghỉ giải lao ${studySettings.shortBreakMins} phút.`);
      if (studySettings.autoStartBreaks) {
        startStudyTimer();
      }
    } else {
      studyState.cycleIndex = maxCycles;
      studyState.mode = 'longbreak';
      studyState.durationMinutes = studySettings.longBreakMins;
      studyState.remainingSeconds = studySettings.longBreakMins * 60;

      if (studySettings.pauseSoundsDuringBreaks) {
        pauseActiveStudyAudioForBreak();
      }
      if (studyState._autoZenActive) {
        exitAutoZenMode();
      }

      toast(`🏆 Hoàn thành trọn vẹn ${maxCycles} lượt Pomodoro! Nghỉ dài ${studySettings.longBreakMins} phút.`);
      if (studySettings.autoStartBreaks) {
        startStudyTimer();
      }
    }
  } else {
    // Was in break -> Advance to Focus
    if (studyState.mode === 'longbreak') {
      studyState.cycleIndex = 1;
    }
    studyState.mode = 'focus';
    studyState.durationMinutes = studySettings.focusMins;
    studyState.remainingSeconds = studySettings.focusMins * 60;

    if (studySettings.pauseSoundsDuringBreaks) {
      resumeActiveStudyAudioAfterBreak();
    }

    toast(`⏱️ Bắt đầu lượt tập trung ${studyState.cycleIndex}/${maxCycles}! Hãy giữ nhịp độ.`);
    if (studySettings.autoStartPomodoros) {
      startStudyTimer();
    }
  }

  studyState.targetEndMs = studyState.isRunning ? Date.now() + studyState.remainingSeconds * 1000 : 0;
  studyState.elapsedSessionSeconds = 0;
  rotateStudyQuote();
  if (studySettings.clockStyle === 'hourglass') {
    triggerHourglassFlipAnimation();
  }
  updateStaticStudyControlsUI();
  updateTimerDisplay();
  syncMeetingRoomTimerIfHost();
  syncStudyToServer();
}

async function syncStudyToServer() {
  if (!canAccessStudyLounge()) return;
  if (!session) return;
  try {
    const isFlowtimeFocus = (studySettings.timerPreset === 'flowtime' && studyState.mode === 'focus');
    const res = await requestAPI("/api/study/sync", {
      method: "POST",
      body: JSON.stringify({
        mode: isFlowtimeFocus ? 'flowtime' : studyState.mode,
        durationMinutes: isFlowtimeFocus ? Math.max(1, Math.round(studyState.elapsedSessionSeconds / 60)) : studyState.durationMinutes,
        remainingSeconds: isFlowtimeFocus ? studyState.elapsedSessionSeconds : studyState.remainingSeconds,
        targetEndMs: studyState.targetEndMs,
        isRunning: studyState.isRunning,
        cycleIndex: studyState.cycleIndex,
        goal: studyState.goal,
        wallpaper: studySettings.activeWallpaper || 'default',
        aura: studySettings.activeAura || 'emerald',
        roomId: currentStudyRoomId || 'commons'
      })
    });
    studyState.lastSyncMs = Date.now();
    return res;
  } catch (e) {
    console.warn("syncStudyToServer:", e);
  }
}

function syncMeetingRoomTimerIfHost() {
  if (currentStudyRoomId && currentStudyRoomData && currentStudyRoomData.type === 'meeting' && currentStudyRoomData.isHost) {
    const payload = {
      roomId: currentStudyRoomId,
      mode: studyState.mode,
      timerPreset: studySettings.timerPreset || '25_5',
      focusMins: studySettings.focusMins || 25,
      shortBreakMins: studySettings.shortBreakMins || 5,
      longBreakMins: studySettings.longBreakMins || 15,
      longBreakInterval: studySettings.longBreakInterval || 4,
      flowtimeRatio: studySettings.flowtimeRatio || '1/4',
      durationMinutes: studyState.durationMinutes,
      remainingSeconds: studyState.remainingSeconds,
      isRunning: studyState.isRunning,
      targetEndMs: studyState.targetEndMs,
      cycleIndex: studyState.cycleIndex || 1,
      timerState: {
        mode: studyState.mode,
        timerPreset: studySettings.timerPreset || '25_5',
        focusMins: studySettings.focusMins || 25,
        shortBreakMins: studySettings.shortBreakMins || 5,
        longBreakMins: studySettings.longBreakMins || 15,
        longBreakInterval: studySettings.longBreakInterval || 4,
        flowtimeRatio: studySettings.flowtimeRatio || '1/4',
        durationMinutes: studyState.durationMinutes,
        remainingSeconds: studyState.remainingSeconds,
        isRunning: studyState.isRunning,
        targetEndMs: studyState.targetEndMs,
        cycleIndex: studyState.cycleIndex || 1,
        timestamp: Date.now()
      }
    };
    return requestAPI("/api/study/rooms/meeting/timer", {
      method: "POST",
      body: JSON.stringify(payload)
    }).catch((err) => console.warn("syncMeetingRoomTimerIfHost:", err));
  }
  return Promise.resolve(null);
}

function applyMeetingRoomTimerState(ts) {
  if (!ts) return;

  // Đồng bộ loại đồng hồ preset từ chủ phòng cho toàn bộ thành viên
  if (ts.timerPreset) {
    studySettings.timerPreset = ts.timerPreset;
    if (ts.focusMins) studySettings.focusMins = Number(ts.focusMins);
    if (ts.shortBreakMins) studySettings.shortBreakMins = Number(ts.shortBreakMins);
    if (ts.longBreakMins) studySettings.longBreakMins = Number(ts.longBreakMins);
    if (ts.longBreakInterval) studySettings.longBreakInterval = Number(ts.longBreakInterval);
    if (ts.flowtimeRatio) studySettings.flowtimeRatio = ts.flowtimeRatio;

    const presetBadge = $("#activePresetBadgeName");
    if (presetBadge) {
      if (ts.timerPreset === 'flowtime') presetBadge.textContent = "# Dòng chảy";
      else if (ts.timerPreset === 'eye_rule') presetBadge.textContent = "# 20-20-20";
      else {
        const pInfo = (typeof STUDY_PRESET_CONFIGS !== 'undefined') ? STUDY_PRESET_CONFIGS[ts.timerPreset] : null;
        presetBadge.textContent = pInfo ? `# ${pInfo.label}` : `# ${studySettings.focusMins}/${studySettings.shortBreakMins}`;
      }
    }
  }

  studyState.mode = ts.mode || 'focus';
  studyState.durationMinutes = Number(ts.durationMinutes) || 25;
  studyState.cycleIndex = Number(ts.cycleIndex) || 1;

  if (ts.isRunning) {
    const now = Date.now();
    let rem = 0;
    if (ts.targetEndMs && ts.targetEndMs > now) {
      rem = Math.max(0, Math.ceil((ts.targetEndMs - now) / 1000));
      studyState.targetEndMs = ts.targetEndMs;
    } else {
      rem = Number(ts.remainingSeconds) || (studyState.durationMinutes * 60);
      studyState.targetEndMs = now + rem * 1000;
    }
    studyState.remainingSeconds = rem;
    studyState.isRunning = true;
    if (!studyState.timerInterval) {
      startLocalTimerTick();
    }
  } else {
    studyState.isRunning = false;
    studyState.targetEndMs = 0;
    if (studyState.timerInterval) {
      clearInterval(studyState.timerInterval);
      studyState.timerInterval = null;
    }
    studyState.remainingSeconds = (ts.remainingSeconds !== undefined && ts.remainingSeconds !== null)
      ? Number(ts.remainingSeconds)
      : (studyState.durationMinutes * 60);
  }
  updateTimerDisplay();
}

function startLocalTimerTick() {
  studyState.isRunning = true;
  if (studyState.timerInterval) {
    clearInterval(studyState.timerInterval);
    studyState.timerInterval = null;
  }

  const now = Date.now();
  if (!studyState.startedAtMs) {
    studyState.startedAtMs = now - (studyState.elapsedSessionSeconds || 0) * 1000;
  }
  studyState._lastTickedSec = null;

  studyState.timerInterval = setInterval(() => {
    const curNow = Date.now();

    // 24/7 continuous library rooms live synchronization
    if (currentStudyRoomId && currentStudyRoomId.startsWith('lib_')) {
      const cfg = LIBRARY_ROOM_CONFIGS.find(c => c.id === currentStudyRoomId);
      if (cfg) {
        const live = getLibraryLiveState(cfg.focus, cfg.break, curNow);
        if (live.remainingSec !== studyState._lastTickedSec) {
          studyState._lastTickedSec = live.remainingSec;
          studyState.mode = live.isFocus ? 'focus' : 'shortbreak';
          studyState.durationMinutes = live.isFocus ? cfg.focus : cfg.break;
          studyState.remainingSeconds = live.remainingSec;
          updateTimerDisplay();
          if (typeof updateAllCoStudyCards === 'function') {
            updateAllCoStudyCards(lastFetchedLearners);
          }
        }
        return;
      }
    }

    const isFlowtimeFocus = (studySettings.timerPreset === 'flowtime' && studyState.mode === 'focus');

    if (isFlowtimeFocus) {
      const elapsed = Math.max(0, Math.floor((curNow - studyState.startedAtMs) / 1000));
      if (elapsed !== studyState._lastTickedSec) {
        studyState._lastTickedSec = elapsed;
        studyState.elapsedSessionSeconds = elapsed;
        studyState.remainingSeconds = elapsed;
        if (studySettings.tickingSound && studySettings.tickingSound !== 'off') {
          playTickSound();
        }
        updateTimerDisplay();
        if (typeof updateAllCoStudyCards === 'function') {
          updateAllCoStudyCards(lastFetchedLearners);
        }
      }
      return;
    }

    if (!isFlowtimeFocus && studyState.targetEndMs <= 0 && studyState.remainingSeconds > 0) {
      studyState.targetEndMs = curNow + studyState.remainingSeconds * 1000;
    }

    if (studyState.targetEndMs > 0) {
      const remaining = Math.max(0, Math.ceil((studyState.targetEndMs - curNow) / 1000));
      if (remaining !== studyState._lastTickedSec) {
        studyState._lastTickedSec = remaining;
        studyState.remainingSeconds = remaining;
        studyState.elapsedSessionSeconds = Math.max(0, Math.floor((curNow - studyState.startedAtMs) / 1000));

        // Ticking sound during focus
        if (studyState.mode === 'focus' && studySettings.tickingSound && studySettings.tickingSound !== 'off') {
          playTickSound();
        }

        // Pre-end reminder chime
        if (studyState.mode === 'focus' && studySettings.reminderBeforeEnd > 0) {
          const remindSecs = Number(studySettings.reminderBeforeEnd) * 60;
          if (remaining === remindSecs && !studyState._reminderFiredThisSession) {
            studyState._reminderFiredThisSession = true;
            playSoftReminderChime();
            toast(`⏳ Còn ${studySettings.reminderBeforeEnd} phút nữa là kết thúc ca học!`);
          }
        }

        updateTimerDisplay();
        if (typeof updateAllCoStudyCards === 'function') {
          updateAllCoStudyCards(lastFetchedLearners);
        }
        if (remaining <= 0) {
          finishStudySession(true);
        }
      }
    } else {
      if (studyState.remainingSeconds <= 0) {
        finishStudySession(true);
      }
    }
  }, 100);

  if (studyState.syncHeartbeatInterval) {
    clearInterval(studyState.syncHeartbeatInterval);
    studyState.syncHeartbeatInterval = null;
  }
  studyState.syncHeartbeatInterval = setInterval(syncStudyToServer, 10000);
}

async function startStudyTimer() {
  if (studyState.isRunning) return;
  if (studyState.cycleIndex === 0) {
    studyState.cycleIndex = 1;
  }
  studyState.goal = ($("#studyGoalInput") ? $("#studyGoalInput").value : "").trim();
  const now = Date.now();
  studyState._reminderFiredThisSession = false;

  const isFlowtimeFocus = (studySettings.timerPreset === 'flowtime' && studyState.mode === 'focus');

  if (!isFlowtimeFocus && studyState.remainingSeconds <= 0) {
    if (studyState.mode === 'shortbreak') {
      studyState.durationMinutes = studySettings.shortBreakMins || 5;
    } else if (studyState.mode === 'longbreak') {
      studyState.durationMinutes = studySettings.longBreakMins || 15;
    } else {
      studyState.durationMinutes = studySettings.focusMins || 25;
    }
    studyState.remainingSeconds = studyState.durationMinutes * 60;
  }

  studyState.startedAtMs = now - (studyState.elapsedSessionSeconds || 0) * 1000;
  studyState.targetEndMs = isFlowtimeFocus ? 0 : (now + studyState.remainingSeconds * 1000);

  if (studyState.audioCtx && studyState.audioCtx.state === 'suspended') {
    studyState.audioCtx.resume();
  }

  // Resume paused audio if returning to focus
  if (studyState.mode === 'focus' && studySettings.pauseSoundsDuringBreaks && studyState._breakPausedSounds) {
    resumeActiveStudyAudioAfterBreak();
  }

  // Auto Zen View while focusing
  if (studyState.mode === 'focus' && studySettings.hideEverythingWhileFocusing) {
    enterAutoZenMode();
  }

  // Khi ở trong phòng cá nhân mà bật đồng hồ thì tự động hiển thị những việc cần làm
  const isPersonalRoom = (!currentStudyRoomId || currentStudyRoomId === 'commons' || currentStudyRoomId === 'private');
  if (isPersonalRoom) {
    const personalTasksEl = $("#integratedPersonalTasksSection");
    if (personalTasksEl) {
      personalTasksEl.style.display = "block";
      togglePersonalTasksCollapse(true);
    }
  }

  startLocalTimerTick();
  updateTimerDisplay();
  syncMeetingRoomTimerIfHost();
  await syncStudyToServer();
  await fetchStudyLounge();
}

async function pauseStudyTimer(sync = true) {
  studyState.isRunning = false;
  if (studyState.timerInterval) {
    clearInterval(studyState.timerInterval);
    studyState.timerInterval = null;
  }
  if (studyState.syncHeartbeatInterval) {
    clearInterval(studyState.syncHeartbeatInterval);
    studyState.syncHeartbeatInterval = null;
  }
  if (studyState.targetEndMs > 0) {
    studyState.remainingSeconds = Math.max(0, Math.ceil((studyState.targetEndMs - Date.now()) / 1000));
    studyState.targetEndMs = 0;
  }

  if (studyState._autoZenActive) {
    exitAutoZenMode();
  }

  updateTimerDisplay();
  if (typeof updateAllCoStudyCards === 'function') {
    updateAllCoStudyCards(lastFetchedLearners);
  }
  syncMeetingRoomTimerIfHost();
  if (sync) {
    await syncStudyToServer();
    await fetchStudyLounge();
  }
}

async function resetStudyTimer() {
  await pauseStudyTimer(false);
  studyState.completedFocusCycles = 0;
  studyState.accumulatedFocusMinutes = 0;

  if (studySettings.timerPreset === 'flowtime') {
    studyState.remainingSeconds = 0;
    studyState.durationMinutes = 0;
  } else if (studySettings.timerPreset === 'eye_rule') {
    studyState.durationMinutes = 20;
    studyState.remainingSeconds = 20 * 60;
  } else {
    studyState.remainingSeconds = studyState.durationMinutes * 60;
  }

  studyState.targetEndMs = 0;
  studyState.startedAtMs = 0;
  studyState.elapsedSessionSeconds = 0;
  studyState.flowtimeFocusHistorySecs = 0;

  syncMeetingRoomTimerIfHost();

  if (session) {
    try {
      await requestAPI("/api/study/leave", { method: "POST" });
    } catch (e) { }
  }
  if (studySettings.clockStyle === 'hourglass') {
    triggerHourglassFlipAnimation();
  }
  updateTimerDisplay();
  if (typeof updateAllCoStudyCards === 'function') {
    updateAllCoStudyCards(lastFetchedLearners);
  }
  await fetchStudyLounge();
  toast("Đã đặt lại đồng hồ.");
}

async function finishStudySession(autoCompleted = false) {
  await pauseStudyTimer(false);
  triggerSessionAlarm();
  sendStudyNotification();

  const totalElapsedMins = Math.round(studyState.elapsedSessionSeconds / 60);
  const isFocus = (studyState.mode === 'focus' || studyState.mode === 'pomodoro');

  let sessionMinutesToLog = 0;
  if (isFocus) {
    // Chỉ khi hoàn thành 100% thời gian một lượt tập trung (autoCompleted === true) mới tính cộng 1 lượt vào mục tiêu hàng ngày
    if (autoCompleted) {
      recordTodayCompletedPomodoro();
      studyState.completedFocusCycles = (studyState.completedFocusCycles || 0) + 1;
      sessionMinutesToLog = studyState.durationMinutes || 25;
      studyState.accumulatedFocusMinutes = (studyState.accumulatedFocusMinutes || 0) + sessionMinutesToLog;
    } else {
      sessionMinutesToLog = totalElapsedMins;
      studyState.accumulatedFocusMinutes = (studyState.accumulatedFocusMinutes || 0) + sessionMinutesToLog;
    }
  }

  const durationToCredit = sessionMinutesToLog;
  const cyclesToCredit = studyState.completedFocusCycles || 0;

  if (session && (durationToCredit >= 1 || cyclesToCredit >= 1)) {
    try {
      const res = await requestAPI("/api/study/complete", {
        method: "POST",
        body: JSON.stringify({
          durationMinutes: durationToCredit,
          cyclesCompleted: cyclesToCredit,
          goal: studyState.goal || "Tự học NCKH"
        })
      });
      if (res && res.success) {
        if (res.message) {
          toast(res.message);
        } else if (res.pointsAwarded > 0) {
          toast(`🎉 Hoàn thành xuất sắc ca tự học (${cyclesToCredit} lượt)! +${res.pointsAwarded} điểm thưởng tuần & giữ chuỗi!`);
        } else {
          toast(`🎉 Hoàn tất ca học (${cyclesToCredit} lượt)! Hoạt động đã được ghi nhận.`);
        }
        loadContributions();
      }
    } catch (e) {
      console.error(e);
    }
  } else if (durationToCredit >= 1 || cyclesToCredit >= 1) {
    toast(`🎉 Hoàn thành ca tự học ${durationToCredit} phút! (Đăng nhập để lưu điểm & giữ chuỗi)`);
  } else {
    toast("🎉 Đã hoàn tất ca học!");
  }

  if (!autoCompleted) {
    studyState.completedFocusCycles = 0;
    studyState.accumulatedFocusMinutes = 0;
    studyState.cycleIndex = 0;
    studyState.mode = 'focus';
    studyState.durationMinutes = studySettings.focusMins;
    studyState.remainingSeconds = (studySettings.timerPreset === 'flowtime' ? 0 : studySettings.focusMins * 60);
    studyState.targetEndMs = 0;
    studyState.elapsedSessionSeconds = 0;

    if (session) {
      try {
        await requestAPI("/api/study/leave", { method: "POST" });
      } catch (e) { }
    }

    updateTimerDisplay();
    await fetchStudyLounge();
  } else {
    advanceStudyCycle(false);
  }
}

function resumeActiveStudyAudioIfPaused() {
  try {
    if (studyState.activeEnvTrack) {
      const p = studyState.envAudioPlayers[studyState.activeEnvTrack];
      if (p && p.paused && !p._isExplicitlyStopped) p.play().catch(() => { });
    }
    if (studyState.activeMusicTrack) {
      const p = studyState.musicAudioPlayers[studyState.activeMusicTrack];
      if (p && p.paused && !p._isExplicitlyStopped) p.play().catch(() => { });
    }
    Object.keys(studyState.activeMixSounds || {}).forEach(k => {
      if (studyState.activeMixSounds[k]) {
        const p = studyState.mixAudioPlayers[k];
        if (p && p.paused && !p._isExplicitlyStopped) p.play().catch(() => { });
      }
    });
    if (studyState.activeCustomEnvId && studyState.customEnvAudioPlayer && studyState.customEnvAudioPlayer.paused && !studyState.customEnvAudioPlayer._isExplicitlyStopped) {
      studyState.customEnvAudioPlayer.play().catch(() => { });
    }
    if (studyState.activeCustomMusicId && studyState.customMusicAudioPlayer && studyState.customMusicAudioPlayer.paused && !studyState.customMusicAudioPlayer._isExplicitlyStopped) {
      studyState.customMusicAudioPlayer.play().catch(() => { });
    }
    Object.keys(studyState.activeCustomMixSounds || {}).forEach(k => {
      if (studyState.activeCustomMixSounds[k]) {
        const p = studyState.customMixAudioPlayers[k];
        if (p && p.paused && !p._isExplicitlyStopped) p.play().catch(() => { });
      }
    });
  } catch (e) { }
}

// Background tab throttling resolution via Page Visibility & Focus APIs
document.addEventListener("visibilitychange", () => {
  if (document.visibilityState === "visible") {
    if (studyState.isRunning && studyState.targetEndMs > 0) {
      const remaining = Math.max(0, Math.floor((studyState.targetEndMs - Date.now()) / 1000));
      studyState.remainingSeconds = remaining;
      updateTimerDisplay();
      if (remaining <= 0) {
        finishStudySession(true);
      }
    }
    fetchStudyLounge();
    resumeActiveStudyAudioIfPaused();
  }
});
window.addEventListener("focus", () => {
  if (studyState.isRunning && studyState.targetEndMs > 0) {
    const remaining = Math.max(0, Math.floor((studyState.targetEndMs - Date.now()) / 1000));
    studyState.remainingSeconds = remaining;
    updateTimerDisplay();
  }
  fetchStudyLounge();
  resumeActiveStudyAudioIfPaused();
});

/* --- 5. CO-STUDY LOUNGE & FLEXIBLE SPACES (Real-Time Synchronized) --- */
let lastFetchedLearners = [];
let currentStudyRoomId = "commons";
let currentStudyRoomData = null;
let cachedStudyRooms = [];
let activeSpaceFilter = 'all';
let totalCampusLearnersCount = 0;

const WALLPAPER_CARD_GRADIENTS = {
  default_light: 'linear-gradient(135deg, #ffffff 0%, #f0f8f4 100%)',
  default_light_self: 'linear-gradient(135deg, #ffffff 0%, #e3f5ec 100%)',
  default_glass: 'linear-gradient(135deg, rgba(255, 255, 255, 0.92) 0%, rgba(240, 248, 243, 0.9) 100%)',
  default_glass_self: 'linear-gradient(135deg, rgba(255, 255, 255, 0.95) 0%, rgba(228, 245, 236, 0.92) 100%)',
  library: 'linear-gradient(135deg, #4d2813 0%, #361a0a 50%, #1e0d05 100%)', // Rich Oxford warm mahogany brown
  cafe: 'linear-gradient(135deg, #3f271a 0%, #29170d 50%, #160b05 100%)', // Warm roasted coffee mocha
  mountain: 'linear-gradient(135deg, #1b3834 0%, #102522 50%, #071513 100%)', // Mountain pine mist teal slate
  sunset: 'linear-gradient(135deg, #521e2d 0%, #35101d 50%, #1e0710 100%)', // Sunset dusk burgundy rose
  lofi: 'linear-gradient(135deg, #371a4f 0%, #220e33 50%, #11051c 100%)', // Lo-fi twilight neon purple
  zen: 'linear-gradient(135deg, #1e3822 0%, #112315 50%, #061309 100%)', // Zen tranquil bamboo green
  space: 'linear-gradient(135deg, #131a44 0%, #090e29 50%, #030514 100%)', // Space cosmic midnight navy
  christmas_2026: 'linear-gradient(135deg, #5c191e 0%, #163a2a 55%, #0c1f17 100%)' // Cozy Christmas cabin hearth & pine
};

function getWallpaperCardInfo(wallId, isSelf) {
  const isDefault = (!wallId || wallId === 'default');
  const studyEl = document.getElementById("study");
  const hasCustomBg = studyEl ? studyEl.classList.contains("has-custom-bg") : false;

  if (isDefault) {
    if (hasCustomBg) {
      return {
        gradient: isSelf ? WALLPAPER_CARD_GRADIENTS.default_glass_self : WALLPAPER_CARD_GRADIENTS.default_glass,
        isDark: false
      };
    } else {
      return {
        gradient: isSelf ? WALLPAPER_CARD_GRADIENTS.default_light_self : WALLPAPER_CARD_GRADIENTS.default_light,
        isDark: false
      };
    }
  }

  if (WALLPAPER_CARD_GRADIENTS[wallId]) {
    return {
      gradient: WALLPAPER_CARD_GRADIENTS[wallId],
      isDark: true
    };
  }

  // Custom uploaded wallpaper or others
  return {
    gradient: 'linear-gradient(135deg, rgba(26, 32, 44, 0.88) 0%, rgba(15, 19, 28, 0.94) 100%)',
    isDark: true
  };
}

const AURA_STYLES = {
  emerald: { border: 'rgba(16, 185, 129, 0.85)', glow: 'rgba(16, 185, 129, 0.35)', primary: '#10b981' },
  cyan: { border: 'rgba(0, 242, 254, 0.85)', glow: 'rgba(0, 242, 254, 0.35)', primary: '#00f2fe' },
  amber: { border: 'rgba(255, 126, 95, 0.85)', glow: 'rgba(255, 126, 95, 0.35)', primary: '#ff7e5f' },
  purple: { border: 'rgba(181, 23, 158, 0.85)', glow: 'rgba(181, 23, 158, 0.35)', primary: '#b5179e' },
  rose: { border: 'rgba(255, 65, 108, 0.85)', glow: 'rgba(255, 65, 108, 0.35)', primary: '#ff416c' },
  gold: { border: 'rgba(255, 215, 0, 0.9)', glow: 'rgba(245, 159, 0, 0.4)', primary: '#ffd700' },
  aurora: { border: 'rgba(0, 242, 254, 0.9)', glow: 'rgba(0, 242, 254, 0.45)', primary: '#00f2fe' },
  sunset_grad: { border: 'rgba(253, 160, 133, 0.9)', glow: 'rgba(253, 160, 133, 0.45)', primary: '#fda085' },
  cyberpunk: { border: 'rgba(240, 147, 251, 0.9)', glow: 'rgba(240, 147, 251, 0.45)', primary: '#f093fb' },
  cosmic: { border: 'rgba(94, 231, 223, 0.9)', glow: 'rgba(94, 231, 223, 0.45)', primary: '#5ee7df' }
};

function getAuraCardStyle(auraId, isSelf, isDark = true) {
  const a = AURA_STYLES[auraId] || (isSelf ? AURA_STYLES.emerald : null);
  if (!a) {
    return {
      border: isDark ? 'rgba(255, 255, 255, 0.18)' : 'rgba(18, 61, 48, 0.12)',
      glow: isDark ? 'none' : '0 2px 8px rgba(18, 61, 48, 0.04)'
    };
  }
  return {
    border: a.border,
    glow: `0 4px 16px ${a.glow}`
  };
}

function getSelfPresenceData() {
  const curSession = session || (typeof window !== 'undefined' && window.session);
  const myStreak = getUserStudyStreak();
  const goalInput = $("#studyGoalInput");
  const goalText = (studyState.goal && studyState.goal.trim()) ? studyState.goal.trim() : (goalInput ? goalInput.value.trim() : "") || "Nghiên cứu khoa học";
  const userTier = (curSession && curSession.streakTier !== undefined) ? curSession.streakTier : (myStreak >= 50 ? 5 : (myStreak >= 30 ? 4 : (myStreak >= 14 ? 3 : (myStreak >= 7 ? 2 : (myStreak >= 3 ? 1 : 0)))));

  return {
    userId: curSession ? curSession.id : 0,
    name: curSession ? curSession.displayName : "Bạn",
    role: curSession ? curSession.role : "student",
    avatar: curSession ? (curSession.avatar || curSession.initials || (curSession.role === 'admin' ? '🛡️' : (curSession.role === 'ta' ? '🎓' : '🦊'))) : "🦊",
    streak: myStreak,
    streakTier: userTier,
    goal: goalText,
    mode: studyState.mode || 'focus',
    durationMinutes: studyState.durationMinutes || 25,
    remainingSeconds: studyState.remainingSeconds,
    cycleIndex: studyState.cycleIndex || 1,
    isRunning: Boolean(studyState.isRunning),
    wallpaper: studySettings.activeWallpaper || 'default',
    aura: studySettings.activeAura || 'emerald',
    isSelf: true
  };
}

let lastRenderedCoStudySig = "";

function updateAllCoStudyCards(rawLearners = []) {
  const list = $("#coStudyList");
  if (!list) return;

  const learners = Array.isArray(rawLearners) ? [...rawLearners] : [];
  const selfData = getSelfPresenceData();
  const curSession = session || (typeof window !== 'undefined' && window.session);

  const selfIdx = learners.findIndex(l => l.isSelf || (curSession && l.userId === curSession.id));
  if (selfIdx >= 0) {
    learners[selfIdx] = selfData;
  } else {
    learners.unshift(selfData);
  }

  learners.forEach(l => {
    const card = list.querySelector(`.co-study-item[data-learner-user-id="${l.userId}"]`);
    if (!card) return;

    let statusText = '';
    let statusIcon = '';
    if (l.isRunning) {
      const remainingMin = Math.max(1, Math.ceil((l.remainingSeconds || 0) / 60));
      if (l.mode === 'shortbreak') {
        statusIcon = '☕';
        statusText = `${remainingMin}m`;
      } else if (l.mode === 'longbreak') {
        statusIcon = '🌿';
        statusText = `${remainingMin}m`;
      } else {
        statusIcon = '🔥';
        statusText = `${remainingMin}m`;
      }
    } else {
      if (l.remainingSeconds < (l.durationMinutes * 60) && l.remainingSeconds > 0) {
        statusIcon = '⏸️';
        statusText = 'Tạm dừng';
      } else {
        statusIcon = '✨';
        statusText = 'Sẵn sàng';
      }
    }

    const badgeEl = card.querySelector(".co-study-status-badge");
    const timeEl = card.querySelector(".co-study-time");
    const goalEl = card.querySelector(".co-study-goal");

    if (badgeEl) {
      const targetClass = `co-study-status-badge ${l.isRunning ? 'running' : 'idle'}`;
      if (badgeEl.className !== targetClass) {
        badgeEl.className = targetClass;
      }
    }
    if (timeEl) {
      const newHtml = `${statusIcon} ${statusText}`;
      if (timeEl.innerHTML !== newHtml) {
        timeEl.innerHTML = newHtml;
      }
    }
    if (goalEl) {
      const newGoal = `🎯 ${escapeHTML(l.goal || 'Nghiên cứu khoa học')}`;
      if (goalEl.innerHTML !== newGoal) {
        goalEl.innerHTML = newGoal;
      }
    }
  });

  const activeCount = learners.filter(l => Boolean(l.isRunning)).length;
  const totalCount = learners.length;
  const badge1 = $("#studyLiveCount");
  const badge2 = $("#coStudyCountBadge");
  if (badge1) badge1.textContent = totalCampusLearnersCount > 0 ? totalCampusLearnersCount : activeCount;
  if (badge2) badge2.textContent = `${totalCount} người trong phòng`;
}

function updateSelfCoStudyCard() {
  updateAllCoStudyCards(lastFetchedLearners);
}

function renderCoStudyList(rawLearners = [], force = false) {
  let learners = Array.isArray(rawLearners) ? [...rawLearners] : [];
  const curSession = session || (typeof window !== 'undefined' && window.session);
  const myStreak = getUserStudyStreak();

  // Find self if already in list and replace with live local state, or unshift self
  const selfIdx = learners.findIndex(l => l.isSelf || (curSession && l.userId === curSession.id));
  const selfData = getSelfPresenceData();

  if (selfIdx >= 0) {
    learners.splice(selfIdx, 1);
  }
  // Always guarantee self is at the top of the shared study room
  learners.unshift(selfData);

  const activeCount = learners.filter(l => Boolean(l.isRunning)).length;
  const totalCount = learners.length;
  const badge1 = $("#studyLiveCount");
  const badge2 = $("#coStudyCountBadge");
  if (badge1) badge1.textContent = totalCampusLearnersCount > 0 ? totalCampusLearnersCount : activeCount;
  if (badge2) badge2.textContent = `${totalCount} người trong phòng`;

  const list = $("#coStudyList");
  if (!list) return;

  // Generate a signature of learners data to avoid resetting DOM & CSS animations if unchanged
  const sig = learners.map(l => `${l.userId}_${l.name}_${l.streakTier}_${l.goal}_${l.isRunning}_${l.mode}_${l.wallpaper}_${l.aura}_${Math.ceil((l.remainingSeconds || 0) / 60)}`).join("|");
  if (!force && sig === lastRenderedCoStudySig && list.children.length === learners.length) {
    // If only timer or minor state changed for learners, do an in-place update without re-creating nodes
    updateAllCoStudyCards(learners);
    return;
  }
  lastRenderedCoStudySig = sig;

  const canCheer = myStreak >= 3;

  list.innerHTML = learners.map(l => {
    const isSelfClass = l.isSelf ? 'is-self' : '';
    const nameDisplay = l.isSelf ? `${escapeHTML(l.name)} (Bạn)` : escapeHTML(l.name);
    const roleBadge = l.role === 'admin' ? '<span class="lb-role lb-role-admin">Admin</span>' : (l.role === 'ta' ? '<span class="lb-role lb-role-ta">TA</span>' : '');

    let statusText = '';
    let statusIcon = '';
    if (l.isRunning) {
      const remainingMin = Math.max(1, Math.ceil((l.remainingSeconds || 0) / 60));
      if (l.mode === 'shortbreak') {
        statusIcon = '☕';
        statusText = `${remainingMin}m`;
      } else if (l.mode === 'longbreak') {
        statusIcon = '🌿';
        statusText = `${remainingMin}m`;
      } else {
        statusIcon = '🔥';
        statusText = `${remainingMin}m`;
      }
    } else {
      if (l.remainingSeconds < (l.durationMinutes * 60) && l.remainingSeconds > 0) {
        statusIcon = '⏸️';
        statusText = 'Tạm dừng';
      } else {
        statusIcon = '✨';
        statusText = 'Sẵn sàng';
      }
    }

    const cardInfo = getWallpaperCardInfo(l.wallpaper, l.isSelf);
    const auraStyle = getAuraCardStyle(l.aura, l.isSelf, cardInfo.isDark);
    const cardThemeClass = cardInfo.isDark ? 'theme-dark-card' : 'theme-light-card';
    const cardInlineStyle = `background: ${cardInfo.gradient}; border: 1.5px solid ${auraStyle.border}; box-shadow: ${auraStyle.glow};`;
    const avatarClass = getAvatarClass(l.streakTier, false, l.role);
    const nameClass = getNameClass(l.streakTier);

    return `
      <div class="co-study-item ${isSelfClass} ${cardThemeClass}" data-learner-user-id="${l.userId}" style="${cardInlineStyle}">
        <div class="co-study-header-row">
          <span class="avatar avatar-sm ${avatarClass}" data-namecard-user-id="${l.userId}" style="cursor: pointer;" title="Xem thẻ tên">${escapeHTML(l.avatar || '🦊')}</span>
          <div class="co-study-info">
            <div class="co-study-name">
              <span class="co-study-user-title ${nameClass}" data-namecard-user-id="${l.userId}" style="cursor: pointer;" title="Xem thẻ tên">${nameDisplay}</span> ${roleBadge}
            </div>
            <div class="co-study-goal">🎯 ${escapeHTML(l.goal || 'Nghiên cứu khoa học')}</div>
          </div>
          <div class="co-study-status-badge ${l.isRunning ? 'running' : 'idle'}">
            <span class="co-study-time">${statusIcon} ${statusText}</span>
          </div>
        </div>
        ${!l.isSelf && curSession ? `
          <div class="co-study-cheers-row">
            <span class="co-study-cheers-label">Gửi cổ vũ:</span>
            <div class="co-study-cheers">
              <button class="cheer-btn ${canCheer ? '' : 'locked'}" title="${canCheer ? 'Vỗ tay tán thưởng' : 'Mở khóa ở chuỗi 3 ngày 🔥'}" onclick="${canCheer ? `sendStudyCheer(${l.userId}, '👏')` : 'notifyCheerLocked()'}">👏</button>
              <button class="cheer-btn ${canCheer ? '' : 'locked'}" title="${canCheer ? 'Mời cà phê tỉnh táo' : 'Mở khóa ở chuỗi 3 ngày 🔥'}" onclick="${canCheer ? `sendStudyCheer(${l.userId}, '☕')` : 'notifyCheerLocked()'}">☕</button>
              <button class="cheer-btn ${canCheer ? '' : 'locked'}" title="${canCheer ? 'Tiếp lửa quyết tâm' : 'Mở khóa ở chuỗi 3 ngày 🔥'}" onclick="${canCheer ? `sendStudyCheer(${l.userId}, '🔥')` : 'notifyCheerLocked()'}">🔥</button>
              <button class="cheer-btn ${canCheer ? '' : 'locked'}" title="${canCheer ? 'Gửi tim yêu thương' : 'Mở khóa ở chuỗi 3 ngày 🔥'}" onclick="${canCheer ? `sendStudyCheer(${l.userId}, '❤️')` : 'notifyCheerLocked()'}">❤️</button>
              <button class="cheer-btn ${canCheer ? '' : 'locked'}" title="${canCheer ? 'Gợi ý ý tưởng sáng tạo' : 'Mở khóa ở chuỗi 3 ngày 🔥'}" onclick="${canCheer ? `sendStudyCheer(${l.userId}, '💡')` : 'notifyCheerLocked()'}">💡</button>
              <button class="cheer-btn ${canCheer ? '' : 'locked'}" title="${canCheer ? 'Tăng tốc về đích' : 'Mở khóa ở chuỗi 3 ngày 🔥'}" onclick="${canCheer ? `sendStudyCheer(${l.userId}, '🚀')` : 'notifyCheerLocked()'}">🚀</button>
            </div>
          </div>
        ` : ''}
      </div>
    `;
  }).join("");
}

async function fetchStudyLounge() {
  if (!canAccessStudyLounge()) return;
  try {
    const qRoom = encodeURIComponent(currentStudyRoomId || 'commons');
    const res = await requestAPI(`/api/study/lounge?roomId=${qRoom}`);
    if (!res) return;

    lastFetchedLearners = res.learners || [];
    if (res.totalCampusLearners !== undefined) {
      totalCampusLearnersCount = res.totalCampusLearners;
    }
    if (res.currentRoom) {
      currentStudyRoomData = res.currentRoom;
      currentStudyRoomId = res.currentRoom.id;
    }
    if (res.meetingRooms) {
      cachedMeetingRooms = res.meetingRooms;
      const cntEl = $("#countMeetingRooms");
      if (cntEl) cntEl.textContent = cachedMeetingRooms.length;
      if (activeStudySpaceTab === 'meeting') {
        renderMeetingRoomsList();
      }
    }
    if (res.libraryRooms) {
      res.libraryRooms.forEach(lr => {
        cachedLibraryOccupancies[lr.id] = lr.occupancy;
      });
      if (activeStudySpaceTab === 'library') {
        renderLibraryRoomsGrid();
      }
    }
    if (res.privatePodsCount !== undefined) {
      const privEl = $("#activePrivatePodsCount");
      if (privEl) privEl.textContent = res.privatePodsCount;
    }

    renderActiveSpaceBanner(currentStudyRoomData);
    renderSharedCohortTasks(currentStudyRoomData ? currentStudyRoomData.sharedTasks : []);

    const liveHeaderBadge = $("#studyLiveCount");
    if (liveHeaderBadge) {
      liveHeaderBadge.textContent = (typeof totalCampusLearnersCount === 'number')
        ? totalCampusLearnersCount
        : lastFetchedLearners.filter(l => Boolean(l.isRunning)).length;
    }

    renderCoStudyList(lastFetchedLearners);

    // 1. Đồng bộ đồng hồ Phòng Thư viện 24/7
    if (currentStudyRoomId && currentStudyRoomId.startsWith('lib_')) {
      const cfg = LIBRARY_ROOM_CONFIGS.find(c => c.id === currentStudyRoomId) || LIBRARY_ROOM_CONFIGS[0];
      const live = getLibraryLiveState(cfg.focus, cfg.break);
      studyState.mode = live.isFocus ? 'focus' : 'shortbreak';
      studyState.durationMinutes = live.isFocus ? cfg.focus : cfg.break;
      studyState.targetEndMs = live.targetEndMs;
      studyState.isRunning = true;
      if (!studyState.timerInterval) {
        studyState.remainingSeconds = live.remainingSec;
        startLocalTimerTick();
        updateTimerDisplay();
      }
    }
    // 2. Đồng bộ đồng hồ Phòng Học Nhóm theo Chủ phòng (dành cho thành viên)
    else if (currentStudyRoomData && currentStudyRoomData.type === 'meeting' && !currentStudyRoomData.isHost) {
      applyMeetingRoomTimerState(currentStudyRoomData.timerState);
    }
    // 3. Đồng bộ cá nhân đa thiết bị (chỉ áp dụng khi máy hiện tại chưa chạy timer)
    else if (res.mySession) {
      const s = res.mySession;
      const now = Date.now();
      if (s.isRunning) {
        const serverRemaining = Math.max(0, Math.ceil((s.targetEndMs - now) / 1000));
        if (!studyState.isRunning) {
          studyState.mode = s.mode;
          studyState.durationMinutes = s.durationMinutes;
          studyState.remainingSeconds = serverRemaining;
          studyState.targetEndMs = s.targetEndMs;
          studyState.cycleIndex = s.cycleIndex || 1;
          studyState.goal = s.goal || '';

          const goalInput = $("#studyGoalInput");
          if (goalInput && !goalInput.matches(":focus")) {
            goalInput.value = studyState.goal;
          }

          startLocalTimerTick();
          updateTimerDisplay();
        }
      } else {
        if (studyState.isRunning && (now - studyState.lastSyncMs > 15000) && (!s.targetEndMs || s.targetEndMs < now)) {
          // Chỉ pause khi session server thực sự hết hạn hoặc dừng từ thiết bị khác
          if (Date.now() - studyState.startedAtMs > 20000) {
            pauseStudyTimer(false);
            studyState.remainingSeconds = s.remainingSeconds;
            updateTimerDisplay();
          }
        }
      }
    }

    if (res.myCheers && res.myCheers.length > 0) {
      res.myCheers.forEach(c => {
        showCheerToast(c);
      });
    }
  } catch (e) {
    console.error("fetchStudyLounge error:", e);
    renderCoStudyList(lastFetchedLearners);
  }
}

/* --- FLEXIBLE STUDY SPACES & COHORT DESKS HANDLERS --- */
function renderActiveSpaceBanner(room) {
  if (!room) {
    const isLib = Boolean(currentStudyRoomId && currentStudyRoomId.startsWith('lib_'));
    const cfg = isLib ? (typeof LIBRARY_ROOM_CONFIGS !== 'undefined' ? LIBRARY_ROOM_CONFIGS.find(c => c.id === currentStudyRoomId) : null) : null;
    const isMeeting = Boolean(currentStudyRoomId && currentStudyRoomId !== 'commons' && currentStudyRoomId !== 'private');
    room = {
      id: currentStudyRoomId || 'private',
      name: cfg ? cfg.name : (isMeeting ? 'Phòng học nhóm' : 'Phòng học cá nhân'),
      type: isLib ? 'library' : (isMeeting ? 'meeting' : 'private'),
      description: cfg ? cfg.desc : (isMeeting ? 'Phòng học nhóm đang hoạt động' : 'Không gian học một mình hoàn toàn riêng tư, tự do tập trung và quản lý ca học của bạn'),
      icon: isLib ? '📖' : (isMeeting ? '👥' : '🔒'),
      max_seats: cfg ? cfg.max_seats : 1,
      occupancy: 1
    };
  }

  const browseView = $("#studySpacesBrowseView");
  const activeView = $("#studyActiveRoomView");

  if (!currentStudyRoomId || currentStudyRoomId === 'commons' || currentStudyRoomId === 'private') {
    if (browseView) browseView.style.display = 'block';
    if (activeView) activeView.style.display = 'none';
    return;
  }

  // Inside a room: hide all other room cards, show ONLY active room view with Exit button
  if (browseView) browseView.style.display = 'none';
  if (activeView) activeView.style.display = 'block';

  const iconEl = $("#activeSpaceIcon");
  const titleEl = $("#activeSpaceTitle");
  const badgeEl = $("#activeSpaceBadge");
  const descEl = $("#activeSpaceDesc");
  const seatsEl = $("#activeSpaceSeatsCount");
  const shareToolbar = $("#meetingShareToolbar");
  const tasksBox = $("#sharedCohortTasksBox");
  const codeText = $("#currentMeetingCodeText");

  if (iconEl) {
    let iconSvg = '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"></path><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"></path></svg>';
    if (room.type === 'meeting') {
      iconSvg = '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><path d="M23 21v-2a4 4 0 0 0-3-3.87"></path><path d="M16 3.13a4 4 0 0 1 0 7.75"></path></svg>';
    } else if (room.type === 'private' || (room.id && room.id.startsWith('private_'))) {
      iconSvg = '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path></svg>';
    }
    iconEl.innerHTML = iconSvg;
  }

  if (titleEl) titleEl.textContent = room.name || 'Phòng học cá nhân';

  if (badgeEl) {
    if (room.type === 'meeting') {
      badgeEl.className = 'active-space-badge badge-shared';
      badgeEl.textContent = 'Phòng học nhóm';
    } else if (room.type === 'private' || (room.id && room.id.startsWith('private_'))) {
      badgeEl.className = 'active-space-badge badge-private';
      badgeEl.textContent = 'Phòng học cá nhân';
    } else {
      badgeEl.className = 'active-space-badge badge-commons';
      badgeEl.textContent = 'Thư viện 24/7';
    }
  }

  if (descEl) {
    if (room.type === 'meeting') {
      descEl.textContent = room.hostName ? `Chủ phòng: ${room.hostName}` : 'Phòng học nhóm đồng bộ';
    } else if (room.type === 'private' || (room.id && room.id.startsWith('private_'))) {
      descEl.textContent = 'Không gian học cá nhân bảo mật tuyệt đối';
    } else {
      descEl.textContent = room.description || 'Đồng hồ tuần hoàn tự động 24/7';
    }
  }

  const occ = room.occupancy !== undefined ? room.occupancy : (lastFetchedLearners.length || 1);
  if (seatsEl) {
    seatsEl.textContent = `${occ} người`;
  }

  const personalTasksSection = $("#integratedPersonalTasksSection");
  const personalHeading = $("#personalTodoHeadingText");

  if (room.type === 'meeting') {
    if (shareToolbar) shareToolbar.style.display = 'flex';
    if (codeText) codeText.textContent = room.id || '0000';
    if (tasksBox) tasksBox.style.display = 'block';
    if (personalTasksSection) personalTasksSection.style.display = 'none';
  } else {
    if (shareToolbar) shareToolbar.style.display = 'none';
    if (tasksBox) tasksBox.style.display = 'none';
    if (personalTasksSection) {
      personalTasksSection.style.display = 'block';
      if (personalHeading) {
        personalHeading.textContent = currentStudyRoomId ? 'Việc cần làm của bạn' : 'Những việc cần làm';
      }
    }
  }
}

function togglePersonalTasksCollapse(forceState) {
  const body = $("#personalTasksBodyWrap");
  const btn = $("#btnTogglePersonalTasks");
  const icon = $("#iconTogglePersonalTasks");
  if (!body) return;
  const isCurrentlyHidden = (body.style.display === "none");
  const willShow = (forceState !== undefined) ? forceState : isCurrentlyHidden;
  body.style.display = willShow ? "block" : "none";
  if (btn) btn.title = willShow ? "Thu gọn danh sách việc" : "Mở rộng danh sách việc";
  if (icon) {
    icon.innerHTML = willShow
      ? '<polyline points="18 15 12 9 6 15"></polyline>'
      : '<polyline points="6 9 12 15 18 9"></polyline>';
  }
}
window.togglePersonalTasksCollapse = togglePersonalTasksCollapse;

function renderSharedCohortTasks(tasks = []) {
  const box = $("#sharedCohortTasksBox");
  if (!box) return;

  if (!currentStudyRoomData || currentStudyRoomData.type !== 'meeting') {
    box.style.display = 'none';
    return;
  }
  box.style.display = 'block';

  const taskList = Array.isArray(tasks) ? tasks : [];
  const total = taskList.length;

  let totalWeight = 0;
  taskList.forEach(t => {
    if (t.done || t.status === "hoan_thanh") {
      totalWeight += 1.0;
    } else {
      const st = (typeof STUDY_TASK_STATUSES !== 'undefined' ? STUDY_TASK_STATUSES : []).find(s => s.id === t.status);
      totalWeight += st ? (st.weight || 0) : 0;
    }
  });
  const pct = total > 0 ? Math.min(100, Math.round((totalWeight / total) * 100)) : 0;
  const doneCount = taskList.filter(t => t.done || t.status === "hoan_thanh").length;

  const pctBadge = $("#sharedTaskPctBadge");
  const progressFill = $("#sharedTaskProgressFill");
  if (pctBadge) pctBadge.textContent = `${pct}% (${doneCount}/${total})`;
  if (progressFill) progressFill.style.width = `${pct}%`;

  const listEl = $("#sharedTasksList");
  if (!listEl) return;

  if (total === 0) {
    listEl.innerHTML = `<li class="todo-item" style="color:var(--muted); font-size:12px; justify-content:center;">Chưa có nhiệm vụ chung nào. Bấm [+] để thêm việc cho cả phòng!</li>`;
    return;
  }

  listEl.innerHTML = taskList.map(t => {
    const isDone = Boolean(t.done || t.status === "hoan_thanh");
    const statusId = t.status || (isDone ? "hoan_thanh" : "chua_lam");
    const statusObj = (typeof STUDY_TASK_STATUSES !== 'undefined' ? STUDY_TASK_STATUSES : []).find(s => s.id === statusId) || { label: "Chưa làm", color: "#94a3b8" };
    const safeId = escapeHTML(String(t.id));

    let tagHtml = "";
    if (t.tagId && studySettings.taskLabels) {
      const tag = studySettings.taskLabels.find(l => l.id === t.tagId);
      if (tag) {
        tagHtml = `<span class="todo-tag-pill" style="background-color: ${tag.color};">${escapeHTML(tag.name)}</span>`;
      }
    }

    const editor = t.lastEditedBy || {};
    const editorName = editor.name || t.by || "Thành viên phòng";
    const editorAvatar = editor.avatar || "🦊";
    const editorTitle = `Chỉnh sửa gần nhất bởi ${editorName}`;

    return `
      <li class="todo-item ${isDone ? 'done' : ''}">
        <input type="checkbox" ${isDone ? 'checked' : ''} onchange="toggleSharedRoomTask('${safeId}')" title="Đánh dấu hoàn thành" />
        <button type="button" class="todo-status-badge" style="background: ${statusObj.color}20; color: ${statusObj.color}; border-color: ${statusObj.color}66;" onclick="cycleSharedTaskStatus('${safeId}')" title="Nhấp để chuyển trạng thái (${statusObj.label})">
          <span style="display:inline-block; width:6px; height:6px; border-radius:50%; background:${statusObj.color}; margin-right:4px;"></span>${statusObj.label}
        </button>
        <span class="todo-item-text">${escapeHTML(t.text)}</span>
        ${tagHtml}
        <span class="shared-task-editor-avatar" title="${escapeHTML(editorTitle)}" style="font-size:13px; margin-left:auto; display:inline-flex; align-items:center; justify-content:center; width:22px; height:22px; border-radius:50%; background:rgba(0,0,0,0.06); cursor:help; flex-shrink:0;">
          ${escapeHTML(editorAvatar)}
        </span>
        <button type="button" class="todo-del-btn" onclick="deleteSharedRoomTask('${safeId}')" title="Xóa việc">×</button>
      </li>
    `;
  }).join('');
}

async function cycleSharedTaskStatus(taskId) {
  if (!session) {
    openAuth();
    return;
  }
  try {
    const res = await requestAPI("/api/study/rooms/task/cycle-status", {
      method: "POST",
      body: JSON.stringify({
        roomId: currentStudyRoomId,
        taskId: String(taskId)
      })
    });
    if (res && res.success) {
      const updatedTasks = res.sharedTasks || res.tasks || [];
      if (currentStudyRoomData) {
        currentStudyRoomData.sharedTasks = updatedTasks;
      }
      renderSharedCohortTasks(updatedTasks);
    } else {
      toast(res.error || "Không thể cập nhật trạng thái nhiệm vụ.");
    }
  } catch (e) {
    console.error("cycleSharedTaskStatus error:", e);
  }
}
window.cycleSharedTaskStatus = cycleSharedTaskStatus;

async function deleteSharedRoomTask(taskId) {
  if (!session) {
    openAuth();
    return;
  }
  try {
    const res = await requestAPI("/api/study/rooms/task/delete", {
      method: "POST",
      body: JSON.stringify({
        roomId: currentStudyRoomId,
        taskId: String(taskId)
      })
    });
    if (res && res.success) {
      const updatedTasks = res.sharedTasks || res.tasks || [];
      if (currentStudyRoomData) {
        currentStudyRoomData.sharedTasks = updatedTasks;
      }
      renderSharedCohortTasks(updatedTasks);
      toast("Đã xóa nhiệm vụ.");
    } else {
      toast(res.error || "Không thể xóa nhiệm vụ.");
    }
  } catch (e) {
    console.error("deleteSharedRoomTask error:", e);
  }
}
window.deleteSharedRoomTask = deleteSharedRoomTask;

/* ==========================================================================
   3 FUNCTIONAL STUDY SPACES: LIBRARY (24/7), MEETING ROOMS & PRIVATE PODS
   ========================================================================== */
const LIBRARY_ROOM_CONFIGS = [
  {
    id: 'lib_study_25_5',
    name: 'Khu vực tự học',
    preset: '25/5',
    desc: 'Theo phương pháp Pomodoro cơ bản, thư giãn học tập',
    focus: 25,
    break: 5,
    icon: '📖'
  },
  {
    id: 'lib_reading_50_10',
    name: 'Khu vực đọc sách',
    preset: '50/10',
    desc: 'Tập trung sâu hơn, làm nhiều việc hơn',
    focus: 50,
    break: 10,
    icon: '📚'
  },
  {
    id: 'lib_lounge_15_5',
    name: 'Khu vực sảnh',
    preset: '15/5',
    desc: 'Làm việc nhanh, dành cho những ngày nhẹ nhàng',
    focus: 15,
    break: 5,
    icon: '☕'
  }
];

function getLibraryLiveState(focusMins, breakMins, nowMs = Date.now()) {
  const cycleSec = (focusMins + breakMins) * 60;
  const secInCycle = Math.floor(nowMs / 1000) % cycleSec;
  const focusSec = focusMins * 60;
  const isFocus = secInCycle < focusSec;
  const remainingSec = isFocus ? (focusSec - secInCycle) : (cycleSec - secInCycle);
  const m = Math.floor(remainingSec / 60);
  const s = remainingSec % 60;
  return {
    isFocus,
    remainingSec,
    timeText: `${m}:${s < 10 ? '0' : ''}${s}`,
    minsLeft: Math.ceil(remainingSec / 60)
  };
}

let cachedLibraryOccupancies = {};
let cachedMeetingRooms = [];
let activeStudySpaceTab = 'private';

function renderLibraryRoomsGrid() {
  const container = $("#libraryRoomsGrid");
  if (!container) return;

  const html = LIBRARY_ROOM_CONFIGS.map(cfg => {
    const live = getLibraryLiveState(cfg.focus, cfg.break);
    const isCurrent = (currentStudyRoomId === cfg.id);
    const occ = cachedLibraryOccupancies[cfg.id] || (isCurrent ? 1 : 0);

    return `
      <div class="library-room-card ${isCurrent ? 'is-current' : ''}">
        <div class="library-room-info">
          <div class="library-room-title-row">
            <h4 class="library-room-title">${escapeHTML(cfg.name)}</h4>
            <span class="library-preset-pill">${cfg.preset}</span>
          </div>
          <p class="library-room-desc">${escapeHTML(cfg.desc)}</p>
          <div class="library-room-meta-row">
            <span class="library-live-status-pill ${live.isFocus ? 'mode-focus' : 'mode-break'}">
              <span class="live-pulse-dot"></span>
              ${live.isFocus ? 'Đang học' : 'Đang nghỉ giải lao'} · Còn ${live.timeText}
            </span>
            <span class="library-occupancy-text">${occ} người trong phòng</span>
          </div>
        </div>
        <div>
          ${isCurrent ? `
            <button type="button" class="button button-xs button-quiet" disabled style="font-weight:700;">✓ Đang ở phòng này</button>
          ` : `
            <button type="button" class="button button-xs button-primary btn-join-library-room" data-room-id="${cfg.id}" onclick="joinStudySpace('${cfg.id}')" style="display:inline-flex; align-items:center; gap:4px;">
              Tham gia →
            </button>
          `}
        </div>
      </div>
    `;
  }).join('');

  container.innerHTML = html;
}

function renderMeetingRoomsList() {
  const container = $("#meetingRoomsList");
  if (!container) return;

  if (cachedMeetingRooms.length === 0) {
    container.innerHTML = `
      <div style="text-align: center; padding: 24px 12px; color: var(--muted); background: var(--surface-bg); border-radius: 10px; border: 1px dashed var(--line);">
        <p style="font-size: 13px; margin-bottom: 8px;">Chưa có phòng học nhóm nào đang mở. Hãy tạo phòng học nhóm đầu tiên!</p>
        <button type="button" class="button button-xs button-primary" onclick="openCreateMeetingModal()">+ Tạo phòng học nhóm ngay</button>
      </div>
    `;
    return;
  }

  container.innerHTML = cachedMeetingRooms.map(r => {
    const isCurrent = (currentStudyRoomId === r.id);
    const occ = r.occupancy || 0;
    const taskCount = r.taskCount || (Array.isArray(r.sharedTasks) ? r.sharedTasks.length : 0);
    const hasPin = Boolean(r.requiresPin || r.has_pin);

    return `
      <div class="meeting-room-card ${isCurrent ? 'is-current' : ''}">
        <div style="flex: 1; min-width: 0;">
          <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-bottom: 3px;">
            <strong style="font-size: 13.5px; color: var(--ink);">${escapeHTML(r.name)}</strong>
            <span class="meeting-code-pill">
              ${hasPin ? `<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path></svg>` : ''}
              Mã: ${escapeHTML(r.id)}
            </span>
          </div>
          <div style="display: flex; align-items: center; gap: 10px; font-size: 11.5px; color: var(--muted); flex-wrap: wrap;">
            <span>Chủ phòng: <b style="color: var(--ink);">${escapeHTML(r.hostName || 'Thành viên')}</b></span>
            ${taskCount > 0 ? `<span style="color: var(--primary); font-weight: 600;">🎯 ${taskCount} nhiệm vụ</span>` : ''}
            <span>👥 ${occ} người</span>
          </div>
        </div>
        <div>
          ${isCurrent ? `
            <button type="button" class="button button-xs button-quiet" disabled style="font-weight:700;">✓ Đang ở phòng</button>
          ` : `
            <button type="button" class="button button-xs button-primary" onclick="prepareJoinMeetingRoom('${escapeHTML(r.id)}', ${hasPin})">
              Vào phòng →
            </button>
          `}
        </div>
      </div>
    `;
  }).join('');
}

function switchStudySpaceCategoryTab(tab) {
  activeStudySpaceTab = tab;
  $$(".space-filter-pill").forEach(p => {
    p.classList.toggle("active", p.dataset.spaceTab === tab);
  });
  const paneLib = $("#paneSpaceLibrary");
  const paneMeet = $("#paneSpaceMeeting");
  const panePriv = $("#paneSpacePrivate");

  if (paneLib) paneLib.style.display = (tab === 'library') ? 'block' : 'none';
  if (paneMeet) paneMeet.style.display = (tab === 'meeting') ? 'block' : 'none';
  if (panePriv) panePriv.style.display = (tab === 'private') ? 'block' : 'none';

  const personalTasksEl = $("#integratedPersonalTasksSection");
  if (personalTasksEl) {
    if (tab === 'private') {
      personalTasksEl.style.display = 'block';
    } else {
      personalTasksEl.style.display = 'none';
    }
  }

  if (tab === 'library') {
    renderLibraryRoomsGrid();
  } else if (tab === 'meeting') {
    renderMeetingRoomsList();
  }
}

async function loadAndRenderStudyRooms() {
  try {
    const res = await requestAPI("/api/study/rooms");
    if (!res) return;

    if (res.libraryRooms) {
      res.libraryRooms.forEach(lr => {
        cachedLibraryOccupancies[lr.id] = lr.occupancy;
      });
      renderLibraryRoomsGrid();
    }

    if (res.meetingRooms) {
      cachedMeetingRooms = res.meetingRooms;
      const cntEl = $("#countMeetingRooms");
      if (cntEl) cntEl.textContent = cachedMeetingRooms.length;
      renderMeetingRoomsList();
    }

    if (res.privatePodsCount !== undefined) {
      const privEl = $("#activePrivatePodsCount");
      if (privEl) privEl.textContent = res.privatePodsCount;
    }

    if (res.totalCampusLearners !== undefined) {
      const badge = $("#coStudyCountBadge");
      if (badge) badge.textContent = `${res.totalCampusLearners} đang học`;
    }
  } catch (e) {
    console.error("loadAndRenderStudyRooms error:", e);
    renderLibraryRoomsGrid();
  }
}

let pendingSwitchSpaceAction = null;

function requestSwitchStudySpace(actionFn, targetRoomName = "") {
  const isTimerActive = Boolean(
    studyState.isRunning ||
    (studyState.targetEndMs > 0 && studyState.remainingSeconds > 0) ||
    (studyState.elapsedSessionSeconds > 0)
  );

  if (!isTimerActive) {
    actionFn();
    return;
  }

  pendingSwitchSpaceAction = actionFn;
  const modal = document.getElementById("studySwitchSpaceConfirmModal");
  const msg = document.getElementById("switchSpaceConfirmMsg");
  if (msg) {
    if (targetRoomName) {
      msg.innerHTML = `Đồng hồ ca học của bạn hiện đang chạy. Khi chuyển sang <strong>${escapeHTML(targetRoomName)}</strong>, đồng hồ hiện tại sẽ được <strong>đặt lại (reset)</strong> và đồng bộ theo thời gian của phòng mới.`;
    } else {
      msg.innerHTML = `Đồng hồ ca học của bạn hiện đang chạy. Khi chuyển sang không gian mới, đồng hồ hiện tại sẽ được <strong>đặt lại (reset)</strong> và đồng bộ theo thời gian của phòng đó.`;
    }
  }

  if (modal && typeof modal.showModal === 'function') {
    modal.showModal();
  } else if (confirm("Đồng hồ đang chạy! Chuyển phòng sẽ reset và đồng bộ theo thời gian phòng mới. Bạn có muốn tiếp tục?")) {
    executeConfirmedSwitchSpace();
  }
}

function cancelSwitchSpaceModal() {
  pendingSwitchSpaceAction = null;
  const modal = document.getElementById("studySwitchSpaceConfirmModal");
  if (modal && typeof modal.close === 'function' && modal.open) {
    modal.close();
  }
}

async function executeConfirmedSwitchSpace() {
  const modal = document.getElementById("studySwitchSpaceConfirmModal");
  if (modal && typeof modal.close === 'function' && modal.open) {
    modal.close();
  }

  const action = pendingSwitchSpaceAction;
  pendingSwitchSpaceAction = null;

  // Reset timer to clean state before entering new room
  await pauseStudyTimer(false);
  studyState.isRunning = false;
  studyState.remainingSeconds = 0;
  studyState.durationMinutes = 0;
  studyState.targetEndMs = 0;
  studyState.elapsedSessionSeconds = 0;
  if (studyState.timerInterval) {
    clearInterval(studyState.timerInterval);
    studyState.timerInterval = null;
  }
  updateTimerDisplay();

  if (typeof action === 'function') {
    action();
  }
}

async function joinStudySpace(roomId, pinCode = null, skipConfirm = false) {
  if (!skipConfirm) {
    let targetName = "không gian học mới";
    if (roomId.startsWith('lib_')) {
      const cfg = LIBRARY_ROOM_CONFIGS.find(c => c.id === roomId);
      targetName = cfg ? cfg.name : "Phòng Thư viện 24/7";
    } else if (roomId.startsWith('meet_')) {
      const m = cachedMeetingRooms.find(r => r.id === roomId);
      targetName = m ? `Phòng học nhóm "${m.name}"` : `Phòng học nhóm #${roomId}`;
    } else if (roomId === 'private') {
      targetName = "Phòng học cá nhân";
    }
    requestSwitchStudySpace(() => joinStudySpace(roomId, pinCode, true), targetName);
    return;
  }
  if (!session) {
    pendingJoinMeetingId = roomId;
    openAuth();
    return;
  }
  try {
    const payload = { roomId };
    if (pinCode) payload.pinCode = pinCode;
    const res = await requestAPI("/api/study/rooms/join", {
      method: "POST",
      body: JSON.stringify(payload)
    });

    if (res && res.requiresPin) {
      pendingJoinMeetingId = roomId;
      const modal = document.getElementById("studyJoinPinModal");
      const desc = document.getElementById("joinPinRoomDesc");
      const input = document.getElementById("inputJoinPinCode");
      if (desc) desc.textContent = `Phòng học nhóm "${res.roomName || roomId}" được bảo vệ bởi mật khẩu 4 chữ số:`;
      if (input) input.value = "";
      if (modal && typeof modal.showModal === 'function') {
        modal.showModal();
        if (input) setTimeout(() => input.focus(), 100);
      }
      if (pinCode) {
        toast("Mật khẩu 4 chữ số chưa đúng. Vui lòng thử lại.");
      }
      return;
    }

    if (res && res.success) {
      currentStudyRoomId = res.room ? res.room.id : roomId;
      currentStudyRoomData = res.room || null;
      try {
        localStorage.setItem("research_study_room_id", currentStudyRoomId);
      } catch (e) { }

      // If this is a continuous library room, synchronize timer immediately
      if (currentStudyRoomId.startsWith('lib_')) {
        const cfg = LIBRARY_ROOM_CONFIGS.find(c => c.id === currentStudyRoomId) || LIBRARY_ROOM_CONFIGS[0];
        const live = getLibraryLiveState(cfg.focus, cfg.break);
        studyState.mode = live.isFocus ? 'focus' : 'shortbreak';
        studyState.durationMinutes = live.isFocus ? cfg.focus : cfg.break;
        studyState.remainingSeconds = live.remainingSec;
        studyState.targetEndMs = live.targetEndMs;
        studyState.isRunning = true;
        if (!studyState.timerInterval) {
          startLocalTimerTick();
        }
        updateTimerDisplay();
      } else if (res.room && res.room.type === 'meeting' && !res.room.isHost && res.room.timerState) {
        applyMeetingRoomTimerState(res.room.timerState);
      }

      renderActiveSpaceBanner(res.room);
      renderSharedCohortTasks(res.room ? (res.room.sharedTasks || []) : []);
      toast(`Đã vào: ${res.room ? res.room.name : currentStudyRoomId}`);
      fetchStudyLounge();
    } else {
      toast(res?.error || "Không thể vào phòng này.");
    }
  } catch (e) {
    console.error("joinStudySpace error:", e);
    toast("Lỗi khi tham gia không gian học.");
  }
}

function confirmLeaveCurrentRoom() {
  const modal = document.getElementById("studyExitConfirmModal");
  if (modal && typeof modal.showModal === 'function') {
    modal.showModal();
  } else if (confirm("Bạn có chắc chắn muốn rời khỏi phòng học hiện tại?")) {
    executeLeaveCurrentRoom();
  }
}

async function executeLeaveCurrentRoom() {
  const modal = document.getElementById("studyExitConfirmModal");
  if (modal && typeof modal.close === 'function' && modal.open) {
    modal.close();
  }
  try {
    await requestAPI("/api/study/rooms/leave", {
      method: "POST",
      body: JSON.stringify({ roomId: currentStudyRoomId })
    });
  } catch (e) { }

  currentStudyRoomId = null;
  currentStudyRoomData = null;
  try {
    localStorage.removeItem("research_study_room_id");
  } catch (e) { }

  // Khôi phục lại cấu hình cá nhân của người dùng từ localStorage khi rời phòng nhóm
  studySettings = getInitialStudySettings();

  // Reset timer to 0 on leaving room
  studyState.isRunning = false;
  studyState.remainingSeconds = 0;
  studyState.durationMinutes = 0;
  studyState.targetEndMs = 0;
  studyState.flowtimeElapsedSeconds = 0;
  studyState.elapsedSessionSeconds = 0;
  if (studyState.timerInterval) {
    clearInterval(studyState.timerInterval);
    studyState.timerInterval = null;
  }
  updateTimerDisplay();
  syncStudyToServer();

  const browseView = $("#studySpacesBrowseView");
  const activeView = $("#studyActiveRoomView");
  if (browseView) browseView.style.display = "block";
  if (activeView) activeView.style.display = "none";

  const personalTasksEl = $("#integratedPersonalTasksSection");
  if (personalTasksEl) {
    personalTasksEl.style.display = (activeStudySpaceTab === 'private') ? "block" : "none";
  }

  toast("Đã rời khỏi phòng học.");
  fetchStudyLounge();
  loadAndRenderStudyRooms();
}

let pendingJoinMeetingId = null;

function prepareJoinMeetingRoom(roomId, requiresPin, skipConfirm = false) {
  if (!skipConfirm) {
    const m = cachedMeetingRooms.find(r => r.id === roomId);
    const targetName = m ? `Phòng học nhóm "${m.name}"` : `Phòng học nhóm #${roomId}`;
    requestSwitchStudySpace(() => prepareJoinMeetingRoom(roomId, requiresPin, true), targetName);
    return;
  }
  if (!session) {
    openAuth();
    return;
  }
  if (requiresPin) {
    pendingJoinMeetingId = roomId;
    const modal = document.getElementById("studyJoinPinModal");
    const input = document.getElementById("inputJoinPinCode");
    if (input) input.value = "";
    if (modal && typeof modal.showModal === 'function') {
      modal.showModal();
      if (input) setTimeout(() => input.focus(), 100);
    }
  } else {
    joinStudySpace(roomId, null, true);
  }
}

function submitJoinPinRoom() {
  const input = document.getElementById("inputJoinPinCode");
  const pin = input ? input.value.trim() : "";
  if (!pin || pin.length < 4) {
    toast("Vui lòng nhập đúng mã PIN 4 số.");
    return;
  }
  const modal = document.getElementById("studyJoinPinModal");
  if (modal && typeof modal.close === 'function') {
    modal.close();
  }
  if (pendingJoinMeetingId) {
    joinStudySpace(pendingJoinMeetingId, pin);
    pendingJoinMeetingId = null;
  }
}

function handleQuickJoinMeetingSubmit() {
  const input = document.getElementById("inputQuickJoinCode");
  const code = input ? input.value.trim() : "";
  if (!code || code.length !== 4) {
    toast("Vui lòng nhập mã phòng gồm 4 chữ số.");
    if (input) input.focus();
    return;
  }
  const found = cachedMeetingRooms.find(r => r.id === code);
  const hasPin = found ? Boolean(found.requiresPin || found.has_pin) : false;
  prepareJoinMeetingRoom(code, hasPin);
}

function openCreateMeetingModal() {
  if (!session) {
    openAuth();
    return;
  }
  const modal = document.getElementById("studyCreateMeetingModal");
  if (modal && typeof modal.showModal === 'function') {
    modal.showModal();
    const nameInput = document.getElementById("inputMeetingName");
    if (nameInput) {
      nameInput.value = "";
      setTimeout(() => nameInput.focus(), 100);
    }
  }
}

async function handleCreateMeetingSubmit(skipConfirm = false) {
  if (!session) {
    openAuth();
    return;
  }
  if (!skipConfirm) {
    requestSwitchStudySpace(() => handleCreateMeetingSubmit(true), "Phòng học nhóm mới");
    return;
  }
  const nameEl = document.getElementById("inputMeetingName");
  const pinEl = document.getElementById("inputMeetingPin");
  const tasksEl = document.getElementById("inputMeetingTasks");

  const name = nameEl ? nameEl.value.trim() : "";
  if (!name) {
    toast("Vui lòng nhập tên phòng học nhóm.");
    if (nameEl) nameEl.focus();
    return;
  }
  const pinCode = pinEl ? pinEl.value.trim() : "";
  if (pinCode && pinCode.length !== 4) {
    toast("Mật khẩu phòng học nhóm phải gồm đúng 4 chữ số hoặc để trống.");
    if (pinEl) pinEl.focus();
    return;
  }

  const initialTasks = tasksEl ? tasksEl.value.split('\n').map(s => s.trim()).filter(Boolean) : [];

  try {
    const res = await requestAPI("/api/study/rooms/create", {
      method: "POST",
      body: JSON.stringify({
        name,
        type: 'meeting',
        pinCode: pinCode || null,
        initialTasks,
        timerPreset: studySettings.timerPreset || '25_5',
        focusMins: studySettings.focusMins || 25,
        shortBreakMins: studySettings.shortBreakMins || 5,
        longBreakMins: studySettings.longBreakMins || 15,
        longBreakInterval: studySettings.longBreakInterval || 4,
        flowtimeRatio: studySettings.flowtimeRatio || '1/4'
      })
    });
    if (res && res.success && res.room) {
      toast(`Đã tạo phòng học nhóm "${res.room.name}" (Mã: ${res.room.id})!`);
      const modal = document.getElementById("studyCreateMeetingModal");
      if (modal && typeof modal.close === 'function') {
        modal.close();
      }
      currentStudyRoomId = res.room.id;
      currentStudyRoomData = res.room;
      try {
        localStorage.setItem("research_study_room_id", currentStudyRoomId);
      } catch (e) { }
      renderActiveSpaceBanner(res.room);
      renderSharedCohortTasks(res.room.sharedTasks || []);
      fetchStudyLounge();
    } else {
      toast(res.error || "Không thể tạo phòng học nhóm.");
    }
  } catch (e) {
    console.error("handleCreateMeetingSubmit error:", e);
    toast("Lỗi khi tạo phòng học nhóm.");
  }
}

async function joinPrivateStudyPod() {
  if (!session) {
    openAuth();
    return;
  }
  await joinStudySpace('private');
}

function copyMeetingRoomCode() {
  if (!currentStudyRoomId) return;
  navigator.clipboard.writeText(currentStudyRoomId).then(() => {
    toast(`Đã sao chép mã phòng: ${currentStudyRoomId}`);
  }).catch(() => {
    toast(`Mã phòng: ${currentStudyRoomId}`);
  });
}

function copyMeetingRoomLink() {
  if (!currentStudyRoomId) return;
  const url = `${window.location.origin}${window.location.pathname}#study?room=${encodeURIComponent(currentStudyRoomId)}`;
  navigator.clipboard.writeText(url).then(() => {
    toast("Đã sao chép liên kết mời vào phòng!");
  }).catch(() => {
    toast(`Liên kết: ${url}`);
  });
}

function checkUrlStudyRoomParam() {
  const hash = window.location.hash || '';
  const search = window.location.search || '';
  let roomId = null;
  const hashMatch = hash.match(/[?&]room=([^&]+)/);
  if (hashMatch) {
    roomId = decodeURIComponent(hashMatch[1]);
  } else {
    const searchMatch = search.match(/[?&]room=([^&]+)/);
    if (searchMatch) roomId = decodeURIComponent(searchMatch[1]);
  }

  if (roomId && (!currentStudyRoomId || currentStudyRoomId !== roomId)) {
    if (typeof currentActiveRoute !== "undefined" && currentActiveRoute !== "study" && typeof go === "function") {
      go("study", false);
    }
    setTimeout(() => {
      if (!session) {
        pendingJoinMeetingId = roomId;
        toast(`Bạn nhận được liên kết tham gia phòng học ${roomId}. Vui lòng đăng nhập để vào phòng!`);
        openAuth();
        return;
      }
      joinStudySpace(roomId);
    }, 250);
  }
}

async function toggleSharedRoomTask(taskId) {
  if (!session) {
    openAuth();
    return;
  }
  try {
    const res = await requestAPI("/api/study/rooms/task/toggle", {
      method: "POST",
      body: JSON.stringify({
        roomId: currentStudyRoomId,
        taskId: String(taskId)
      })
    });
    if (res && res.success) {
      const updatedTasks = res.sharedTasks || res.tasks || [];
      if (currentStudyRoomData) {
        currentStudyRoomData.sharedTasks = updatedTasks;
      }
      renderSharedCohortTasks(updatedTasks);
      if (res.completed) {
        toast(`🎉 Đã hoàn thành nhiệm vụ chung!`);
      }
    } else {
      toast(res.error || "Không thể cập nhật nhiệm vụ.");
      fetchStudyLounge();
    }
  } catch (e) {
    console.error("toggleSharedRoomTask error:", e);
  }
}

function toggleAddSharedTaskInput() {
  const row = document.getElementById("sharedTaskAddRow");
  const input = document.getElementById("newSharedTaskInput");
  if (!row) return;
  const isHidden = (row.style.display === 'none' || !row.style.display);
  row.style.display = isHidden ? 'flex' : 'none';
  if (isHidden && input) {
    input.focus();
  }
}

async function submitNewSharedTask() {
  if (!session) {
    openAuth();
    return;
  }
  const input = document.getElementById("newSharedTaskInput");
  const tagSelect = document.getElementById("newSharedTaskTagSelect");
  if (!input) return;
  const text = input.value.trim();
  if (!text) {
    input.focus();
    return;
  }
  const tagId = tagSelect ? tagSelect.value : "";

  try {
    const res = await requestAPI("/api/study/rooms/task/add", {
      method: "POST",
      body: JSON.stringify({
        roomId: currentStudyRoomId,
        text: text,
        taskText: text,
        tagId: tagId,
        status: "chuan_bi"
      })
    });
    if (res && res.success) {
      input.value = "";
      toggleAddSharedTaskInput();
      const updatedTasks = res.sharedTasks || res.tasks || [];
      if (currentStudyRoomData) {
        currentStudyRoomData.sharedTasks = updatedTasks;
      }
      renderSharedCohortTasks(updatedTasks);
      toast("Đã thêm nhiệm vụ chung vào phòng!");
    } else {
      toast(res.error || "Không thể thêm nhiệm vụ.");
    }
  } catch (e) {
    console.error("submitNewSharedTask error:", e);
  }
}

