function renderColorPalette() {
  const cont = $("#colorPalettePicker");
  if (!cont) return;
  const streak = getUserStudyStreak();

  const existingSwatches = cont.querySelectorAll(".color-swatch");
  if (existingSwatches.length === COLOR_AURAS.length) {
    existingSwatches.forEach((btn, idx) => {
      const c = COLOR_AURAS[idx];
      if (!c) return;
      const isSelected = (studySettings.activeAura === c.id);
      const isUnlocked = (idx === 0 || streak >= 7);
      const reqDays = 7;

      btn.classList.toggle("active", isSelected);
      btn.classList.toggle("locked", !isUnlocked);
      const clickAction = isUnlocked
        ? `applyColorAura('${c.id}')`
        : `notifyPerkLocked(${reqDays}, 'Phối màu ${escapeHTML(c.name)}')`;
      btn.setAttribute("onclick", clickAction);
    });
    return;
  }

  cont.innerHTML = COLOR_AURAS.map((c, idx) => {
    const isSelected = (studySettings.activeAura === c.id);
    const isUnlocked = (idx === 0 || streak >= 7);
    const reqDays = 7;

    const clickAction = isUnlocked
      ? `applyColorAura('${c.id}')`
      : `notifyPerkLocked(${reqDays}, 'Phối màu ${escapeHTML(c.name)}')`;

    return `
      <button type="button" class="color-swatch ${isSelected ? 'active' : ''} ${!isUnlocked ? 'locked' : ''}" style="background:${c.gradient};" title="${escapeHTML(c.name)}${!isUnlocked ? ` (Mở khóa ở Chuỗi ${reqDays} ngày)` : ''}" onclick="${clickAction}"></button>
    `;
  }).join("");
}

function applyColorAura(auraId) {
  const idx = COLOR_AURAS.findIndex(x => x.id === auraId);
  const c = idx !== -1 ? COLOR_AURAS[idx] : COLOR_AURAS[0];
  const streak = getUserStudyStreak();

  if (idx !== 0 && streak < 7) {
    notifyPerkLocked(7, `Phối màu ${c.name}`);
    return;
  }

  studySettings.activeAura = c.id;
  saveStudySettings(false);

  const studyEl = $("#study");
  if (studyEl) {
    studyEl.style.setProperty("--primary", c.primary);
    studyEl.style.setProperty("--primary-gradient", c.gradient);
    studyEl.style.setProperty("--primary-glow", c.glow);
  }

  // Tái áp dụng 3 bộ màu độc lập (Chính, Phụ, Phụ kiện) để đảm bảo đồng hồ và nút không bị đè màu
  applyStudyColorRoles();

  renderColorPalette();
  syncStudyToServer();
  if (typeof renderCoStudyList === 'function') {
    renderCoStudyList(lastFetchedLearners);
  }
  toast(`Đã chuyển phối màu: ${c.name} ✨`);
}

function resetStudyTheme() {
  studySettings.activeWallpaper = 'default';
  studySettings.activeAura = 'emerald';
  studySettings.clockColor = 'default';
  studySettings.wallpaperDim = 35;
  studySettings.cardGlassOpacity = 50;
  saveStudySettings(false);

  const studyEl = $("#study");
  if (studyEl) {
    studyEl.classList.remove("has-custom-bg");
    studyEl.classList.remove("study-zen-view");
    studyEl.style.removeProperty("--primary");
    studyEl.style.removeProperty("--primary-gradient");
    studyEl.style.removeProperty("--primary-glow");
    studyEl.style.removeProperty("--study-overlay-opacity");
    studyEl.style.removeProperty("--study-card-opacity");
  }
  const bgLayer = $("#studyBackgroundLayer");
  if (bgLayer) {
    bgLayer.style.backgroundImage = "";
  }
  const stop1 = $("#timerGradStop1");
  const stop2 = $("#timerGradStop2");
  if (stop1 && stop2) {
    stop1.setAttribute("stop-color", "#10b981");
    stop2.setAttribute("stop-color", "#059669");
  }
  const knob = $("#timerProgressKnob");
  if (knob) {
    knob.style.fill = "#10b981";
  }
  const progCircle = $("#timerProgressCircle");
  if (progCircle) {
    progCircle.style.stroke = "url(#timerGrad)";
  }
  const clock = $("#timerClock");
  if (clock) {
    clock.style.removeProperty("color");
  }
  studySettings.primaryColor = "#10b981";
  studySettings.secondaryColor = "#10b981";
  studySettings.accessoryColor = "#10b981";
  applyStudyColorRoles();
  const nameEl = $("#customWallName");
  if (nameEl) nameEl.textContent = "Chưa chọn ảnh";

  applyWallpaperDim(35);
  applyCardGlass(50);
  renderWallpaperPresets();
  renderClockColorPicker();
  renderColorPalette();
  renderCustomWallpapersList();
  syncStudyToServer();
  if (typeof renderCoStudyList === 'function') {
    renderCoStudyList(lastFetchedLearners);
  }
  toast("Đã đặt lại không gian học tập mặc định.");
}

window.notifyPerkLocked = function (days, perkName) {
  toast(`🔒 ${perkName} mở khóa ở Chuỗi ${days} ngày!`);
};

/* --- 11. FULLSCREEN ZEN MODE --- */
function toggleStudyFullscreen() {
  const isZen = document.body.classList.toggle("study-zen-fullscreen");
  const btn = $("#studyFullscreenBtn");
  if (btn) btn.textContent = isZen ? "✕" : "⛶";
  if (isZen) {
    if (document.documentElement.requestFullscreen) {
      document.documentElement.requestFullscreen().catch(() => { });
    }
  } else {
    if (document.fullscreenElement && document.exitFullscreen) {
      document.exitFullscreen().catch(() => { });
    }
  }
}

document.addEventListener("fullscreenchange", () => {
  if (!document.fullscreenElement) {
    document.body.classList.remove("study-zen-fullscreen");
    const btn = $("#studyFullscreenBtn");
    if (btn) btn.textContent = "⛶";
  }
});

/* --- 12. PUSH NOTIFICATION --- */
function sendStudyNotification() {
  if (!studySettings.browserNotifications) return;
  if (!("Notification" in window)) return;
  if (Notification.permission === "granted") {
    const isFocus = (studyState.mode === 'focus');
    const title = isFocus ? "🎉 Hoàn thành lượt tập trung!" : "⏰ Hết giờ nghỉ giải lao!";
    const body = isFocus
      ? "Bạn đã hoàn thành xuất sắc lượt học. Hãy đứng dậy vươn vai và thư giãn nhé!"
      : "Thời gian nghỉ đã hết. Sẵn sàng bắt đầu lượt tập trung mới nào!";
    try {
      new Notification(title, {
        body,
        icon: "/favicon.ico"
      });
    } catch (e) { }
  }
}

/* --- 13. SETTINGS MODAL HANDLERS --- */
window.switchStudySettingsTab = function (tabName) {
  $$(".settings-tab-btn").forEach(btn => {
    btn.classList.toggle("active", btn.dataset.settingsTab === tabName);
  });
  const tabMap = {
    timer: "paneSettingsTimer",
    extras: "paneSettingsExtras",
    alarms: "paneSettingsAlarms",
    tasks: "paneSettingsTasks",
    audio: "paneSettingsAudio",
    theme: "paneSettingsTheme"
  };
  Object.keys(tabMap).forEach(key => {
    const pane = $("#" + tabMap[key]);
    if (pane) pane.style.display = (key === tabName) ? "block" : "none";
  });
  if (tabName === "timer") {
    updateClockStyleGridUI();
  } else if (tabName === "tasks") {
    renderTaskLabelsManagerList();
  } else if (tabName === "audio") {
    renderEnvironmentAudioGrid();
    renderMixAudioGrid();
    renderMusicAudioGrid();
    if (typeof loadCustomAudioFromDB === "function") loadCustomAudioFromDB();
  } else if (tabName === "theme") {
    renderWallpaperPresets();
    if (typeof renderCustomWallpapersList === "function") renderCustomWallpapersList();
    renderStudyColorRoleSwatches();
    renderClockColorPicker();
    renderColorPalette();
  }
};

window.selectModalPreset = function (presetId) {
  $$("#presetSelectorGrid .preset-card").forEach(c => {
    c.classList.toggle("active", c.dataset.preset === presetId);
  });

  const ftGroup = $("#groupFlowtimeConfig");
  if (ftGroup) {
    ftGroup.style.display = (presetId === "flowtime") ? "block" : "none";
  }

  const customGroup = $("#groupCustomDuration");
  if (customGroup) {
    customGroup.style.display = (presetId === "custom") ? "block" : "none";
  }

  const cfg = STUDY_PRESET_CONFIGS[presetId];
  if (cfg && presetId !== "flowtime" && presetId !== "custom") {
    const fInput = $("#settingFocusMins");
    const sInput = $("#settingShortBreakMins");
    const lInput = $("#settingLongBreakMins");
    const intInput = $("#settingLongBreakInterval");
    if (fInput) fInput.value = cfg.focus;
    if (sInput) sInput.value = (cfg.shortBreak >= 1) ? cfg.shortBreak : 1;
    if (lInput) lInput.value = cfg.longBreak;
    if (intInput) intInput.value = cfg.sessions || 4;
  }
  handleCustomDurationChange();
};

window.stepDuration = function (type, delta) {
  let input = null;
  let min = 1, max = 180;
  if (type === 'focus') {
    input = $("#settingFocusMins");
    min = 1; max = 180;
  } else if (type === 'shortbreak') {
    input = $("#settingShortBreakMins");
    min = 1; max = 60;
  } else if (type === 'longbreak') {
    input = $("#settingLongBreakMins");
    min = 1; max = 90;
  }
  if (!input) return;
  const current = Number(input.value) || min;
  const next = Math.max(min, Math.min(max, current + delta));
  input.value = next;
  handleCustomDurationChange();
};

window.stepLongBreakInterval = function (delta) {
  const input = $("#settingLongBreakInterval");
  if (!input) return;
  const current = Number(input.value) || 4;
  const next = Math.max(1, Math.min(12, current + delta));
  input.value = next;
  handleCustomDurationChange();
};

window.stepDailyGoal = function (delta) {
  const input = $("#settingDailyGoal");
  if (!input) return;
  const current = Number(input.value) || 8;
  const next = Math.max(1, Math.min(30, current + delta));
  input.value = next;
};

window.handleCustomDurationChange = function () {
  const fInput = $("#settingFocusMins");
  const sInput = $("#settingShortBreakMins");
  const lInput = $("#settingLongBreakMins");
  const intInput = $("#settingLongBreakInterval");
  const estEl = $("#settingFullCycleEstimate");

  const focus = Number(fInput?.value) || 25;
  const sBreak = Number(sInput?.value) || 5;
  const lBreak = Number(lInput?.value) || 15;
  const interval = Number(intInput?.value) || 4;

  const totalMins = (interval * focus) + (Math.max(0, interval - 1) * sBreak) + lBreak;
  const hours = Math.floor(totalMins / 60);
  const mins = totalMins % 60;
  const timeStr = `${hours > 0 ? hours + 'g ' : ''}${mins}p`;

  if (estEl) {
    estEl.textContent = `➔ Một chu kỳ học sẽ kéo dài ${timeStr}`;
  }
};

window.handleAlarmVolumeChange = function (val) {
  const num = Math.max(0, Math.min(100, Number(val) || 0));
  const textEl = $("#alarmVolumeVal");
  if (textEl) textEl.textContent = `${num}%`;
  studySettings.alarmVolume = num;
};

window.setAlarmRings = function (rings) {
  const num = Number(rings) || 1;
  studySettings.alarmRings = num;
  $$("#ringMultiplierGroup .ring-mult-btn").forEach(btn => {
    btn.classList.toggle("active", Number(btn.dataset.rings) === num);
  });
};

window.setReminderBeforeEnd = function (mins) {
  const num = Number(mins) || 0;
  studySettings.reminderBeforeEnd = num;
  $$("#reminderPillGroup .remind-pill-btn").forEach(btn => {
    btn.classList.toggle("active", Number(btn.dataset.remind) === num);
  });
};

window.updateFlowtimeRatioSetting = function (val) {
  studySettings.flowtimeRatio = val;
};

window.openMethodGuideModal = function (method = 'all') {
  const modal = $("#studyMethodGuideModal");
  if (!modal) return;
  modal.showModal();
  if (method === 'flowtime') {
    const card = modal.querySelector(".method-card:first-child");
    if (card) card.scrollIntoView({ behavior: 'smooth' });
  } else if (method === 'eye_rule') {
    const cards = modal.querySelectorAll(".method-card");
    if (cards[1]) cards[1].scrollIntoView({ behavior: 'smooth' });
  }
};

window.openStudySettingsModal = function (initialTab = 'timer', showCustom = false) {
  const modal = $("#studySettingsModal");
  if (!modal) return;

  switchStudySettingsTab(initialTab);
  updateClockStyleGridUI();
  renderStudyColorRoleSwatches();

  if (showCustom) {
    studySettings.timerPreset = "custom";
  }

  const activePreset = studySettings.timerPreset || "25_5";
  $$("#presetSelectorGrid .preset-card").forEach(c => {
    c.classList.toggle("active", c.dataset.preset === activePreset);
  });
  const ftGroup = $("#groupFlowtimeConfig");
  if (ftGroup) {
    ftGroup.style.display = (activePreset === "flowtime") ? "block" : "none";
  }
  const customGroup = $("#groupCustomDuration");
  if (customGroup) {
    customGroup.style.display = (activePreset === "custom" || showCustom) ? "block" : "none";
  }
  const ratioInputs = $$("input[name='flowtimeRatioModal']");
  ratioInputs.forEach(r => {
    r.checked = (r.value === (studySettings.flowtimeRatio || "1/4"));
  });

  const fInput = $("#settingFocusMins");
  const sInput = $("#settingShortBreakMins");
  const lInput = $("#settingLongBreakMins");
  const intInput = $("#settingLongBreakInterval");

  if (fInput) fInput.value = studySettings.focusMins || 25;
  if (sInput) sInput.value = studySettings.shortBreakMins || 5;
  if (lInput) lInput.value = studySettings.longBreakMins || 15;
  if (intInput) intInput.value = studySettings.longBreakInterval || 4;
  handleCustomDurationChange();

  const aBreaks = $("#settingAutoStartBreaks");
  const aPoms = $("#settingAutoStartPomodoros");
  const dGoal = $("#settingDailyGoal");
  const pSounds = $("#settingPauseSoundsDuringBreaks");
  const hFocus = $("#settingHideEverythingWhileFocusing");
  const sSecs = $("#settingShowSeconds");

  if (aBreaks) aBreaks.checked = studySettings.autoStartBreaks ?? true;
  if (aPoms) aPoms.checked = studySettings.autoStartPomodoros ?? false;
  if (dGoal) dGoal.value = studySettings.dailyGoalPomodoros || 8;
  if (pSounds) pSounds.checked = studySettings.pauseSoundsDuringBreaks ?? true;
  if (hFocus) hFocus.checked = studySettings.hideEverythingWhileFocusing ?? false;
  if (sSecs) sSecs.checked = studySettings.showSeconds ?? true;

  const selAlarm = $("#settingEndAlarm");
  const volRange = $("#settingAlarmVolume");
  const volVal = $("#alarmVolumeVal");
  const selTick = $("#settingTickingSound");
  const bNotifs = $("#settingBrowserNotifications");

  if (selAlarm) selAlarm.value = studySettings.alarmSound || "bell";
  if (volRange) volRange.value = studySettings.alarmVolume ?? 80;
  if (volVal) volVal.textContent = `${studySettings.alarmVolume ?? 80}%`;
  setAlarmRings(studySettings.alarmRings || 1);
  setReminderBeforeEnd(studySettings.reminderBeforeEnd || 0);
  if (selTick) selTick.value = studySettings.tickingSound || "off";

  if (bNotifs) {
    bNotifs.checked = studySettings.browserNotifications ?? false;
    bNotifs.onchange = () => {
      if (bNotifs.checked && "Notification" in window && Notification.permission !== "granted") {
        Notification.requestPermission();
      }
    };
  }

  const streak = getUserStudyStreak();
  const taskUnlocked = streak >= 7;
  const bannerLock = $("#bannerTasksLocked");
  if (bannerLock) bannerLock.style.display = taskUnlocked ? "none" : "flex";
  renderTaskLabelsManagerList();

  modal.showModal();
};

window.saveStudySettings = function (closeModal = true) {
  const modal = $("#studySettingsModal");
  if (closeModal || (modal && modal.open)) {
    const fInput = $("#settingFocusMins");
    const sInput = $("#settingShortBreakMins");
    const lInput = $("#settingLongBreakMins");
    const intInput = $("#settingLongBreakInterval");
    const aBreaks = $("#settingAutoStartBreaks");
    const aPoms = $("#settingAutoStartPomodoros");
    const dGoal = $("#settingDailyGoal");
    const pSounds = $("#settingPauseSoundsDuringBreaks");
    const hFocus = $("#settingHideEverythingWhileFocusing");
    const sSecs = $("#settingShowSeconds");
    const selAlarm = $("#settingEndAlarm");
    const volRange = $("#settingAlarmVolume");
    const selTick = $("#settingTickingSound");
    const bNotifs = $("#settingBrowserNotifications");

    const activeCard = $("#presetSelectorGrid .preset-card.active");
    if (activeCard && activeCard.dataset.preset) {
      studySettings.timerPreset = activeCard.dataset.preset;
    }

    if (fInput) studySettings.focusMins = Math.max(1, Math.min(180, Number(fInput.value) || 25));
    if (sInput) studySettings.shortBreakMins = Math.max(1, Math.min(60, Number(sInput.value) || 5));
    if (lInput) studySettings.longBreakMins = Math.max(1, Math.min(90, Number(lInput.value) || 15));
    if (intInput) studySettings.longBreakInterval = Math.max(1, Math.min(12, Number(intInput.value) || 4));

    if (aBreaks) studySettings.autoStartBreaks = aBreaks.checked;
    if (aPoms) studySettings.autoStartPomodoros = aPoms.checked;
    if (dGoal) studySettings.dailyGoalPomodoros = Math.max(1, Math.min(30, Number(dGoal.value) || 8));
    if (pSounds) studySettings.pauseSoundsDuringBreaks = pSounds.checked;
    if (hFocus) studySettings.hideEverythingWhileFocusing = hFocus.checked;
    if (sSecs) studySettings.showSeconds = sSecs.checked;

    if (selAlarm) studySettings.alarmSound = selAlarm.value;
    if (volRange) studySettings.alarmVolume = Number(volRange.value);
    if (selTick) studySettings.tickingSound = selTick.value;

    if (bNotifs) {
      studySettings.browserNotifications = bNotifs.checked;
      if (bNotifs.checked && "Notification" in window && Notification.permission !== "granted") {
        Notification.requestPermission();
      }
    }
  }

  try {
    localStorage.setItem(STUDY_SETTINGS_KEY, JSON.stringify(studySettings));
  } catch (e) { }

  if (closeModal && !studyState.isRunning) {
    if (studySettings.timerPreset === 'flowtime') {
      studyState.durationMinutes = 0;
      studyState.remainingSeconds = 0;
    } else if (studyState.mode === 'focus') {
      studyState.durationMinutes = studySettings.focusMins;
      studyState.remainingSeconds = studySettings.focusMins * 60;
    } else if (studyState.mode === 'shortbreak') {
      studyState.durationMinutes = studySettings.shortBreakMins;
      studyState.remainingSeconds = studySettings.shortBreakMins * 60;
    } else if (studyState.mode === 'longbreak') {
      studyState.durationMinutes = studySettings.longBreakMins;
      studyState.remainingSeconds = studySettings.longBreakMins * 60;
    }
  }

  applyStudyColorRoles();
  updateStaticStudyControlsUI();
  updateTimerDisplay();
  updateDailyGoalUI();
  syncMeetingRoomTimerIfHost();

  if (closeModal) {
    const modal = $("#studySettingsModal");
    if (modal) modal.close();
    toast("Đã lưu cài đặt phòng tự học & Pomodoro!");
  }
};

/* --- 14. TASK CATEGORIES & TO-DO CHECKLIST MANAGER --- */
const STUDY_TODO_STORAGE_KEY = "research_study_todos_v1";

const STUDY_TASK_STATUSES = [
  { id: "chua_lam", label: "Chưa làm", color: "#94a3b8", weight: 0 },
  { id: "chuan_bi", label: "Chuẩn bị", color: "#64748b", weight: 0.1 },
  { id: "dang_thuc_hien", label: "Đang thực hiện", color: "#3b82f6", weight: 0.2 },
  { id: "pct_25", label: "25%", color: "#06b6d4", weight: 0.25 },
  { id: "pct_50", label: "50%", color: "#f59e0b", weight: 0.5 },
  { id: "pct_75", label: "75%", color: "#8b5cf6", weight: 0.75 },
  { id: "pct_99", label: "99%", color: "#ec4899", weight: 0.99 },
  { id: "hoan_thanh", label: "Hoàn thành", color: "#10b981", weight: 1.0 },
  { id: "hoan", label: "Hoãn", color: "#f97316", weight: 0 },
  { id: "huy", label: "Huỷ", color: "#ef4444", weight: 0 }
];

function updateTodoProgressBar() {
  const bar = $("#todoProgressBar");
  const pctBadge = $("#todoPctBadge");
  let todos = [];
  try {
    todos = JSON.parse(localStorage.getItem(STUDY_TODO_STORAGE_KEY) || "[]");
  } catch (e) {
    todos = [];
  }
  if (!bar) return;
  if (todos.length === 0) {
    bar.style.width = "0%";
    if (pctBadge) pctBadge.textContent = "0%";
    return;
  }

  let totalWeight = 0;
  todos.forEach(t => {
    if (t.done || t.status === "hoan_thanh") {
      totalWeight += 1.0;
    } else {
      const st = STUDY_TASK_STATUSES.find(s => s.id === t.status);
      totalWeight += st ? (st.weight || 0) : 0;
    }
  });

  const pct = Math.min(100, Math.round((totalWeight / todos.length) * 100));
  bar.style.width = `${pct}%`;
  if (pctBadge) pctBadge.textContent = `${pct}%`;
}

function loadStudyTodos() {
  const listEl = $("#studyTodoList");
  if (!listEl) return;
  let todos = [];
  try {
    todos = JSON.parse(localStorage.getItem(STUDY_TODO_STORAGE_KEY) || "[]");
  } catch (e) {
    todos = [];
  }

  if (todos.length === 0) {
    listEl.innerHTML = `<li class="todo-item" style="color:var(--muted); font-size:12px; justify-content:center;">Chưa có việc cần làm nào. Hãy thêm việc ở trên!</li>`;
    updateTodoProgressBar();
    return;
  }

  listEl.innerHTML = todos.map((t, idx) => {
    const isDone = Boolean(t.done || t.status === "hoan_thanh");
    const statusId = t.status || (isDone ? "hoan_thanh" : "chua_lam");
    const statusObj = STUDY_TASK_STATUSES.find(s => s.id === statusId) || STUDY_TASK_STATUSES[0];

    let tagHtml = "";
    if (t.tagId && studySettings.taskLabels) {
      const tag = studySettings.taskLabels.find(l => l.id === t.tagId);
      if (tag) {
        tagHtml = `<span class="todo-tag-pill" style="background-color: ${tag.color};">${escapeHTML(tag.name)}</span>`;
      }
    }

    return `
      <li class="todo-item ${isDone ? 'done' : ''}">
        <input type="checkbox" ${isDone ? 'checked' : ''} onchange="toggleStudyTodo(${idx})" title="Đánh dấu hoàn thành" />
        <button type="button" class="todo-status-badge" style="background: ${statusObj.color}20; color: ${statusObj.color}; border-color: ${statusObj.color}66;" onclick="cycleTaskStatus(${idx})" title="Nhấp để chuyển trạng thái (${statusObj.label})">
          <span style="display:inline-block; width:6px; height:6px; border-radius:50%; background:${statusObj.color}; margin-right:4px;"></span>${statusObj.label}
        </button>
        <span class="todo-item-text">${escapeHTML(t.text)}</span>
        ${tagHtml}
        <button class="todo-del-btn" onclick="deleteStudyTodo(${idx})" title="Xoá việc">×</button>
      </li>
    `;
  }).join("");

  updateTodoProgressBar();
}

function saveStudyTodos(todos) {
  try {
    localStorage.setItem(STUDY_TODO_STORAGE_KEY, JSON.stringify(todos));
  } catch (e) { }
  loadStudyTodos();
}

function addStudyTodo() {
  const input = $("#newTodoInput");
  const tagSelect = $("#newTodoTagSelect");
  if (!input) return;
  const text = input.value.trim();
  if (!text) return;
  const tagId = tagSelect ? tagSelect.value : "";
  let todos = [];
  try {
    todos = JSON.parse(localStorage.getItem(STUDY_TODO_STORAGE_KEY) || "[]");
  } catch (e) {
    todos = [];
  }
  todos.push({
    id: "task_" + Date.now(),
    text,
    status: "chuan_bi",
    tagId,
    done: false,
    createdAt: Date.now()
  });
  input.value = "";
  saveStudyTodos(todos);
}

window.cycleTaskStatus = function (idx) {
  let todos = [];
  try {
    todos = JSON.parse(localStorage.getItem(STUDY_TODO_STORAGE_KEY) || "[]");
  } catch (e) { }
  if (!todos[idx]) return;

  const currentStatusId = todos[idx].status || (todos[idx].done ? "hoan_thanh" : "chua_lam");
  const currentIndex = STUDY_TASK_STATUSES.findIndex(s => s.id === currentStatusId);
  const nextIndex = (currentIndex + 1) % STUDY_TASK_STATUSES.length;
  const nextStatus = STUDY_TASK_STATUSES[nextIndex];

  todos[idx].status = nextStatus.id;
  todos[idx].done = (nextStatus.id === "hoan_thanh");
  saveStudyTodos(todos);
};

window.toggleStudyTodo = function (idx) {
  let todos = [];
  try {
    todos = JSON.parse(localStorage.getItem(STUDY_TODO_STORAGE_KEY) || "[]");
  } catch (e) { }
  if (todos[idx]) {
    const nextDone = !todos[idx].done;
    todos[idx].done = nextDone;
    todos[idx].status = nextDone ? "hoan_thanh" : "chua_lam";
    saveStudyTodos(todos);
  }
};

window.deleteStudyTodo = function (idx) {
  let todos = [];
  try {
    todos = JSON.parse(localStorage.getItem(STUDY_TODO_STORAGE_KEY) || "[]");
  } catch (e) { }
  todos.splice(idx, 1);
  saveStudyTodos(todos);
};

function clearCompletedTodos() {
  let todos = [];
  try {
    todos = JSON.parse(localStorage.getItem(STUDY_TODO_STORAGE_KEY) || "[]");
  } catch (e) { }
  todos = todos.filter(t => !t.done && t.status !== "hoan_thanh" && t.status !== "huy");
  saveStudyTodos(todos);
  toast("Đã dọn dẹp các việc đã xong / hủy!");
}

/* --- Task Category Labels (Quản lý nhãn công việc) --- */
function renderTaskTagSelect() {
  const labels = studySettings.taskLabels || [];
  let html = `<option value="">Không gắn nhãn</option>`;
  labels.forEach(l => {
    html += `<option value="${l.id}">🏷️ ${escapeHTML(l.name)}</option>`;
  });
  const sel = $("#newTodoTagSelect");
  if (sel) {
    sel.disabled = false;
    sel.innerHTML = html;
  }
  const sharedSel = $("#newSharedTaskTagSelect");
  if (sharedSel) {
    sharedSel.disabled = false;
    sharedSel.innerHTML = html;
  }
}

function renderTaskLabelsManagerList() {
  const listEl = $("#taskLabelsMgrList");
  if (!listEl) return;
  const labels = studySettings.taskLabels || [];
  if (labels.length === 0) {
    listEl.innerHTML = `<p style="font-size:12px; color:var(--muted); text-align:center; padding:10px;">Chưa có nhãn công việc nào. Nhập tên nhãn ở trên để tạo nhãn mới!</p>`;
    return;
  }
  listEl.innerHTML = labels.map(l => `
    <div class="task-label-mgr-row" data-tag-id="${l.id}">
      <input type="color" class="task-label-color-input" value="${l.color}" onchange="updateTaskLabelColor('${l.id}', this.value)" title="Chọn màu nhãn" />
      <input type="text" class="task-label-mgr-name" value="${escapeHTML(l.name)}" onchange="updateTaskLabelName('${l.id}', this.value)" maxlength="30" />
      <button type="button" class="task-label-del-btn" onclick="deleteTaskLabel('${l.id}')" title="Xóa nhãn">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path></svg>
      </button>
    </div>
  `).join("");
}

window.handleCreateTaskLabel = function () {
  const nameInput = $("#newLabelNameInput");
  const colorInput = $("#newLabelColorInput");
  if (!nameInput) return;
  const name = nameInput.value.trim();
  if (!name) {
    toast("Vui lòng nhập tên nhãn công việc.");
    nameInput.focus();
    return;
  }
  const color = colorInput ? colorInput.value : "#3b82f6";
  const newTag = {
    id: "tag_" + Date.now(),
    name: name,
    color: color
  };
  if (!studySettings.taskLabels) studySettings.taskLabels = [];
  studySettings.taskLabels.push(newTag);
  nameInput.value = "";
  saveStudySettings(false);
  renderTaskLabelsManagerList();
  renderTaskTagSelect();
  loadStudyTodos();
  toast(`Đã thêm nhãn: "${newTag.name}"`);
};

window.promptAddNewTaskLabel = function () {
  window.handleCreateTaskLabel();
};

window.updateTaskLabelColor = function (id, color) {
  const target = (studySettings.taskLabels || []).find(l => l.id === id);
  if (target) {
    target.color = color;
    saveStudySettings(false);
    renderTaskTagSelect();
    loadStudyTodos();
  }
};

window.updateTaskLabelName = function (id, name) {
  const target = (studySettings.taskLabels || []).find(l => l.id === id);
  if (target && name.trim()) {
    target.name = name.trim();
    saveStudySettings(false);
    renderTaskTagSelect();
    loadStudyTodos();
  }
};

window.deleteTaskLabel = function (id) {
  if (!confirm("Bạn có chắc muốn xóa nhãn này không?")) return;
  studySettings.taskLabels = (studySettings.taskLabels || []).filter(l => l.id !== id);
  saveStudySettings(false);
  renderTaskLabelsManagerList();
  renderTaskTagSelect();
  loadStudyTodos();
  toast("Đã xóa nhãn!");
};

/* --- 15. ROUTE LIFECYCLE & EVENT INITIALIZATION --- */
function onEnterStudyLounge() {
  if (!canAccessStudyLounge()) {
    toast(STUDY_MAINTENANCE_MSG);
    go("home");
    return;
  }

  // 1. Chỉ khởi tạo phòng mặc định & bộ đếm ở lần đầu tiên mở ứng dụng
  // Khi người dùng chuyển qua lại giữa các tính năng (Trang chủ, Arena, Diễn đàn, Tài liệu...),
  // TUYỆT ĐỐI GIỮ NGUYÊN phòng đang học và tiến độ ca học hiện tại.
  if (!window._studyLoungeInitialized) {
    window._studyLoungeInitialized = true;
    const hash = window.location.hash || '';
    const search = window.location.search || '';
    const hasRoomParam = hash.includes('room=') || search.includes('room=');
    if (!hasRoomParam) {
      let savedRoomId = null;
      try {
        savedRoomId = localStorage.getItem("research_study_room_id");
      } catch (e) { }

      if (savedRoomId && savedRoomId !== 'commons' && savedRoomId !== 'private') {
        currentStudyRoomId = savedRoomId;
      } else {
        currentStudyRoomId = "commons";
        currentStudyRoomData = null;
      }

      studyState.isRunning = false;
      studyState.targetEndMs = 0;
      if (studyState.timerInterval) {
        clearInterval(studyState.timerInterval);
        studyState.timerInterval = null;
      }
      const focusM = studySettings.focusMins || 25;
      studyState.durationMinutes = focusM;
      studyState.remainingSeconds = (studySettings.timerPreset === 'flowtime' ? 0 : focusM * 60);
      activeStudySpaceTab = (currentStudyRoomId && currentStudyRoomId.startsWith('lib_')) ? 'library' : 'private';
      switchStudySpaceCategoryTab(activeStudySpaceTab);
    }
  }

  // 2. Đồng bộ & hiển thị đúng không gian phòng và tiến độ hiện tại
  renderActiveSpaceBanner(currentStudyRoomData);
  renderClockTicks();
  updateStudyStreakPerks();
  renderCoStudyList(lastFetchedLearners);
  fetchStudyLounge();
  if (studyState.isRunning && session) {
    syncStudyToServer();
  }
  renderTaskTagSelect();
  loadStudyTodos();
  applyStudyColorRoles();
  renderStudyColorRoleSwatches();
  updateClockStyleGridUI();
  updateStaticStudyControlsUI();
  updateDailyGoalUI();
  renderEnvironmentAudioGrid();
  renderMixAudioGrid();
  renderMusicAudioGrid();
  loadCustomAudioFromDB();
  renderWallpaperPresets();
  renderCustomWallpapersList();
  renderClockColorPicker();
  renderColorPalette();
  updateTimerDisplay();
  rotateStudyQuote(false);

  // Apply saved wallpaper dim & card glass opacity
  applyWallpaperDim(studySettings.wallpaperDim ?? 35);
  applyCardGlass(studySettings.cardGlassOpacity ?? 50);

  // Apply saved clock color
  if (studySettings.clockColor && studySettings.clockColor !== 'default') {
    applyClockColor(studySettings.clockColor);
  }

  // Apply saved theme & aura
  const studyEl = $("#study");
  if (studySettings.activeWallpaper && studySettings.activeWallpaper !== 'default') {
    if (studySettings.activeWallpaper.startsWith('custom_')) {
      idbGetAll("custom_wallpapers").then(walls => {
        const wallId = studySettings.activeWallpaper.replace('custom_', '');
        const target = walls.find(w => w.id === wallId);
        if (target && target.dataUrl) {
          if (studyEl) studyEl.classList.add("has-custom-bg");
          const bgLayer = $("#studyBackgroundLayer");
          if (bgLayer) {
            bgLayer.style.backgroundImage = `url(${target.dataUrl})`;
            bgLayer.style.backgroundSize = "cover";
            bgLayer.style.backgroundPosition = "center";
          }
          const nameEl = $("#customWallName");
          if (nameEl) nameEl.textContent = target.name;
        } else {
          if (studyEl) studyEl.classList.remove("has-custom-bg");
        }
      });
    } else {
      applyStudyWallpaperPreset(studySettings.activeWallpaper);
    }
  } else {
    if (studyEl) studyEl.classList.remove("has-custom-bg");
  }
  applyColorAura(studySettings.activeAura || 'pomodoro');

  loadAndRenderStudyRooms();
  checkUrlStudyRoomParam();

  if (!window._studySpacesTicker) {
    window._studySpacesTicker = setInterval(() => {
      if (!currentStudyRoomId && activeStudySpaceTab === 'library') {
        renderLibraryRoomsGrid();
      }
    }, 1000);
  }

  if (!studyState.pollingInterval) {
    studyState.pollingInterval = setInterval(fetchStudyLounge, 3500);
  }
}

function onLeaveStudyLounge() {
  if (window._studySpacesTicker) {
    clearInterval(window._studySpacesTicker);
    window._studySpacesTicker = null;
  }
  if (studyState.pollingInterval) {
    clearInterval(studyState.pollingInterval);
    studyState.pollingInterval = null;
  }
  // Lưu ý: Không gửi /api/study/leave khi chỉ chuyển tab trang web!
  // Tiến độ học và phòng vẫn tiếp tục chạy trong nền hoặc được giữ nguyên khi quay lại.
}

function initStudyLoungeEvents() {
  const goalInput = $("#studyGoalInput");
  if (goalInput) {
    let goalSyncTimeout = null;
    goalInput.addEventListener("input", () => {
      studyState.goal = goalInput.value.trim();
      updateAllCoStudyCards(lastFetchedLearners);
      clearTimeout(goalSyncTimeout);
      goalSyncTimeout = setTimeout(() => {
        if (session && canAccessStudyLounge()) {
          syncStudyToServer();
        }
      }, 600);
    });
  }

  $$(".study-mode-btn, .mode-capsule-btn").forEach(btn => {
    btn.onclick = () => {
      const mode = btn.dataset.studyMode;
      setStudyMode(mode);
    };
  });

  const startBtn = $("#studyStartBtn");
  if (startBtn) startBtn.onclick = startStudyTimer;

  const pauseBtn = $("#studyPauseBtn");
  if (pauseBtn) pauseBtn.onclick = () => pauseStudyTimer(true);

  const resetBtn = $("#studyResetBtn");
  if (resetBtn) resetBtn.onclick = resetStudyTimer;

  const nextBtn = $("#studyNextBtn");
  if (nextBtn) nextBtn.onclick = () => advanceStudyCycle(true);

  const completeBtn = $("#studyCompleteBtn");
  if (completeBtn) completeBtn.onclick = () => finishStudySession(false);

  const fullscreenBtn = $("#studyFullscreenBtn");
  if (fullscreenBtn) fullscreenBtn.onclick = toggleStudyFullscreen;

  // Sound arena tab switching: 'env' vs 'mix' vs 'music'
  $$(".sound-tab").forEach(tab => {
    tab.onclick = () => {
      const tabName = tab.dataset.soundTab;
      $$(".sound-tab").forEach(t => t.classList.toggle("active", t === tab));
      const targetPaneId = (tabName === 'music') ? 'paneMusicAudio' : (tabName === 'mix') ? 'paneMixAudio' : 'paneEnvAudio';
      $$(".sound-tab-pane").forEach(p => {
        p.style.display = (p.id === targetPaneId) ? "block" : "none";
      });
      studyState.activeSoundTab = tabName;
    };
  });

  // Sound master toggle: stop all or play default env
  const masterAmbientBtn = $("#toggleAmbientMaster");
  if (masterAmbientBtn) {
    masterAmbientBtn.onclick = () => {
      const anyActive = (studyState.activeEnvTrack !== null) ||
        (studyState.activeMusicTrack !== null) ||
        (studyState.activeCustomEnvId !== null) ||
        (studyState.activeCustomMusicId !== null) ||
        Object.values(studyState.activeMixSounds).some(v => v) ||
        Object.values(studyState.activeCustomMixSounds).some(v => v);
      if (anyActive) {
        stopAllStudyAudio();
      } else {
        toggleEnvTrack('env_1');
      }
      updateMasterAmbientButtonState();
    };
  }

  // Custom audio file inputs (Rạch ròi: Môi trường, Phối hợp & Âm nhạc)
  const envAudioInput = $("#customEnvAudioInput");
  if (envAudioInput) {
    envAudioInput.onchange = (e) => {
      const file = e.target.files && e.target.files[0];
      if (file) handleCustomEnvAudioUpload(file);
      envAudioInput.value = "";
    };
  }

  const mixAudioInput = $("#customMixAudioInput");
  if (mixAudioInput) {
    mixAudioInput.onchange = (e) => {
      const file = e.target.files && e.target.files[0];
      if (file) handleCustomMixAudioUpload(file);
      mixAudioInput.value = "";
    };
  }

  const musicAudioInput = $("#customMusicAudioInput");
  if (musicAudioInput) {
    musicAudioInput.onchange = (e) => {
      const file = e.target.files && e.target.files[0];
      if (file) handleCustomMusicAudioUpload(file);
      musicAudioInput.value = "";
    };
  }

  const wallInput = $("#customWallInput");
  if (wallInput) {
    wallInput.onchange = (e) => {
      const file = e.target.files && e.target.files[0];
      if (file) handleCustomWallpaperUpload(file);
      wallInput.value = "";
    };
  }

  // To-do checklist buttons
  const addTodoBtn = $("#addTodoBtn");
  if (addTodoBtn) addTodoBtn.onclick = addStudyTodo;
  const todoInput = $("#newTodoInput");
  if (todoInput) {
    todoInput.onkeydown = (e) => {
      if (e.key === "Enter") addStudyTodo();
    };
  }
  const clearTodoBtn = $("#clearCompletedTodos");
  if (clearTodoBtn) clearTodoBtn.onclick = clearCompletedTodos;

  // Motivational quote interaction
  const quoteWrap = $("#timerQuoteWrap");
  if (quoteWrap) {
    quoteWrap.onclick = () => rotateStudyQuote(true);
  }
  rotateStudyQuote(false);

  const flowtimeBreakBtn = $("#studyFlowtimeBreakBtn");
  if (flowtimeBreakBtn) flowtimeBreakBtn.onclick = triggerFlowtimeBreak;

  renderTaskTagSelect();
  loadStudyTodos();
  updateDailyGoalUI();

  // Initialize UI components
  renderEnvironmentAudioGrid();
  renderMixAudioGrid();
  renderMusicAudioGrid();
  loadCustomAudioFromDB();
  renderWallpaperPresets();
  renderCustomWallpapersList();
  renderClockColorPicker();
  renderColorPalette();
  applyWallpaperDim(studySettings.wallpaperDim ?? 35);
  applyCardGlass(studySettings.cardGlassOpacity ?? 50);
}

