        <path d="M-1.5 4.4 C-2.5 7.4 -2.6 10.6 -1.5 13 C-0.5 14.3 0.8 14.3 1.5 12.8 C2.4 10.5 2.2 7.2 1.4 4.4 Z" fill="${b.tip}" opacity="0.48"/>
