function createSeededTreeRng(seed) {
  let state = seed >>> 0;
  return function nextRand() {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

function getChristmasTreeLayout(w, h) {
  const isMobile = w <= 760;
  if (isMobile) {
    const treeH = Math.round(Math.min(305, Math.max(218, h * 0.36)));
    const treeR = Math.round(treeH * 0.25);
    return {
      isMobile: true,
      anchorX: w - 42,
      baseY: h - 76,
      treeH,
      treeR
    };
  }
  const gutterRight = Math.max(0, (w - 1208) * 0.5);
  const edgeOffset = gutterRight >= 92 ? Math.min(108, gutterRight * 0.72) : Math.max(58, Math.min(88, w * 0.06));
  const treeH = Math.round(Math.min(470, Math.max(305, h * 0.54)));
  const treeR = Math.round(Math.min(116, Math.max(76, treeH * 0.246)));
  return {
    isMobile: false,
    anchorX: w - edgeOffset,
    baseY: h - 22,
    treeH,
    treeR
  };
}

function getChristmasTreeStudioLayout(w, h) {
  const safeW = Math.max(260, w);
  const safeH = Math.max(280, h);
  // Keep summit star safely below top floating milestone pill & spin controls on mobile & desktop
  const topClearance = safeH <= 360 ? 52 : 44;
  const baseY = Math.round(safeH * 0.91);
  const maxTreeHByHeight = Math.max(180, baseY - topClearance - 14);
  const treeH = Math.round(Math.min(maxTreeHByHeight, safeW * 0.9));
  const treeR = Math.round(treeH * 0.285);
  return {
    isMobile: safeW <= 440,
    anchorX: Math.round(safeW * 0.5),
    baseY,
    treeH,
    treeR
  };
}

function buildGlowSprite(innerColor, midColor, outerColor, size) {
  const c = document.createElement("canvas");
  c.width = size;
  c.height = size;
  const gctx = c.getContext("2d");
  if (!gctx) return c;
  const half = size * 0.5;
  const grad = gctx.createRadialGradient(half, half, 0, half, half, half);
  grad.addColorStop(0, innerColor);
  grad.addColorStop(0.28, midColor);
  grad.addColorStop(1, outerColor);
  gctx.fillStyle = grad;
  gctx.fillRect(0, 0, size, size);
  return c;
}

function getChristmasTreeSprites(isDark) {
  const key = isDark ? "dark" : "light";
  if (christmasTreeState.sprites && christmasTreeState.spriteThemeKey === key) {
    return christmasTreeState.sprites;
  }
  const starGlow = buildGlowSprite(
    "rgba(255, 251, 214, 0.94)",
    isDark ? "rgba(255, 215, 0, 0.34)" : "rgba(245, 158, 11, 0.26)",
    "rgba(255, 215, 0, 0)",
    56
  );
  const bulbSpecs = isDark
    ? {
        gold: ["rgba(255, 253, 224, 1)", "rgba(255, 213, 79, 0.44)", "rgba(255, 213, 79, 0)"],
        red: ["rgba(255, 232, 232, 1)", "rgba(255, 59, 48, 0.42)", "rgba(255, 59, 48, 0)"],
        green: ["rgba(220, 255, 232, 1)", "rgba(34, 197, 94, 0.4)", "rgba(34, 197, 94, 0)"],
        blue: ["rgba(224, 244, 255, 1)", "rgba(56, 189, 248, 0.42)", "rgba(56, 189, 248, 0)"],
        yellow: ["rgba(255, 255, 220, 1)", "rgba(250, 204, 21, 0.42)", "rgba(250, 204, 21, 0)"]
      }
    : {
        gold: ["rgba(255, 252, 225, 1)", "rgba(245, 158, 11, 0.34)", "rgba(245, 158, 11, 0)"],
        red: ["rgba(255, 235, 235, 1)", "rgba(220, 38, 38, 0.34)", "rgba(220, 38, 38, 0)"],
        green: ["rgba(220, 252, 231, 1)", "rgba(22, 163, 74, 0.32)", "rgba(22, 163, 74, 0)"],
        blue: ["rgba(224, 242, 254, 1)", "rgba(37, 99, 235, 0.34)", "rgba(37, 99, 235, 0)"],
        yellow: ["rgba(254, 249, 195, 1)", "rgba(234, 179, 8, 0.36)", "rgba(234, 179, 8, 0)"]
      };
  const bulbs = {};
  Object.keys(bulbSpecs).forEach((k) => {
    const s = bulbSpecs[k];
    bulbs[k] = buildGlowSprite(s[0], s[1], s[2], 24);
  });
  christmasTreeState.sprites = { starGlow, bulbs };
  christmasTreeState.spriteThemeKey = key;
  return christmasTreeState.sprites;
}

function coneRadiusAtHeight(u) {
  // Foliage starts cleanly above wooden trunk at u >= 0.215 up to tip u = 0.99
  if (u < 0.215) return 0.14;
  const relU = Math.max(0, Math.min(1, (u - 0.215) / 0.775));
  const taper = Math.max(0.02, Math.pow(1 - relU, 0.9));
  const whorl = (1 - relU) * 6.5;
  const frac = whorl - Math.floor(whorl);
  const boughFlare = 0.84 + 0.25 * (1 - frac);
  return taper * boughFlare;
}

function paintTinyPineSilhouette(ctx, cx, baseY, h, w, color) {
  ctx.fillStyle = color;
  for (let t = 0; t < 3; t++) {
    const ty = baseY - h * (0.28 + t * 0.25);
    const topY = baseY - h * (0.58 + t * 0.19);
    const halfW = w * (0.56 - t * 0.13);
    ctx.beginPath();
    ctx.moveTo(cx, topY);
    ctx.lineTo(cx + halfW, ty);
    ctx.lineTo(cx - halfW, ty);
    ctx.closePath();
    ctx.fill();
  }
}

function buildPresetThumbnailCanvas(presetKey) {
  const S = 160;
  const c = document.createElement("canvas");
  c.width = S;
  c.height = S;
  const ctx = c.getContext("2d");
  if (!ctx) return c;

  const drawStars = (pts) => {
    ctx.save();
    pts.forEach(([sx, sy, sr]) => {
      ctx.fillStyle = "#FFFBEB";
      ctx.globalAlpha = 0.85;
      ctx.beginPath();
      ctx.arc(sx, sy, sr, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.restore();
  };

  if (presetKey === "preset:aurora") {
    const sky = ctx.createLinearGradient(0, 0, 0, S);
    sky.addColorStop(0, "#040b1a");
    sky.addColorStop(0.55, "#0b2942");
    sky.addColorStop(1, "#0f4c5c");
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, S, S);
    drawStars([[18, 20, 1.3], [44, 14, 1], [88, 12, 1.4], [126, 22, 1.2], [146, 36, 0.9], [66, 30, 1]]);

    // Curtain ribbon aurora beams
    const aur1 = ctx.createLinearGradient(10, 74, 150, 18);
    aur1.addColorStop(0, "rgba(16, 185, 129, 0.05)");
    aur1.addColorStop(0.35, "rgba(52, 211, 153, 0.72)");
    aur1.addColorStop(0.65, "rgba(56, 189, 248, 0.62)");
    aur1.addColorStop(1, "rgba(168, 85, 247, 0.25)");
    ctx.fillStyle = aur1;
    ctx.beginPath();
    ctx.moveTo(0, 68);
    ctx.bezierCurveTo(38, 18, 72, 72, 118, 22);
    ctx.bezierCurveTo(138, 8, 152, 24, S, 18);
    ctx.lineTo(S, 54);
    ctx.bezierCurveTo(122, 68, 86, 42, 42, 84);
    ctx.lineTo(0, 88);
    ctx.closePath();
    ctx.fill();

    // Distant snowy peaks
    ctx.fillStyle = "#163554";
    ctx.beginPath();
    ctx.moveTo(0, 118);
    ctx.lineTo(30, 82);
    ctx.lineTo(64, 106);
    ctx.lineTo(106, 74);
    ctx.lineTo(142, 102);
    ctx.lineTo(S, 92);
    ctx.lineTo(S, 122);
    ctx.lineTo(0, 122);
    ctx.closePath();
    ctx.fill();
    // Snow ridges
    ctx.fillStyle = "rgba(224, 242, 254, 0.85)";
    ctx.beginPath();
    ctx.moveTo(30, 82);
    ctx.lineTo(41, 92);
    ctx.lineTo(31, 90);
    ctx.lineTo(22, 95);
    ctx.closePath();
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(106, 74);
    ctx.lineTo(120, 86);
    ctx.lineTo(108, 84);
    ctx.lineTo(96, 89);
    ctx.closePath();
    ctx.fill();

    // Frozen mirror lake
    const lake = ctx.createLinearGradient(0, 118, 0, S);
    lake.addColorStop(0, "#0d3b54");
    lake.addColorStop(0.5, "#155e75");
    lake.addColorStop(1, "#082f49");
    ctx.fillStyle = lake;
    ctx.fillRect(0, 118, S, 42);
    ctx.fillStyle = "rgba(110, 231, 183, 0.28)";
    ctx.fillRect(28, 128, 92, 6);
    ctx.fillRect(48, 140, 64, 4);

    // Foreground pine silhouette & cozy amber window glow
    paintTinyPineSilhouette(ctx, 20, 134, 46, 22, "#061d24");
    paintTinyPineSilhouette(ctx, 138, 136, 50, 24, "#061d24");
    ctx.fillStyle = "#1c1917";
    ctx.fillRect(70, 108, 22, 14);
    ctx.fillStyle = "#fef08a";
    ctx.fillRect(77, 112, 8, 6);
  } else if (presetKey === "preset:fireplace") {
    const wall = ctx.createLinearGradient(0, 0, 0, S);
    wall.addColorStop(0, "#3b1708");
    wall.addColorStop(0.7, "#5a220c");
    wall.addColorStop(1, "#2a1207");
    ctx.fillStyle = wall;
    ctx.fillRect(0, 0, S, S);

    // Festive spruce garland + red berries across mantle top
    ctx.strokeStyle = "#14532d";
    ctx.lineWidth = 10;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(12, 46);
    ctx.quadraticCurveTo(80, 62, 148, 46);
    ctx.stroke();
    [[26, 48], [54, 54], [80, 56], [108, 54], [134, 48]].forEach(([lx, ly], idx) => {
      ctx.fillStyle = idx % 2 === 0 ? "#fde047" : "#ef4444";
      ctx.beginPath();
      ctx.arc(lx, ly, 3.2, 0, Math.PI * 2);
      ctx.fill();
    });

    // Mantle shelf & brick surround
    ctx.fillStyle = "#78350f";
    ctx.fillRect(14, 58, 132, 10);
    ctx.fillStyle = "#57534e";
    ctx.fillRect(22, 68, 116, 84);
    ctx.fillStyle = "#1c1917";
    ctx.beginPath();
    ctx.roundRect(42, 80, 76, 72, [28, 28, 0, 0]);
    ctx.fill();

    // Warm hearth floor glow
    const glow = ctx.createRadialGradient(80, 126, 6, 80, 126, 68);
    glow.addColorStop(0, "rgba(253, 224, 71, 0.72)");
    glow.addColorStop(0.5, "rgba(249, 115, 22, 0.36)");
    glow.addColorStop(1, "rgba(249, 115, 22, 0)");
    ctx.fillStyle = glow;
    ctx.fillRect(0, 72, S, 88);

    // Firewood logs & multi-layered dancing flames
    ctx.fillStyle = "#451a03";
    ctx.fillRect(54, 134, 52, 9);
    ctx.fillStyle = "#ea580c";
    ctx.beginPath();
    ctx.moveTo(62, 136);
    ctx.quadraticCurveTo(58, 104, 80, 92);
    ctx.quadraticCurveTo(104, 106, 98, 136);
    ctx.fill();
    ctx.fillStyle = "#fef08a";
    ctx.beginPath();
    ctx.moveTo(70, 136);
    ctx.quadraticCurveTo(72, 112, 80, 104);
    ctx.quadraticCurveTo(90, 112, 90, 136);
    ctx.fill();

    // Knit stockings hanging
    [32, 118].forEach((sx, i) => {
      ctx.fillStyle = i === 0 ? "#dc2626" : "#15803d";
      ctx.fillRect(sx, 68, 10, 22);
      ctx.fillStyle = "#fffbeb";
      ctx.fillRect(sx - 1, 66, 12, 6);
      ctx.fillStyle = i === 0 ? "#dc2626" : "#15803d";
      ctx.fillRect(sx, 84, 15, 8);
    });

    // Steaming mug & rug
    ctx.fillStyle = "#991b1b";
    ctx.fillRect(0, 150, S, 10);
  } else if (presetKey === "preset:snowman") {
    const sky = ctx.createLinearGradient(0, 0, 0, 126);
    sky.addColorStop(0, "#0f172a");
    sky.addColorStop(0.6, "#1d4ed8");
    sky.addColorStop(1, "#93c5fd");
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, S, S);
    drawStars([[24, 18, 1.3], [60, 28, 1], [110, 16, 1.4], [142, 26, 1.1]]);

    // Soft rolling snow slopes
    ctx.fillStyle = "#dbeafe";
    ctx.beginPath();
    ctx.moveTo(0, 118);
    ctx.quadraticCurveTo(44, 106, 86, 118);
    ctx.quadraticCurveTo(126, 128, S, 110);
    ctx.lineTo(S, S);
    ctx.lineTo(0, S);
    ctx.closePath();
    ctx.fill();
    paintTinyPineSilhouette(ctx, 22, 118, 42, 20, "#14532d");
    paintTinyPineSilhouette(ctx, 138, 116, 46, 22, "#0f3d28");

    ctx.fillStyle = "#f8fafc";
    ctx.beginPath();
    ctx.ellipse(80, 148, 96, 30, 0, 0, Math.PI * 2);
    ctx.fill();

    // Plump snowman body with icy shading
    const snowSphere = (cx, cy, r) => {
      const sg = ctx.createRadialGradient(cx - r * 0.3, cy - r * 0.3, 2, cx, cy, r);
      sg.addColorStop(0, "#ffffff");
      sg.addColorStop(0.75, "#f1f5f9");
      sg.addColorStop(1, "#cbd5e1");
      ctx.fillStyle = sg;
      ctx.beginPath();
      ctx.arc(cx, cy, r, 0, Math.PI * 2);
      ctx.fill();
    };
    snowSphere(80, 114, 24);
    snowSphere(80, 76, 17);

    // Coal buttons & rosy cheeks + scarf + carrot + hat
    ctx.fillStyle = "#1e293b";
    [104, 114, 124].forEach((by) => { ctx.beginPath(); ctx.arc(80, by, 2.2, 0, Math.PI * 2); ctx.fill(); });
    ctx.beginPath(); ctx.arc(74, 72, 2.1, 0, Math.PI * 2); ctx.arc(86, 72, 2.1, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = "rgba(251, 113, 133, 0.55)";
    ctx.beginPath(); ctx.arc(70, 78, 3, 0, Math.PI * 2); ctx.arc(90, 78, 3, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = "#f97316";
    ctx.beginPath(); ctx.moveTo(80, 74); ctx.lineTo(95, 77); ctx.lineTo(80, 80); ctx.closePath(); ctx.fill();
    ctx.fillStyle = "#dc2626";
    ctx.fillRect(65, 89, 30, 7);
    ctx.fillRect(86, 94, 7, 16);
    ctx.fillStyle = "#0f172a";
    ctx.fillRect(62, 57, 36, 5);
    ctx.fillRect(68, 38, 24, 20);
    ctx.fillStyle = "#dc2626";
    ctx.fillRect(68, 53, 24, 4);

    // Street lantern glow
    const lg = ctx.createRadialGradient(34, 88, 2, 34, 88, 28);
    lg.addColorStop(0, "rgba(254, 240, 138, 0.85)");
    lg.addColorStop(1, "rgba(254, 240, 138, 0)");
    ctx.fillStyle = lg;
    ctx.fillRect(6, 60, 56, 56);
    ctx.fillStyle = "#334155";
    ctx.fillRect(32, 92, 3, 36);
    ctx.fillStyle = "#fef08a";
    ctx.fillRect(29, 82, 9, 10);
  } else if (presetKey === "preset:cabin") {
    const sky = ctx.createLinearGradient(0, 0, 0, S);
    sky.addColorStop(0, "#1e1b4b");
    sky.addColorStop(0.55, "#312e81");
    sky.addColorStop(1, "#6366f1");
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, S, S);
    drawStars([[20, 20, 1.2], [54, 12, 1.5], [108, 18, 1], [138, 28, 1.3], [78, 34, 0.9]]);

    // Crescent moon + smoke
    ctx.fillStyle = "#fef9c3";
    ctx.beginPath();
    ctx.arc(32, 32, 11, 0, Math.PI * 2);
    ctx.fill();

    // Pines behind cabin
    paintTinyPineSilhouette(ctx, 24, 118, 54, 28, "#0f2e24");
    paintTinyPineSilhouette(ctx, 136, 118, 56, 30, "#0f2e24");

    // Snowy ground & golden window path light
    ctx.fillStyle = "#e2e8f0";
    ctx.fillRect(0, 114, S, 46);
    ctx.fillStyle = "rgba(253, 224, 71, 0.25)";
    ctx.beginPath();
    ctx.moveTo(70, 120);
    ctx.lineTo(106, 158);
    ctx.lineTo(54, 158);
    ctx.closePath();
    ctx.fill();

    // Timber cabin + snowy gable roof
    ctx.fillStyle = "#451a03";
    ctx.fillRect(102, 46, 10, 24);
    ctx.fillStyle = "rgba(241, 245, 249, 0.55)";
    ctx.beginPath();
    ctx.arc(109, 36, 5, 0, Math.PI * 2);
    ctx.arc(115, 24, 7, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = "#78350f";
    ctx.fillRect(46, 78, 68, 42);
    ctx.fillStyle = "#3f1d0b";
    ctx.beginPath();
    ctx.moveTo(36, 82);
    ctx.lineTo(80, 42);
    ctx.lineTo(124, 82);
    ctx.closePath();
    ctx.fill();
    // Fluffy white snow cap on roof
    ctx.strokeStyle = "#ffffff";
    ctx.lineWidth = 6;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(38, 80);
    ctx.lineTo(80, 42);
    ctx.lineTo(122, 80);
    ctx.stroke();

    // Warm paned windows + doorway
    ctx.fillStyle = "#9a3412";
    ctx.fillRect(72, 92, 16, 28);
    ctx.fillStyle = "#fde047";
    ctx.fillRect(52, 88, 14, 14);
    ctx.fillRect(94, 88, 14, 14);
  } else if (presetKey === "preset:study_night") {
    const room = ctx.createLinearGradient(0, 0, S, S);
    room.addColorStop(0, "#0b192c");
    room.addColorStop(0.6, "#172554");
    room.addColorStop(1, "#312e81");
    ctx.fillStyle = room;
    ctx.fillRect(0, 0, S, S);

    // Frosted window looking out at snowy night
    ctx.fillStyle = "#081226";
    ctx.fillRect(20, 16, 86, 84);
    drawStars([[36, 30, 1.3], [78, 26, 1.1], [54, 48, 1], [92, 60, 1.2], [44, 72, 1]]);
    paintTinyPineSilhouette(ctx, 84, 100, 38, 18, "#0f2e24");
    ctx.strokeStyle = "#78350f";
    ctx.lineWidth = 5;
    ctx.strokeRect(20, 16, 86, 84);
    ctx.beginPath();
    ctx.moveTo(63, 16);
    ctx.lineTo(63, 100);
    ctx.moveTo(20, 58);
    ctx.lineTo(106, 58);
    ctx.stroke();

    // Wooden desk + lamp glow
    const lampGlow = ctx.createRadialGradient(128, 76, 4, 122, 110, 68);
    lampGlow.addColorStop(0, "rgba(254, 240, 138, 0.72)");
    lampGlow.addColorStop(1, "rgba(254, 240, 138, 0)");
    ctx.fillStyle = lampGlow;
    ctx.fillRect(54, 42, 106, 118);

    ctx.fillStyle = "#5c2d16";
    ctx.fillRect(0, 112, S, 48);
    // Open notebook
    ctx.fillStyle = "#fffbeb";
    ctx.fillRect(28, 122, 54, 24);
    ctx.strokeStyle = "#94a3b8";
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(55, 122);
    ctx.lineTo(55, 146);
    ctx.moveTo(33, 129);
    ctx.lineTo(50, 129);
    ctx.moveTo(60, 129);
    ctx.lineTo(76, 129);
    ctx.stroke();
    // Steaming cocoa mug & desk lamp
    ctx.fillStyle = "#dc2626";
    ctx.fillRect(92, 126, 16, 18);
    ctx.fillStyle = "#475569";
    ctx.fillRect(128, 92, 4, 34);
    ctx.fillStyle = "#f59e0b";
    ctx.beginPath();
    ctx.moveTo(116, 92);
    ctx.lineTo(144, 92);
    ctx.lineTo(138, 74);
    ctx.lineTo(122, 74);
    ctx.closePath();
    ctx.fill();
  } else {
    // preset:starlight — Bethlehem radiance above snowy valley town
    const g = ctx.createRadialGradient(80, 44, 6, 80, 68, 120);
    g.addColorStop(0, "#fef08a");
    g.addColorStop(0.28, "#6366f1");
    g.addColorStop(0.65, "#1e1b4b");
    g.addColorStop(1, "#090d1f");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, S, S);
    drawStars([[18, 22, 1.3], [44, 18, 1], [122, 20, 1.4], [142, 42, 1.1], [28, 58, 1]]);

    // 4-point starflare + diagonal light rays
    ctx.fillStyle = "#fffbeb";
    ctx.beginPath();
    ctx.moveTo(80, 18);
    ctx.lineTo(86, 38);
    ctx.lineTo(106, 44);
    ctx.lineTo(86, 50);
    ctx.lineTo(80, 70);
    ctx.lineTo(74, 50);
    ctx.lineTo(54, 44);
    ctx.lineTo(74, 38);
    ctx.closePath();
    ctx.fill();

    // Valley hills + cottages + glowing windows
    ctx.fillStyle = "#1e293b";
    ctx.beginPath();
    ctx.moveTo(0, 130);
    ctx.quadraticCurveTo(50, 108, 98, 124);
    ctx.quadraticCurveTo(132, 134, S, 116);
    ctx.lineTo(S, S);
    ctx.lineTo(0, S);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "#f1f5f9";
    ctx.beginPath();
    ctx.ellipse(80, 152, 95, 22, 0, 0, Math.PI * 2);
    ctx.fill();
    paintTinyPineSilhouette(ctx, 26, 132, 34, 16, "#0f2e24");
    paintTinyPineSilhouette(ctx, 134, 132, 36, 18, "#0f2e24");
    ctx.fillStyle = "#334155";
    ctx.fillRect(58, 114, 18, 18);
    ctx.fillRect(82, 108, 20, 24);
    ctx.fillStyle = "#fef08a";
    ctx.fillRect(63, 120, 6, 6);
    ctx.fillRect(88, 116, 7, 7);
  }
  return c;
}

function getChristmasTreePhotoAsset(photoData) {
  if (!photoData) return null;
  if (christmasTreeMediaCache.has(photoData)) {
    return christmasTreeMediaCache.get(photoData);
  }
  if (photoData.startsWith("preset:")) {
    const canvas = buildPresetThumbnailCanvas(photoData);
    const entry = { ready: true, drawable: canvas, dataUrl: canvas.toDataURL("image/png") };
    christmasTreeMediaCache.set(photoData, entry);
    return entry;
  }
  if (
    photoData.startsWith("data:image/") ||
    photoData.startsWith("/api/christmas-tree/photos/") ||
    photoData.startsWith("public/") ||
    photoData.startsWith("/public/")
  ) {
    const img = new Image();
    const entry = { ready: false, drawable: img, dataUrl: photoData };
    img.onload = () => {
      entry.ready = true;
    };
    img.src = photoData;
    christmasTreeMediaCache.set(photoData, entry);
    return entry;
  }
  return null;
}

function buildChristmasTreeGeometry(isMobile) {
  const rng = createSeededTreeRng(20261225);
  const items = [];
  const goldenAngle = 2.399963229728653;

  // Depth-sorted segmented wooden trunk running continuously from snow base up to summit star
  const trunkSegments = 48;
  for (let k = 0; k < trunkSegments; k++) {
    const u0 = k / trunkSegments;
    const u1 = (k + 1) / trunkSegments;
    items.push({
      kind: "trunk_seg",
      segIdx: k,
      segTotal: trunkSegments,
      u0,
      u1,
      u: (u0 + u1) * 0.5,
      rNorm: 0,
      angle: 0
    });
  }

  // 1. Conical evergreen pine needles starting cleanly above trunk (u = 0.215..0.985)
  // Area-weighted distribution (1 - (1 - t)^2.05) keeps lush pine foliage density across wide lower boughs
  const foliageCount = isMobile ? 820 : 1650;
  for (let i = 0; i < foliageCount; i++) {
    const tRatio = i / foliageCount;
    const uLin = 1 - Math.pow(1 - tRatio, 2.05);
    const u = 0.215 + uLin * 0.77;
    const angle = i * goldenAngle + (rng() - 0.5) * 0.24;
    const minShell = u < 0.36 ? 0.25 : 0.14;
    const shell = minShell + (1 - minShell) * Math.pow(rng(), 0.44);
    const rNorm = coneRadiusAtHeight(u) * shell;
    const toneRoll = rng();
    const tone = toneRoll < 0.42 ? 0 : (toneRoll < 0.74 ? 1 : (toneRoll < 0.94 ? 2 : 3));
    const lowerSizeBoost = 1 + (1 - uLin) * 0.18;
    items.push({
      kind: "needle",
      u: Math.max(0.215, Math.min(0.99, u + (rng() - 0.5) * 0.015)),
      rNorm,
      angle,
      size: ((isMobile ? 2.15 : 2.35) + rng() * 2.15) * lowerSizeBoost,
      tone,
      phase: rng() * Math.PI * 2
    });
  }

  // 2. Humble starter state: ONLY gentle warm golden fairy pinpoints (community items add Polaroids, gifts, baubles & rainbow lights)
  const lightCount = isMobile ? 18 : 26;
  const strandTurns = 3.8;
  for (let i = 0; i < lightCount; i++) {
    const u = 0.235 + (i / lightCount) * 0.705;
    const angle = u * Math.PI * 2 * strandTurns + (rng() - 0.5) * 0.22;
    items.push({
      kind: "light",
      u,
      rNorm: coneRadiusAtHeight(u) * 1.02,
      angle,
      key: "gold",
      coreColor: "#FDE68A",
      size: isMobile ? 1.85 : 2.15,
      phase: rng() * Math.PI * 2,
      speed: 1.6 + rng() * 1.6
    });
  }

  // 3. Soft subtle dust sparkles
  const sparkleCount = isMobile ? 6 : 12;
  for (let i = 0; i < sparkleCount; i++) {
    items.push({
      kind: "sparkle",
      u: 0.14 + rng() * 0.88,
      rNorm: (0.45 + rng() * 0.75) * Math.max(0.24, coneRadiusAtHeight(0.2 + rng() * 0.72)),
      angle: rng() * Math.PI * 2,
      speedY: 0.045 + rng() * 0.055,
      size: 1.3 + rng() * 1.3,
      phase: rng() * Math.PI * 2,
      isGold: rng() > 0.35
    });
  }

  christmasTreeState.baseItems = items;
  syncCombinedChristmasTreeItems();
}

function buildCommunityOrnamentNodes(communityItems) {
  if (!Array.isArray(communityItems) || !communityItems.length) return [];
  const nodes = [];
  const totalGifts = communityItems.reduce((acc, it) => (
    it && (it.slotKind === "gift" || String(it.itemStyle || "").startsWith("gift_")) ? acc + 1 : acc
  ), 0);
  const giftCrowdScale = totalGifts <= 10 ? 1 : Math.max(0.44, Math.sqrt(10 / totalGifts));
  let giftIdx = 0;
  for (let i = 0; i < communityItems.length; i++) {
    const item = communityItems[i];
    if (!item || !item.id) continue;
    const uClamped = Math.max(0.245, Math.min(0.84, Number(item.posU) || 0.48));
    const angle = Number(item.posAngle) || (i * 2.15);

    if (item.slotKind === "polaroid") {
      nodes.push({
        kind: "community_polaroid",
        data: item,
        u: uClamped,
        rNorm: coneRadiusAtHeight(uClamped) * 1.13,
        angle,
        frameColor: item.frameColor || TREE_POLAROID_FRAME_MAP[item.itemStyle] || "#FFFAF0",
        gradientStops: Array.isArray(item.gradientStops)
          ? item.gradientStops
          : (TREE_POLAROID_GRADIENT_MAP[item.itemStyle] || null),
        accentColor: item.accentColor || "#F0E68C",
        photoData: item.photoData || "",
        swayPhase: ((item.id * 1.37) % (Math.PI * 2)),
        baseTilt: (((item.id % 5) - 2) * 0.08),
        scale: 1.05
      });
    } else if (item.slotKind === "card") {
      const tplKey = normalizeCardTemplateKey(item.itemStyle);
      const finKey = normalizeCardFinishKey(item.itemFinish);
      const finishSpec = TREE_CARD_FINISH_MAP[finKey] || TREE_CARD_FINISH_MAP.pastel_white;
      nodes.push({
        kind: "community_card",
        data: item,
        u: uClamped,
        rNorm: coneRadiusAtHeight(uClamped) * 1.14,
        angle,
        itemStyle: tplKey,
        itemFinish: finKey,
        gradientStops: Array.isArray(item.gradientStops) ? item.gradientStops : finishSpec.gradientStops,
        frameColor: finishSpec.bg || item.frameColor || "#FFFFFF",
        accentColor: item.accentColor || "#C8102E",
        cardName: item.cardName || item.authorName || "RE:SEARCH",
        swayPhase: ((item.id * 1.71) % (Math.PI * 2)),
        baseTilt: (((item.id % 5) - 2) * 0.07),
        scale: 1.06
      });
    } else if (item.slotKind === "gift" || String(item.itemStyle || "").startsWith("gift_")) {
      const palette = TREE_GIFT_PALETTE_MAP[item.itemStyle] || TREE_GIFT_PALETTE_MAP.gift_red;
      const stops = Array.isArray(item.gradientStops) ? item.gradientStops : palette.gradientStops;
      // Vogel annulus phyllotaxis scatters 1..100+ gifts evenly across the entire snow ring & scales size automatically
      const minRing = totalGifts > 14 ? 0.25 : 0.38;
      const maxRing = totalGifts > 14 ? 0.84 : 0.72;
      const areaFrac = totalGifts <= 1 ? 0.5 : (giftIdx + 0.5) / totalGifts;
      const rNorm = totalGifts > 10
        ? Math.sqrt(minRing * minRing + areaFrac * (maxRing * maxRing - minRing * minRing))
        : (minRing + ((giftIdx * 0.61803398875) % 1) * (maxRing - minRing));
      const orbitAngle = totalGifts > 10 ? ((giftIdx * 2.399963229728653) % (Math.PI * 2)) : angle;
      giftIdx += 1;
      nodes.push({
        kind: "community_gift",
        data: item,
        u: -0.016,
        rNorm,
        angle: orbitAngle,
        yawOffset: ((item.id * 1.13) % (Math.PI * 2)),
        palette: { ...palette, gradientStops: stops },
        size: 13.8 * giftCrowdScale
      });
    } else if (item.itemStyle === "fairy_garland" || item.itemStyle === "prism_multi_garland") {
      const isPrism = item.itemStyle === "prism_multi_garland";
      const garlandKeys = isPrism ? ["red", "gold", "green", "blue", "gold"] : ["red", "gold", "blue", "green"];
      const bulbColors = { gold: "#FFD54F", red: "#FF2D2D", blue: "#38BDF8", green: "#22C55E" };
      const prismColors = ["#F43F5E", "#F59E0B", "#10B981", "#38BDF8", "#C084FC"];
      const bandCenter = Math.max(0.26, Math.min(0.8, uClamped));
      const bulbCount = isPrism ? 11 : 9;
      const midIdx = (bulbCount - 1) / 2;
      for (let b = 0; b < bulbCount; b++) {
        const offsetFrac = (b - midIdx) / midIdx;
        const bu = Math.max(0.19, Math.min(0.91, bandCenter + offsetFrac * 0.12));
        const key = garlandKeys[(item.id + b) % garlandKeys.length];
        nodes.push({
          kind: "community_garland_bulb",
          data: item,
          u: bu,
          rNorm: coneRadiusAtHeight(bu) * 1.05,
          angle: angle + offsetFrac * 1.2,
          key,
          coreColor: isPrism ? prismColors[b % prismColors.length] : bulbColors[key],
          size: isPrism ? 2.85 : 2.55,
          phase: b * 0.8 + item.id,
          speed: 2.4 + (b % 3) * 0.45
        });
      }
    } else if (item.itemStyle === "star_grad_gold") {
      nodes.push({
        kind: "community_star_ornament",
        data: item,
        u: uClamped,
        rNorm: coneRadiusAtHeight(uClamped) * 1.05,
        angle,
        gradientStops: Array.isArray(item.gradientStops) ? item.gradientStops : TREE_ACCESSORY_GRADIENT_MAP.star_grad_gold,
        swayPhase: ((item.id * 1.19) % (Math.PI * 2)),
        size: 6.4
      });
    } else if (item.itemStyle === "ribbon_grad_velvet") {
      nodes.push({
        kind: "community_ribbon_bow",
        data: item,
        u: uClamped,
        rNorm: coneRadiusAtHeight(uClamped) * 1.06,
        angle,
        gradientStops: Array.isArray(item.gradientStops) ? item.gradientStops : TREE_ACCESSORY_GRADIENT_MAP.ribbon_grad_velvet,
        swayPhase: ((item.id * 1.43) % (Math.PI * 2)),
        size: 6.8
      });
    } else {
      const color = TREE_BAUBLE_COLOR_MAP[item.itemStyle] || item.accentColor || "#E11D48";
      const stops = Array.isArray(item.gradientStops)
        ? item.gradientStops
        : (TREE_ACCESSORY_GRADIENT_MAP[item.itemStyle] || null);
      nodes.push({
        kind: "community_bauble",
        data: item,
        u: uClamped,
        rNorm: coneRadiusAtHeight(uClamped) * 1.02,
        angle,
        color,
        gradientStops: stops,
        size: stops ? 5.2 : 4.8
      });
    }
  }
  return nodes;
}

function syncCombinedChristmasTreeItems() {
  const base = christmasTreeState.baseItems || [];
  const community = buildCommunityOrnamentNodes(christmasTreeEventState.items);
  const combined = base.concat(community);
  christmasTreeState.items = combined;
  christmasTreeState.projected = new Array(combined.length);
}

function drawSoftSnowDriftLobe(ctx, cx, cy, rx, ry, isDark) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(1, ry / Math.max(1, rx));
  const g = ctx.createRadialGradient(0, -rx * 0.14, rx * 0.06, 0, 0, rx);
  if (isDark) {
    g.addColorStop(0, "rgba(248, 250, 252, 0.92)");
    g.addColorStop(0.55, "rgba(226, 232, 240, 0.45)");
    g.addColorStop(1, "rgba(226, 232, 240, 0)");
  } else {
    g.addColorStop(0, "rgba(255, 255, 255, 0.98)");
    g.addColorStop(0.58, "rgba(248, 252, 255, 0.52)");
    g.addColorStop(1, "rgba(255, 255, 255, 0)");
  }
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, rx, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function drawTreeBaseAndMound(ctx, anchorX, baseY, treeR, isDark) {
  // Natural sculpted snowdrift bank tapering softly to alpha=0 along the floor (zero hard saucer outline)
  ctx.save();
  const bankHalfW = treeR * 0.95;
  const moundH = Math.max(10, treeR * 0.21);
  const steps = 28;

  // Wavy multi-hump snowbank silhouette blending vertically from sunlit snow crest to transparent floor
  const bankGrad = ctx.createLinearGradient(anchorX, baseY - moundH, anchorX, baseY + moundH * 0.65);
  if (isDark) {
    bankGrad.addColorStop(0, "rgba(255, 255, 255, 0.92)");
    bankGrad.addColorStop(0.45, "rgba(219, 234, 254, 0.68)");
    bankGrad.addColorStop(0.82, "rgba(148, 163, 184, 0.18)");
    bankGrad.addColorStop(1, "rgba(148, 163, 184, 0)");
  } else {
    bankGrad.addColorStop(0, "rgba(255, 255, 255, 0.98)");
    bankGrad.addColorStop(0.42, "rgba(241, 248, 255, 0.84)");
    bankGrad.addColorStop(0.82, "rgba(224, 242, 254, 0.24)");
    bankGrad.addColorStop(1, "rgba(255, 255, 255, 0)");
  }

  ctx.beginPath();
  ctx.moveTo(anchorX - bankHalfW, baseY + moundH * 0.55);
  for (let i = 0; i <= steps; i++) {
    const u = i / steps;
    const x = anchorX - bankHalfW + u * bankHalfW * 2;
    const env = Math.pow(Math.sin(u * Math.PI), 0.85);
    const wave =
      Math.sin(u * Math.PI * 2.7 + 0.55) * 0.22 +
      Math.cos(u * Math.PI * 4.4 - 0.3) * 0.12 +
      0.72;
    const crestY = baseY + 2 - moundH * env * Math.max(0.35, wave);
    ctx.lineTo(x, crestY);
  }
  ctx.lineTo(anchorX + bankHalfW, baseY + moundH * 0.55);
  ctx.quadraticCurveTo(anchorX, baseY + moundH * 0.82, anchorX - bankHalfW, baseY + moundH * 0.55);
  ctx.closePath();
  ctx.fillStyle = bankGrad;
  ctx.fill();

  // Soft pine-branch contact occlusion tucked into the snow right under the lowest foliage skirt
  const castGrad = ctx.createRadialGradient(anchorX, baseY - 1, 2, anchorX, baseY + 1, treeR * 0.72);
  castGrad.addColorStop(0, isDark ? "rgba(2, 16, 18, 0.44)" : "rgba(15, 23, 42, 0.14)");
  castGrad.addColorStop(0.65, isDark ? "rgba(2, 16, 18, 0.16)" : "rgba(15, 23, 42, 0.04)");
  castGrad.addColorStop(1, "rgba(0, 0, 0, 0)");
  ctx.fillStyle = castGrad;
  ctx.beginPath();
  ctx.ellipse(anchorX, baseY + 1, treeR * 0.72, moundH * 0.62, 0, 0, Math.PI * 2);
  ctx.fill();

  // Powdery snow drifts pillowing organically around foreground & trunk collar
  drawSoftSnowDriftLobe(ctx, anchorX - treeR * 0.32, baseY + 1, treeR * 0.42, moundH * 0.72, isDark);
  drawSoftSnowDriftLobe(ctx, anchorX + treeR * 0.3, baseY + 2, treeR * 0.38, moundH * 0.68, isDark);
  drawSoftSnowDriftLobe(ctx, anchorX, baseY - moundH * 0.32, treeR * 0.24, moundH * 0.54, isDark);

  // Subtle icy surface glints along upper sunlit ridges
  const glints = [-0.32, -0.12, 0.11, 0.29];
  ctx.fillStyle = "#ffffff";
  for (let i = 0; i < glints.length; i++) {
    ctx.globalAlpha = 0.78 - i * 0.08;
    ctx.beginPath();
    ctx.arc(anchorX + treeR * glints[i], baseY - moundH * (0.26 + (i % 2) * 0.22), 1.15, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

function projectTreeAxisY(u, baseY, treeH) {
  const fov = 560;
  const tiltSin = 0.11;
  const tiltCos = 0.9939;
  const yRel = (0.44 - u) * treeH;
  const y3Tilt = yRel * tiltCos;
  const z3Tilt = yRel * tiltSin;
  const persp = fov / (fov + z3Tilt);
  return (baseY - treeH * 0.44) + y3Tilt * persp;
}

function getTreeTrunkHalfWidth(u, treeR) {
  const uc = Math.max(0, Math.min(1, u));
  const rootHalfW = Math.max(5.5, treeR * 0.125);
  const skirtHalfW = Math.max(3.6, treeR * 0.072);
  const tipHalfW = Math.max(2.0, treeR * 0.023);
  if (uc <= 0.215) {
    const p = uc / 0.215;
    return rootHalfW + (skirtHalfW - rootHalfW) * Math.pow(p, 0.72);
  }
  const upperP = (uc - 0.215) / 0.785;
  return skirtHalfW + (tipHalfW - skirtHalfW) * upperP;
}

function drawTreeTrunkSegment(ctx, it, anchorX, baseY, treeH, treeR, starY, rot, isDark) {
  const k = it.segIdx;
  const isBase = k === 0;
  const isTop = k === it.segTotal - 1;
  const y0 = isBase ? (baseY - treeH * 0.004) : projectTreeAxisY(it.u0, baseY, treeH);
  const y1 = isTop ? starY : projectTreeAxisY(it.u1, baseY, treeH);
  const yTopDraw = isTop ? y1 : (y1 - 1.4);
  const hw0 = getTreeTrunkHalfWidth(it.u0, treeR) * (isBase ? 1.04 : 1);
  const hw1 = getTreeTrunkHalfWidth(it.u1, treeR);
  const gradHalfW = Math.max(hw0, hw1, 2.2);

  ctx.save();
  ctx.globalAlpha = 1;

  const trunkGrad = ctx.createLinearGradient(anchorX - gradHalfW, 0, anchorX + gradHalfW, 0);
  if (isDark) {
    trunkGrad.addColorStop(0, "#27160c");
    trunkGrad.addColorStop(0.32, "#5c3824");
    trunkGrad.addColorStop(0.56, "#7c4f35");
    trunkGrad.addColorStop(1, "#21120a");
  } else {
    trunkGrad.addColorStop(0, "#3d2415");
    trunkGrad.addColorStop(0.34, "#794c31");
    trunkGrad.addColorStop(0.56, "#9a6343");
    trunkGrad.addColorStop(1, "#331c0f");
  }

  ctx.beginPath();
  ctx.moveTo(anchorX - hw0, y0);
  ctx.lineTo(anchorX - hw1, yTopDraw);
  ctx.lineTo(anchorX + hw1, yTopDraw);
  ctx.lineTo(anchorX + hw0, y0);
  if (isBase) {
    ctx.quadraticCurveTo(anchorX, y0 + 1.4, anchorX - hw0, y0);
  }
  ctx.closePath();
  ctx.fillStyle = trunkGrad;
  ctx.fill();

  // Smooth rotating bark ridges (alpha faded by cos(angle) so zero pop/flicker)
  ctx.save();
  ctx.clip();
  ctx.strokeStyle = isDark ? "rgb(18, 9, 4)" : "rgb(44, 24, 12)";
  ctx.lineWidth = Math.max(0.75, gradHalfW * 0.13);
  for (let b = 0; b < 4; b++) {
    const barkPhase = rot + b * (Math.PI * 0.5);
    const cosA = Math.cos(barkPhase);
    if (cosA > 0.02) {
      const sinA = Math.sin(barkPhase);
      ctx.globalAlpha = Math.min(1, cosA * 1.15) * (isDark ? 0.48 : 0.36);
      ctx.beginPath();
      ctx.moveTo(anchorX + sinA * hw0 * 0.72, y0);
      ctx.lineTo(anchorX + sinA * hw1 * 0.72, yTopDraw);
      ctx.stroke();
    }
  }

  // Subtle ambient shadow under the lowest foliage skirt (u around 0.14..0.24)
  if (it.u >= 0.12 && it.u <= 0.25) {
    const shadeAlpha = it.u < 0.215
      ? Math.max(0, (it.u - 0.12) / 0.095) * 0.42
      : 0.42 * (1 - (it.u - 0.215) / 0.045);
    if (shadeAlpha > 0.01) {
      ctx.globalAlpha = shadeAlpha;
      ctx.fillStyle = "#000000";
      ctx.fillRect(anchorX - hw0 - 1, yTopDraw - 1, (hw0 + 1) * 2, (y0 - yTopDraw) + 2);
    }
  }
  ctx.restore();
  ctx.restore();

  if (isBase) {
    // Grounded contact shadow & soft radial snow collar tucked over trunk root
    ctx.save();
    ctx.globalAlpha = 1;
    const collarRx = hw0 * 1.48;
    const collarRy = Math.max(3.0, hw0 * 0.42);
    const contactGrad = ctx.createRadialGradient(anchorX, y0 + 1.2, 1, anchorX, y0 + 1.2, collarRx * 1.15);
    contactGrad.addColorStop(0, isDark ? "rgba(2, 12, 24, 0.34)" : "rgba(71, 85, 105, 0.14)");
    contactGrad.addColorStop(1, "rgba(0, 0, 0, 0)");
    ctx.fillStyle = contactGrad;
    ctx.beginPath();
    ctx.ellipse(anchorX, y0 + 1.2, collarRx * 1.15, collarRy * 1.1, 0, 0, Math.PI * 2);
    ctx.fill();

    const snowGrad = ctx.createRadialGradient(anchorX, y0 - 0.6, 1, anchorX, y0 - 0.6, collarRx);
    snowGrad.addColorStop(0, isDark ? "rgba(236, 244, 255, 0.96)" : "rgba(255, 255, 255, 0.98)");
    snowGrad.addColorStop(0.68, isDark ? "rgba(218, 232, 248, 0.85)" : "rgba(248, 252, 255, 0.88)");
    snowGrad.addColorStop(1, isDark ? "rgba(203, 222, 242, 0)" : "rgba(241, 247, 255, 0)");
    ctx.fillStyle = snowGrad;
    ctx.beginPath();
    ctx.ellipse(anchorX, y0 - 0.6, collarRx, collarRy, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }
}

function drawFacetedTopStar(ctx, cx, cy, outerR, rotY, isDark, sprites) {
  const glowSize = outerR * 3.8;
  ctx.save();
  ctx.globalAlpha = isDark ? 0.88 : 0.74;
  ctx.drawImage(sprites.starGlow, cx - glowSize * 0.5, cy - glowSize * 0.5, glowSize, glowSize);

  const cosY = Math.cos(rotY);
  const scaleX = Math.sign(cosY || 1) * Math.max(0.28, Math.abs(cosY));
  const innerR = outerR * 0.44;
  const pts = [];
  for (let i = 0; i < 10; i++) {
    const a = (i * Math.PI) / 5 - Math.PI / 2;
    const r = (i % 2 === 0) ? outerR : innerR;
    pts.push({ x: cx + Math.cos(a) * r * scaleX, y: cy + Math.sin(a) * r });
  }

  const depthShift = -Math.sin(rotY) * outerR * 0.18;
  ctx.globalAlpha = 1;
  ctx.beginPath();
  pts.forEach((p, i) => (i === 0 ? ctx.moveTo(p.x + depthShift, p.y) : ctx.lineTo(p.x + depthShift, p.y)));
  ctx.closePath();
  ctx.fillStyle = "#B45309";
  ctx.fill();

  for (let i = 0; i < 10; i++) {
    const p1 = pts[i];
    const p2 = pts[(i + 1) % 10];
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.closePath();
    ctx.fillStyle = (i % 2 === 0) ? "#FFD700" : "#F59E0B";
    ctx.fill();
  }

  ctx.strokeStyle = isDark ? "#FFFBEB" : "#D97706";
  ctx.lineWidth = 0.85;
  ctx.lineJoin = "round";
  ctx.beginPath();
  pts.forEach((p, idx) => (idx === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y)));
  ctx.closePath();
  ctx.stroke();

  ctx.fillStyle = "#FFFBEB";
  ctx.beginPath();
  ctx.arc(cx, cy, Math.max(1.4, outerR * 0.16), 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function hexShadeRgb(hex, mult) {
  const clean = String(hex || "").replace("#", "");
  if (clean.length !== 6) return String(hex || "#e2e8f0");
  const r = Math.max(0, Math.min(255, Math.round(parseInt(clean.slice(0, 2), 16) * mult)));
  const g = Math.max(0, Math.min(255, Math.round(parseInt(clean.slice(2, 4), 16) * mult)));
  const b = Math.max(0, Math.min(255, Math.round(parseInt(clean.slice(4, 6), 16) * mult)));
  return `rgb(${r}, ${g}, ${b})`;
}

function lerpQuadUV(quad, u, v) {
  const [p0, p1, p2, p3] = quad;
  const u1 = 1 - u;
  const v1 = 1 - v;
  return {
    x: u1 * v1 * p0.sx + u * v1 * p1.sx + u * v * p2.sx + u1 * v * p3.sx,
    y: u1 * v1 * p0.sy + u * v1 * p1.sy + u * v * p2.sy + u1 * v * p3.sy
  };
}

function drawQuadBandUV(ctx, quad, u0, v0, u1, v1, fillStyle, strokeStyle = "") {
  const c0 = lerpQuadUV(quad, u0, v0);
  const c1 = lerpQuadUV(quad, u1, v0);
  const c2 = lerpQuadUV(quad, u1, v1);
  const c3 = lerpQuadUV(quad, u0, v1);
  ctx.beginPath();
  ctx.moveTo(c0.x, c0.y);
  ctx.lineTo(c1.x, c1.y);
  ctx.lineTo(c2.x, c2.y);
  ctx.lineTo(c3.x, c3.y);
  ctx.closePath();
  ctx.fillStyle = fillStyle;
  ctx.fill();
  if (strokeStyle) {
    ctx.strokeStyle = strokeStyle;
    ctx.lineWidth = 0.7;
    ctx.stroke();
  }
}

function createGradientFillFromStops(ctx, x0, y0, x1, y1, stops, shadeMult = 1) {
  if (!Array.isArray(stops) || stops.length < 2) {
    return shadeMult === 1 ? (stops && stops[0]) || "#FFFAF0" : hexShadeRgb((stops && stops[0]) || "#FFFAF0", shadeMult);
  }
  const grad = ctx.createLinearGradient(x0, y0, x1, y1);
  const denom = Math.max(1, stops.length - 1);
  for (let i = 0; i < stops.length; i++) {
    const col = shadeMult === 1 ? stops[i] : hexShadeRgb(stops[i], shadeMult);
    grad.addColorStop(i / denom, col);
  }
  return grad;
}

function drawProjected3DGiftBox(ctx, cx, cy, s, yaw, palette, { isDark, isMystery, isSelected }) {
  const cosY = Math.cos(yaw);
  const sinY = Math.sin(yaw);
  const pitch = 0.36;
  const cosP = Math.cos(pitch);
  const sinP = Math.sin(pitch);
  const fovLocal = Math.max(24, s * 6.0);
  const gradStops = Array.isArray(palette && palette.gradientStops) ? palette.gradientStops : null;

  const projPt = (lx, ly, lz) => {
    const rx = lx * cosY - lz * sinY;
    const rz = lx * sinY + lz * cosY;
    const pl = fovLocal / (fovLocal + rz);
    return {
      sx: cx + rx * pl,
      sy: cy + (ly * cosP - rz * sinP) * pl,
      rz
    };
  };

  const renderPrism = (hx, yTop, yBot, hz, baseHex, lidMode) => {
    const t0 = projPt(-hx, yTop, -hz);
    const t1 = projPt(hx, yTop, -hz);
    const t2 = projPt(hx, yTop, hz);
    const t3 = projPt(-hx, yTop, hz);
    const b0 = projPt(-hx, yBot, -hz);
    const b1 = projPt(hx, yBot, -hz);
    const b2 = projPt(hx, yBot, hz);
    const b3 = projPt(-hx, yBot, hz);

    const sides = [
      { pts: [t0, t1, b1, b0], nx: sinY, nz: -cosY },
      { pts: [t1, t2, b2, b1], nx: cosY, nz: sinY },
      { pts: [t2, t3, b3, b2], nx: -sinY, nz: cosY },
      { pts: [t3, t0, b0, b3], nx: -cosY, nz: -sinY }
    ].filter((f) => f.nz < -0.001);

    sides.forEach((f) => {
      f.avgZ = (f.pts[0].rz + f.pts[1].rz + f.pts[2].rz + f.pts[3].rz) * 0.25;
    });
    sides.sort((a, b) => b.avgZ - a.avgZ);

    let bestFrontFace = null;
    for (let i = 0; i < sides.length; i++) {
      const f = sides[i];
      if (!bestFrontFace || -f.nz > -bestFrontFace.nz) bestFrontFace = f;
      const light = 0.72 + 0.34 * Math.max(0, -f.nz * 0.85 - f.nx * 0.42);
      const faceFill = gradStops
        ? createGradientFillFromStops(ctx, f.pts[0].sx, f.pts[0].sy, f.pts[2].sx, f.pts[2].sy, gradStops, light)
        : hexShadeRgb(baseHex, light);
      drawQuadBandUV(ctx, f.pts, 0, 0, 1, 1, faceFill, "rgba(255,255,255,0.12)");
      const ribShade = 0.84 + 0.24 * Math.max(0, -f.nz * 0.85 - f.nx * 0.42);
      drawQuadBandUV(ctx, f.pts, 0.39, 0, 0.61, 1, hexShadeRgb(palette.ribbon, ribShade));
      if (!lidMode) {
        drawQuadBandUV(ctx, f.pts, 0, 0.45, 1, 0.61, hexShadeRgb(palette.ribbon, ribShade));
        drawQuadBandUV(ctx, f.pts, 0, 0, 1, 0.14, "rgba(0, 0, 0, 0.24)");
      }
    }

    const topQuad = [t3, t2, t1, t0];
    const topFill = gradStops
      ? createGradientFillFromStops(ctx, t3.sx, t3.sy, t1.sx, t1.sy, gradStops, 1.08)
      : hexShadeRgb(baseHex, 1.08);
    drawQuadBandUV(ctx, topQuad, 0, 0, 1, 1, topFill, "rgba(255,255,255,0.22)");
    if (lidMode) {
      drawQuadBandUV(ctx, topQuad, 0.39, 0, 0.61, 1, palette.ribbon);
      drawQuadBandUV(ctx, topQuad, 0, 0.39, 1, 0.61, palette.ribbon);
    }
    return bestFrontFace;
  };

  ctx.save();
  // Soft ground/branch contact shadow directly beneath gift
  ctx.fillStyle = isDark ? "rgba(0, 0, 0, 0.42)" : "rgba(15, 23, 42, 0.22)";
  ctx.beginPath();
  ctx.ellipse(cx, cy + s * 0.46, s * 0.56, s * 0.18, 0, 0, Math.PI * 2);
  ctx.fill();

  const hx = s * 0.44;
  const bodyFace = renderPrism(hx, -s * 0.22, s * 0.44, hx, palette.box, false);
  renderPrism(hx * 1.11, -s * 0.46, -s * 0.19, hx * 1.11, palette.lid, true);

  // Rotating 3D top ribbon bow centered on lid
  const bowC = projPt(0, -s * 0.48, 0);
  const bowSpan = s * 0.24;
  const dxBow = cosY * bowSpan;
  const dyBow = -sinY * sinP * bowSpan * 0.85;
  ctx.strokeStyle = palette.ribbon;
  ctx.lineWidth = Math.max(1.2, s * 0.12);
  ctx.beginPath();
  ctx.ellipse(bowC.sx - dxBow * 0.62, bowC.sy - dyBow * 0.62 - s * 0.05, Math.max(1.5, Math.abs(cosY) * bowSpan * 0.68 + s * 0.08), s * 0.11, yaw * 0.15 - 0.3, 0, Math.PI * 2);
  ctx.ellipse(bowC.sx + dxBow * 0.62, bowC.sy + dyBow * 0.62 - s * 0.05, Math.max(1.5, Math.abs(cosY) * bowSpan * 0.68 + s * 0.08), s * 0.11, -yaw * 0.15 + 0.3, 0, Math.PI * 2);
  ctx.stroke();
  ctx.fillStyle = hexShadeRgb(palette.ribbon, 1.08);
  ctx.beginPath();
  ctx.arc(bowC.sx, bowC.sy - s * 0.03, Math.max(1.3, s * 0.1), 0, Math.PI * 2);
  ctx.fill();

  if (isMystery && bodyFace) {
    const fc = lerpQuadUV(bodyFace.pts, 0.5, 0.55);
    const faceScale = Math.max(0.28, -bodyFace.nz);
    const badgeR = Math.max(3.1, s * 0.24);
    ctx.save();
    ctx.translate(fc.x, fc.y);
    ctx.scale(faceScale, 1);
    ctx.fillStyle = "#fde047";
    ctx.beginPath();
    ctx.arc(0, 0, badgeR, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#7f1d1d";
    ctx.font = `900 ${Math.max(6, Math.round(badgeR * 1.35))}px sans-serif`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("?", 0, badgeR * 0.06);
    ctx.restore();
  }

  if (isSelected) {
    ctx.strokeStyle = "#FACC15";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.ellipse(cx, cy - s * 0.02, s * 0.72, s * 0.68, 0, 0, Math.PI * 2);
    ctx.stroke();
  }
  ctx.restore();
}

function drawProjected3DPolaroid(ctx, sx, sy, pw, ph, sway, angle, it, { isDark, isSelected }) {
  // Outward normal faces radial angle: facing=+1 front (-pi/2), 0 edge-on (0 or pi), -1 back (+pi/2)
  const facing = -Math.sin(angle);
  const absFacing = Math.abs(facing);
  const edgeCos = Math.cos(angle);
  const scaleX = Math.max(0.08, absFacing);
  const isFront = facing >= 0;

  ctx.save();
  ctx.translate(sx, sy);

  // Delicate gold string leaning slightly inward toward cone trunk
  ctx.strokeStyle = "#EAB308";
  ctx.lineWidth = Math.max(0.7, pw * 0.045);
  ctx.beginPath();
  ctx.moveTo(0, -ph * 0.48);
  ctx.lineTo(-edgeCos * Math.max(1.5, pw * 0.14), -ph * 0.5 - Math.max(4, pw * 0.24));
  ctx.stroke();

  ctx.rotate(sway * (0.35 + 0.65 * absFacing));
  // Perspective foreshortening & subtle vertical slant as ornament sweeps around cylinder
  ctx.transform(scaleX, edgeCos * 0.14, 0, 1, 0, 0);

  // Drop shadow behind Polaroid card
  ctx.fillStyle = isDark ? "rgba(0, 0, 0, 0.38)" : "rgba(15, 23, 42, 0.2)";
  ctx.fillRect(-pw * 0.5 + 1.4, -ph * 0.5 + 1.8, pw, ph);

  // Visible 3D cardstock side edge when rotated past ~35 deg
  if (absFacing < 0.84) {
    const edgeThick = (1 - absFacing) * Math.max(1.6, pw * 0.16) / scaleX;
    const edgeDir = edgeCos >= 0 ? -1 : 1;
    ctx.fillStyle = isDark ? "#94a3b8" : "#cbd5e1";
    ctx.fillRect(
      edgeDir < 0 ? -pw * 0.5 - edgeThick : pw * 0.5,
      -ph * 0.5,
      edgeThick,
      ph
    );
  }

  if (isFront) {
    ctx.fillStyle = Array.isArray(it.gradientStops) && it.gradientStops.length >= 2
      ? createGradientFillFromStops(ctx, -pw * 0.5, -ph * 0.5, pw * 0.5, ph * 0.5, it.gradientStops)
      : (it.frameColor || "#FFFAF0");
    ctx.fillRect(-pw * 0.5, -ph * 0.5, pw, ph);
    if (isSelected || !isDark) {
      ctx.strokeStyle = isSelected ? "#F59E0B" : "rgba(15, 23, 42, 0.22)";
      ctx.lineWidth = isSelected ? 2 : 0.7;
      ctx.strokeRect(-pw * 0.5, -ph * 0.5, pw, ph);
    }

    const pad = pw * 0.12;
    const imgW = pw - pad * 2;
    const imgH = ph * 0.66;
    const imgX = -pw * 0.5 + pad;
    const imgY = -ph * 0.5 + pad;
    const isMystery = Boolean(it.data && it.data.isMysteryLocked);
    if (isMystery) {
      const mg = ctx.createLinearGradient(imgX, imgY, imgX + imgW, imgY + imgH);
      mg.addColorStop(0, "#9f1239");
      mg.addColorStop(1, "#be123c");
      ctx.fillStyle = mg;
      ctx.fillRect(imgX, imgY, imgW, imgH);
      ctx.strokeStyle = "#fde047";
      ctx.lineWidth = Math.max(0.8, pw * 0.045);
      ctx.beginPath();
      ctx.moveTo(imgX, imgY + imgH * 0.5);
      ctx.lineTo(imgX + imgW, imgY + imgH * 0.5);
      ctx.moveTo(imgX + imgW * 0.5, imgY);
      ctx.lineTo(imgX + imgW * 0.5, imgY + imgH);
      ctx.stroke();
      ctx.fillStyle = "#fffbeb";
      ctx.font = `800 ${Math.max(8, Math.round(imgH * 0.54))}px sans-serif`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText("?", 0, imgY + imgH * 0.52);
    } else {
      const asset = getChristmasTreePhotoAsset(it.photoData);
      const canDraw = asset && asset.ready && asset.drawable && (
        asset.drawable instanceof HTMLCanvasElement || Number(asset.drawable.naturalWidth) > 0
      );
      if (canDraw) {
        ctx.drawImage(asset.drawable, imgX, imgY, imgW, imgH);
      } else {
        ctx.fillStyle = it.accentColor || "#F0E68C";
        ctx.fillRect(imgX, imgY, imgW, imgH);
      }
      if (it.data && it.data.message && pw >= 15) {
        ctx.fillStyle = "rgba(51, 65, 85, 0.52)";
        ctx.fillRect(-pw * 0.34, ph * 0.31, pw * 0.68, Math.max(1.2, pw * 0.05));
      }
    }
  } else {
    // Authentic cardstock back when spun 180 deg behind tree
    ctx.fillStyle = isDark ? "#e2dcd0" : "#efe6d5";
    ctx.fillRect(-pw * 0.5, -ph * 0.5, pw, ph);
    ctx.strokeStyle = isSelected ? "#F59E0B" : "rgba(100, 116, 139, 0.32)";
    ctx.lineWidth = isSelected ? 2 : 0.75;
    ctx.strokeRect(-pw * 0.5, -ph * 0.5, pw, ph);
    // Decorative craft tape + wax seal on reverse
    ctx.fillStyle = "rgba(217, 119, 6, 0.42)";
    ctx.fillRect(-pw * 0.16, -ph * 0.54, pw * 0.32, ph * 0.15);
    ctx.fillStyle = "#b91c1c";
    ctx.beginPath();
    ctx.arc(0, 0, Math.max(1.8, pw * 0.14), 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

function drawProjected3DGreetingCard(ctx, sx, sy, cw, ch, sway, angle, it, { isDark, isSelected }) {
  const facing = -Math.sin(angle);
  const absFacing = Math.abs(facing);
  const edgeCos = Math.cos(angle);
  const scaleX = Math.max(0.08, absFacing);
  const isFront = facing >= 0;

  ctx.save();
  ctx.translate(sx, sy);

  // Crimson hanging thread attached to card top
  ctx.strokeStyle = "#EF4444";
  ctx.lineWidth = Math.max(0.7, cw * 0.045);
  ctx.beginPath();
  ctx.moveTo(0, -ch * 0.48);
  ctx.lineTo(-edgeCos * Math.max(1.4, cw * 0.13), -ch * 0.5 - Math.max(4, cw * 0.22));
  ctx.stroke();

  ctx.rotate(sway * (0.35 + 0.65 * absFacing));
  ctx.transform(scaleX, edgeCos * 0.14, 0, 1, 0, 0);

  ctx.fillStyle = isDark ? "rgba(0, 0, 0, 0.4)" : "rgba(15, 23, 42, 0.2)";
  ctx.fillRect(-cw * 0.5 + 1.3, -ch * 0.5 + 1.8, cw, ch);

  if (absFacing < 0.84) {
    const edgeThick = (1 - absFacing) * Math.max(1.6, cw * 0.16) / scaleX;
    const edgeDir = edgeCos >= 0 ? -1 : 1;
    ctx.fillStyle = isDark ? "#cbd5e1" : "#e2e8f0";
    ctx.fillRect(edgeDir < 0 ? -cw * 0.5 - edgeThick : cw * 0.5, -ch * 0.5, edgeThick, ch);
  }

  if (isFront) {
    const hasGradTrim = Array.isArray(it.gradientStops) && it.gradientStops.length >= 2;
    const bgFill = hasGradTrim
      ? createGradientFillFromStops(ctx, -cw * 0.5, -ch * 0.5, cw * 0.5, ch * 0.5, it.gradientStops)
      : (it.frameColor || "#FFFFFF");
    ctx.fillStyle = bgFill;
    ctx.fillRect(-cw * 0.5, -ch * 0.5, cw, ch);

    const isMystery = Boolean(it.data && it.data.isMysteryLocked);
    if (isMystery) {
      const mg = ctx.createLinearGradient(-cw * 0.45, -ch * 0.45, cw * 0.45, ch * 0.45);
      mg.addColorStop(0, "#7f1d1d");
      mg.addColorStop(1, "#be123c");
      ctx.fillStyle = mg;
      ctx.fillRect(-cw * 0.44, -ch * 0.44, cw * 0.88, ch * 0.88);
      ctx.strokeStyle = "#fde047";
      ctx.lineWidth = Math.max(0.8, cw * 0.045);
      ctx.beginPath();
      ctx.moveTo(-cw * 0.44, -ch * 0.12);
      ctx.lineTo(0, ch * 0.14);
      ctx.lineTo(cw * 0.44, -ch * 0.12);
      ctx.stroke();
      ctx.fillStyle = "#fde047";
      ctx.beginPath();
      ctx.arc(0, ch * 0.14, Math.max(2.2, cw * 0.16), 0, Math.PI * 2);
      ctx.fill();
    } else {
      const tplKey = normalizeCardTemplateKey(it.itemStyle);
      const tplSpec = TREE_CARD_TEMPLATE_MAP[tplKey] || TREE_CARD_TEMPLATE_MAP.card_sparkle;
      const asset = tplSpec && tplSpec.img ? getChristmasTreePhotoAsset(tplSpec.img) : null;
      const canDraw = asset && asset.ready && asset.drawable && (
        asset.drawable instanceof HTMLCanvasElement || Number(asset.drawable.naturalWidth) > 0
      );
      if (canDraw) {
        ctx.drawImage(asset.drawable, -cw * 0.5, -ch * 0.5, cw, ch);
      } else {
        ctx.fillStyle = tplSpec ? tplSpec.accent : "#dc2626";
        ctx.fillRect(-cw * 0.34, -ch * 0.28, cw * 0.68, ch * 0.08);
        ctx.fillStyle = "rgba(30, 41, 59, 0.28)";
        ctx.fillRect(-cw * 0.34, -ch * 0.05, cw * 0.68, ch * 0.05);
        ctx.fillRect(-cw * 0.34, ch * 0.1, cw * 0.54, ch * 0.05);
      }
    }

    ctx.strokeStyle = isSelected ? "#F59E0B" : (isDark ? "rgba(255,255,255,0.55)" : "rgba(15, 23, 42, 0.24)");
    ctx.lineWidth = isSelected ? 2.1 : 0.75;
    ctx.strokeRect(-cw * 0.5, -ch * 0.5, cw, ch);
  } else {
    ctx.fillStyle = isDark ? "#fee2e2" : "#fff1f2";
    ctx.fillRect(-cw * 0.5, -ch * 0.5, cw, ch);
    ctx.strokeStyle = isSelected ? "#F59E0B" : "rgba(190, 18, 60, 0.35)";
    ctx.lineWidth = isSelected ? 2 : 0.8;
    ctx.strokeRect(-cw * 0.5, -ch * 0.5, cw, ch);
    ctx.fillStyle = "#be123c";
    ctx.beginPath();
    ctx.arc(0, 0, Math.max(2, cw * 0.15), 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

function drawProjected3DStarOrnament(ctx, sx, sy, r, sway, angle, stops, { isDark, isSelected }) {
  const facingScale = 0.28 + 0.72 * Math.abs(-Math.sin(angle));
  ctx.save();
  ctx.translate(sx, sy);
  ctx.rotate(sway * 0.4);
  ctx.scale(facingScale, 1);

  const pts = [];
  for (let i = 0; i < 10; i++) {
    const a = -Math.PI * 0.5 + (i * Math.PI) / 5;
    const rad = i % 2 === 0 ? r : r * 0.44;
    pts.push({ x: Math.cos(a) * rad, y: Math.sin(a) * rad });
  }
  ctx.beginPath();
  pts.forEach((p, idx) => (idx === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y)));
  ctx.closePath();
  ctx.fillStyle = createGradientFillFromStops(ctx, -r, -r, r, r, stops || ["#FEF9C3", "#FBBF24", "#D97706"]);
  ctx.fill();
  ctx.strokeStyle = isSelected ? "#FFFFFF" : (isDark ? "#FFFBEB" : "#B45309");
  ctx.lineWidth = isSelected ? 2 : 0.9;
  ctx.stroke();

  if (isSelected) {
    ctx.strokeStyle = "#FACC15";
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.arc(0, 0, r + 3.2, 0, Math.PI * 2);
    ctx.stroke();
  }
  ctx.restore();
}

function drawProjected3DRibbonBow(ctx, sx, sy, s, sway, angle, stops, { isSelected }) {
  const facingScale = 0.35 + 0.65 * Math.abs(-Math.sin(angle));
  ctx.save();
  ctx.translate(sx, sy);
  ctx.rotate(sway * 0.35);
  ctx.scale(facingScale, 1);
  const grad = createGradientFillFromStops(ctx, -s, -s * 0.7, s, s, stops || ["#F43F5E", "#BE123C", "#FBBF24"]);
  ctx.fillStyle = grad;
  // Twin hanging tails
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(-s * 0.46, s * 0.92);
  ctx.lineTo(-s * 0.14, s * 0.66);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(s * 0.46, s * 0.92);
  ctx.lineTo(s * 0.14, s * 0.66);
  ctx.closePath();
  ctx.fill();
  // Left & right loops + gold rim knot
  ctx.beginPath();
  ctx.ellipse(-s * 0.45, -s * 0.08, s * 0.48, s * 0.28, -0.35, 0, Math.PI * 2);
  ctx.ellipse(s * 0.45, -s * 0.08, s * 0.48, s * 0.28, 0.35, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = "#FDE047";
  ctx.lineWidth = Math.max(0.8, s * 0.08);
  ctx.stroke();
  ctx.fillStyle = "#FBBF24";
  ctx.beginPath();
  ctx.arc(0, -s * 0.04, Math.max(1.8, s * 0.2), 0, Math.PI * 2);
  ctx.fill();
  if (isSelected) {
    ctx.strokeStyle = "#FACC15";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(0, s * 0.12, s + 2, 0, Math.PI * 2);
    ctx.stroke();
  }
  ctx.restore();
}

function renderChristmasTreeScene(ctx, layout, projBuffer, sceneParams) {
  const { anchorX, baseY, treeH, treeR, isMobile } = layout;
  const {
    items,
    rot,
    starRotation,
    timeSec,
    isDark,
    interactive = false,
    selectedId = null,
    hoverId = null,
    hitBoxes = null
  } = sceneParams;

  const sprites = getChristmasTreeSprites(isDark);
  const t = timeSec;
  const fov = 560;
  const tiltSin = 0.11;
  const tiltCos = 0.9939;

  drawTreeBaseAndMound(ctx, anchorX, baseY, treeR, isDark);

  const foliagePalette = isDark
    ? ["#004225", "#146c43", "#2E7D32", "#81C784"]
    : ["#003820", "#004D2B", "#15683E", "#2E7D32"];

  if (projBuffer.length !== items.length) {
    projBuffer.length = items.length;
  }

  const starYOffset = Math.sin(t * 2.0) * 1.8;
  const starY = (baseY - treeH) - (isMobile ? 8 : 11) + starYOffset;
  const starOuterR = interactive ? 21 : (isMobile ? 12 : 16);

  for (let i = 0; i < items.length; i++) {
    const it = items[i];
    const u = it.kind === "sparkle" ? ((it.u + t * it.speedY) % 1.03) : it.u;
    const isTrunkSeg = it.kind === "trunk_seg";
    const swayAngle = isTrunkSeg ? 0 : (it.angle + rot + (it.kind === "sparkle" ? t * 0.2 : 0));
    const radius = it.rNorm * treeR;
    const x3 = Math.cos(swayAngle) * radius;
    const z3 = isTrunkSeg ? 0 : Math.sin(swayAngle) * radius;
    const yRel = (0.44 - u) * treeH;
    const y3Tilt = yRel * tiltCos - z3 * tiltSin;
    const z3Tilt = yRel * tiltSin + z3 * tiltCos;
    const persp = fov / (fov + z3Tilt);
    const sx = anchorX + x3 * persp;
    const sy = (baseY - treeH * 0.44) + y3Tilt * persp;

    let slot = projBuffer[i];
    if (!slot) {
      slot = {};
      projBuffer[i] = slot;
    }
    slot.item = it;
    slot.sx = sx;
    slot.sy = sy;
    slot.z = z3Tilt;
    slot.persp = persp;
    slot.angle = swayAngle;
  }

  projBuffer.sort((a, b) => b.z - a.z);
  if (hitBoxes) hitBoxes.length = 0;

  const scaleBoost = interactive ? 1.18 : 1;

  for (let i = 0; i < projBuffer.length; i++) {
    const p = projBuffer[i];
    const it = p.item;
    const persp = p.persp;
    const depthNorm = Math.max(0.34, Math.min(1, 0.72 - p.z / (treeR * 2.2)));

    ctx.globalAlpha = 1;

    if (it.kind === "trunk_seg") {
      drawTreeTrunkSegment(ctx, it, anchorX, baseY, treeH, treeR, starY, rot, isDark);
      continue;
    }

    if (it.kind === "needle") {
      const r = it.size * persp;
      const shimmer = it.tone === 3 ? (0.65 + 0.35 * Math.sin(t * 2.2 + it.phase)) : 1;
      ctx.globalAlpha = (isDark ? 0.9 : 0.88) * depthNorm * shimmer;
      ctx.fillStyle = foliagePalette[it.tone];
      ctx.beginPath();
      ctx.arc(p.sx, p.sy, r, 0, Math.PI * 2);
      ctx.fill();
    } else if (it.kind === "light" || it.kind === "community_garland_bulb") {
      const pulse = 0.42 + 0.58 * Math.pow(0.5 + 0.5 * Math.sin(t * it.speed + it.phase), 1.4);
      const glowRadius = it.size * (3.1 + pulse * 1.1) * persp * scaleBoost;
      const sprite = sprites.bulbs[it.key] || sprites.bulbs.gold;
      const isSelected = it.data && (it.data.id === selectedId || it.data.id === hoverId);
      ctx.globalAlpha = (isDark ? 0.88 : 0.76) * depthNorm * (0.55 + pulse * 0.45);
      ctx.drawImage(sprite, p.sx - glowRadius, p.sy - glowRadius, glowRadius * 2, glowRadius * 2);
      ctx.fillStyle = it.coreColor;
      ctx.beginPath();
      ctx.arc(p.sx, p.sy, Math.max(1.2, it.size * 0.56 * persp * scaleBoost), 0, Math.PI * 2);
      ctx.fill();
      if (interactive && it.data) {
        if (isSelected) {
          ctx.save();
          ctx.strokeStyle = "#FACC15";
          ctx.lineWidth = 1.6;
          ctx.beginPath();
          ctx.arc(p.sx, p.sy, Math.max(7, it.size * 2.6 * persp), 0, Math.PI * 2);
          ctx.stroke();
          ctx.restore();
        }
        if (hitBoxes) {
          hitBoxes.push({ item: it.data, x: p.sx, y: p.sy, r: Math.max(14, it.size * 3.8 * persp) });
        }
      }
    } else if (it.kind === "community_polaroid") {
      const baseW = isMobile ? 13.5 : (interactive ? 24 : 15.5);
      const pw = baseW * it.scale * persp;
      const ph = pw * 1.24;
      const sway = it.baseTilt + Math.sin(t * 1.45 + it.swayPhase) * 0.12;
      const isSelected = it.data && (it.data.id === selectedId || it.data.id === hoverId);
      ctx.save();
      ctx.globalAlpha = 0.82 + 0.18 * depthNorm;
      drawProjected3DPolaroid(ctx, p.sx, p.sy, pw, ph, sway, p.angle, it, { isDark, isSelected });
      ctx.restore();
      if (interactive && it.data && hitBoxes) {
        hitBoxes.push({ item: it.data, x: p.sx, y: p.sy, r: Math.max(18, ph * 0.64) });
      }
    } else if (it.kind === "community_card") {
      const baseW = isMobile ? 13.5 : (interactive ? 24.5 : 15.5);
      const cw = baseW * it.scale * persp;
      const ch = cw * 1.4;
      const sway = it.baseTilt + Math.sin(t * 1.38 + it.swayPhase) * 0.11;
      const isSelected = it.data && (it.data.id === selectedId || it.data.id === hoverId);
      ctx.save();
      ctx.globalAlpha = 0.84 + 0.16 * depthNorm;
      drawProjected3DGreetingCard(ctx, p.sx, p.sy, cw, ch, sway, p.angle, it, { isDark, isSelected });
      ctx.restore();
      if (interactive && it.data && hitBoxes) {
        hitBoxes.push({ item: it.data, x: p.sx, y: p.sy, r: Math.max(18, ch * 0.64) });
      }
    } else if (it.kind === "community_gift") {
      const s = it.size * persp * scaleBoost;
      const giftCenterY = p.sy - s * 0.44;
      const isSelected = it.data && (it.data.id === selectedId || it.data.id === hoverId);
      const isMystery = Boolean(it.data && it.data.isMysteryLocked);
      ctx.save();
      ctx.globalAlpha = 0.88 + 0.12 * depthNorm;
      drawProjected3DGiftBox(
        ctx,
        p.sx,
        giftCenterY,
        s,
        p.angle + (it.yawOffset || 0),
        it.palette,
        { isDark, isMystery, isSelected }
      );
      ctx.restore();
      if (interactive && it.data && hitBoxes) {
        hitBoxes.push({ item: it.data, x: p.sx, y: giftCenterY, r: Math.max(15, s * 0.95) });
      }
    } else if (it.kind === "community_star_ornament") {
      const r = it.size * persp * scaleBoost;
      const sway = Math.sin(t * 1.6 + (it.swayPhase || 0)) * 0.14;
      const isSelected = it.data && (it.data.id === selectedId || it.data.id === hoverId);
      ctx.save();
      ctx.globalAlpha = 0.88 + 0.12 * depthNorm;
      drawProjected3DStarOrnament(ctx, p.sx, p.sy, r, sway, p.angle, it.gradientStops, { isDark, isSelected });
      ctx.restore();
      if (interactive && it.data && hitBoxes) {
        hitBoxes.push({ item: it.data, x: p.sx, y: p.sy, r: Math.max(16, r * 1.8) });
      }
    } else if (it.kind === "community_ribbon_bow") {
      const s = it.size * persp * scaleBoost;
      const sway = Math.sin(t * 1.4 + (it.swayPhase || 0)) * 0.11;
      const isSelected = it.data && (it.data.id === selectedId || it.data.id === hoverId);
      ctx.save();
      ctx.globalAlpha = 0.88 + 0.12 * depthNorm;
      drawProjected3DRibbonBow(ctx, p.sx, p.sy, s, sway, p.angle, it.gradientStops, { isDark, isSelected });
      ctx.restore();
      if (interactive && it.data && hitBoxes) {
        hitBoxes.push({ item: it.data, x: p.sx, y: p.sy, r: Math.max(16, s * 1.7) });
      }
    } else if (it.kind === "community_bauble") {
      const r = it.size * persp * scaleBoost;
      const isSelected = it.data && (it.data.id === selectedId || it.data.id === hoverId);
      const specOffsetX = Math.cos(p.angle) * r * 0.22 - r * 0.26;
      ctx.save();
      ctx.globalAlpha = 0.84 + 0.16 * depthNorm;
      ctx.fillStyle = "#F59E0B";
      ctx.fillRect(p.sx - r * 0.28, p.sy - r * 1.18, r * 0.56, r * 0.28);
      if (Array.isArray(it.gradientStops) && it.gradientStops.length >= 2) {
        ctx.fillStyle = createGradientFillFromStops(ctx, p.sx - r, p.sy - r, p.sx + r, p.sy + r, it.gradientStops);
        ctx.beginPath();
        ctx.arc(p.sx, p.sy, r, 0, Math.PI * 2);
        ctx.fill();
        const specGrad = ctx.createRadialGradient(p.sx + specOffsetX, p.sy - r * 0.34, 0.4, p.sx + specOffsetX, p.sy - r * 0.34, r * 0.72);
        specGrad.addColorStop(0, "rgba(255, 255, 255, 0.85)");
        specGrad.addColorStop(1, "rgba(255, 255, 255, 0)");
        ctx.fillStyle = specGrad;
        ctx.beginPath();
        ctx.arc(p.sx, p.sy, r, 0, Math.PI * 2);
        ctx.fill();
      } else {
        const baubleGrad = ctx.createRadialGradient(p.sx + specOffsetX, p.sy - r * 0.34, Math.max(0.5, r * 0.12), p.sx, p.sy, r);
        baubleGrad.addColorStop(0, "#ffffff");
        baubleGrad.addColorStop(0.28, it.color);
        baubleGrad.addColorStop(1, hexShadeRgb(it.color, 0.58 + 0.22 * depthNorm));
        ctx.fillStyle = baubleGrad;
        ctx.beginPath();
        ctx.arc(p.sx, p.sy, r, 0, Math.PI * 2);
        ctx.fill();
      }
      if (isSelected) {
        ctx.strokeStyle = "#FACC15";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(p.sx, p.sy, r + 3, 0, Math.PI * 2);
        ctx.stroke();
      }
      ctx.restore();
      if (interactive && it.data && hitBoxes) {
        hitBoxes.push({ item: it.data, x: p.sx, y: p.sy, r: Math.max(15, r * 1.8) });
      }
    } else if (it.kind === "sparkle") {
      const tw = 0.3 + 0.7 * Math.abs(Math.sin(t * 2.4 + it.phase));
      ctx.globalAlpha = tw * (isDark ? 0.78 : 0.62);
      ctx.fillStyle = it.isGold ? "#FFD700" : (isDark ? "#ECEFF1" : "#94A3B8");
      const r = it.size * persp * tw;
      ctx.beginPath();
      ctx.moveTo(p.sx, p.sy - r * 1.5);
      ctx.lineTo(p.sx + r * 0.5, p.sy);
      ctx.lineTo(p.sx, p.sy + r * 1.5);
      ctx.lineTo(p.sx - r * 0.5, p.sy);
      ctx.closePath();
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1;
  drawFacetedTopStar(ctx, anchorX, starY, starOuterR, starRotation, isDark, sprites);
}

function resizeChristmasTreeCanvas() {
  const canvas = christmasTreeState.canvas;
  if (!canvas) return;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const w = window.innerWidth;
  const h = window.innerHeight;
  const wasMobile = christmasTreeState.width > 0 && christmasTreeState.width <= 760;
  const isMobile = w <= 760;
  christmasTreeState.width = w;
  christmasTreeState.height = h;
  canvas.width = Math.max(1, Math.floor(w * dpr));
  canvas.height = Math.max(1, Math.floor(h * dpr));
  const ctx = canvas.getContext("2d");
  if (ctx) {
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    christmasTreeState.ctx = ctx;
  }
  if (!christmasTreeState.baseItems.length || wasMobile !== isMobile) {
    buildChristmasTreeGeometry(isMobile);
  }
}

function renderChristmasTreeFrame(nowMs) {
  if (!isChristmas2026Season() || !christmasSnowState.enabled || christmasSnowState.reducedMotion || document.hidden) {
    christmasTreeState.rafId = null;
    christmasTreeState.lastMs = 0;
    if (christmasTreeState.ctx && christmasTreeState.width && christmasTreeState.height) {
      christmasTreeState.ctx.clearRect(0, 0, christmasTreeState.width, christmasTreeState.height);
    }
    return;
  }

  const ctx = christmasTreeState.ctx;
  const w = christmasTreeState.width;
  const h = christmasTreeState.height;
  if (!ctx || !w || !h) {
    christmasTreeState.rafId = requestAnimationFrame(renderChristmasTreeFrame);
    return;
  }

  const dt = christmasTreeState.lastMs ? Math.min(0.05, Math.max(0.004, (nowMs - christmasTreeState.lastMs) / 1000)) : 0.016;
  christmasTreeState.lastMs = nowMs;
  christmasTreeState.timeSec += dt;
  christmasTreeState.rotation = (christmasTreeState.rotation + dt * 0.38) % (Math.PI * 2);
  christmasTreeState.starRotation = (christmasTreeState.starRotation + dt * 0.85) % (Math.PI * 2);

  ctx.clearRect(0, 0, w, h);
  const layout = getChristmasTreeLayout(w, h);
  renderChristmasTreeScene(ctx, layout, christmasTreeState.projected, {
    items: christmasTreeState.items,
    rot: christmasTreeState.rotation,
    starRotation: christmasTreeState.starRotation,
    timeSec: christmasTreeState.timeSec,
    isDark: christmasTreeState.isDark,
    interactive: false
  });

  christmasTreeState.rafId = requestAnimationFrame(renderChristmasTreeFrame);
}

function getTrackedCardSnowRegistry() {
  if (!christmasSnowState.cardCaps) christmasSnowState.cardCaps = new Map();
  if (!christmasSnowState.cascades) christmasSnowState.cascades = [];
  return christmasSnowState.cardCaps;
}

function buildCardSnowProfile(width, colW, seedOffset) {
  const count = Math.max(16, Math.ceil(width / colW) + 1);
  const cols = new Float32Array(count);
  const target = new Float32Array(count);
  for (let i = 0; i < count; i++) {
    const frac = i / Math.max(1, count - 1);
    const leftEdge = Math.sin(Math.min(1, frac * 9.5) * Math.PI * 0.5);
    const rightEdge = Math.sin(Math.min(1, (1 - frac) * 9.5) * Math.PI * 0.5);
    const edgeTaper = Math.pow(leftEdge * rightEdge, 0.78);
    // Scalloped pillowy snowdrifts piled ABOVE the card's upper rim
    const billow = Math.abs(Math.sin(frac * Math.PI * 7.2 + seedOffset)) * 4.2;
    const ripple = Math.sin(frac * 25.0 + seedOffset * 1.9) * 1.2 + Math.cos(frac * 9.2 + seedOffset * 0.8) * 1.65;
    const rawH = Math.max(4.0, Math.min(15.5, 6.8 + billow + ripple));
    const h = i === 0 || i === count - 1 ? 0 : rawH * edgeTaper;
    cols[i] = h;
    target[i] = h;
  }
  return { cols, target };
}

function cardCornerDropY(cardX, cardWidth, effR) {
  if (!effR || effR <= 1) return 0;
  let dx = 0;
  if (cardX < effR) dx = effR - cardX;
  else if (cardX > cardWidth - effR) dx = cardX - (cardWidth - effR);
  else return 0;
  return effR - Math.sqrt(Math.max(0, effR * effR - dx * dx));
}

const CARD_EDGE_SNOW_SELECTOR = [
  "#homeContributionCard",
  "#bannerStackCard",
  "#weeklyCompetitionModule",
  "#forum .mini-card",
  "#timerMainCard",
  "#studySpacesMainCard",
  "#studyTimerPage .study-quote-card",
  "#compGatewayHero",
  "#arenaLockedNotice",
  "#arenaPausedNotice",
  "#arenaStudentIdRequiredNotice"
].join(", ");

const CARD_EDGE_CANVAS_H = 26;
const CARD_EDGE_BASE_Y = 20;

function removeCardEdgeSnowDom(el) {
  if (!el) return;
  el.classList.remove("xmas-snow-card", "is-snow-hover");
  el.querySelectorAll(":scope > canvas.xmas-card-edge-snow, :scope > canvas.xmas-card-snow-canvas").forEach((c) => c.remove());
}

function syncCardSnowCaps() {
  const registry = getTrackedCardSnowRegistry();
  const active = isChristmas2026Season() && christmasSnowState.enabled && !christmasSnowState.reducedMotion;
  if (!active) {
    registry.forEach((entry) => {
      if (entry.el) removeCardEdgeSnowDom(entry.el);
    });
    registry.clear();
    return;
  }

  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const matchedSet = new Set();
  const cardEls = Array.from(document.querySelectorAll(CARD_EDGE_SNOW_SELECTOR));

  cardEls.forEach((el, idx) => {
    if (!el || !el.isConnected) return;
    // On mobile showcase carousel, #weeklyCompetitionModule lives inside #bannerTrack (which clips overflow); #bannerStackCard owns the top cap.
    if (el.id === "weeklyCompetitionModule" && el.closest && el.closest("#bannerTrack")) {
      return;
    }
    matchedSet.add(el);
    // Clean legacy canvas if present
    const legacyCanvas = el.querySelector(":scope > canvas.xmas-card-snow-canvas");
    if (legacyCanvas) legacyCanvas.remove();

    el.classList.add("xmas-snow-card");
    const rectW = Math.round(el.offsetWidth || el.getBoundingClientRect().width || el.clientWidth || 0);
    const parsedRadius = parseFloat(window.getComputedStyle(el).borderTopLeftRadius || "14") || 14;
    const cornerR = Math.max(0, Math.min(parsedRadius, Math.max(0, rectW * 0.22)));
    const insetX = Math.max(4, Math.round(cornerR * 0.36));
    const usableW = Math.max(0, rectW - insetX * 2);

    let canvas = el.querySelector(":scope > canvas.xmas-card-edge-snow");
    if (!canvas) {
      canvas = document.createElement("canvas");
      canvas.className = "xmas-card-edge-snow";
      canvas.setAttribute("aria-hidden", "true");
      el.appendChild(canvas);
    }

    const canvasW = Math.max(0, rectW + 2);
    const backingW = Math.round(canvasW * dpr);
    const backingH = Math.round(CARD_EDGE_CANVAS_H * dpr);
    let sizedNow = false;
    if (canvasW > 20 && (canvas.width !== backingW || canvas.height !== backingH)) {
      canvas.width = backingW;
      canvas.height = backingH;
      sizedNow = true;
    }

    let entry = registry.get(el);
    if (!entry) {
      const colW = 3;
      const initW = Math.max(120, usableW || 320);
      const prof = buildCardSnowProfile(initW, colW, idx * 1.93 + 0.7);
      entry = {
        el,
        canvas,
        ctx: canvas.getContext("2d"),
        dpr,
        width: usableW > 20 ? usableW : 0,
        cardWidth: rectW,
        cornerR,
        insetX,
        colW,
        cols: prof.cols,
        target: prof.target,
        dirty: true,
        glints: Array.from({ length: 14 }, (_, gi) => ({
          frac: 0.06 + (gi / 13) * 0.88,
          phase: gi * 1.27 + idx
        }))
      };
      registry.set(el, entry);
    } else {
      if (entry.canvas !== canvas) {
        entry.canvas = canvas;
        entry.ctx = canvas.getContext("2d");
        entry.dirty = true;
      }
      entry.dpr = dpr;
      entry.cornerR = cornerR;
      entry.insetX = insetX;
      entry.cardWidth = rectW;
      if (sizedNow) entry.dirty = true;
    }

    if (usableW > 20 && Math.abs(usableW - entry.width) > 4) {
      const oldCols = entry.cols;
      const oldTarget = entry.target;
      const oldLen = oldCols ? oldCols.length : 0;
      const prof = buildCardSnowProfile(usableW, entry.colW, idx * 1.93 + 0.7);
      if (oldLen > 0 && oldTarget) {
        for (let i = 0; i < prof.cols.length; i++) {
          const mapped = Math.min(oldLen - 1, Math.round((i / Math.max(1, prof.cols.length - 1)) * (oldLen - 1)));
          const baseT = oldTarget[mapped];
          const ratio = baseT > 0.2 ? Math.min(1, oldCols[mapped] / baseT) : 1;
          prof.cols[i] = prof.target[i] * ratio;
        }
      }
      entry.cols = prof.cols;
      entry.target = prof.target;
      entry.width = usableW;
      entry.dirty = true;
    }

    if (entry.dirty && rectW > 20 && el.offsetParent !== null) {
      renderCardEdgeCanvas(entry, christmasSnowState.isDark, christmasSnowState.windAngle * 3.2);
    }
  });

  // Prune detached or moved-into-carousel elements
  registry.forEach((entry, el) => {
    if (!el || !el.isConnected || !matchedSet.has(el)) {
      removeCardEdgeSnowDom(el);
      registry.delete(el);
    }
  });
}

function brushCardSnowSegment(entry, rect, localX0, localX1, velX) {
  const { cols, target, width, insetX, cornerR } = entry;
  if (!cols || !cols.length || width < 20) return 0;
  const colStep = width / Math.max(1, cols.length - 1);
  const minX = Math.min(localX0, localX1);
  const maxX = Math.max(localX0, localX1);
  const brushR = 22;
  const startCol = Math.max(0, Math.floor((minX - brushR) / colStep));
  const endCol = Math.min(cols.length - 1, Math.ceil((maxX + brushR) / colStep));
  let removedSum = 0;

  for (let i = startCol; i <= endCol; i++) {
    const cx = i * colStep;
    const dist = cx < minX ? minX - cx : (cx > maxX ? cx - maxX : 0);
    const falloff = Math.max(0, Math.cos((dist / brushR) * Math.PI * 0.5));
    if (falloff <= 0.04) continue;
    const prevH = cols[i];
    if (prevH <= 0.45) continue;
    const clearFloor = Math.max(0.2, target[i] * (1 - falloff) * 0.3);
    const nextH = Math.max(0.2, Math.min(prevH, prevH * (1 - 0.88 * falloff)));
    const newH = Math.max(clearFloor, nextH);
    const diff = prevH - newH;
    if (diff > 0.12) {
      cols[i] = newH;
      entry.dirty = true;
      removedSum += diff;
      if (removedSum > 0.55 && (i % 3 === 0) && christmasSnowState.cascades.length < 150) {
        const dropY = cardCornerDropY(insetX + cx, rect.width, cornerR);
        christmasSnowState.cascades.push({
          x: rect.left + insetX + cx + (Math.random() - 0.5) * 8,
          y: rect.top + dropY - prevH * 0.4 + Math.random() * 4,
          vx: Math.max(-4.2, Math.min(4.2, velX * 0.18 + (Math.random() - 0.5) * 2.1)),
          vy: 0.7 + Math.random() * 1.8,
          r: 1.5 + Math.random() * 2.3,
          alpha: 0.82 + Math.random() * 0.18,
          life: 1.0
        });
      }
    }
  }
  return removedSum;
}

function renderCardEdgeCanvas(entry, isDark, tPhase) {
  const { cols, width, insetX, cornerR, glints, canvas, ctx, dpr, cardWidth } = entry;
  if (!canvas || !ctx || !cols || cols.length < 3 || width < 20 || cardWidth < 20) return;

  const logicalW = canvas.width / Math.max(1, dpr || 1);
  ctx.setTransform(dpr || 1, 0, 0, dpr || 1, 0, 0);
  ctx.clearRect(0, 0, logicalW, CARD_EDGE_CANVAS_H);

  let maxCol = 0;
  for (let i = 0; i < cols.length; i++) {
    if (cols[i] > maxCol) maxCol = cols[i];
  }
  if (maxCol < 0.35) {
    entry.dirty = false;
    return;
  }

  const spanW = Math.max(20, cardWidth - insetX * 2);
  const lastIdx = cols.length - 1;
  const ptsX = new Float32Array(cols.length);
  const ptsBaseY = new Float32Array(cols.length);
  const ptsTopY = new Float32Array(cols.length);
  let minTopY = CARD_EDGE_BASE_Y;
  let maxBaseY = CARD_EDGE_BASE_Y;

  for (let i = 0; i < cols.length; i++) {
    const localX = (i / lastIdx) * spanW;
    const vx = 1 + insetX + localX;
    const drop = cardCornerDropY(insetX + localX, cardWidth, cornerR);
    const by = CARD_EDGE_BASE_Y + drop + 1.5;
    const ty = Math.max(1.5, by - cols[i]);
    ptsX[i] = vx;
    ptsBaseY[i] = by;
    ptsTopY[i] = ty;
    if (ty < minTopY) minTopY = ty;
    if (by > maxBaseY) maxBaseY = by;
  }

  ctx.save();
  ctx.beginPath();
  ctx.moveTo(ptsX[0], ptsBaseY[0]);
  for (let i = 0; i < lastIdx; i++) {
    const midX = (ptsX[i] + ptsX[i + 1]) * 0.5;
    const midY = (ptsTopY[i] + ptsTopY[i + 1]) * 0.5;
    ctx.quadraticCurveTo(ptsX[i], ptsTopY[i], midX, midY);
  }
  ctx.lineTo(ptsX[lastIdx], ptsTopY[lastIdx]);
  ctx.lineTo(ptsX[lastIdx], ptsBaseY[lastIdx]);
  for (let i = lastIdx; i >= 1; i--) {
    const midX = (ptsX[i] + ptsX[i - 1]) * 0.5;
    const midY = (ptsBaseY[i] + ptsBaseY[i - 1]) * 0.5;
    ctx.quadraticCurveTo(ptsX[i], ptsBaseY[i], midX, midY);
  }
  ctx.closePath();

  const bodyGrad = ctx.createLinearGradient(0, minTopY - 1, 0, maxBaseY + 1);
  if (isDark) {
    bodyGrad.addColorStop(0, "rgba(255, 255, 255, 0.98)");
    bodyGrad.addColorStop(0.55, "rgba(224, 242, 254, 0.94)");
    bodyGrad.addColorStop(1, "rgba(147, 197, 253, 0.86)");
  } else {
    bodyGrad.addColorStop(0, "rgba(255, 255, 255, 0.99)");
    bodyGrad.addColorStop(0.56, "rgba(232, 244, 255, 0.96)");
    bodyGrad.addColorStop(1, "rgba(186, 224, 252, 0.92)");
  }
  ctx.fillStyle = bodyGrad;
  ctx.shadowColor = isDark ? "rgba(2, 12, 24, 0.5)" : "rgba(15, 23, 42, 0.17)";
  ctx.shadowBlur = 4;
  ctx.shadowOffsetY = 1.5;
  ctx.fill();

  ctx.shadowColor = "transparent";
  ctx.shadowBlur = 0;
  ctx.beginPath();
  ctx.moveTo(ptsX[0], ptsTopY[0]);
  for (let i = 1; i < lastIdx; i++) {
    const midX = (ptsX[i] + ptsX[i + 1]) * 0.5;
    const midY = (ptsTopY[i] + ptsTopY[i + 1]) * 0.5;
    ctx.quadraticCurveTo(ptsX[i], ptsTopY[i], midX, midY);
  }
  ctx.lineTo(ptsX[lastIdx], ptsTopY[lastIdx]);
  ctx.strokeStyle = isDark ? "rgba(224, 242, 254, 0.55)" : "rgba(148, 163, 184, 0.45)";
  ctx.lineWidth = 0.9;
  ctx.stroke();

  for (let i = 0; i < glints.length; i++) {
    const g = glints[i];
    const ci = Math.min(lastIdx, Math.floor(g.frac * lastIdx));
    const ch = cols[ci];
    if (ch < 4) continue;
    const shimmer = 0.25 + 0.75 * Math.pow(0.5 + 0.5 * Math.sin(tPhase + g.phase), 2);
    ctx.globalAlpha = shimmer * 0.85;
    ctx.fillStyle = "#ffffff";
    ctx.beginPath();
    ctx.arc(ptsX[ci], Math.max(2, ptsBaseY[ci] - ch * 0.56), 1.15, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
  entry.dirty = false;
}

function handleCardSnowPointer(ev, isDownClick) {
  if (!isChristmas2026Season() || !christmasSnowState.enabled || christmasSnowState.reducedMotion) return;
  if (document.body.classList.contains("arena-quiz-active")) return;
  if (!ev || typeof ev.clientX !== "number" || typeof ev.clientY !== "number") return;
  const target = ev.target;
  if (target && target.closest && target.closest("dialog[open], .floating-menu, .quick-menu-popover, .site-header")) return;

  const registry = getTrackedCardSnowRegistry();
  const prev = christmasSnowState.pointerPrev;
  const cx = ev.clientX;
  const cy = ev.clientY;
  const dx = prev ? (cx - prev.x) : 0;
  let hoveredCard = null;
  let sweptAny = false;

  registry.forEach((entry, el) => {
    if (!el.isConnected || el.offsetParent === null) return;
    const rect = el.getBoundingClientRect();
    if (rect.width < 20 || rect.height < 20) return;
    if (rect.bottom < 0 || rect.top > window.innerHeight) return;

    if (cx >= rect.left - 8 && cx <= rect.right + 8 && cy >= rect.top - 24 && cy <= rect.top + 14) {
      hoveredCard = el;
      const offsetL = rect.left + (entry.insetX || 0);
      const localX1 = cx - offsetL;
      const sameCardPrev = prev && prev.card === el;
      const localX0 = sameCardPrev ? (prev.x - offsetL) : localX1;
      if (isDownClick || (prev && (Math.hypot(dx, cy - prev.y) > 1.5))) {
        const brushed = brushCardSnowSegment(entry, rect, localX0, localX1, dx);
        if (brushed > 0.2) {
          sweptAny = true;
          renderCardEdgeCanvas(entry, christmasSnowState.isDark, christmasSnowState.windAngle * 3.2);
          if (Math.abs(dx) > 4 && (el.id === "weeklyCompetitionModule" || el.id === "bannerStackCard")) {
            window.__xmasSnowSwipeLockUntil = Date.now() + 260;
          }
        }
      }
    }
  });

  if (christmasSnowState.activeSnowHoverCard && christmasSnowState.activeSnowHoverCard !== hoveredCard) {
    christmasSnowState.activeSnowHoverCard.classList.remove("is-snow-hover");
  }
  if (hoveredCard) {
    hoveredCard.classList.add("is-snow-hover");
  }
  christmasSnowState.activeSnowHoverCard = hoveredCard;
  christmasSnowState.pointerPrev = { x: cx, y: cy, card: hoveredCard, swept: sweptAny };
}

function renderChristmasSnowFrame() {
  if (!isChristmas2026Season() || !christmasSnowState.enabled || christmasSnowState.reducedMotion || document.hidden) {
    christmasSnowState.rafId = null;
    if (christmasSnowState.ctx && christmasSnowState.width && christmasSnowState.height) {
      christmasSnowState.ctx.clearRect(0, 0, christmasSnowState.width, christmasSnowState.height);
    }
    return;
  }
  const ctx = christmasSnowState.ctx;
  const w = christmasSnowState.width;
  const h = christmasSnowState.height;
  if (!ctx || !w || !h) {
    christmasSnowState.rafId = requestAnimationFrame(renderChristmasSnowFrame);
    return;
  }

  ctx.clearRect(0, 0, w, h);
  const isDark = christmasSnowState.isDark;
  const isQuietMode = document.documentElement.classList.contains("study-mode-active") || document.body.classList.contains("arena-quiz-active");
  const pile = christmasSnowState.snowPile;
  const colW = christmasSnowState.pileColWidth || 3;
  const maxHeight = getSnowPileMaxHeight(w);

  christmasSnowState.windAngle += 0.008;
  const globalBreeze = Math.sin(christmasSnowState.windAngle) * 0.28 + 0.14;

  for (let i = 0; i < christmasSnowState.flakes.length; i++) {
    const f = christmasSnowState.flakes[i];
    f.phase += f.swayFreq;
    f.rot += f.rotSpeed;
    f.x += Math.sin(f.phase) * f.swayAmp + globalBreeze * (f.layer === 0 ? 0.5 : 1);
    f.y += f.speedY;

    if (f.x < -16) f.x = w + 16;
    if (f.x > w + 16) f.x = -16;

    const colIdx = Math.max(0, Math.min(pile.length - 1, Math.round(f.x / colW)));
    const groundY = (!isQuietMode && pile.length) ? (h - pile[colIdx]) : (h + 10);

    if (f.y + f.r * 0.45 >= groundY) {
      if (!isQuietMode && pile.length) {
        // Real granular deposition shaped softly by flake size & gentle downwind drift
        const deposit = (f.layer === 2 ? 0.52 : (f.layer === 1 ? 0.34 : 0.16)) * (0.65 + f.r * 0.08);
        const windBias = Math.round(globalBreeze * 1.4);
        for (let k = -4; k <= 4; k++) {
          const idx = colIdx + k + windBias;
          if (idx >= 0 && idx < pile.length) {
            const bell = Math.exp(-(k * k) / 4.2);
            pile[idx] = Math.min(maxHeight, pile[idx] + deposit * bell * 0.44);
          }
        }
        if (christmasSnowState.sparkles.length < 44 && f.layer > 0) {
          christmasSnowState.sparkles.push({
            x: f.x,
            y: groundY - 1,
            vx: (Math.random() - 0.5) * 1.25 + globalBreeze * 0.4,
            vy: -Math.random() * 1.15 - 0.3,
            r: Math.random() * 1.4 + 0.85,
            life: 1
          });
        }
      }
      christmasSnowState.flakes[i] = createSnowFlake(w, h, true);
      continue;
    }

    const alpha = f.alpha * (isDark ? 0.94 : 0.88);
    ctx.globalAlpha = alpha;
    if (f.layer === 2) {
      ctx.strokeStyle = isDark ? "#bae6fd" : "#3485bf";
      ctx.lineWidth = isDark ? 1.25 : 1.35;
      ctx.lineCap = "round";
      drawDendriticSnowflake(ctx, f.x, f.y, f.r, f.rot);
      ctx.strokeStyle = "#ffffff";
      ctx.lineWidth = 0.78;
      drawDendriticSnowflake(ctx, f.x, f.y, f.r * 0.76, f.rot);
    } else if (f.layer === 1) {
      const puff = ctx.createRadialGradient(f.x, f.y, 0, f.x, f.y, f.r * 1.45);
      if (isDark) {
        puff.addColorStop(0, "rgba(255, 255, 255, 0.98)");
        puff.addColorStop(0.55, "rgba(224, 242, 254, 0.78)");
        puff.addColorStop(1, "rgba(186, 230, 253, 0)");
      } else {
        puff.addColorStop(0, "rgba(255, 255, 255, 0.98)");
        puff.addColorStop(0.52, "rgba(186, 226, 252, 0.72)");
        puff.addColorStop(1, "rgba(125, 195, 240, 0)");
      }
      ctx.fillStyle = puff;
      ctx.beginPath();
      ctx.arc(f.x, f.y, f.r * 1.45, 0, Math.PI * 2);
      ctx.fill();
    } else {
      ctx.fillStyle = isDark ? "#e0f2fe" : "#7dc1ea";
      ctx.beginPath();
      ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  for (let i = christmasSnowState.sparkles.length - 1; i >= 0; i--) {
    const s = christmasSnowState.sparkles[i];
    s.x += s.vx;
    s.y += s.vy;
    s.vy += 0.04;
    s.life -= 0.045;
    if (s.life <= 0) {
      christmasSnowState.sparkles.splice(i, 1);
      continue;
    }
    ctx.globalAlpha = s.life * 0.85;
    ctx.fillStyle = isDark ? "#ffffff" : "#7dd3fc";
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
    ctx.fill();
  }

  // Cascade snow chunks swept off card edges falling downward to replenish bottom drifts
  const cascades = christmasSnowState.cascades || [];
  for (let i = cascades.length - 1; i >= 0; i--) {
    const cp = cascades[i];
    cp.vx *= 0.986;
    cp.vy += 0.145;
    cp.x += cp.vx + globalBreeze * 0.16;
    cp.y += cp.vy;
    const cIdx = (!isQuietMode && pile.length) ? Math.max(0, Math.min(pile.length - 1, Math.round(cp.x / colW))) : 0;
    const floorY = (!isQuietMode && pile.length) ? (h - pile[cIdx]) : (h + 24);
    if (cp.y >= floorY || cp.y > h + 16) {
      if (!isQuietMode && pile.length && cp.y >= floorY) {
        pile[cIdx] = Math.min(maxHeight, pile[cIdx] + 0.35);
      }
      cascades.splice(i, 1);
      continue;
    }
    ctx.globalAlpha = cp.alpha * (isDark ? 0.94 : 0.88);
    ctx.fillStyle = isDark ? "#f8fafc" : "#ffffff";
    ctx.beginPath();
    ctx.arc(cp.x, cp.y, cp.r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  if (!isQuietMode && pile.length) {
    relaxSnowPile(pile, maxHeight);
    drawBottomSnowPile(ctx, w, h, pile, isDark);
  }

  // Sync, regrow & paint DOM-anchored per-card edge snow (zero scroll bounce!)
  christmasSnowState._cardSyncTick = ((christmasSnowState._cardSyncTick || 0) + 1) % 24;
  if (christmasSnowState._cardSyncTick === 1) {
    syncCardSnowCaps();
  }
  const cardRegistry = getTrackedCardSnowRegistry();
  const cardRegrowRate = 0.014;
  const isArenaQuiz = document.body.classList.contains("arena-quiz-active");
  const shimmerTick = (christmasSnowState._cardSyncTick % 4) === 0;

  if (!isArenaQuiz) {
    cardRegistry.forEach((entry) => {
      if (!entry.el || !entry.el.isConnected || entry.el.offsetParent === null) return;
      const cols = entry.cols;
      const target = entry.target;
      let changed = Boolean(entry.dirty);
      if (cols && target) {
        for (let i = 0; i < cols.length; i++) {
          if (cols[i] < target[i] - 0.02) {
            cols[i] = Math.min(target[i], cols[i] + cardRegrowRate);
            changed = true;
          }
        }
        for (let i = 1; i < cols.length - 1; i++) {
          const avg = (cols[i - 1] + cols[i] * 2 + cols[i + 1]) * 0.25;
          if (Math.abs(avg - cols[i]) > 0.08 && cols[i] < target[i]) {
            cols[i] = Math.min(target[i], cols[i] + (avg - cols[i]) * 0.08);
            changed = true;
          }
        }
      }
      if (changed || shimmerTick) {
        renderCardEdgeCanvas(entry, isDark, christmasSnowState.windAngle * 3.2);
      }
    });
  }

  christmasSnowState.rafId = requestAnimationFrame(renderChristmasSnowFrame);
}

function startOrStopChristmasSnowLoop() {
  syncChristmasSeasonalControlsVisibility();
  updateChristmasEffectsToggleUI();
  renderChristmasHeaderGarland();
  syncCardSnowCaps();
  const shouldRun = isChristmas2026Season() && christmasSnowState.enabled && !christmasSnowState.reducedMotion && !document.hidden;
  if (shouldRun && !christmasSnowState.rafId) {
    christmasSnowState.rafId = requestAnimationFrame(renderChristmasSnowFrame);
  } else if (!shouldRun && christmasSnowState.rafId) {
    cancelAnimationFrame(christmasSnowState.rafId);
    christmasSnowState.rafId = null;
    if (christmasSnowState.ctx && christmasSnowState.width && christmasSnowState.height) {
      christmasSnowState.ctx.clearRect(0, 0, christmasSnowState.width, christmasSnowState.height);
    }
  }
  if (shouldRun && !christmasTreeState.rafId && christmasTreeState.canvas) {
    christmasTreeState.lastMs = 0;
    christmasTreeState.rafId = requestAnimationFrame(renderChristmasTreeFrame);
  } else if (!shouldRun && christmasTreeState.rafId) {
    cancelAnimationFrame(christmasTreeState.rafId);
    christmasTreeState.rafId = null;
    christmasTreeState.lastMs = 0;
    if (christmasTreeState.ctx && christmasTreeState.width && christmasTreeState.height) {
      christmasTreeState.ctx.clearRect(0, 0, christmasTreeState.width, christmasTreeState.height);
    }
  }
}

function updateChristmasEffectsToggleUI() {
  const isActive = Boolean(isChristmas2026Season() && christmasSnowState.enabled && !christmasSnowState.reducedMotion);
  const labelEl = $("#quickMenuXmasSnowLabel");
  const switchEl = $("#quickMenuXmasSnowToggle");
  const widgetBtn = $("#christmasSnowToggleBtn");

  if (labelEl) {
    labelEl.textContent = "Không khí Giáng sinh";
    labelEl.title = christmasSnowState.reducedMotion
      ? "Không khí Giáng sinh (Thiết bị đang bật Giảm chuyển động)"
      : "Không khí Giáng sinh";
  }
  if (switchEl) {
    switchEl.classList.toggle("active", isActive);
    switchEl.setAttribute("aria-checked", String(isActive));
  }
  if (widgetBtn) {
    widgetBtn.classList.toggle("active", isActive);
    widgetBtn.setAttribute("aria-pressed", String(isActive));
    widgetBtn.title = "Không khí Giáng sinh";
  }
}

window.toggleChristmasEffects = function (e) {
  if (e) {
    e.preventDefault();
    e.stopPropagation();
  }
  if (!isChristmas2026Season()) return;
  if (christmasSnowState.reducedMotion) {
    toast("Thiết bị đang bật chế độ Giảm chuyển động (Reduced Motion).");
    return;
  }
  christmasSnowState.enabled = !christmasSnowState.enabled;
  try {
    localStorage.setItem(XMAS_EFFECTS_STORAGE_KEY, christmasSnowState.enabled ? "on" : "off");
  } catch (err) { }
  startOrStopChristmasSnowLoop();
  toast(christmasSnowState.enabled ? "Đã bật Không khí Giáng sinh" : "Đã tạm dừng Không khí Giáng sinh");
};

function ensureChristmasAudioElement() {
  if (christmasBgmState.audio) return christmasBgmState.audio;
  const audio = new Audio(CHRISTMAS_BGM_URL);
  audio.loop = true;
  audio.preload = "none";
  audio.volume = 0.24;
  audio.addEventListener("play", updateChristmasMusicUI);
  audio.addEventListener("pause", updateChristmasMusicUI);
  audio.addEventListener("error", () => {
    console.warn("Không thể tải tệp nhạc nền Giáng sinh.");
    updateChristmasMusicUI();
  });
  christmasBgmState.audio = audio;
  return audio;
}

function updateChristmasMusicUI() {
  const audio = christmasBgmState.audio;
  const isPlaying = Boolean(audio && !audio.paused && isChristmas2026Season());
  const btn = $("#christmasMusicToggleBtn");
  const statusEl = $("#christmasMusicStatusText");
  const rowLabel = $("#quickMenuXmasMusicLabel");
  const rowSwitch = $("#quickMenuXmasMusicToggle");

  if (btn) {
    btn.classList.toggle("is-playing", isPlaying);
    btn.setAttribute("aria-pressed", String(isPlaying));
    btn.title = (christmasBgmState.pausedByStudy && christmasBgmState.userWantsPlay)
      ? "Nhạc nền Giáng sinh (đang tạm nhường âm thanh Study)"
      : "Nhạc nền Giáng sinh (Ikson - Christmas)";
  }
  if (statusEl) {
    statusEl.textContent = "Nhạc nền Giáng sinh";
  }
  if (rowLabel) {
    rowLabel.textContent = "Nhạc nền Giáng sinh";
  }
  if (rowSwitch) {
    rowSwitch.classList.toggle("active", isPlaying);
    rowSwitch.setAttribute("aria-checked", String(isPlaying));
  }
}

function syncChristmasBgmWithStudyAudio(studyAudioActive) {
  if (!christmasBgmState.initialized) return;
  const audio = christmasBgmState.audio;
  if (studyAudioActive) {
    if (audio && !audio.paused) {
      audio.pause();
      christmasBgmState.pausedByStudy = true;
      toast("🎧 Đã tạm dừng nhạc Giáng sinh để ưu tiên âm thanh Phòng tự học.");
    } else if (christmasBgmState.userWantsPlay) {
      christmasBgmState.pausedByStudy = true;
    }
    updateChristmasMusicUI();
  } else if (christmasBgmState.pausedByStudy) {
    christmasBgmState.pausedByStudy = false;
    if (christmasBgmState.userWantsPlay && isChristmas2026Season()) {
      const targetAudio = ensureChristmasAudioElement();
      const p = targetAudio.play();
      if (p && typeof p.catch === "function") {
        p.catch(() => updateChristmasMusicUI());
      }
    } else {
      updateChristmasMusicUI();
    }
  }
}
window.syncChristmasBgmWithStudyAudio = syncChristmasBgmWithStudyAudio;

function isStudyAudioCurrentlyPlaying() {
  if (typeof studyState === "undefined" || !studyState) return false;
  return Boolean(
    studyState.activeEnvTrack !== null ||
    studyState.activeMusicTrack !== null ||
    studyState.activeCustomEnvId !== null ||
    studyState.activeCustomMusicId !== null ||
    Object.values(studyState.activeMixSounds || {}).some(Boolean) ||
    Object.values(studyState.activeCustomMixSounds || {}).some(Boolean)
  );
}

window.toggleChristmasMusic = async function (e) {
  if (e) {
    e.preventDefault();
    e.stopPropagation();
  }
  if (!isChristmas2026Season()) return;
  const audio = ensureChristmasAudioElement();

  if (!audio.paused) {
    audio.pause();
    christmasBgmState.userWantsPlay = false;
    christmasBgmState.pausedByStudy = false;
    try { localStorage.setItem(XMAS_MUSIC_STORAGE_KEY, "off"); } catch (err) { }
    updateChristmasMusicUI();
    toast("🔇 Đã tắt nhạc nền Giáng sinh.");
    return;
  }

  // User clicked while Study Room audio is active: stop Study audio cleanly so streams never clash
  if (isStudyAudioCurrentlyPlaying() && typeof stopAllStudyAudio === "function") {
    stopAllStudyAudio();
  }

  christmasBgmState.userWantsPlay = true;
  christmasBgmState.pausedByStudy = false;
  try { localStorage.setItem(XMAS_MUSIC_STORAGE_KEY, "on"); } catch (err) { }

  try {
    await audio.play();
    updateChristmasMusicUI();
    toast("🎄 Đang phát nhạc Giáng sinh: Ikson - Christmas");
  } catch (err) {
    if (err && err.name !== "AbortError") {
      console.warn("Christmas BGM play blocked:", err);
      toast("Nhấn lại nút Nhạc nền Giáng sinh để cho phép trình duyệt phát âm thanh.");
    }
    updateChristmasMusicUI();
  }
};

function armFirstGestureAutoResume() {
  if (christmasBgmState.gestureArmed) return;
  christmasBgmState.gestureArmed = true;

  const tryResumeOnGesture = (ev) => {
    const target = ev && ev.target;
    if (target && target.closest && (target.closest("#christmasMusicWidget") || target.closest("#quickMenuXmasMusicRow") || target.closest(".ambient-grid") || target.closest("#paneSettingsAudio"))) {
      document.removeEventListener("pointerdown", tryResumeOnGesture, true);
      document.removeEventListener("keydown", tryResumeOnGesture, true);
      christmasBgmState.gestureArmed = false;
      return;
    }
    document.removeEventListener("pointerdown", tryResumeOnGesture, true);
    document.removeEventListener("keydown", tryResumeOnGesture, true);
    christmasBgmState.gestureArmed = false;

    if (!isChristmas2026Season() || !christmasBgmState.userWantsPlay || isStudyAudioCurrentlyPlaying()) {
      return;
    }
    const audio = ensureChristmasAudioElement();
    if (audio.paused) {
      audio.play().then(updateChristmasMusicUI).catch(() => updateChristmasMusicUI());
    }
  };

  document.addEventListener("pointerdown", tryResumeOnGesture, { capture: true, passive: true });
  document.addEventListener("keydown", tryResumeOnGesture, { capture: true, passive: true });
}

function initChristmasMusicPlayer() {
  if (christmasBgmState.initialized) return;
  christmasBgmState.initialized = true;

  const musicBtn = $("#christmasMusicToggleBtn");
  if (musicBtn) {
    musicBtn.addEventListener("click", window.toggleChristmasMusic);
  }
  const snowBtn = $("#christmasSnowToggleBtn");
  if (snowBtn) {
    snowBtn.addEventListener("click", window.toggleChristmasEffects);
  }

  let savedPref = null;
  try { savedPref = localStorage.getItem(XMAS_MUSIC_STORAGE_KEY); } catch (e) { }
  christmasBgmState.userWantsPlay = (savedPref !== "off");

  if (isChristmas2026Season() && christmasBgmState.userWantsPlay && !isStudyAudioCurrentlyPlaying()) {
    const audio = ensureChristmasAudioElement();
    const playPromise = audio.play();
    if (playPromise && typeof playPromise.then === "function") {
      playPromise.then(() => {
        updateChristmasMusicUI();
      }).catch(() => {
        // Browsers block unmuted autoplay until first interaction; arm gentle resume if not opted out
        armFirstGestureAutoResume();
        updateChristmasMusicUI();
      });
    }
  } else {
    updateChristmasMusicUI();
  }
}

function syncChristmasSpinButton(spinning) {
  const btn = $("#xmasTreeAutoSpinBtn");
  if (!btn) return;
  btn.setAttribute("aria-pressed", String(Boolean(spinning)));
  const iconSvg = btn.querySelector(".xmas-spin-icon");
  if (iconSvg) {
    iconSvg.innerHTML = spinning
      ? '<rect x="6" y="4" width="4" height="16"></rect><rect x="14" y="4" width="4" height="16"></rect>'
      : '<polygon points="6 3 20 12 6 21 6 3"></polygon>';
  }
}

function focusChristmasTreeItemOnStage(itemId, options = {}) {
  const { pauseAutoSpin = true } = options || {};
  const item = (christmasTreeEventState.items || []).find((it) => Number(it.id) === Number(itemId));
  if (!item) return;
  christmasTreeStudioState.selectedId = item.id;
  const keepSpinning = !pauseAutoSpin && !christmasSnowState.reducedMotion;
  christmasTreeStudioState.autoSpin = keepSpinning;
  christmasTreeStudioState.rotation = -Math.PI * 0.5 - Number(item.posAngle || 0);
  syncChristmasSpinButton(keepSpinning);
  showChristmasTreeInspector(item);
  renderChristmasTreeGallery();
  if (!christmasTreeStudioState.rafId && christmasTreeStudioState.isOpen) {
    christmasTreeStudioState.rafId = requestAnimationFrame(renderStudioChristmasTreeFrame);
  }
}

function hideChristmasTreeInspector() {
  christmasTreeStudioState.selectedId = null;
  const card = $("#xmasTreeInspectorCard");
  if (card) card.hidden = true;
}

function buildTreeInlineSvgIcon(kind, styleKey, size = 22) {
  const s = Math.max(14, Number(size) || 22);
  if (kind === "lock") {
    return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="11" width="18" height="11" rx="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path></svg>`;
  }
  if (kind === "polaroid") {
    return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="2"></rect><circle cx="8.5" cy="8.5" r="1.5"></circle><path d="m21 15-5-5L5 21"></path></svg>`;
  }
  if (kind === "card") {
    const tplKey = normalizeCardTemplateKey(styleKey);
    const tpl = TREE_CARD_TEMPLATE_MAP[tplKey] || TREE_CARD_TEMPLATE_MAP.card_sparkle;
    return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect x="3" y="2" width="18" height="20" rx="2.5" fill="#FFFFFF" stroke="${escapeHTML(tpl.accent)}" stroke-width="1.8"/><path d="M7 8h10M7 12h8M7 16h5" stroke="${escapeHTML(tpl.accent)}" stroke-width="1.6" stroke-linecap="round"/></svg>`;
  }
  if (kind === "gift") {
    const pal = TREE_GIFT_PALETTE_MAP[styleKey] || TREE_GIFT_PALETTE_MAP.gift_red;
    return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect x="3" y="10" width="18" height="11" rx="2" fill="${escapeHTML(pal.box)}"/><rect x="2" y="7" width="20" height="4.5" rx="1.2" fill="${escapeHTML(pal.lid)}"/><rect x="10.5" y="7" width="3" height="14" fill="${escapeHTML(pal.ribbon)}"/><path d="M12 7C9.2 7 7.4 4.8 8.6 3.5c1.1-1.2 2.9-.2 3.4 3.5Zm0 0c2.8 0 4.6-2.2 3.4-3.5-1.1-1.2-2.9-.2-3.4 3.5Z" fill="${escapeHTML(pal.ribbon)}"/></svg>`;
  }
  if (styleKey === "star_grad_gold") {
    return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="#FBBF24" stroke="#B45309" stroke-width="1.4" stroke-linejoin="round" aria-hidden="true"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>`;
  }
  if (styleKey === "ribbon_grad_velvet") {
    return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 12L7 21l2.5-1.8L12 14l2.5 5.2L17 21l-5-9Z" fill="#BE123C"/><ellipse cx="7.5" cy="9.5" rx="4.5" ry="3" fill="#E11D48" stroke="#FBBF24" stroke-width="1.2"/><ellipse cx="16.5" cy="9.5" rx="4.5" ry="3" fill="#E11D48" stroke="#FBBF24" stroke-width="1.2"/><circle cx="12" cy="10" r="2.2" fill="#FBBF24"/></svg>`;
  }
  if (styleKey === "fairy_garland" || styleKey === "prism_multi_garland") {
    const c1 = styleKey === "prism_multi_garland" ? "#EC4899" : "#F59E0B";
    const c2 = styleKey === "prism_multi_garland" ? "#38BDF8" : "#EF4444";
    const c3 = "#22C55E";
    return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M2 7c5 5 15 5 20 0" stroke="#15803D" stroke-width="1.8" stroke-linecap="round"/><circle cx="6.5" cy="10.5" r="2.5" fill="${c1}"/><circle cx="12" cy="12" r="2.6" fill="${c2}"/><circle cx="17.5" cy="10.5" r="2.5" fill="${c3}"/></svg>`;
  }
  const baubleCol = TREE_BAUBLE_COLOR_MAP[styleKey] || "#E11D48";
  return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect x="10" y="3" width="4" height="3" rx="0.8" fill="#F59E0B"/><circle cx="12" cy="14" r="7.5" fill="${escapeHTML(baubleCol)}"/><circle cx="9.6" cy="11.4" r="2.1" fill="#ffffff" opacity="0.72"/></svg>`;
}

function buildOrnamentThumbnailHtml(item) {
  if (item && item.isMysteryLocked) {
    return item.slotKind === "gift"
      ? buildTreeInlineSvgIcon("gift", item.itemStyle, 24)
      : buildTreeInlineSvgIcon("lock", "", 22);
  }
  if (item.slotKind === "polaroid") {
    const asset = getChristmasTreePhotoAsset(item.photoData || "");
    if (asset && asset.dataUrl) {
      return `<img src="${asset.dataUrl}" alt="" />`;
    }
    return buildTreeInlineSvgIcon("polaroid", item.itemStyle, 22);
  }
  if (item.slotKind === "card") {
    const tplKey = normalizeCardTemplateKey(item.itemStyle);
    const tpl = TREE_CARD_TEMPLATE_MAP[tplKey] || TREE_CARD_TEMPLATE_MAP.card_sparkle;
    if (tpl && tpl.img) {
      return `<img src="${tpl.img}" alt="" style="object-fit:contain;" />`;
    }
    return buildTreeInlineSvgIcon("card", tplKey, 24);
  }
  if (item.slotKind === "gift" || String(item.itemStyle || "").startsWith("gift_")) {
    return buildTreeInlineSvgIcon("gift", item.itemStyle, 24);
  }
  return buildTreeInlineSvgIcon("accessory", item.itemStyle, 22);
}

function getCardFinishBackgroundStyle(itemFinish, gradientStops) {
  const finKey = normalizeCardFinishKey(itemFinish);
  const spec = TREE_CARD_FINISH_MAP[finKey] || TREE_CARD_FINISH_MAP.pastel_white;
  const stops = Array.isArray(gradientStops) ? gradientStops : spec.gradientStops;
  if (stops && stops.length >= 2) {
    return `background:linear-gradient(145deg,${stops.map((c) => escapeHTML(c)).join(",")});`;
  }
  return `background:${escapeHTML(spec.bg || "#FFFFFF")};`;
}

function renderGreetingCardHTML({ itemStyle, itemFinish, gradientStops, cardName, message, viewerMode = false }) {
  const tplKey = normalizeCardTemplateKey(itemStyle);
  const tplSpec = TREE_CARD_TEMPLATE_MAP[tplKey] || TREE_CARD_TEMPLATE_MAP.card_sparkle;
  const bgCss = getCardFinishBackgroundStyle(itemFinish, gradientStops);
  const nameTxt = escapeHTML((cardName || "").trim() || (typeof session !== "undefined" && session && session.displayName) || "RE:SEARCH Member");
  const rawWish = (message || "").trim();
  const wishTxt = escapeHTML(rawWish || "Chúc bạn một mùa Giáng sinh an lành và tràn ngập niềm vui!");
  return `
    <div class="xmas-greeting-card xmas-card-sheet tpl-${tplKey}${viewerMode ? " is-viewer" : ""}" style="${bgCss}">
      <img src="${tplSpec.img}" alt="${escapeHTML(tplSpec.label)}" class="xc-tpl-artwork" draggable="false" />
      <div class="xc-tpl-name" style="${tplSpec.nameStyle}">${nameTxt}</div>
      <div class="xc-tpl-wish" style="${tplSpec.wishStyle}">${wishTxt}</div>
    </div>
  `;
}

function buildXmasLikeButtonHtml(item, extraClass = "") {
  if (!item || !item.id) return "";
  const count = Number(item.likesCount || 0);
  const likedCls = item.hasLiked ? " has-liked" : "";
  const selfCls = item.isSelf ? " is-self" : "";
  const titleTxt = item.isSelf
    ? "Bấm để xem người đã thả tim trang trí của bạn"
    : (item.hasLiked ? "Bạn đã thả tim trang trí này" : "Thả tim trang trí này");
  return `
    <button type="button" class="xmas-like-btn${likedCls}${selfCls}${extraClass ? ` ${extraClass}` : ""}" data-tree-like-id="${item.id}" title="${escapeHTML(titleTxt)}" aria-label="${escapeHTML(titleTxt)}">
      <svg class="xmas-heart-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"></path></svg>
      <span class="xmas-like-count">${count}</span>
    </button>
  `;
}

function getEffectiveViewerStreakAccess() {
  const fromServer = christmasTreeEventState.viewerAccess;
  if (fromServer && typeof fromServer.streak === "number") {
    return {
      streak: Number(fromServer.streak || 0),
      streakTier: Number(fromServer.streakTier || 0),
      canUploadPhoto: Boolean(fromServer.canUploadPhoto || Number(fromServer.streak || 0) >= 3)
    };
  }
  const s = typeof session !== "undefined" ? session : null;
  if (!s) return { streak: 0, streakTier: 0, canUploadPhoto: false };
  if (typeof s.streakTier === "number") {
    const streakVal = Math.max(0, Number(s.streak || 0));
    const tierVal = Math.max(0, Math.min(5, Number(s.streakTier || 0)));
    return {
      streak: streakVal,
      streakTier: tierVal,
      canUploadPhoto: typeof s.canUploadPhoto === "boolean" ? s.canUploadPhoto : streakVal >= 3,
    };
  }
  if (s.role === "admin" || s.role === "ta") {
    return { streak: Math.max(52, Number(s.streak || 0)), streakTier: 5, canUploadPhoto: true };
  }
  const streak = Math.max(0, Number(s.streak || 0));
  let tier = Number(s.streakTier || 0);
  if (!tier) {
    for (let i = TREE_STREAK_REQUIREMENTS.length - 1; i >= 0; i--) {
      if (streak >= TREE_STREAK_REQUIREMENTS[i]) {
        tier = i;
        break;
      }
    }
  }
  return { streak, streakTier: tier, canUploadPhoto: streak >= 3 };
}

function syncChristmasTreeStreakAccess() {
  const access = getEffectiveViewerStreakAccess();
  const tierNames = ["Tân binh", "Khởi động (≥3d)", "Bền bỉ (≥7d)", "Kiên trì (≥14d)", "Tinh anh (≥30d)", "Huyền thoại (≥50d)"];
  const tierText = $("#xmasUserTierText");
  if (tierText) {
    tierText.textContent = `Chuỗi ${access.streak} ngày · ${tierNames[Math.min(5, access.streakTier)] || "Tân binh"}`;
  }

  const uploadBox = $("#xmasPolaroidDropzone");
  const fileEl = $("#xmasPolaroidFile");
  const uploadBadge = $("#xmasPolaroidUploadBadge");
  const uploadTitle = $("#xmasPolaroidUploadTitle");
  const lockNote = $("#xmasPolaroidLockNote");
  const canUpload = Boolean(access.canUploadPhoto);
  if (uploadBox) {
    uploadBox.classList.toggle("is-locked", !canUpload);
    uploadBox.setAttribute("aria-disabled", String(!canUpload));
  }
  if (fileEl) fileEl.disabled = !canUpload;
  if (uploadBadge) {
    uploadBadge.textContent = canUpload ? "Đã mở (≥3d)" : "Chuỗi ≥3 ngày";
    uploadBadge.classList.toggle("is-unlocked", canUpload);
  }
  if (uploadTitle) {
    uploadTitle.textContent = canUpload ? "Tải ảnh lên" : "Mở khóa khi chuỗi ≥3 ngày";
  }
  if (lockNote) lockNote.hidden = canUpload;

  $$("#christmasTreeModal .is-tier-option[data-min-tier]").forEach((opt) => {
    const minTier = Number(opt.dataset.minTier || 0);
    const unlocked = access.streakTier >= minTier;
    opt.classList.toggle("is-locked", !unlocked);
    const radio = opt.querySelector('input[type="radio"]');
    if (radio) {
      radio.disabled = !unlocked;
      if (radio.checked && !unlocked) {
        const groupName = radio.getAttribute("name");
        const fallback = groupName && document.querySelector(`input[name="${groupName}"]:not(:disabled)`);
        if (fallback) fallback.checked = true;
      }
    }
  });
}

function getXmasItemViewerActionLabel(item) {
  if (!item) return "Xem";
  if (item.slotKind === "card") return "Xem thiệp";
  if (item.slotKind === "polaroid") return "Xem Polaroid";
  if (item.slotKind === "gift") return "Mở hộp quà";
  return "Xem";
}

function getChristmasOrnamentThumbBgStyle(item) {
  if (!item) return "";
  if (item.isMysteryLocked) {
    return "background:linear-gradient(135deg,#9f1239,#be123c);color:#fffbeb;";
  }
  if (item.slotKind === "polaroid") {
    const grad = TREE_POLAROID_GRADIENT_MAP[item.itemStyle];
    const polGradBg = grad && grad.length >= 2
      ? `linear-gradient(135deg,${grad.join(",")})`
      : (Array.isArray(item.gradientStops) && item.gradientStops.length >= 2
        ? `linear-gradient(135deg,${item.gradientStops.join(",")})`
        : (item.frameColor || TREE_POLAROID_FRAME_MAP[item.itemStyle] || "#FFFAF0"));
    return `background:${escapeHTML(polGradBg)};`;
  }
  if (item.slotKind === "card") {
    return getCardFinishBackgroundStyle(item.itemFinish, item.gradientStops);
  }
  if (item.slotKind === "gift") {
    const pal = TREE_GIFT_PALETTE_MAP[item.itemStyle] || TREE_GIFT_PALETTE_MAP.gift_red;
    if (pal.gradientStops && pal.gradientStops.length >= 2) {
      return `background:linear-gradient(135deg,${pal.gradientStops.join(",")});`;
    }
    return `background:color-mix(in srgb, ${escapeHTML(pal.box)} 16%, transparent);`;
  }
  return "";
}

function renderChristmasOrnamentLikesHtml(likes) {
  if (!Array.isArray(likes) || !likes.length) {
    return '<div class="xmas-likes-empty">Chưa có ai thả tim trang trí này.</div>';
  }
  return `
    <div class="xmas-likes-list-head">Người đã thả tim (${likes.length})</div>
    <div class="xmas-likes-list-rows">
      ${likes.map((u) => {
        const avHtml = u.avatar
          ? `<img src="${escapeHTML(u.avatar)}" alt="" class="xmas-liker-av" />`
          : `<span class="xmas-liker-av is-fallback">${escapeHTML((u.displayName || "?").charAt(0).toUpperCase())}</span>`;
        return `
          <button type="button" class="xmas-liker-row" data-open-namecard="${Number(u.userId)}">
            ${avHtml}
            <span class="xmas-liker-name">${escapeHTML(u.displayName || "Thành viên RE:SEARCH")}</span>
          </button>
        `;
      }).join("")}
    </div>
  `;
}

async function openChristmasItemLikesPopover(itemId) {
  const item = (christmasTreeEventState.items || []).find((it) => Number(it.id) === Number(itemId));
  if (!item) return;
  const canViewLikers = Boolean(item.isSelf || (typeof session !== "undefined" && session && session.role === "admin"));
  if (!canViewLikers) return;

  const modal = $("#xmasItemViewerModal");
  if (!modal || !modal.open || Number(christmasTreeStudioState.activeViewerItemId) !== Number(itemId)) {
    openChristmasItemViewer(itemId, { showLikesPanel: true });
    return;
  }

  const popover = $("#xmasItemViewerLikesPopover");
  if (!popover) return;
  if (!popover.hidden) {
    popover.hidden = true;
    return;
  }
  popover.hidden = false;
  popover.innerHTML = '<div class="xmas-likes-empty">Đang tải danh sách thả tim...</div>';
  try {
    const res = await requestAPI(`/api/christmas-tree/${item.id}/likes`, { method: "GET" });
    popover.innerHTML = renderChristmasOrnamentLikesHtml(res && res.likes);
  } catch (err) {
    popover.innerHTML = `<div class="xmas-likes-empty">${escapeHTML((err && err.message) || "Không tải được danh sách thả tim.")}</div>`;
  }
}

function openChristmasItemViewer(itemId, options = {}) {
  const { showLikesPanel = false } = options || {};
  const item = (christmasTreeEventState.items || []).find((it) => Number(it.id) === Number(itemId));
  const viewerModal = $("#xmasItemViewerModal");
  const titleEl = $("#xmasItemViewerTitle");
  const subEl = $("#xmasItemViewerSub");
  const likeSlotEl = $("#xmasItemViewerLikeSlot");
  const bodyEl = $("#xmasItemViewerBody");
  const likesPop = $("#xmasItemViewerLikesPopover");
  if (!item || !viewerModal || !bodyEl) return;

  const isLocked = Boolean(item.isMysteryLocked);
  if (isLocked && !showLikesPanel) {
    toast(item.lockedNotice || CHRISTMAS_LOCKED_NOTICE);
    return;
  }

  christmasTreeStudioState.activeViewerItemId = item.id;
  const typeLabel = TREE_STYLE_LABELS[item.itemStyle] || "Trang trí Giáng sinh";
  if (titleEl) {
    if (item.slotKind === "gift" && !isLocked) {
      titleEl.textContent = "Mở hộp quà Giáng sinh";
    } else {
      titleEl.textContent = typeLabel;
    }
  }
  if (subEl) {
    const finSpec = item.slotKind === "card"
      ? (TREE_CARD_FINISH_MAP[normalizeCardFinishKey(item.itemFinish)] || null)
      : null;
    const finSuffix = finSpec ? ` · Nền ${escapeHTML(finSpec.label)}` : "";
    subEl.innerHTML = `Từ <button type="button" class="xmas-inspector-author" data-open-namecard="${item.userId}">${escapeHTML(item.authorName || "Thành viên RE:SEARCH")}</button>${finSuffix}`;
  }
  if (likeSlotEl) {
    likeSlotEl.innerHTML = buildXmasLikeButtonHtml(item, "is-viewer-like");
  }
  if (likesPop) {
    likesPop.hidden = true;
    likesPop.innerHTML = "";
  }

  if (isLocked) {
    bodyEl.innerHTML = `
      <div class="xmas-viewer-locked-card">
        <div class="xmas-viewer-locked-icon">${buildTreeInlineSvgIcon("lock", "", 36)}</div>
        <p>${escapeHTML(item.lockedNotice || CHRISTMAS_LOCKED_NOTICE)}</p>
      </div>
    `;
  } else if (item.slotKind === "card") {
    bodyEl.innerHTML = `
      <div class="xmas-viewer-card-stage">
        ${renderGreetingCardHTML({
          itemStyle: item.itemStyle,
          itemFinish: item.itemFinish,
          gradientStops: item.gradientStops,
          cardName: item.cardName || item.authorName,
          message: item.message,
          viewerMode: true
        })}
      </div>
    `;
  } else if (item.slotKind === "polaroid") {
    const grad = TREE_POLAROID_GRADIENT_MAP[item.itemStyle];
    const polBg = grad && grad.length >= 2
      ? `linear-gradient(145deg,${grad.join(",")})`
      : (Array.isArray(item.gradientStops) && item.gradientStops.length >= 2
        ? `linear-gradient(145deg,${item.gradientStops.join(",")})`
        : (item.frameColor || TREE_POLAROID_FRAME_MAP[item.itemStyle] || "#FFFAF0"));
    const darkFrame = item.itemStyle === "grad_crimson_velvet" || item.itemStyle === "grad_mythic_prism";
    const viewerSrc = item.photoFullData || item.photoData || "";
    let photoHtml = buildTreeInlineSvgIcon("polaroid", item.itemStyle, 48);
    if (viewerSrc) {
      if (viewerSrc.startsWith("preset:")) {
        const asset = getChristmasTreePhotoAsset(viewerSrc);
        if (asset && asset.dataUrl) {
          photoHtml = `<img src="${asset.dataUrl}" alt="Ảnh Polaroid kỷ niệm" />`;
        }
      } else {
        photoHtml = `<img src="${escapeHTML(viewerSrc)}" alt="Ảnh Polaroid kỷ niệm" decoding="async" />`;
      }
    }
    const captionTxt = escapeHTML((item.message || "").trim() || "Kỷ niệm mùa đông RE:SEARCH");
    bodyEl.innerHTML = `
      <div class="xmas-viewer-polaroid-frame${darkFrame ? " is-dark-frame" : ""}" style="background:${escapeHTML(polBg)};">
        <div class="xmas-viewer-polaroid-photo">${photoHtml}</div>
        <div class="xmas-viewer-polaroid-caption">
          <p class="xmas-viewer-polaroid-msg">${captionTxt}</p>
          <span class="xmas-viewer-polaroid-by">— ${escapeHTML(item.authorName || "Thành viên")}</span>
        </div>
      </div>
    `;
  } else if (item.slotKind === "gift") {
    const pal = TREE_GIFT_PALETTE_MAP[item.itemStyle] || TREE_GIFT_PALETTE_MAP.gift_red;
    const outerBg = pal.gradientStops && pal.gradientStops.length >= 2
      ? `linear-gradient(145deg,${pal.gradientStops.join(",")})`
      : `linear-gradient(145deg,${pal.lid},${pal.box})`;
    const wishTxt = (item.message || "").trim()
      ? `“${escapeHTML(item.message.trim())}”`
      : "Một món quà Giáng sinh ấm áp dành tặng cộng đồng RE:SEARCH!";
    bodyEl.innerHTML = `
      <div class="xmas-viewer-gift-box" style="background:${escapeHTML(outerBg)};border-color:${escapeHTML(pal.ribbon)};">
        <div class="xmas-viewer-gift-ribbon" style="background:${escapeHTML(pal.ribbon)};" aria-hidden="true"></div>
        <div class="xmas-viewer-gift-emblem">
          ${buildTreeInlineSvgIcon("gift", item.itemStyle, 44)}
        </div>
        <div class="xmas-viewer-gift-note">
          <span class="xmas-viewer-gift-tag" style="color:${escapeHTML(pal.box)};">${escapeHTML(typeLabel)}</span>
          <p class="xmas-viewer-gift-msg">${wishTxt}</p>
          <div class="xmas-viewer-gift-from">Gửi từ <strong>${escapeHTML(item.authorName || "Thành viên RE:SEARCH")}</strong></div>
        </div>
      </div>
    `;
  } else {
    bodyEl.innerHTML = `
      <div class="xmas-viewer-locked-card">
        <div class="xmas-viewer-locked-icon">${buildOrnamentThumbnailHtml(item)}</div>
        <p>${escapeHTML(typeLabel)}</p>
      </div>
    `;
  }

  if (!viewerModal.open) {
    viewerModal.showModal();
  }
  if (showLikesPanel && likesPop) {
    likesPop.hidden = true;
    openChristmasItemLikesPopover(item.id);
  }
}

function syncChristmasLikeButtonsInDom(itemId, likesCount, hasLiked) {
  $$(`[data-tree-like-id="${Number(itemId)}"]`).forEach((btn) => {
    btn.classList.toggle("has-liked", Boolean(hasLiked));
    const cnt = btn.querySelector(".xmas-like-count");
    if (cnt) cnt.textContent = String(Number(likesCount || 0));
    if (hasLiked) {
      btn.setAttribute("title", "Bạn đã thả tim trang trí này");
      btn.setAttribute("aria-label", "Bạn đã thả tim trang trí này");
    }
  });
}

async function handleChristmasTreeLikeClick(itemId, btnEl) {
  const item = (christmasTreeEventState.items || []).find((it) => Number(it.id) === Number(itemId));
  if (!item) return;

  if (item.isSelf) {
    await openChristmasItemLikesPopover(item.id);
    return;
  }

  if (!(typeof session !== "undefined" && session && session.id)) {
    toast("Vui lòng đăng nhập để thả tim trang trí Giáng sinh.");
    return;
  }
  if (item.hasLiked) {
    if (typeof session !== "undefined" && session && session.role === "admin") {
      await openChristmasItemLikesPopover(item.id);
      return;
    }
    toast("Bạn đã thả tim trang trí này rồi!");
    return;
  }
  if (btnEl && btnEl.dataset.liking === "1") return;
  if (btnEl) btnEl.dataset.liking = "1";

  try {
    const res = await requestAPI(`/api/christmas-tree/${item.id}/like`, { method: "POST" });
    if (res && res.ok) {
      item.likesCount = Number(res.likesCount || 0);
      item.hasLiked = true;
      if (res.likesLeaderboard) {
        christmasTreeEventState.likesLeaderboard = res.likesLeaderboard;
        renderChristmasTreeLikesLeaderboard();
      }
      syncChristmasLikeButtonsInDom(item.id, item.likesCount, true);
      $$(`[data-tree-like-id="${Number(item.id)}"]`).forEach((b) => {
        b.classList.remove("animate-pop");
        void b.offsetWidth;
        b.classList.add("animate-pop");
      });
    }
  } catch (err) {
    toast((err && err.message) || "Không thể thả tim lúc này.");
  } finally {
    if (btnEl) delete btnEl.dataset.liking;
  }
}

function showChristmasTreeInspector(item) {
  const card = $("#xmasTreeInspectorCard");
  const body = $("#xmasTreeInspectorBody");
  if (!card || !body || !item) return;
  const typeLabel = TREE_STYLE_LABELS[item.itemStyle] || "Trang trí Giáng sinh";
  const isLocked = Boolean(item.isMysteryLocked);
  const deleteBtnHtml = item.canDelete
    ? `<button type="button" class="xmas-gallery-delete-btn" data-tree-delete-id="${item.id}">Gỡ món này</button>`
    : "";
  const thumbStyle = getChristmasOrnamentThumbBgStyle(item);
  const openBtnHtml = (!isLocked && item.slotKind !== "accessory")
    ? `<button type="button" class="xmas-open-viewer-btn" data-tree-open-viewer="${item.id}">${escapeHTML(getXmasItemViewerActionLabel(item))}</button>`
    : "";
  const cardNameLine = (item.slotKind === "card" && !isLocked && item.cardName && item.cardName !== item.authorName)
    ? `<div class="xmas-inspector-subname">Tên trên thiệp: <strong>${escapeHTML(item.cardName)}</strong></div>`
    : "";
  const lockedLine = isLocked
    ? `<p class="xmas-inspector-wish"><span class="xmas-mystery-tag">${buildTreeInlineSvgIcon("lock", "", 13)} ${escapeHTML(item.lockedNotice || CHRISTMAS_LOCKED_NOTICE)}</span></p>`
    : "";

  body.innerHTML = `
    <div class="xmas-inspector-content">
      <div class="xmas-inspector-thumb" style="${thumbStyle}">
        ${buildOrnamentThumbnailHtml(item)}
      </div>
      <div class="xmas-inspector-meta">
        <button type="button" class="xmas-inspector-author" data-open-namecard="${item.userId}">
          ${escapeHTML(item.authorName || "Thành viên RE:SEARCH")}
        </button>
        <div class="xmas-inspector-type">${escapeHTML(typeLabel)}</div>
        ${cardNameLine}
        ${lockedLine}
        <div class="xmas-inspector-actions-row">
          ${openBtnHtml}
          ${buildXmasLikeButtonHtml(item)}
          ${deleteBtnHtml}
        </div>
      </div>
    </div>
  `;
  card.hidden = false;
}

function updateChristmasTreeBadges() {
  const stats = christmasTreeEventState.stats || { totalItems: 0, contributors: 0 };
  const total = Number(stats.totalItems || 0);
  const contributors = Number(stats.contributors || 0);
  const widgetBadge = $("#christmasTreeWidgetCount");
  if (widgetBadge) widgetBadge.textContent = String(total);
  const heroBadge = $("#heroTreeCountBadge");
  if (heroBadge) heroBadge.textContent = String(total);
  const qmCount = $("#quickMenuTreeCount");
  if (qmCount) qmCount.textContent = `(${total})`;

  const summary = $("#xmasTreeStatsSummary");
  if (summary) {
    summary.textContent = "Trang trí phụ kiện của bạn lên cây thông để cùng tạo nên mùa Giáng sinh ấm áp";
  }

  const milestone = $("#xmasTreeMilestoneBar");
  if (milestone) {
    if (total === 0) {
      milestone.textContent = "🎄 Cây thông khởi đầu · Mời bạn treo món đầu tiên";
    } else if (total < 5) {
      milestone.textContent = `🎄 Cây thông bắt đầu lên đèn (${total} món từ ${contributors} thành viên)`;
    } else if (total < 15) {
      milestone.textContent = `🎄 Cây thông đang rực rỡ sắc màu (${total} món · ${contributors} người)`;
    } else {
      milestone.textContent = `🎄 Cây thông đại lễ hội RE:SEARCH (${total} món · ${contributors} người chung tay)`;
    }
  }
}

function renderPolaroidFormPreview() {
  const previewCard = $("#xmasPolaroidLivePreview");
  const photoBox = $("#xmasPreviewPhotoBox");
  const captionBox = $("#xmasPreviewCaption");
  const msgInput = $("#xmasPolaroidMsg");
  const charCount = $("#xmasPolaroidCharCount");
  const sealBadge = $("#xmasPreviewSealBadge");
  const checkedStyle = document.querySelector('input[name="polaroidStyle"]:checked');
  const styleVal = checkedStyle ? checkedStyle.value : "classic";

  if (previewCard) {
    const gradStops = TREE_POLAROID_GRADIENT_MAP[styleVal];
    previewCard.style.background = gradStops
      ? `linear-gradient(135deg, ${gradStops.join(", ")})`
      : (TREE_POLAROID_FRAME_MAP[styleVal] || "#FFFAF0");
  }
  const msgVal = msgInput ? msgInput.value : "";
  if (charCount) charCount.textContent = String(msgVal.length);
  if (captionBox) {
    captionBox.textContent = msgVal.trim() || "Kỷ niệm mùa đông...";
  }
  const myPol = (christmasTreeEventState.items || []).find((it) => it.isSelf && it.slotKind === "polaroid");
  if (sealBadge) {
    sealBadge.hidden = !(myPol && myPol.isMysteryLocked);
  }
  const photoData = christmasTreeStudioState.polaroidPhotoData || "";
  const previewSrc = christmasTreeStudioState.polaroidPhotoFullData || photoData;
  if (photoBox) {
    if (previewSrc) {
      const asset = getChristmasTreePhotoAsset(previewSrc);
      if (asset && asset.dataUrl) {
        photoBox.innerHTML = `<img src="${asset.dataUrl}" alt="" />`;
      } else if (previewSrc.startsWith("/api/christmas-tree/photos/") || previewSrc.startsWith("data:image/")) {
        photoBox.innerHTML = `<img src="${escapeHTML(previewSrc)}" alt="" />`;
      } else {
        photoBox.innerHTML = buildTreeInlineSvgIcon("polaroid", styleVal, 26);
      }
    } else {
      photoBox.innerHTML = buildTreeInlineSvgIcon("polaroid", styleVal, 26);
    }
  }
  $$("#christmasTreeModal .xmas-preset-card[data-photo-preset]").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.photoPreset === photoData);
  });
}

function getSelectedChristmasCardSpec() {
  const checkedTpl = document.querySelector('input[name="cardStyle"]:checked');
  const tplKey = normalizeCardTemplateKey(checkedTpl ? checkedTpl.value : "card_sparkle");
  return { tplKey, spec: TREE_CARD_TEMPLATE_MAP[tplKey] || TREE_CARD_TEMPLATE_MAP.card_sparkle };
}

function syncChristmasCardTemplateConstraints() {
  const { spec } = getSelectedChristmasCardSpec();
  const maxChars = Number(spec.maxChars || 300);
  const msgEl = $("#xmasCardMsg");
  const countEl = $("#xmasCardCharCount");
  const limitEl = $("#xmasCardLimitCount");
  const maxLabelEl = $("#xmasCardMaxLabel");
  if (msgEl) msgEl.maxLength = maxChars;
  if (limitEl) limitEl.textContent = String(maxChars);
  if (maxLabelEl) maxLabelEl.textContent = String(maxChars);
  const len = msgEl ? msgEl.value.length : 0;
  if (countEl) {
    countEl.textContent = String(len);
    countEl.classList.toggle("is-over-limit", len > maxChars);
  }
  return maxChars;
}

function renderCardFormPreview() {
  const host = $("#xmasCardLivePreview");
  const { tplKey } = getSelectedChristmasCardSpec();
  const checkedFinish = document.querySelector('input[name="cardFinish"]:checked');
  const nameEl = $("#xmasCardName");
  const msgEl = $("#xmasCardMsg");
  syncChristmasCardTemplateConstraints();
  const msgVal = msgEl ? msgEl.value : "";
  if (!host) return;
  const finishKey = normalizeCardFinishKey(checkedFinish ? checkedFinish.value : "pastel_white");
  const finishSpec = TREE_CARD_FINISH_MAP[finishKey] || TREE_CARD_FINISH_MAP.pastel_white;
  host.innerHTML = renderGreetingCardHTML({
    itemStyle: tplKey,
    itemFinish: finishKey,
    gradientStops: finishSpec.gradientStops,
    cardName: nameEl ? nameEl.value : "",
    message: msgVal,
    viewerMode: false
  });
}

function renderGiftFormPreview() {
  const checkedGift = document.querySelector('input[name="giftStyle"]:checked');
  const giftVal = checkedGift ? checkedGift.value : "gift_red";
  const iconEl = $("#xmasGiftPreviewIcon");
  const labelEl = $("#xmasGiftPreviewLabel");
  const wishEl = $("#xmasGiftPreviewWish");
  const msgEl = $("#xmasGiftMsg");
  const pal = TREE_GIFT_PALETTE_MAP[giftVal] || TREE_GIFT_PALETTE_MAP.gift_red;
  if (iconEl) {
    iconEl.innerHTML = buildTreeInlineSvgIcon("gift", giftVal, 28);
    iconEl.style.background = pal.gradientStops ? `linear-gradient(135deg,${pal.gradientStops.join(",")})` : "";
  }
  if (labelEl) {
    labelEl.textContent = TREE_STYLE_LABELS[giftVal] || "Hộp quà Giáng sinh";
  }
  if (wishEl) {
    const val = msgEl ? msgEl.value.trim() : "";
    wishEl.textContent = val || "Món quà đặt dưới gốc thông";
  }
}

function renderAccessoryFormPreview() {
  const checkedAcc = document.querySelector('input[name="accessoryStyle"]:checked');
  const accVal = checkedAcc ? checkedAcc.value : "bauble_ruby";
  const iconEl = $("#xmasAccPreviewIcon");
  const labelEl = $("#xmasAccPreviewLabel");
  const stops = TREE_ACCESSORY_GRADIENT_MAP[accVal];
  if (iconEl) {
    iconEl.innerHTML = buildTreeInlineSvgIcon("accessory", accVal, 28);
    iconEl.style.background = stops ? `linear-gradient(135deg,${stops.join(",")})` : "";
  }
  if (labelEl) {
    labelEl.textContent = TREE_STYLE_LABELS[accVal] || "Phụ kiện Giáng sinh";
  }
}

function renderChristmasTreeGallery() {
  const listEl = $("#xmasTreeGalleryList");
  const galleryCount = $("#xmasGalleryCount");
  const items = christmasTreeEventState.items || [];
  if (galleryCount) galleryCount.textContent = String(items.length);
  if (!listEl) return;

  if (!items.length) {
    listEl.innerHTML = `<div class="xmas-tree-guest-box"><p>Cây thông hiện chưa có món trang trí nào từ cộng đồng. Hãy là người đầu tiên treo Polaroid, thiệp chúc, hộp quà hoặc phụ kiện!</p></div>`;
    return;
  }

  listEl.innerHTML = items.map((item) => {
    const typeLabel = TREE_STYLE_LABELS[item.itemStyle] || "Trang trí";
    const isSel = Number(christmasTreeStudioState.selectedId) === Number(item.id);
    const isLocked = Boolean(item.isMysteryLocked);
    let msgHtml = "";
    if (isLocked) {
      msgHtml = `<p class="xmas-gallery-msg"><span class="xmas-mystery-tag">${buildTreeInlineSvgIcon("lock", "", 13)} ${escapeHTML(item.lockedNotice || CHRISTMAS_LOCKED_NOTICE)}</span></p>`;
    } else if (item.slotKind === "card" && item.cardName && item.cardName !== item.authorName) {
      msgHtml = `<p class="xmas-gallery-msg xmas-gallery-submeta">Tên trên thiệp: <strong>${escapeHTML(item.cardName)}</strong></p>`;
    }

    const delBtn = item.canDelete
      ? `<button type="button" class="xmas-gallery-delete-btn" data-tree-delete-id="${item.id}">Gỡ</button>`
      : "";
    const openBtn = (!isLocked && item.slotKind !== "accessory")
      ? `<button type="button" class="xmas-open-viewer-btn" data-tree-open-viewer="${item.id}">${escapeHTML(getXmasItemViewerActionLabel(item))}</button>`
      : "";
    const iconBg = getChristmasOrnamentThumbBgStyle(item);
    return `
      <div class="xmas-gallery-item${isSel ? " is-selected" : ""}">
        <div class="xmas-gallery-icon" style="${iconBg}">
          ${buildOrnamentThumbnailHtml(item)}
        </div>
        <div class="xmas-gallery-info">
          <div class="xmas-gallery-head">
            <button type="button" class="xmas-inspector-author" data-open-namecard="${item.userId}">
              ${escapeHTML(item.authorName || "Thành viên")}
            </button>
            <span class="xmas-inspector-type">· ${escapeHTML(typeLabel)}</span>
          </div>
          ${msgHtml}
        </div>
        <div class="xmas-gallery-actions">
          ${buildXmasLikeButtonHtml(item)}
          ${openBtn}
          <button type="button" class="xmas-gallery-locate-btn" data-tree-focus-id="${item.id}" title="Xoay cây tới món này">Trên cây</button>
          ${delBtn}
        </div>
      </div>
    `;
  }).join("");
}

function populateUserTreeFormsFromItems() {
  const myItems = (christmasTreeEventState.items || []).filter((it) => it.isSelf);
  const myPolaroid = myItems.find((it) => it.slotKind === "polaroid") || null;
  const myCard = myItems.find((it) => it.slotKind === "card") || null;
  const myGift = myItems.find((it) => it.slotKind === "gift") || null;
  const myAccessory = myItems.find((it) => it.slotKind === "accessory") || null;

  const slotCountEl = $("#xmasMySlotCount");
  if (slotCountEl) slotCountEl.textContent = String(myItems.length);
  const quotaEl = $("#xmasSlotQuotaNote");
  if (quotaEl) {
    quotaEl.textContent = myItems.length >= 2
      ? `Đã dùng ${myItems.length}/2 loại · Gỡ bớt 1 món để đổi loại`
      : `Đã dùng ${myItems.length}/2 loại`;
  }

  $("#xmasSlotBtnPolaroid")?.classList.toggle("is-used", Boolean(myPolaroid));
  $("#xmasSlotBtnCard")?.classList.toggle("is-used", Boolean(myCard));
  $("#xmasSlotBtnGift")?.classList.toggle("is-used", Boolean(myGift));
  $("#xmasSlotBtnAccessory")?.classList.toggle("is-used", Boolean(myAccessory));

  // Sync Polaroid form fields
  const polMsg = $("#xmasPolaroidMsg");
  const polSubmit = $("#xmasPolaroidSubmitBtn");
  const polDelete = $("#xmasPolaroidDeleteBtn");
  const fileLabel = $("#xmasPolaroidFileName");
  if (myPolaroid) {
    const draftMsg = myPolaroid.ownerDraft ? myPolaroid.ownerDraft.message : (myPolaroid.message || "");
    const draftPhoto = myPolaroid.ownerDraft ? myPolaroid.ownerDraft.photoData : (myPolaroid.photoData || "");
    const draftPhotoFull = myPolaroid.ownerDraft
      ? (myPolaroid.ownerDraft.photoFullData || draftPhoto)
      : (myPolaroid.photoFullData || draftPhoto);
    if (polMsg) polMsg.value = draftMsg;
    const radio = document.querySelector(`input[name="polaroidStyle"][value="${myPolaroid.itemStyle}"]`);
    if (radio && !radio.disabled) radio.checked = true;
    christmasTreeStudioState.polaroidPhotoData = draftPhoto;
    christmasTreeStudioState.polaroidPhotoFullData = draftPhoto.startsWith("preset:") ? "" : draftPhotoFull;
    if (fileLabel) {
      fileLabel.textContent = draftPhoto
        ? (draftPhoto.startsWith("preset:") ? "Đang dùng tranh minh họa có sẵn" : "Đã đính kèm ảnh kỷ niệm")
        : "PNG, JPG, WEBP · Kéo thả hoặc bấm chọn";
    }
    if (polSubmit) polSubmit.textContent = "Cập nhật Polaroid";
    if (polDelete) {
      polDelete.hidden = false;
      polDelete.dataset.deleteId = String(myPolaroid.id);
    }
  } else {
    if (polMsg && !polMsg.matches(":focus")) polMsg.value = "";
    christmasTreeStudioState.polaroidPhotoData = "";
    christmasTreeStudioState.polaroidPhotoFullData = "";
    if (fileLabel) fileLabel.textContent = "PNG, JPG, WEBP · Kéo thả hoặc bấm chọn";
    if (polSubmit) polSubmit.textContent = "Treo lên cây";
    if (polDelete) {
      polDelete.hidden = true;
      delete polDelete.dataset.deleteId;
    }
  }
  renderPolaroidFormPreview();

  // Sync Greeting Card form fields
  const cardNameEl = $("#xmasCardName");
  const cardMsgEl = $("#xmasCardMsg");
  const cardSubmit = $("#xmasCardSubmitBtn");
  const cardDelete = $("#xmasCardDeleteBtn");
  const defaultAuthor = (typeof session !== "undefined" && session && session.displayName) || "";
  if (myCard) {
    const draft = myCard.ownerDraft || myCard;
    if (cardNameEl && !cardNameEl.matches(":focus")) cardNameEl.value = draft.cardName || defaultAuthor;
    if (cardMsgEl && !cardMsgEl.matches(":focus")) cardMsgEl.value = draft.message || "";
    const normStyle = normalizeCardTemplateKey(myCard.itemStyle);
    const tplR = document.querySelector(`input[name="cardStyle"][value="${normStyle}"]`);
    if (tplR) tplR.checked = true;
    const normFin = normalizeCardFinishKey(draft.itemFinish || myCard.itemFinish || "pastel_white");
    const finR = document.querySelector(`input[name="cardFinish"][value="${normFin}"]`);
    if (finR && !finR.disabled) finR.checked = true;
    if (cardSubmit) cardSubmit.textContent = "Cập nhật thiệp";
    if (cardDelete) {
      cardDelete.hidden = false;
      cardDelete.dataset.deleteId = String(myCard.id);
    }
  } else {
    if (cardNameEl && !cardNameEl.matches(":focus") && !cardNameEl.value) cardNameEl.value = defaultAuthor;
    if (cardMsgEl && !cardMsgEl.matches(":focus")) cardMsgEl.value = "";
    if (cardSubmit) cardSubmit.textContent = "Treo lên cây";
    if (cardDelete) {
      cardDelete.hidden = true;
      delete cardDelete.dataset.deleteId;
    }
  }
  renderCardFormPreview();

  // Sync Gift form fields
  const giftMsg = $("#xmasGiftMsg");
  const giftSubmit = $("#xmasGiftSubmitBtn");
  const giftDelete = $("#xmasGiftDeleteBtn");
  if (myGift) {
    const draftMsg = myGift.ownerDraft ? myGift.ownerDraft.message : (myGift.message || "");
    if (giftMsg && !giftMsg.matches(":focus")) giftMsg.value = draftMsg;
    const radio = document.querySelector(`input[name="giftStyle"][value="${myGift.itemStyle}"]`);
    if (radio && !radio.disabled) radio.checked = true;
    if (giftSubmit) giftSubmit.textContent = "Cập nhật hộp quà";
    if (giftDelete) {
      giftDelete.hidden = false;
      giftDelete.dataset.deleteId = String(myGift.id);
    }
  } else {
    if (giftMsg && !giftMsg.matches(":focus")) giftMsg.value = "";
    if (giftSubmit) giftSubmit.textContent = "Treo lên cây";
    if (giftDelete) {
      giftDelete.hidden = true;
      delete giftDelete.dataset.deleteId;
    }
  }
  renderGiftFormPreview();

  // Sync Accessory form fields
  const accSubmit = $("#xmasAccSubmitBtn");
  const accDelete = $("#xmasAccDeleteBtn");
  if (myAccessory) {
    const radio = document.querySelector(`input[name="accessoryStyle"][value="${myAccessory.itemStyle}"]`);
    if (radio && !radio.disabled) radio.checked = true;
    if (accSubmit) accSubmit.textContent = "Cập nhật phụ kiện";
    if (accDelete) {
      accDelete.hidden = false;
      accDelete.dataset.deleteId = String(myAccessory.id);
    }
  } else {
    if (accSubmit) accSubmit.textContent = "Treo lên cây";
    if (accDelete) {
      accDelete.hidden = true;
      delete accDelete.dataset.deleteId;
    }
  }
  renderAccessoryFormPreview();
}

function renderChristmasTreeLikesLeaderboard() {
  const podiumWrap = $("#xmasTreeLbPodium");
  const listWrap = $("#xmasTreeLbListWrap");
  const listEl = $("#xmasTreeLbList");
  if (!podiumWrap) return;

  const lb = christmasTreeEventState.likesLeaderboard || { top10: [], totalRanked: 0, currentUserEntry: null };
  const top10 = Array.isArray(lb.top10) ? lb.top10 : [];
  const currentUserEntry = lb.currentUserEntry || null;

  if (!top10.length) {
    podiumWrap.innerHTML = `<div class="comp-lb-empty xmas-lb-empty">Chưa có lượt yêu thích nào cho các món trang trí. Hãy thả tim cho món bạn thích nhé!</div>`;
    if (listWrap) listWrap.hidden = true;
    if (listEl) listEl.innerHTML = "";
    return;
  }

  const top1 = top10.find((u) => u.rank === 1) || null;
  const top2 = top10.find((u) => u.rank === 2) || null;
  const top3 = top10.find((u) => u.rank === 3) || null;
  const opts = { scoreIconHtml: XMAS_LIKE_HEART_SVG, useLikesCount: true };

  podiumWrap.innerHTML = renderArenaTop3(top1, top2, top3, false, opts);

  const rest = top10.filter((u) => u.rank >= 4);
  let rowsHtml = "";
  rest.forEach((u) => {
    const isCurrent = Boolean(
      u.isCurrentUser ||
      (currentUserEntry && Number(currentUserEntry.userId) === Number(u.userId)) ||
      (typeof session !== "undefined" && session && Number(session.id) === Number(u.userId))
    );
    rowsHtml += buildArenaLeaderboardRowHtml(u, isCurrent, opts);
  });

  if (currentUserEntry && currentUserEntry.rank > 10) {
    rowsHtml += buildArenaLeaderboardRowHtml(currentUserEntry, true, { ...opts, isPinnedMyRow: true });
  }

  if (listEl) listEl.innerHTML = rowsHtml;
  if (listWrap) listWrap.hidden = !rowsHtml;
}

function renderChristmasTreeStudioUI(syncForms = true) {
  updateChristmasTreeBadges();
  syncChristmasTreeStreakAccess();
  renderChristmasTreeGallery();
  renderChristmasTreeLikesLeaderboard();

  const guestBox = $("#xmasTreeGuestBox");
  const formsWrap = $("#xmasTreeFormsWrap");
  const loggedIn = Boolean(typeof session !== "undefined" && session && session.id);
  const currentUid = loggedIn ? session.id : null;
  if (guestBox) guestBox.hidden = loggedIn;
  if (formsWrap) formsWrap.hidden = !loggedIn;

  if (christmasTreeStudioState.initialized && christmasTreeStudioState.lastSessionUserId !== currentUid) {
    christmasTreeStudioState.lastSessionUserId = currentUid;
    fetchChristmasTreeData(true);
  }

  if (loggedIn && syncForms) {
    populateUserTreeFormsFromItems();
  } else {
    const myItems = (christmasTreeEventState.items || []).filter((it) => it.isSelf);
    const slotCountEl = $("#xmasMySlotCount");
    if (slotCountEl) slotCountEl.textContent = String(loggedIn ? myItems.length : 0);
  }

  if (loggedIn && christmasTreeStudioState.pendingReopenModal) {
    christmasTreeStudioState.pendingReopenModal = false;
    setTimeout(() => {
      if (isChristmas2026Season()) openChristmasTreeModal();
    }, 180);
  }
}

function applyChristmasTreeServerPayload(data, syncForms = true) {
  if (!data) return;
  christmasTreeEventState.loaded = true;
  christmasTreeEventState.active = data.active !== false;
  christmasTreeEventState.expiresAt = Number(data.expiresAt || CHRISTMAS_2026_END_MS);
  christmasTreeEventState.viewerAccess = data.viewerAccess || null;
  christmasTreeEventState.items = Array.isArray(data.items) ? data.items : [];
  christmasTreeEventState.stats = data.stats || { totalItems: 0, contributors: 0, polaroids: 0, cards: 0, gifts: 0, accessories: 0 };
  christmasTreeEventState.likesLeaderboard = data.likesLeaderboard || { top10: [], totalRanked: 0, currentUserEntry: null };
  syncCombinedChristmasTreeItems();
  renderChristmasTreeStudioUI(syncForms);
}

async function fetchChristmasTreeData(syncForms = true) {
  const token = (christmasTreeEventState._fetchToken || 0) + 1;
  christmasTreeEventState._fetchToken = token;
  christmasTreeEventState.loading = true;
  try {
    const data = await requestAPI("/api/christmas-tree", { method: "GET" });
    if (token !== christmasTreeEventState._fetchToken) return;
    applyChristmasTreeServerPayload(data, syncForms);
  } catch (err) {
    if (token === christmasTreeEventState._fetchToken) {
      console.warn("Không thể tải dữ liệu cây thông Giáng sinh:", err);
    }
  } finally {
    if (token === christmasTreeEventState._fetchToken) {
      christmasTreeEventState.loading = false;
    }
  }
}
window.fetchChristmasTreeData = fetchChristmasTreeData;

function setChristmasTreeStatus(msg, isError = false) {
  const el = $("#xmasTreeFormStatus");
  if (el) {
    el.textContent = msg || "";
    el.classList.toggle("is-error", Boolean(isError));
    if (isError && msg && typeof el.scrollIntoView === "function") {
      try {
        el.scrollIntoView({ behavior: "smooth", block: "nearest" });
      } catch {}
    }
  }
  if (isError && msg && typeof toast === "function") {
    toast(msg);
  }
}

function encodeScaledImageWithinBudget(img, sideCandidates, qualityCandidates, maxDataUrlLen) {
  let lastUrl = "";
  for (const maxSide of sideCandidates) {
    const scale = Math.min(1, maxSide / Math.max(1, img.width, img.height));
    const tw = Math.max(32, Math.round(img.width * scale));
    const th = Math.max(32, Math.round(img.height * scale));
    const c = document.createElement("canvas");
    c.width = tw;
    c.height = th;
    const g = c.getContext("2d");
    if (g) {
      g.imageSmoothingEnabled = true;
      g.imageSmoothingQuality = "high";
      g.drawImage(img, 0, 0, tw, th);
    }
    for (const q of qualityCandidates) {
      let url = c.toDataURL("image/webp", q);
      if (!url.startsWith("data:image/webp")) {
        url = c.toDataURL("image/jpeg", Math.max(0.5, q - 0.06));
      }
      lastUrl = url;
      if (url.length <= maxDataUrlLen) {
        return url;
      }
    }
  }
  return lastUrl && lastUrl.length <= maxDataUrlLen ? lastUrl : "";
}

async function compressPolaroidImagePair(file) {
  if (!file || !/^image\/(png|jpeg|jpg|webp)$/i.test(file.type || "")) {
    throw new Error("Chỉ hỗ trợ ảnh PNG, JPG hoặc WEBP.");
  }
  const objectUrl = URL.createObjectURL(file);
  try {
    const img = await new Promise((resolve, reject) => {
      const i = new Image();
      i.onload = () => resolve(i);
      i.onerror = () => reject(new Error("Không thể đọc ảnh này."));
      i.src = objectUrl;
    });
    const fullDataUrl = encodeScaledImageWithinBudget(
      img,
      [840, 720, 600],
      [0.84, 0.78, 0.7, 0.6],
      225000
    );
    const thumbDataUrl = encodeScaledImageWithinBudget(
      img,
      [220, 180],
      [0.78, 0.68, 0.56],
      58000
    );
    if (!fullDataUrl || !thumbDataUrl) {
      throw new Error("Ảnh quá lớn hoặc quá chi tiết, vui lòng chọn ảnh khác nhẹ hơn.");
    }
    return { thumbDataUrl, fullDataUrl };
  } finally {
    URL.revokeObjectURL(objectUrl);
  }
}

function resizeChristmasTreeStudioCanvas() {
  const canvas = christmasTreeStudioState.canvas;
  if (!canvas) return;
  const wrap = canvas.parentElement;
  const rect = wrap ? wrap.getBoundingClientRect() : canvas.getBoundingClientRect();
  const w = Math.max(260, Math.round(rect.width || 440));
  const h = Math.max(280, Math.round(rect.height || 440));
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  christmasTreeStudioState.width = w;
  christmasTreeStudioState.height = h;
  canvas.width = Math.floor(w * dpr);
  canvas.height = Math.floor(h * dpr);
  const ctx = canvas.getContext("2d");
  if (ctx) {
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    christmasTreeStudioState.ctx = ctx;
  }
}

function renderStudioChristmasTreeFrame(nowMs) {
  const modal = $("#christmasTreeModal");
  if (!christmasTreeStudioState.isOpen || !modal || !modal.open) {
    christmasTreeStudioState.rafId = null;
    christmasTreeStudioState.lastMs = 0;
    return;
  }
  const ctx = christmasTreeStudioState.ctx;
  const w = christmasTreeStudioState.width;
  const h = christmasTreeStudioState.height;
  if (!ctx || !w || !h) {
    christmasTreeStudioState.rafId = requestAnimationFrame(renderStudioChristmasTreeFrame);
    return;
  }

  const dt = christmasTreeStudioState.lastMs
    ? Math.min(0.05, Math.max(0.004, (nowMs - christmasTreeStudioState.lastMs) / 1000))
    : 0.016;
  christmasTreeStudioState.lastMs = nowMs;
  christmasTreeStudioState.timeSec += dt;

  if (christmasTreeStudioState.autoSpin && !christmasTreeStudioState.dragging && !christmasSnowState.reducedMotion) {
    christmasTreeStudioState.rotation = (christmasTreeStudioState.rotation + dt * 0.38) % (Math.PI * 2);
  }
  christmasTreeStudioState.starRotation = (christmasTreeStudioState.starRotation + dt * 0.72) % (Math.PI * 2);

  if (!christmasTreeState.baseItems.length) {
    buildChristmasTreeGeometry(w <= 440);
  }

  ctx.clearRect(0, 0, w, h);
  const layout = getChristmasTreeStudioLayout(w, h);
  renderChristmasTreeScene(ctx, layout, christmasTreeStudioState.projected, {
    items: christmasTreeState.items,
    rot: christmasTreeStudioState.rotation,
    starRotation: christmasTreeStudioState.starRotation,
    timeSec: christmasTreeStudioState.timeSec,
    isDark: christmasTreeState.isDark,
    interactive: true,
    selectedId: christmasTreeStudioState.selectedId,
    hoverId: christmasTreeStudioState.hoverId,
    hitBoxes: christmasTreeStudioState.hitBoxes
  });

  christmasTreeStudioState.rafId = requestAnimationFrame(renderStudioChristmasTreeFrame);
}

function findHitTreeOrnament(clientX, clientY) {
  const canvas = christmasTreeStudioState.canvas;
  if (!canvas) return null;
  const rect = canvas.getBoundingClientRect();
  const lx = clientX - rect.left;
  const ly = clientY - rect.top;
  const boxes = christmasTreeStudioState.hitBoxes;
  for (let i = boxes.length - 1; i >= 0; i--) {
    const b = boxes[i];
    const dx = lx - b.x;
    const dy = ly - b.y;
    if ((dx * dx + dy * dy) <= b.r * b.r) {
      return b.item;
    }
  }
  return null;
}

function updateChristmasCountdownUI() {
  const tickerEl = $("#xmasCountdownTicker");
  if (!tickerEl) return;
  const now = Date.now();
  const targetMs = Date.parse("2026-12-25T00:00:00+07:00");
  const endMs = typeof CHRISTMAS_2026_END_MS === "number" ? CHRISTMAS_2026_END_MS : Date.parse("2026-12-31T23:59:59+07:00");
  if (now >= targetMs && now <= endMs) {
    tickerEl.innerHTML = `<span class="xmas-cd-highlight">Giáng sinh an lành! · Hết 31/12</span>`;
    return;
  }
  if (now > endMs) {
    tickerEl.textContent = "Đã khép lại mùa lễ 2026";
    return;
  }
  const diff = Math.max(0, targetMs - now);
  const days = Math.floor(diff / 86400000);
  const hours = Math.floor((diff % 86400000) / 3600000);
  const mins = Math.floor((diff % 3600000) / 60000);
  const secs = Math.floor((diff % 60000) / 1000);
  const p = (n) => String(n).padStart(2, "0");
  tickerEl.innerHTML = `<span><strong>${days}</strong>d</span> <span><strong>${p(hours)}</strong>h</span> <span><strong>${p(mins)}</strong>m</span> <span><strong>${p(secs)}</strong>s</span>`;
}

function stopChristmasCountdownLoop() {
  if (christmasTreeStudioState.countdownTimerId) {
    clearInterval(christmasTreeStudioState.countdownTimerId);
    christmasTreeStudioState.countdownTimerId = null;
  }
}

function startChristmasCountdownLoop() {
  stopChristmasCountdownLoop();
  updateChristmasCountdownUI();
  christmasTreeStudioState.countdownTimerId = setInterval(() => {
    if (!christmasTreeStudioState.isOpen) {
      stopChristmasCountdownLoop();
      return;
    }
    updateChristmasCountdownUI();
  }, 1000);
}

function setChristmasTreeFullscreen(active) {
  const modal = $("#christmasTreeModal");
  const fsBtn = $("#xmasTreeFullscreenBtn");
  const next = Boolean(active);
  christmasTreeStudioState.stageFullscreen = next;
  if (modal) modal.classList.toggle("is-stage-fullscreen", next);
  if (fsBtn) {
    fsBtn.setAttribute("aria-pressed", String(next));
    fsBtn.setAttribute("title", next ? "Thu gọn cây thông" : "Xem toàn màn hình cây thông");
    fsBtn.setAttribute("aria-label", next ? "Thu gọn cây thông" : "Xem toàn màn hình cây thông");
    fsBtn.innerHTML = next
      ? '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="4 14 10 14 10 20"></polyline><polyline points="20 10 14 10 14 4"></polyline><line x1="14" y1="10" x2="21" y2="3"></line><line x1="3" y1="21" x2="10" y2="14"></line></svg>'
      : '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="15 3 21 3 21 9"></polyline><polyline points="9 21 3 21 3 15"></polyline><line x1="21" y1="3" x2="14" y2="10"></line><line x1="3" y1="21" x2="10" y2="14"></line></svg>';
  }
  requestAnimationFrame(() => resizeChristmasTreeStudioCanvas());
}

function initChristmasTreeStudio() {
  if (christmasTreeStudioState.initialized) return;
  christmasTreeStudioState.initialized = true;

  const modal = $("#christmasTreeModal");
  const canvas = $("#christmasTreeStudioCanvas");
  christmasTreeStudioState.canvas = canvas;

  const openTriggers = [$("#christmasTreeOpenBtn"), $("#heroChristmasTreeBtn")];
  openTriggers.forEach((btn) => {
    if (btn) btn.addEventListener("click", (e) => openChristmasTreeModal(e));
  });

  if (!modal) return;

  if (!("closedBy" in HTMLDialogElement.prototype)) {
    let downOnBackdrop = false;
    modal.addEventListener("pointerdown", (ev) => {
      downOnBackdrop = ev.target === modal;
    });
    modal.addEventListener("pointerup", (ev) => {
      if (downOnBackdrop && ev.target === modal) {
        modal.close();
      }
      downOnBackdrop = false;
    });
  }

  modal.addEventListener("close", () => {
    christmasTreeStudioState.isOpen = false;
    stopChristmasCountdownLoop();
    setChristmasTreeFullscreen(false);
    if (christmasTreeStudioState.rafId) {
      cancelAnimationFrame(christmasTreeStudioState.rafId);
      christmasTreeStudioState.rafId = null;
    }
  });

  const authModal = $("#authModal");
  if (authModal) {
    authModal.addEventListener("close", () => {
      if (!session) christmasTreeStudioState.pendingReopenModal = false;
    });
  }

  $("#xmasInspectorCloseBtn")?.addEventListener("click", hideChristmasTreeInspector);

  $("#xmasTreeFullscreenBtn")?.addEventListener("click", () => {
    setChristmasTreeFullscreen(!christmasTreeStudioState.stageFullscreen);
  });

  $("#xmasTreeRotateLeftBtn")?.addEventListener("click", () => {
    christmasTreeStudioState.rotation -= 0.62;
  });
  $("#xmasTreeRotateRightBtn")?.addEventListener("click", () => {
    christmasTreeStudioState.rotation += 0.62;
  });
  $("#xmasTreeAutoSpinBtn")?.addEventListener("click", () => {
    christmasTreeStudioState.autoSpin = !christmasTreeStudioState.autoSpin;
    syncChristmasSpinButton(christmasTreeStudioState.autoSpin);
  });

  const tabEls = {
    decorate: $("#xmasTabDecorate"),
    gallery: $("#xmasTabGallery"),
    leaderboard: $("#xmasTabLeaderboard")
  };
  const panelEls = {
    decorate: $("#xmasPanelDecorate"),
    gallery: $("#xmasPanelGallery"),
    leaderboard: $("#xmasPanelLeaderboard")
  };
  const switchTab = (tab) => {
    const activeTab = panelEls[tab] ? tab : "decorate";
    christmasTreeStudioState.activeTab = activeTab;
    Object.keys(panelEls).forEach((key) => {
      const isActive = key === activeTab;
      if (tabEls[key]) {
        tabEls[key].classList.toggle("active", isActive);
        tabEls[key].setAttribute("aria-selected", String(isActive));
      }
      if (panelEls[key]) panelEls[key].hidden = !isActive;
    });
    if (activeTab === "leaderboard") {
      renderChristmasTreeLikesLeaderboard();
    }
  };
  Object.keys(tabEls).forEach((key) => {
    tabEls[key]?.addEventListener("click", () => switchTab(key));
  });

  const slotButtons = {
    polaroid: $("#xmasSlotBtnPolaroid"),
    card: $("#xmasSlotBtnCard"),
    gift: $("#xmasSlotBtnGift"),
    accessory: $("#xmasSlotBtnAccessory")
  };
  const slotForms = {
    polaroid: $("#xmasPolaroidForm"),
    card: $("#xmasCardForm"),
    gift: $("#xmasGiftForm"),
    accessory: $("#xmasAccessoryForm")
  };
  const switchSlot = (slot) => {
    if (!slotForms[slot]) return;
    christmasTreeStudioState.activeSlot = slot;
    Object.keys(slotButtons).forEach((k) => {
      const active = k === slot;
      const btn = slotButtons[k];
      if (btn) {
        btn.classList.toggle("active", active);
        btn.setAttribute("aria-selected", String(active));
      }
      if (slotForms[k]) slotForms[k].hidden = !active;
    });
    setChristmasTreeStatus("");
  };
  Object.keys(slotButtons).forEach((k) => {
    slotButtons[k]?.addEventListener("click", () => switchSlot(k));
  });

  $("#xmasTreeLoginBtn")?.addEventListener("click", () => {
    christmasTreeStudioState.pendingReopenModal = true;
    modal.close();
    if (typeof openAuth === "function") openAuth();
  });

  // Notify cleanly when clicking a locked streak-tier option
  $$("#christmasTreeModal .is-tier-option[data-min-tier]").forEach((opt) => {
    opt.addEventListener("click", () => {
      const minTier = Number(opt.dataset.minTier || 0);
      const access = getEffectiveViewerStreakAccess();
      if (access.streakTier < minTier) {
        const reqDays = TREE_STREAK_REQUIREMENTS[minTier] || 3;
        setChristmasTreeStatus(`Mẫu gradient này yêu cầu chuỗi hoạt động từ ${reqDays} ngày trở lên.`, true);
      }
    });
  });

  // Polaroid form controls
  $("#xmasPolaroidMsg")?.addEventListener("input", () => {
    setChristmasTreeStatus("");
    renderPolaroidFormPreview();
  });
  $("#xmasPolaroidMsg")?.addEventListener("blur", () => {
    const el = $("#xmasPolaroidMsg");
    if (el && el.value.length > 140) {
      setChristmasTreeStatus("Lời chúc Polaroid tối đa 140 ký tự.", true);
    }
  });
  $$('input[name="polaroidStyle"]').forEach((r) => {
    r.addEventListener("change", renderPolaroidFormPreview);
  });

  // Greeting Card form controls
  $$('input[name="cardStyle"]').forEach((r) => r.addEventListener("change", renderCardFormPreview));
  $$('input[name="cardFinish"]').forEach((r) => r.addEventListener("change", renderCardFormPreview));
  $("#xmasCardName")?.addEventListener("input", renderCardFormPreview);
  $("#xmasCardMsg")?.addEventListener("input", () => {
    setChristmasTreeStatus("");
    renderCardFormPreview();
  });

  // Gift & Accessory form controls
  $$('input[name="giftStyle"]').forEach((r) => r.addEventListener("change", renderGiftFormPreview));
  $("#xmasGiftMsg")?.addEventListener("input", renderGiftFormPreview);
  $$('input[name="accessoryStyle"]').forEach((r) => r.addEventListener("change", renderAccessoryFormPreview));

  // Hydrate illustrated postcard thumbnails inside preset cards
  $$('#christmasTreeModal .xmas-preset-card[data-photo-preset]').forEach((cardBtn) => {
    const presetKey = cardBtn.dataset.photoPreset || "";
    const thumbWrap = cardBtn.querySelector(".xmas-preset-thumb");
    if (thumbWrap && presetKey) {
      const asset = getChristmasTreePhotoAsset(presetKey);
      if (asset && asset.dataUrl) {
        thumbWrap.innerHTML = `<img src="${asset.dataUrl}" alt="" />`;
      }
    }
    cardBtn.addEventListener("click", () => {
      christmasTreeStudioState.polaroidPhotoData = presetKey;
      christmasTreeStudioState.polaroidPhotoFullData = "";
      const fileEl = $("#xmasPolaroidFile");
      if (fileEl) fileEl.value = "";
      const fileNameEl = $("#xmasPolaroidFileName");
      if (fileNameEl) fileNameEl.textContent = "Đang dùng tranh minh họa có sẵn";
      setChristmasTreeStatus("");
      renderPolaroidFormPreview();
    });
  });

  async function processUploadedPolaroidFile(file) {
    if (!file) return;
    const access = getEffectiveViewerStreakAccess();
    if (!access.canUploadPhoto) {
      setChristmasTreeStatus("Cần đạt chuỗi hoạt động từ 3 ngày trở lên để tải ảnh từ thiết bị.", true);
      return;
    }
    try {
      setChristmasTreeStatus("Đang xử lý ảnh...");
      const { thumbDataUrl, fullDataUrl } = await compressPolaroidImagePair(file);
      christmasTreeStudioState.polaroidPhotoData = thumbDataUrl;
      christmasTreeStudioState.polaroidPhotoFullData = fullDataUrl;
      const fileNameEl = $("#xmasPolaroidFileName");
      if (fileNameEl) fileNameEl.textContent = file.name || "Đã tải ảnh kỷ niệm";
      setChristmasTreeStatus("Ảnh đã sẵn sàng!");
      renderPolaroidFormPreview();
    } catch (err) {
      setChristmasTreeStatus(err.message || "Không thể xử lý ảnh.", true);
    }
  }

  $("#xmasPolaroidFile")?.addEventListener("change", async (ev) => {
    const file = ev.target && ev.target.files && ev.target.files[0];
    await processUploadedPolaroidFile(file);
  });

  const dropzone = $("#xmasPolaroidDropzone");
  if (dropzone) {
    dropzone.addEventListener("click", (ev) => {
      const access = getEffectiveViewerStreakAccess();
      if (!access.canUploadPhoto) {
        ev.preventDefault();
        setChristmasTreeStatus("Cần đạt chuỗi hoạt động từ 3 ngày trở lên để tải ảnh từ thiết bị.", true);
      }
    });
    dropzone.addEventListener("dragover", (ev) => {
      ev.preventDefault();
      if (getEffectiveViewerStreakAccess().canUploadPhoto) {
        dropzone.classList.add("is-dragover");
      }
    });
    dropzone.addEventListener("dragleave", () => {
      dropzone.classList.remove("is-dragover");
    });
    dropzone.addEventListener("drop", async (ev) => {
      ev.preventDefault();
      dropzone.classList.remove("is-dragover");
      const file = ev.dataTransfer && ev.dataTransfer.files && ev.dataTransfer.files[0];
      await processUploadedPolaroidFile(file);
    });
  }

  function askChristmasGiftSealConfirmation(slotKind) {
    if (slotKind === "accessory" || Date.now() >= CHRISTMAS_2026_REVEAL_MS) {
      return Promise.resolve({ confirmed: true, isSealed: false });
    }
    const confirmModal = $("#xmasConfirmHangModal");
    const titleEl = $("#xmasConfirmHangTitle");
    const sealBtn = $("#xmasConfirmChoiceSealBtn");
    const openBtn = $("#xmasConfirmChoiceOpenBtn");
    const sealLabelEl = $("#xmasConfirmSealLabel");
    const openLabelEl = $("#xmasConfirmOpenLabel");
    const cancelBtn = $("#xmasConfirmCancelBtn");
    if (!confirmModal || !sealBtn || !openBtn) {
      return Promise.resolve({ confirmed: true, isSealed: false });
    }

    if (titleEl) titleEl.textContent = "Bạn có muốn giữ món quà này đến Giáng sinh?";
    if (slotKind === "polaroid") {
      if (sealLabelEl) sealLabelEl.textContent = "Ẩn ảnh";
      if (openLabelEl) openLabelEl.textContent = "Hiện ảnh";
    } else if (slotKind === "card") {
      if (sealLabelEl) sealLabelEl.textContent = "Đóng thiệp";
      if (openLabelEl) openLabelEl.textContent = "Mở thiệp";
    } else {
      if (sealLabelEl) sealLabelEl.textContent = "Gói quà";
      if (openLabelEl) openLabelEl.textContent = "Mở quà";
    }

    return new Promise((resolve) => {
      let settled = false;
      let downOnBackdrop = false;
      const cleanup = (result) => {
        if (settled) return;
        settled = true;
        sealBtn.removeEventListener("click", onSeal);
        openBtn.removeEventListener("click", onOpen);
        cancelBtn?.removeEventListener("click", onCancel);
        confirmModal.removeEventListener("close", onDialogClose);
        confirmModal.removeEventListener("pointerdown", onPtrDown);
        confirmModal.removeEventListener("pointerup", onPtrUp);
        if (confirmModal.open) confirmModal.close();
        resolve(result);
      };
      const onSeal = () => cleanup({ confirmed: true, isSealed: true });
      const onOpen = () => cleanup({ confirmed: true, isSealed: false });
      const onCancel = () => cleanup({ confirmed: false, isSealed: false });
      const onDialogClose = () => cleanup({ confirmed: false, isSealed: false });
      const onPtrDown = (ev) => { downOnBackdrop = ev.target === confirmModal; };
      const onPtrUp = (ev) => {
        if (downOnBackdrop && ev.target === confirmModal) onCancel();
        downOnBackdrop = false;
      };

      sealBtn.addEventListener("click", onSeal);
      openBtn.addEventListener("click", onOpen);
      cancelBtn?.addEventListener("click", onCancel);
      confirmModal.addEventListener("close", onDialogClose);
      if (!("closedBy" in HTMLDialogElement.prototype)) {
        confirmModal.addEventListener("pointerdown", onPtrDown);
        confirmModal.addEventListener("pointerup", onPtrUp);
      }
      if (!confirmModal.open) confirmModal.showModal();
    });
  }

  async function saveChristmasTreeOrnament(payload) {
    setChristmasTreeStatus("Đang treo lên cây thông...");
    try {
      const data = await requestAPI("/api/christmas-tree", {
        method: "PUT",
        body: JSON.stringify(payload)
      });
      applyChristmasTreeServerPayload(data, true);
      setChristmasTreeStatus(
        payload.isSealed
          ? "🎄 Đã niêm phong bí mật! Món quà sẽ mở vào 20:00 ngày 24/12."
          : "🎄 Đã lưu trang trí của bạn lên cây thông chung!"
      );
      toast(
        payload.isSealed
          ? "🎄 Đã gói bí mật món quà đến 20:00 ngày 24/12!"
          : "🎄 Đã cập nhật trang trí lên cây thông Giáng sinh!"
      );
      const mine = (christmasTreeEventState.items || []).find(
        (it) => it.isSelf && it.slotKind === payload.slotKind
      );
      if (mine) focusChristmasTreeItemOnStage(mine.id, { pauseAutoSpin: false });
    } catch (err) {
      setChristmasTreeStatus(err.message || "Không thể lưu trang trí.", true);
    }
  }

  async function deleteChristmasTreeOrnamentById(id) {
    if (!id) return;
    setChristmasTreeStatus("Đang gỡ món trang trí...");
    try {
      const data = await requestAPI(`/api/christmas-tree/${id}`, { method: "DELETE" });
      if (Number(christmasTreeStudioState.selectedId) === Number(id)) {
        hideChristmasTreeInspector();
      }
      applyChristmasTreeServerPayload(data, true);
      setChristmasTreeStatus("Đã gỡ món trang trí khỏi cây thông.");
      toast("Đã gỡ khỏi cây thông Giáng sinh.");
    } catch (err) {
      setChristmasTreeStatus(err.message || "Không thể gỡ món này.", true);
    }
  }

  function canSubmitChristmasTreeSlot(slotKind) {
    if (!(typeof session !== "undefined" && session)) {
      setChristmasTreeStatus("Vui lòng đăng nhập để trang trí cây thông Giáng sinh.", true);
      return false;
    }
    const ownSlots = new Set(
      (christmasTreeEventState.items || [])
        .filter((it) => it && it.isSelf)
        .map((it) => it.slotKind)
    );
    if (!ownSlots.has(slotKind) && ownSlots.size >= 2) {
      const slotLabels = { polaroid: "Polaroid", card: "Thiệp", gift: "Hộp quà", accessory: "Phụ kiện" };
      const activeNames = Array.from(ownSlots).map((k) => slotLabels[k] || k).join(" & ");
      setChristmasTreeStatus(
        `Bạn đã treo đủ 2/4 loại (${activeNames}). Hãy gỡ bớt 1 món nếu muốn đổi sang ${slotLabels[slotKind] || "mục này"}.`,
        true
      );
      return false;
    }
    return true;
  }

  slotForms.polaroid?.addEventListener("submit", async (ev) => {
    ev.preventDefault();
    if (!canSubmitChristmasTreeSlot("polaroid")) return;
    const styleEl = document.querySelector('input[name="polaroidStyle"]:checked');
    const msgEl = $("#xmasPolaroidMsg");
    const shuffleEl = $("#xmasPolaroidShuffle");
    const msgVal = (msgEl ? msgEl.value : "").trim();
    if (!christmasTreeStudioState.polaroidPhotoData) {
      setChristmasTreeStatus("Hãy chọn tranh minh họa hoặc tải ảnh kỷ niệm lên khung Polaroid.", true);
      return;
    }
    const choice = await askChristmasGiftSealConfirmation("polaroid");
    if (!choice.confirmed) return;
    await saveChristmasTreeOrnament({
      slotKind: "polaroid",
      itemStyle: styleEl ? styleEl.value : "classic",
      message: msgVal,
      photoData: christmasTreeStudioState.polaroidPhotoData || "",
      photoFullData: christmasTreeStudioState.polaroidPhotoFullData || "",
      shufflePosition: Boolean(shuffleEl && shuffleEl.checked),
      isSealed: choice.isSealed
    });
    if (shuffleEl) shuffleEl.checked = false;
  });

  slotForms.card?.addEventListener("submit", async (ev) => {
    ev.preventDefault();
    if (!canSubmitChristmasTreeSlot("card")) return;
    const { tplKey, spec } = getSelectedChristmasCardSpec();
    const finishEl = document.querySelector('input[name="cardFinish"]:checked');
    const nameEl = $("#xmasCardName");
    const msgEl = $("#xmasCardMsg");
    const shuffleEl = $("#xmasCardShuffle");
    const msgVal = (msgEl ? msgEl.value : "").trim();
    const maxChars = Number(spec.maxChars || 300);
    if (msgVal.length < 2) {
      setChristmasTreeStatus("Hãy viết lời chúc trên tấm thiệp (ít nhất 2 ký tự).", true);
      return;
    }
    if (msgVal.length > maxChars) {
      setChristmasTreeStatus(`Lời chúc cho mẫu thiệp này tối đa ${maxChars} ký tự.`, true);
      return;
    }
    const choice = await askChristmasGiftSealConfirmation("card");
    if (!choice.confirmed) return;
    await saveChristmasTreeOrnament({
      slotKind: "card",
      itemStyle: tplKey,
      itemFinish: normalizeCardFinishKey(finishEl ? finishEl.value : "pastel_white"),
      cardName: (nameEl ? nameEl.value : "").trim(),
      message: msgVal,
      shufflePosition: Boolean(shuffleEl && shuffleEl.checked),
      isSealed: choice.isSealed
    });
    if (shuffleEl) shuffleEl.checked = false;
  });

  slotForms.gift?.addEventListener("submit", async (ev) => {
    ev.preventDefault();
    if (!canSubmitChristmasTreeSlot("gift")) return;
    const styleEl = document.querySelector('input[name="giftStyle"]:checked');
    const msgEl = $("#xmasGiftMsg");
    const shuffleEl = $("#xmasGiftShuffle");
    const choice = await askChristmasGiftSealConfirmation("gift");
    if (!choice.confirmed) return;
    await saveChristmasTreeOrnament({
      slotKind: "gift",
      itemStyle: styleEl ? styleEl.value : "gift_red",
      message: (msgEl ? msgEl.value : "").trim(),
      shufflePosition: Boolean(shuffleEl && shuffleEl.checked),
      isSealed: choice.isSealed
    });
    if (shuffleEl) shuffleEl.checked = false;
  });

  // Accessory hangs directly with zero confirm dialog & zero message
  slotForms.accessory?.addEventListener("submit", async (ev) => {
    ev.preventDefault();
    if (!canSubmitChristmasTreeSlot("accessory")) return;
    const styleEl = document.querySelector('input[name="accessoryStyle"]:checked');
    const shuffleEl = $("#xmasAccShuffle");
    await saveChristmasTreeOrnament({
      slotKind: "accessory",
      itemStyle: styleEl ? styleEl.value : "bauble_ruby",
      message: "",
      shufflePosition: Boolean(shuffleEl && shuffleEl.checked),
      isSealed: false
    });
    if (shuffleEl) shuffleEl.checked = false;
  });

  ["#xmasPolaroidDeleteBtn", "#xmasCardDeleteBtn", "#xmasGiftDeleteBtn", "#xmasAccDeleteBtn"].forEach((sel) => {
    $(sel)?.addEventListener("click", (ev) => {
      const id = ev.currentTarget && ev.currentTarget.dataset.deleteId;
      if (id) deleteChristmasTreeOrnamentById(id);
    });
  });

  modal.addEventListener("click", (ev) => {
    const t = ev.target;
    if (!t || !t.closest) return;
    const likeBtn = t.closest("[data-tree-like-id]");
    if (likeBtn) {
      handleChristmasTreeLikeClick(likeBtn.dataset.treeLikeId, likeBtn);
      return;
    }
    const openViewerBtn = t.closest("[data-tree-open-viewer]");
    if (openViewerBtn) {
      openChristmasItemViewer(openViewerBtn.dataset.treeOpenViewer);
      return;
    }
    const focusBtn = t.closest("[data-tree-focus-id]");
    if (focusBtn) {
      focusChristmasTreeItemOnStage(focusBtn.dataset.treeFocusId);
      return;
    }
    const delBtn = t.closest("[data-tree-delete-id]");
    if (delBtn) {
      deleteChristmasTreeOrnamentById(delBtn.dataset.treeDeleteId);
      return;
    }
    const ncBtn = t.closest("[data-open-namecard]");
    if (ncBtn && typeof openNamecard === "function") {
      const uid = Number(ncBtn.dataset.openNamecard);
      if (uid) {
        modal.close();
        openNamecard(uid);
      }
    }
  });

  const viewerModal = $("#xmasItemViewerModal");
  if (viewerModal) {
    if (!("closedBy" in HTMLDialogElement.prototype)) {
      let downOnViewerBackdrop = false;
      viewerModal.addEventListener("pointerdown", (ev) => {
        downOnViewerBackdrop = ev.target === viewerModal;
      });
      viewerModal.addEventListener("pointerup", (ev) => {
        if (downOnViewerBackdrop && ev.target === viewerModal) {
          viewerModal.close();
        }
        downOnViewerBackdrop = false;
      });
    }
    viewerModal.addEventListener("close", () => {
      christmasTreeStudioState.activeViewerItemId = null;
      const likesPop = $("#xmasItemViewerLikesPopover");
      if (likesPop) {
        likesPop.hidden = true;
        likesPop.innerHTML = "";
      }
    });
    $("#xmasItemViewerCloseBtn")?.addEventListener("click", () => viewerModal.close());
    viewerModal.addEventListener("click", (ev) => {
      const t = ev.target;
      if (!t || !t.closest) return;
      const likeBtn = t.closest("[data-tree-like-id]");
      if (likeBtn) {
        handleChristmasTreeLikeClick(likeBtn.dataset.treeLikeId, likeBtn);
        return;
      }
      const ncBtn = t.closest("[data-open-namecard]");
      if (ncBtn && typeof openNamecard === "function") {
        const uid = Number(ncBtn.dataset.openNamecard);
        if (uid) {
          viewerModal.close();
          modal.close();
          openNamecard(uid);
        }
      }
    });
  }

  if (canvas) {
    canvas.addEventListener("pointerdown", (ev) => {
      christmasTreeStudioState.dragging = true;
      christmasTreeStudioState.dragMoved = false;
      christmasTreeStudioState.dragStartX = ev.clientX;
      christmasTreeStudioState.dragLastX = ev.clientX;
      canvas.classList.add("is-dragging");
    });

    window.addEventListener("pointermove", (ev) => {
      if (!christmasTreeStudioState.isOpen) return;
      if (christmasTreeStudioState.dragging) {
        const dx = ev.clientX - christmasTreeStudioState.dragLastX;
        christmasTreeStudioState.dragLastX = ev.clientX;
        if (Math.abs(ev.clientX - christmasTreeStudioState.dragStartX) > 6) {
          christmasTreeStudioState.dragMoved = true;
        }
        christmasTreeStudioState.rotation += dx * 0.012;
      } else if (ev.target === canvas) {
        const hit = findHitTreeOrnament(ev.clientX, ev.clientY);
        christmasTreeStudioState.hoverId = hit ? hit.id : null;
        canvas.style.cursor = hit ? "pointer" : "grab";
      }
    }, { passive: true });

    window.addEventListener("pointerup", (ev) => {
      if (!christmasTreeStudioState.dragging) return;
      const wasDrag = christmasTreeStudioState.dragMoved;
      christmasTreeStudioState.dragging = false;
      canvas.classList.remove("is-dragging");
      if (!wasDrag && ev.target === canvas) {
        const hit = findHitTreeOrnament(ev.clientX, ev.clientY);
        if (hit) {
          christmasTreeStudioState.selectedId = hit.id;
          showChristmasTreeInspector(hit);
          renderChristmasTreeGallery();
        } else {
          hideChristmasTreeInspector();
          renderChristmasTreeGallery();
        }
      }
    });

    canvas.addEventListener("pointercancel", () => {
      christmasTreeStudioState.dragging = false;
      canvas.classList.remove("is-dragging");
    });
  }

  window.addEventListener("resize", () => {
    if (christmasTreeStudioState.isOpen) {
      resizeChristmasTreeStudioCanvas();
    }
  }, { passive: true });
}

window.openChristmasTreeModal = async function (e) {
  if (e) {
    e.preventDefault();
    e.stopPropagation();
  }
  if (!isChristmas2026Season()) {
    toast("Sự kiện cây thông Giáng sinh 2026 đã kết thúc.");
    return;
  }
  if (typeof window.closeQuickUserMenu === "function") {
    window.closeQuickUserMenu();
  }
  initChristmasTreeStudio();
  const modal = $("#christmasTreeModal");
  if (!modal) return;

  if (!modal.open) {
    modal.showModal();
  }
  christmasTreeStudioState.isOpen = true;
  christmasTreeStudioState.autoSpin = !christmasSnowState.reducedMotion;
  setChristmasTreeFullscreen(false);
  startChristmasCountdownLoop();
  syncChristmasSpinButton(christmasTreeStudioState.autoSpin);
  setChristmasTreeStatus("");
  renderChristmasTreeStudioUI(true);
  requestAnimationFrame(() => {
    resizeChristmasTreeStudioCanvas();
    if (!christmasTreeStudioState.rafId) {
      christmasTreeStudioState.lastMs = 0;
      christmasTreeStudioState.rafId = requestAnimationFrame(renderStudioChristmasTreeFrame);
    }
  });
  await fetchChristmasTreeData(true);
};

function initChristmasSeasonEffects() {
  if (christmasSnowState.initialized) return;
  christmasSnowState.initialized = true;

  christmasSnowState.canvas = $("#christmasSnowCanvas");
  christmasTreeState.canvas = $("#christmasTreeCanvas");
  christmasSnowState.enabled = getChristmasEffectsEnabled();
  updateChristmasSnowTheme();

  const motionQuery = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)");
  christmasSnowState.reducedMotion = Boolean(motionQuery && motionQuery.matches);
  if (motionQuery) {
    const onMotionChange = (ev) => {
      christmasSnowState.reducedMotion = Boolean(ev.matches);
      startOrStopChristmasSnowLoop();
    };
    if (typeof motionQuery.addEventListener === "function") {
      motionQuery.addEventListener("change", onMotionChange);
    } else if (typeof motionQuery.addListener === "function") {
      motionQuery.addListener(onMotionChange);
    }
  }

  renderChristmasHeaderGarland();
  syncCardSnowCaps();
  if (christmasSnowState.canvas) {
    resizeChristmasSnowCanvas();
    window.addEventListener("resize", () => {
      resizeChristmasSnowCanvas();
      syncCardSnowCaps();
    }, { passive: true });
  }
  document.addEventListener("pointermove", (ev) => handleCardSnowPointer(ev, false), { passive: true });
  document.addEventListener("pointerdown", (ev) => handleCardSnowPointer(ev, true), { passive: true });
  initChristmasTreeStudio();
  christmasTreeStudioState.lastSessionUserId = (typeof session !== "undefined" && session && session.id) ? session.id : null;
  if (isChristmas2026Season()) {
    fetchChristmasTreeData(true);
  }
  document.addEventListener("visibilitychange", startOrStopChristmasSnowLoop);
  document.addEventListener("pointerdown", (ev) => {
    if (!isChristmas2026Season() || !christmasSnowState.enabled || christmasSnowState.reducedMotion) return;
    if (document.documentElement.classList.contains("study-mode-active") || document.body.classList.contains("arena-quiz-active")) return;
    const target = ev && ev.target;
    if (target && target.closest && target.closest("input, textarea, select, [contenteditable='true']")) return;
    const x = typeof ev.clientX === "number" ? ev.clientX : 0;
    const y = typeof ev.clientY === "number" ? ev.clientY : 0;
    if (!x && !y) return;
    for (let k = 0; k < 5 && christmasSnowState.sparkles.length < 44; k++) {
      const a = (Math.PI * 2 * k) / 5 + Math.random() * 0.6;
      const spd = 0.8 + Math.random() * 1.4;
      christmasSnowState.sparkles.push({
        x,
        y,
        vx: Math.cos(a) * spd,
        vy: Math.sin(a) * spd - 0.5,
        r: Math.random() * 1.7 + 1.1,
        life: 1
      });
    }
  }, { passive: true });

  startOrStopChristmasSnowLoop();
  initChristmasMusicPlayer();

  // Re-evaluate holiday & Christmas Eve reveal boundaries once per minute
  let lastRevealState = Date.now() >= CHRISTMAS_2026_REVEAL_MS;
  setInterval(() => {
    const stillActive = isChristmas2026Season();
    const nowRevealed = Date.now() >= CHRISTMAS_2026_REVEAL_MS;
    if (stillActive && nowRevealed && !lastRevealState) {
      lastRevealState = true;
      fetchChristmasTreeData(true);
    }
    if (!stillActive) {
      if (christmasBgmState.audio && !christmasBgmState.audio.paused) {
        christmasBgmState.audio.pause();
      }
      startOrStopChristmasSnowLoop();
      updateChristmasMusicUI();
      const confirmModal = $("#xmasConfirmHangModal");
      if (confirmModal && confirmModal.open) confirmModal.close();
      const treeModal = $("#christmasTreeModal");
      if (treeModal && treeModal.open) treeModal.close();
      if (typeof studySettings !== "undefined" && studySettings.activeWallpaper === "christmas_2026") {
        applyStudyWallpaperPreset("default");
      }
      if (typeof renderWallpaperPresets === "function") {
        renderWallpaperPresets();
      }
    }
  }, 60000);
}

initChristmasSeasonEffects();

